/* StewardMD - management/treatment briefs for the NON-INFECTIVE differentials
   shown by the Clinical Reasoning (DX) engine. Keyed by DX diagnosis id.
     dx: how to confirm | tx: first-line management steps | ix: key investigations
     dispo: disposition | src: source(s)
   Concise decision-support aligned to Harrison Principles of Internal Medicine
   22e (2025) + cited society guidelines, and CROSS-CHECKED against the Harrison
   22e text (entries marked "rev. Harrison 22e <page>" were refined in that pass).
   NOT a substitute for clinical judgement / local protocol / full prescribing
   references - verify doses (renal/hepatic/pregnancy, interactions) before use. */
(function () {
  window.DX_MGMT = {
    // ── High-risk toxicology canonical objects (gold122) — added so general
    //    "how to treat X" knowledge queries retrieve management. Standard,
    //    guideline-aligned content; not individualized advice. ──
    paracetamol_poisoning: { name: "Paracetamol (acetaminophen) poisoning", class: "non_infective", system: "Toxicology",
      syn: ["acetaminophen overdose", "paracetamol overdose", "APAP toxicity", "acetaminophen poisoning"],
      dx: "Often asymptomatic early; nausea/RUQ discomfort then hepatotoxicity at 24–72 h. Plot a level drawn ≥4 h post-ingestion on the Rumack–Matthew nomogram; treat staggered/unknown-timing ingestions empirically.",
      tx: ["Resuscitate; activated charcoal only if presenting within ~1–2 h and airway is protected.",
        "N-ACETYLCYSTEINE (NAC) is the antidote — start if the 4-hour level is above the treatment line, or empirically for staggered / unknown-timing / late (>8 h) presentation without waiting for the level.",
        "Continue NAC and monitor for acute liver failure (rising INR, encephalopathy, acidosis, hypoglycaemia).",
        "Refer early to a liver/transplant unit using King's College criteria; correct hypoglycaemia and coagulopathy.",
        "Contact a poisons service for staggered/massive ingestion or established hepatotoxicity."],
      ix: ["Paracetamol level at ≥4 h post-ingestion", "LFTs, INR, creatinine, glucose", "ABG/lactate if severe"],
      dispo: "Admit; ALF → transplant centre/ICU.", src: "Harrison 22e · toxicology guidelines" },
    methanol_poisoning: { name: "Methanol poisoning", class: "non_infective", system: "Toxicology",
      syn: ["methanol toxicity", "methyl alcohol poisoning", "toxic alcohol methanol"],
      dx: "Latent period then visual disturbance/blindness with a high-anion-gap metabolic acidosis and a raised osmolar gap after ingestion of adulterated spirits/solvents.",
      tx: ["Resuscitate; IV sodium bicarbonate for severe metabolic acidosis.",
        "FOMEPIZOLE (preferred) — or ethanol if unavailable — to inhibit alcohol dehydrogenase and block formation of the toxic metabolite (formic acid).",
        "Folinic/folic acid to accelerate formate metabolism.",
        "HAEMODIALYSIS for severe acidosis, visual symptoms, high methanol levels, or renal failure.",
        "Contact a poisons service; monitor acid–base, osmolar/anion gap and vision."],
      ix: ["Serum methanol ± ethanol level", "ABG, anion gap and osmolar gap", "U&E, lactate; fundoscopy"],
      dispo: "ICU; dialysis for severe toxicity.", src: "Harrison 22e · toxicology guidelines" },
    snakebite_envenomation: { name: "Snakebite envenomation", class: "non_infective", system: "Toxicology",
      syn: ["snake bite", "venomous snakebite", "snake envenomation"],
      dx: "Fang marks with local swelling; systemic envenomation shows coagulopathy/bleeding, neurotoxicity (ptosis, bulbar/respiratory weakness) or AKI. Use the 20-minute whole-blood clotting test for coagulopathy.",
      tx: ["Reassure; immobilise the limb at heart level and transport urgently. Do NOT apply a tourniquet, incise, or suck the wound.",
        "ANTIVENOM (polyvalent ASV) for any sign of systemic envenomation — coagulopathy on 20-min WBCT, neurotoxicity, or marked local spread — titrated to reversal; be ready to treat ASV anaphylaxis.",
        "Neurotoxic (elapid) bites: neostigmine + atropine trial and ventilatory support as needed.",
        "Supportive care for AKI (dialysis if required); tetanus prophylaxis; analgesia (avoid NSAIDs if coagulopathic).",
        "Serial monitoring of clotting, neurology and renal function; repeat ASV if coagulopathy persists."],
      ix: ["20-minute whole-blood clotting test", "Coagulation profile, platelets, creatinine, CK, urinalysis", "Monitor neurology and respiration"],
      dispo: "Admit/observe; ICU for neurotoxicity or shock.", src: "Harrison 22e · WHO/national snakebite guidelines" },
    STATUS_EPILEPTICUS: { name: "Status epilepticus", class: "non_infective", system: "Neurology",
      syn: ["convulsive status epilepticus", "refractory status epilepticus"],
      dx: "A seizure lasting >5 min or recurrent seizures without recovery of consciousness — a time-critical emergency.",
      tx: ["ABC; give oxygen, secure IV access, check glucose (treat hypoglycaemia) and give thiamine if malnourished/alcohol.",
        "First-line: IV benzodiazepine — lorazepam (or IM midazolam if no IV) — repeat once if seizures continue.",
        "Second-line if ongoing: IV antiseizure load — levetiracetam, sodium valproate, or (fos)phenytoin.",
        "Refractory status: intubate and start an anaesthetic infusion (midazolam or propofol) with continuous EEG.",
        "Identify and treat the cause (hypoglycaemia, infection/meningitis, electrolytes, eclampsia, toxins, AED non-adherence)."],
      ix: ["Glucose, electrolytes, calcium, magnesium", "AED levels, toxicology screen", "EEG (esp. for non-convulsive); CT/MRI ± LP as indicated"],
      dispo: "ICU for refractory/ongoing seizures.", src: "Harrison 22e · NCS status epilepticus guideline" },
    migraine: { dx: "Recurrent moderate–severe, often unilateral throbbing headache ± aura, photophobia, nausea with a normal exam (ICHD-3). Image only for red flags.", tx: ["Acute: NSAID (e.g. naproxen) or paracetamol; add an oral triptan (e.g. sumatriptan 50–100 mg) if no vascular contraindication.","Add an antiemetic (metoclopramide / prochlorperazine) for nausea.","Treat early; rest in a dark, quiet room.","Limit acute drugs to <10–15 days/month to avoid medication-overuse headache.","Prophylaxis if frequent/disabling: propranolol, amitriptyline, topiramate or candesartan."], ix: ["Clinical (ICHD-3)","Neuroimaging only if red flags"], dispo: "Outpatient; neurology referral if refractory or atypical.", src: "Harrison 22e · ICHD-3" },
    tension_ha: { dx: "Bilateral, pressing/tightening, mild–moderate headache without migrainous features or red flags.", tx: ["Simple analgesia: paracetamol or an NSAID, used sparingly.","Address triggers — stress, poor sleep, posture, caffeine, eye strain.","Prophylaxis with low-dose amitriptyline if chronic (>15 days/month).","Avoid opioids and frequent analgesia (medication-overuse risk)."], ix: ["Clinical diagnosis"], dispo: "Outpatient.", src: "Harrison 22e" },
    sah: { dx: "Sudden thunderclap (worst-ever) headache ± neck stiffness, photophobia, transient LOC. Non-contrast CT head; LP for xanthochromia if CT negative and high suspicion.", tx: ["EMERGENCY — resuscitate (ABC), neurosurgery / stroke team immediately.","CT angiography to localise aneurysm; secure aneurysm early (endovascular coiling or clipping).","Nimodipine 60 mg PO q4h to reduce vasospasm-related deficits.","Control pain and BP (avoid extreme swings); bed rest, analgesia, antiemetics.","Monitor for hydrocephalus, rebleeding, vasospasm, hyponatraemia."], ix: ["Non-contrast CT","LP (xanthochromia)","CT/DSA angiography"], dispo: "ICU + neurosurgery, urgent.", src: "Harrison 22e · AHA/ASA SAH" },
    ischemic_stroke: { dx: "Sudden focal neurological deficit; non-contrast CT to exclude haemorrhage, then confirm ischaemia. Establish last-known-well time.", tx: ["TIME-CRITICAL — activate stroke pathway, non-contrast CT immediately.","IV thrombolysis (alteplase/tenecteplase) if within window and no contraindication.","Mechanical thrombectomy for large-vessel occlusion up to 24 h in selected patients.","Aspirin 300 mg once haemorrhage excluded (delay 24 h after thrombolysis).","Admit to stroke unit; permissive hypertension, glucose/temperature control, swallow screen, early secondary prevention."], ix: ["Non-contrast CT ± CT angio/perfusion","Glucose, ECG","Carotid imaging, echo"], dispo: "Stroke unit / ICU.", src: "Harrison 22e · AHA/ASA stroke" },
    ich: { dx: "Sudden focal deficit ± reduced consciousness, headache, vomiting; non-contrast CT shows intraparenchymal haemorrhage.", tx: ["Resuscitate; protect airway if GCS ≤8.","Reverse anticoagulation urgently (vitamin K + PCC for warfarin; specific reversal agents for DOACs).","Lower SBP to ~140 mmHg (e.g. IV labetalol/nicardipine).","Manage raised ICP; neurosurgical referral (esp. cerebellar bleed, hydrocephalus).","Admit to stroke unit/ICU; VTE prophylaxis (mechanical first)."], ix: ["Non-contrast CT","Coagulation profile","CT angio if structural cause suspected"], dispo: "ICU / neurosurgery.", src: "Harrison 22e · AHA/ASA ICH" },
    brain_tumour: { dx: "Progressive headache (worse on waking/Valsalva), focal signs, new seizures, or papilloedema. MRI brain with contrast.", tx: ["MRI with contrast; refer neuro-oncology / neurosurgery.","Dexamethasone for symptomatic vasogenic oedema (with PPI cover).","Antiepileptics only if seizures have occurred (not routine prophylaxis).","Definitive therapy (surgery, radiotherapy, chemotherapy) is tumour-specific via MDT."], ix: ["MRI brain + contrast","Staging imaging if metastasis suspected","Histology"], dispo: "Refer neuro-oncology/neurosurgery.", src: "Harrison 22e" },
    iih: { dx: "Headache + visual disturbance with papilloedema, typically a young obese woman; normal imaging; LP opening pressure raised with normal CSF.", tx: ["MRI + MR venography (exclude mass/venous sinus thrombosis), then LP to confirm raised opening pressure with normal CSF.","Weight loss is central; consider a GLP-1 receptor agonist if unable to lose weight by diet.","Acetazolamide first-line (250-500 mg bid) to lower CSF production; topiramate is the next agent if ineffective.","Formal perimetry and urgent ophthalmology if visual loss; severe/progressive loss needs CSF diversion (lumboperitoneal shunt) or optic-nerve-sheath fenestration.","Stop precipitants (tetracyclines, vitamin A, retinoids)."], ix: ["Fundoscopy/formal perimetry","MRI + MRV","LP with opening pressure"], dispo: "Refer neurology + ophthalmology.", src: "Harrison 22e · rev. Harrison 22e 116-117," },
    temporal_arteritis: { dx: "New headache, scalp tenderness, jaw claudication ± visual symptoms in age >50; raised ESR/CRP; temporal artery biopsy or US confirms.", tx: ["START high-dose oral glucocorticoids IMMEDIATELY on suspicion - do not wait for biopsy (sight-threatening); IV methylprednisolone if visual loss.","Prednisone ~40-80 mg/day (Harrison cites 80 mg daily for the first 4-6 weeks).","Arrange temporal artery biopsy (or Doppler US) as soon as practical - steroids do not abolish findings immediately but can mask them with prolonged treatment.","Gastroprotection, bone protection, glucose monitoring; tocilizumab as a steroid-sparing alternative.","Slow steroid taper guided by symptoms and ESR/CRP."], ix: ["ESR, CRP","Temporal artery biopsy / Doppler US"], dispo: "Urgent rheumatology ± ophthalmology.", src: "Harrison 22e · ACR/EULAR GCA · rev. Harrison 22e 115," },
    acs: { dx: "Ischaemic chest pain ± ECG changes and troponin rise. Distinguish STEMI from NSTE-ACS by ECG.", tx: ["Aspirin 300 mg + a second antiplatelet (ticagrelor/clopidogrel); analgesia, oxygen only if hypoxic.","STEMI: primary PCI (or thrombolysis if PCI unavailable) — time-critical.","NSTE-ACS: anticoagulate (e.g. fondaparinux/LMWH) and risk-stratify (GRACE) for early angiography.","Start high-intensity statin, beta-blocker and ACE-inhibitor as tolerated.","Continuous monitoring; treat arrhythmia/heart failure."], ix: ["Serial ECG + troponin","Echo","Coronary angiography"], dispo: "CCU / cath lab.", src: "Harrison 22e · ESC ACS" },
    aortic_dissection: { dx: "Sudden tearing chest/back pain ± pulse/BP differential, new aortic regurgitation, widened mediastinum. CT angiography aorta.", tx: ["EMERGENCY — CT angiogram of the aorta; involve cardiothoracic surgery.","Control HR then BP: IV beta-blocker (labetalol/esmolol) to HR <60 and SBP ~100–120, add vasodilator.","Type A (ascending): emergency surgery. Type B: usually medical ± endovascular for complications.","Adequate analgesia (reduces sympathetic drive).","Cross-match blood; ICU monitoring."], ix: ["CT angiography (or TOE)","ECG, troponin (exclude MI mimic)","Group & save"], dispo: "ICU + cardiothoracic surgery.", src: "Harrison 22e · ESC aortic" },
    pe: { dx: "Pleuritic pain/dyspnoea/tachycardia ± leg DVT; risk-stratify (Wells), D-dimer if low probability, CTPA to confirm.", tx: ["Start anticoagulation on clinical suspicion if high probability (LMWH/DOAC).","Massive PE (shock): thrombolysis (or embolectomy) and resuscitation.","Confirm with CTPA (or V/Q); echo for RV strain in unstable patients.","Continue DOAC/LMWH→oral; duration ≥3 months (longer if unprovoked/recurrent).","Oxygen, analgesia; assess for cancer/thrombophilia if unprovoked."], ix: ["CTPA / V-Q","D-dimer (low prob)","ECG, troponin, echo (severity)"], dispo: "Admit; ICU if haemodynamically unstable.", src: "Harrison 22e · ESC PE" },
    pericarditis: { dx: "Sharp pleuritic chest pain relieved by sitting forward, friction rub, widespread saddle ST-elevation/PR depression. Exclude ACS and effusion/tamponade.", tx: ["NSAID (e.g. ibuprofen) + COLCHICINE for ~3 months (reduces recurrence).","Add gastroprotection; restrict strenuous activity until resolved.","Echo to assess for effusion/tamponade.","Treat the underlying cause; reserve steroids for specific indications (refractory, autoimmune).","Investigate for tamponade if hypotensive/raised JVP."], ix: ["ECG, echo","Troponin, CRP","Identify cause (viral, autoimmune, uraemic)"], dispo: "Outpatient if low-risk; admit if effusion/high-risk.", src: "Harrison 22e · ESC pericardial" },
    gerd_chest: { dx: "Burning retrosternal pain, postprandial/positional, acid regurgitation — once cardiac causes are excluded.", tx: ["EXCLUDE cardiac cause first if any doubt.","Lifestyle: weight loss, smaller meals, avoid late meals/triggers, elevate head of bed.","PPI trial (e.g. omeprazole) for 4–8 weeks.","Endoscopy if alarm features (dysphagia, weight loss, anaemia, age/onset).","Step down to lowest effective therapy."], ix: ["Clinical/PPI trial","OGD if alarm features"], dispo: "Outpatient.", src: "Harrison 22e · ACG GERD" },
    pneumothorax: { dx: "Sudden pleuritic pain and dyspnoea with reduced breath sounds; CXR confirms. Tension = hypotension + tracheal shift (clinical, treat immediately).", tx: ["TENSION pneumothorax: immediate needle decompression then chest drain — do NOT wait for imaging.","Primary, small, minimal symptoms: observation ± oxygen.","Larger/symptomatic: needle aspiration or chest drain.","Secondary (underlying lung disease): low threshold for chest drain + admission.","Smoking cessation; refer for recurrence (pleurodesis)."], ix: ["CXR (erect)","CT if complex","ABG if hypoxic"], dispo: "Admit if drained/secondary; ED observation if small primary.", src: "Harrison 22e · BTS pleural" },
    heart_failure: { dx: "Dyspnoea, orthopnoea, raised JVP, basal crackles, oedema; raised BNP/NT-proBNP; echo for ejection fraction.", tx: ["Acute pulmonary oedema: sit up, high-flow O2, IV loop diuretic (furosemide), IV nitrate if hypertensive.","Consider CPAP/NIV for severe respiratory distress.","Identify/treat precipitant (ischaemia, arrhythmia, non-adherence, infection).","Daily weights, fluid/salt restriction, monitor renal function and potassium.","Chronic HFrEF: ACEi/ARNI + beta-blocker + MRA + SGLT2 inhibitor."], ix: ["BNP/NT-proBNP","Echo","ECG, CXR, U&E, troponin"], dispo: "Admit; ICU/HDU if cardiogenic shock or NIV.", src: "Harrison 22e · ESC HF" },
    copd_exac_ni: { dx: "Increased dyspnoea/sputum/wheeze in known COPD without convincing infection. Assess for CO2 retention.", tx: ["Controlled oxygen targeting SpO2 88–92% (avoid over-oxygenation).","Nebulised salbutamol + ipratropium.","Oral prednisolone 30 mg for ~5 days.","Antibiotics only if increased purulent sputum / consolidation / ventilatory support.","NIV for persistent respiratory acidosis (pH <7.35 with hypercapnia)."], ix: ["ABG","CXR","ECG"], dispo: "Admit if hypoxic/acidotic; ICU/NIV if failing.", src: "Harrison 22e · GOLD" },
    cardiogenic_shock: { dx: "Hypotension with hypoperfusion despite adequate filling, due to pump failure (often after large MI). Raised lactate, low cardiac output, congestion.", tx: ["ICU; treat the cause — urgent revascularisation for ischaemic cause.","Inotrope/vasopressor (e.g. noradrenaline ± dobutamine) titrated to perfusion.","Cautious diuresis/fluid guided by filling status; treat arrhythmia.","Consider mechanical support (IABP/Impella/ECMO) in selected cases.","Invasive monitoring; serial lactate, urine output."], ix: ["Echo, ECG, troponin","Lactate, ABG","Coronary angiography"], dispo: "ICU / cardiology.", src: "Harrison 22e · ESC" },
    hypovolemic_shock: { dx: "Hypotension, tachycardia, cool peripheries, low JVP with a source of fluid/blood loss.", tx: ["Two large-bore IV lines; rapid balanced crystalloid resuscitation.","Haemorrhagic: activate major haemorrhage protocol — transfuse blood/products, tranexamic acid early.","Identify and control the source (surgery, endoscopy, IR, compression).","Titrate to perfusion (MAP, urine output, lactate clearance) — avoid over-resuscitation in active bleeding.","Keep warm; correct coagulopathy and calcium."], ix: ["FBC, cross-match, coagulation, lactate","Source imaging (CT/endoscopy)"], dispo: "Resuscitation area → ICU/theatre.", src: "Harrison 22e · ATLS" },
    anaphylaxis: { dx: "Acute onset of airway/breathing/circulation compromise ± urticaria/angioedema after an allergen exposure.", tx: ["IM ADRENALINE 0.5 mg (0.5 mL 1:1000) into anterolateral thigh — repeat every 5 min as needed. FIRST and most important step.","Remove trigger; lie flat with legs raised (sit up if breathing difficulty); high-flow oxygen.","IV fluid bolus for hypotension; nebulised salbutamol for bronchospasm.","Refractory: IV adrenaline infusion in a monitored setting.","Observe 6–12 h (biphasic risk); prescribe adrenaline auto-injector + allergy referral."], ix: ["Clinical diagnosis","Serial mast-cell tryptase","Allergy referral"], dispo: "Admit/observe; refractory → ICU.", src: "Harrison 22e · WAO/Resus Council" },
    adrenal_crisis: { dx: "Hypotension/shock, vomiting, hypoglycaemia, hyponatraemia ± known adrenal insufficiency or steroid withdrawal/stress. Treat on suspicion.", tx: ["Give IV HYDROCORTISONE 100 mg immediately — do NOT wait for cortisol results.","Aggressive IV fluids (0.9% saline) to correct volume and hypotension.","Correct hypoglycaemia (IV glucose) and electrolytes.","Treat the precipitant (often infection); continue hydrocortisone (e.g. 50 mg q6h) then taper.","Sick-day rules and steroid-emergency card education on recovery."], ix: ["Paired cortisol/ACTH (don't delay treatment)","U&E, glucose","Septic screen"], dispo: "Admit; ICU if shocked.", src: "Harrison 22e · Endocrine Society" },
    dka: { dx: "Hyperglycaemia + ketonaemia/ketonuria + high-anion-gap metabolic acidosis. Often a precipitant (infection, missed insulin, new T1DM).", tx: ["IV 0.9% saline resuscitation first (fluid deficit is large); careful in young/cardiac/renal.","Fixed-rate IV insulin infusion (~0.1 U/kg/h); continue basal insulin if on it.","Replace potassium once K <5.5 and urine output adequate (insulin drives K intracellularly).","Add dextrose when glucose <14 mmol/L; monitor ketones, glucose, K, pH hourly.","Find and treat the precipitant; do not stop insulin infusion until ketones cleared and eating."], ix: ["Glucose, ketones, VBG","U&E (potassium), bicarbonate","Septic screen, ECG"], dispo: "Admit (HDU/ICU if severe).", src: "Harrison 22e · ADA/JBDS DKA" },
    hypoglycemia: { dx: "Whipple's triad: low plasma glucose with autonomic/neuroglycopenic symptoms relieved by glucose. Identify cause (insulin/sulfonylurea, sepsis, etc.).", tx: ["Conscious: 15–20 g fast-acting oral carbohydrate, repeat in 15 min if still low.","Impaired/NBM: IV glucose (e.g. 100 mL 20%) or IM glucagon if no IV access.","Follow with longer-acting carbohydrate once recovered.","Sulfonylurea/long-acting insulin overdose: prolonged monitoring ± octreotide; admit.","Review drugs/diabetes regimen; address recurrent causes."], ix: ["Capillary + lab glucose","Insulin/C-peptide if cause unclear","Drug review"], dispo: "Observe; admit if drug-induced (long-acting).", src: "Harrison 22e · Endocrine Society" },
    metabolic_enceph: { dx: "Diffuse alteration of consciousness without focal deficit; asterixis, myoclonus. Identify the metabolic cause.", tx: ["Find and correct the cause — glucose, Na, Ca, uraemia, hypercapnia, ammonia, drugs, hypoxia, sepsis.","Support airway, oxygenation and circulation.","Empirical thiamine in at-risk patients; naloxone if opioid suspected.","Treat the underlying organ failure; review/stop offending drugs.","Monitor neurological status."], ix: ["Glucose, U&E, Ca, LFTs, ammonia, ABG","Toxicology","CT/EEG if cause unclear"], dispo: "Admit; ICU if airway risk.", src: "Harrison 22e" },
    hepatic_enceph: { dx: "Confusion/asterixis with chronic liver disease or porto-systemic shunt; a precipitant (GI bleed, infection, constipation, electrolytes, sedatives) is usually present.", tx: ["Identify and treat the PRECIPITANT (GI bleed, sepsis/SBP, constipation, hypokalaemia, dehydration, sedatives).","Lactulose titrated to 2–3 soft stools/day (oral or enema).","Add rifaximin for inadequate response / secondary prevention.","Avoid sedatives; do not over-restrict protein; correct electrolytes.","Manage underlying cirrhosis; assess for transplant."], ix: ["Ammonia (support, not diagnostic)","Septic screen incl. ascitic tap","Electrolytes, glucose"], dispo: "Admit; ICU if airway risk.", src: "Harrison 22e · AASLD/EASL" },
    drug_intox: { dx: "Altered consciousness/toxidrome after suspected ingestion; identify the agent and toxidrome; assess ABCs and risk.", tx: ["Resuscitate (airway, breathing, circulation); treat hypoglycaemia and give thiamine where relevant.","Identify the toxidrome; contact a poisons service (e.g. TOXBASE/Poison Centre) for agent-specific advice.","Decontamination (activated charcoal) only if early, airway-safe and appropriate agent.","Specific antidotes where indicated (naloxone, NAC, flumazenil caution, etc.); supportive monitoring.","Enhanced elimination/dialysis for selected toxins; psychiatric assessment after medical stabilisation."], ix: ["Glucose, paracetamol/salicylate levels","ABG, U&E, ECG, osmolar gap","Agent-specific levels"], dispo: "Admit/observe; ICU if severe.", src: "Harrison 22e · Poisons service" },
    dvt: { dx: "Unilateral leg pain/swelling/tenderness; risk-stratify (Wells), D-dimer if low probability, compression US confirms.", tx: ["Confirm proximal DVT with compression venous ultrasonography (D-dimer to help exclude when pretest probability is low).","Anticoagulate once confirmed: DOAC monotherapy (rivaroxaban or apixaban) first-line, or parenteral heparin/LMWH bridged to warfarin (target INR 2-3); warfarin not DOACs for antiphospholipid syndrome.","Treat at least 3 months; for first VTE consider extended/indefinite anticoagulation when there is no identifiable risk factor or a persistent risk factor (Harrison de-emphasises 'provoked vs unprovoked').","For cancer-associated VTE use LMWH or a DOAC (apixaban/edoxaban; avoid DOAC with GI cancer) and continue until cancer-free.","Compression stockings for symptomatic relief; check renal function for dosing; counsel on PE warning signs."], ix: ["Compression US","D-dimer (low prob)","FBC, renal function for dosing"], dispo: "Usually outpatient pathway.", src: "Harrison 22e · ASH/NICE VTE · rev. Harrison 22e 2204-2207" },
    asthma_exac: { dx: "Acute wheeze/dyspnoea/cough with reduced PEF; grade severity (PEF, SpO2, ability to speak, silent chest).", tx: ["High-flow oxygen to SpO2 94–98%; back-to-back nebulised salbutamol (+ ipratropium if severe).","Oral prednisolone 40–50 mg (or IV hydrocortisone) early.","IV magnesium sulfate for severe/life-threatening attacks.","Reassess with PEF/ABG; escalate to ICU for exhaustion, rising CO2 or silent chest.","Identify trigger; review inhaler technique/adherence and step-up preventer at discharge."], ix: ["PEF, SpO2","ABG if severe","CXR if atypical / no response"], dispo: "Admit if not responding; ICU if life-threatening.", src: "Harrison 22e · GINA/BTS" },
    atrial_fib: { dx: "Irregularly irregular pulse; ECG shows AF/flutter. Assess haemodynamic stability and onset/duration.", tx: ["Unstable (shock, ischaemia, pulmonary oedema): emergency synchronised DC cardioversion.","Stable: rate control with a beta-blocker or diltiazem/verapamil (digoxin if HF/hypotension).","Rhythm control (drug/electrical cardioversion) for selected/recent-onset; anticoagulate appropriately around cardioversion.","Anticoagulate per CHA2DS2-VASc (DOAC preferred) for stroke prevention.","Identify/treat triggers — sepsis, thyroid, electrolytes, alcohol, ischaemia."], ix: ["ECG","TFTs, electrolytes, echo","CHA2DS2-VASc / HAS-BLED"], dispo: "Admit if unstable/new with HF; else outpatient pathway.", src: "Harrison 22e · ESC AF" },
    aortic_stenosis: { dx: "Exertional syncope/angina/dyspnoea with an ejection-systolic murmur radiating to carotids, slow-rising pulse. Echo confirms severity.", tx: ["Echocardiography to grade severity; refer cardiology.","Avoid aggressive vasodilators/nitrates in severe AS (preload-dependent — risk of collapse).","Symptomatic severe AS → aortic valve replacement (surgical or TAVI).","Treat heart failure cautiously; manage concomitant CAD.","Endocarditis awareness/dental hygiene."], ix: ["Echocardiography","ECG, CXR","Coronary assessment pre-intervention"], dispo: "Cardiology referral; admit if decompensated.", src: "Harrison 22e · ESC/AHA valve" },
    pancreatitis: { dx: "Severe epigastric pain radiating to back with lipase/amylase >3× upper limit (or imaging). Identify cause (gallstones, alcohol); score severity.", tx: ["Aggressive early IV fluid resuscitation (balanced crystalloid) with monitoring.","Analgesia (opioids), antiemetics; early enteral nutrition as tolerated (avoid prolonged NBM).","NO routine antibiotics (only for proven infected necrosis/cholangitis).","Gallstone cause with cholangitis/obstruction: urgent ERCP; cholecystectomy on the same admission for mild biliary pancreatitis.","Severe/organ failure → HDU/ICU; monitor for necrosis, pseudocyst, collections."], ix: ["Lipase/amylase, LFTs, calcium, triglycerides","USS (gallstones)","CT if severe/uncertain"], dispo: "Admit; severe → HDU/ICU.", src: "Harrison 22e · ACG/IAP pancreatitis" },
    peptic_ulcer: { dx: "Epigastric pain ± upper-GI bleed (melaena/haematemesis). Risk-stratify bleed (Glasgow-Blatchford); OGD diagnostic and therapeutic.", tx: ["Active bleed: resuscitate (IV access, fluids/blood, transfuse to Hb ~70 g/L threshold); correct coagulopathy.","Urgent endoscopy (within 24 h) for haemostasis; IV PPI infusion for high-risk stigmata.","Test and treat H. pylori; stop NSAIDs; continue PPI.","Repeat endoscopy/IR embolisation or surgery for rebleeding.","Risk score (Glasgow-Blatchford/Rockall) guides admission and timing."], ix: ["FBC, U&E, coagulation, group&save","OGD","H. pylori testing"], dispo: "Admit; ICU/HDU if unstable bleed.", src: "Harrison 22e · NICE/ACG UGIB" },
    bowel_obstruction: { dx: "Colicky abdominal pain, vomiting, distension, absolute constipation; imaging (AXR/CT) confirms level and cause.", tx: ["'Drip and suck': NBM, IV fluids + electrolyte correction, nasogastric decompression.","CT to identify cause/level and detect ischaemia/strangulation.","Strangulation, closed-loop, ischaemia or perforation → urgent surgery.","Adhesional small-bowel obstruction without ischaemia: trial of conservative management.","Analgesia, antiemetics, urinary catheter; surgical review for all."], ix: ["AXR / CT abdomen","U&E, lactate, FBC","VBG"], dispo: "Surgical admission; theatre if strangulation.", src: "Harrison 22e · ACS/WSES" },
    mesenteric_ischemia: { dx: "Severe abdominal pain OUT OF PROPORTION to exam, ± AF/vascular disease, rising lactate. CT angiography is key.", tx: ["EMERGENCY — urgent CT angiography; do not delay for equivocal exam.","Resuscitate (fluids), broad-spectrum antibiotics, correct acidosis; NG decompression.","Urgent surgical/IR intervention — revascularisation (embolectomy/stent) and resect non-viable bowel.","Therapeutic anticoagulation for embolic/thrombotic arterial or venous occlusion.","ICU; high mortality — speed is critical."], ix: ["CT angiography","Lactate, ABG, FBC","ECG (AF)"], dispo: "Emergency surgery + ICU.", src: "Harrison 22e · WSES" },
    biliary_colic: { dx: "Postprandial RUQ/epigastric pain ± radiation to scapula, lasting <6 h, with gallstones on US and no fever/inflammation.", tx: ["Analgesia (NSAID/opioid) and antiemetics for the acute episode.","USS to confirm gallstones; check LFTs (exclude CBD stone/cholecystitis).","Low-fat dietary advice while awaiting surgery.","Elective laparoscopic cholecystectomy for symptomatic gallstones.","Escalate if fever, persistent pain or jaundice (cholecystitis/cholangitis)."], ix: ["USS abdomen","LFTs","MRCP if CBD stone suspected"], dispo: "Outpatient; surgical referral.", src: "Harrison 22e · NICE gallstones" },
    renal_colic: { dx: "Sudden severe loin-to-groin colicky pain ± haematuria, restless patient; non-contrast CT KUB confirms a stone and its size/site.", tx: ["Analgesia: an NSAID (e.g. IM/PR diclofenac) is first-line; opioid if NSAID contraindicated.","Antiemetic and fluids as needed; non-contrast CT KUB to confirm and size the stone.","Most stones <5 mm pass spontaneously — manage conservatively with analgesia ± medical expulsive therapy (alpha-blocker) and strain urine.","URGENT urology if obstruction WITH infection (obstructed infected system = emergency decompression), AKI, single kidney, or uncontrolled pain.","Larger/non-passing stones → urology for lithotripsy/ureteroscopy; advise hydration and prevention."], ix: ["Non-contrast CT KUB","Urinalysis, U&E, FBC/CRP","Stone analysis/metabolic work-up if recurrent"], dispo: "Often outpatient; admit if infected/obstructed, AKI, or intractable pain.", src: "Harrison 22e · EAU urolithiasis" },
    aaa: { dx: "Sudden abdominal/back/flank pain with hypotension and a pulsatile mass in an older patient — ruptured AAA until proven otherwise.", tx: ["EMERGENCY — call vascular surgery immediately; do NOT delay for extensive imaging if unstable.","Permissive hypotension (avoid aggressive fluids/overshoot before repair); large-bore access, major haemorrhage protocol.","Immediate transfer to theatre / endovascular suite for repair (EVAR or open).","CT angiography only if stable enough.","Cross-match; ICU post-op."], ix: ["Bedside US / CT angio if stable","Cross-match","FBC, coagulation"], dispo: "Emergency vascular surgery.", src: "Harrison 22e · ESVS" },
    thyroid_storm: { dx: "Severe thyrotoxicosis with fever, tachyarrhythmia, agitation/delirium, GI/hepatic dysfunction (Burch-Wartofsky score). Treat clinically.", tx: ["ICU; beta-blocker (propranolol) for adrenergic symptoms and to block T4→T3 conversion.","Antithyroid drug — propylthiouracil (preferred in storm) or carbimazole.","Give iodine (Lugol's/potassium iodide) at least 1 h AFTER the antithyroid drug.","Hydrocortisone (reduces T4→T3 and treats relative adrenal insufficiency).","Supportive: cooling, fluids, treat the precipitant (often infection); avoid aspirin."], ix: ["TFTs (don't delay treatment)","ECG, glucose, LFTs","Septic screen"], dispo: "ICU.", src: "Harrison 22e · ATA" },
    seizure_epilepsy: { dx: "Stereotyped paroxysmal event ± post-ictal confusion. First seizure vs known epilepsy; status if >5 min or recurrent without recovery.", tx: ["Status epilepticus: protect airway, O2, glucose; IV lorazepam (or IM midazolam), repeat once.","Second-line: IV levetiracetam, valproate or phenytoin/fosphenytoin.","Refractory status → ICU, intubation, anaesthetic infusion (propofol/midazolam).","Correct provoking causes (hypoglycaemia, hyponatraemia, alcohol, drugs, infection).","First unprovoked seizure: usually no drug; start AED if high recurrence risk / abnormal EEG-MRI; neurology referral, driving advice."], ix: ["Glucose, electrolytes, Ca/Mg","CT/MRI brain, EEG","Drug levels/toxicology"], dispo: "Status → ICU; first seizure → neurology.", src: "Harrison 22e · NICE/AES" },
    vasovagal_syncope: { dx: "Transient LOC with prodrome (warmth, nausea, greying vision), rapid full recovery, typical triggers; orthostatic drop or reflex pattern. Exclude cardiac/structural cause.", tx: ["Reassure once cardiac causes excluded; explain mechanism.","Avoid triggers; ensure hydration and adequate salt intake.","Teach physical counter-pressure manoeuvres (leg crossing, hand grip) at prodrome.","Review/stop hypotensive drugs; treat orthostatic component (compression, slow rising).","ECG ± monitoring to rule out arrhythmia; refer cardiology if exertional/red-flag features."], ix: ["12-lead ECG, lying/standing BP","Bloods (anaemia, glucose)","Tilt-table/ambulatory monitor if uncertain"], dispo: "Outpatient; cardiology if red flags.", src: "Harrison 22e · ESC syncope" },
    anemia_sympt: { dx: "Fatigue, dyspnoea, pallor, tachycardia with low haemoglobin; classify by MCV and look for blood loss/haemolysis.", tx: ["Assess haemodynamic tolerance; transfuse for symptomatic/severe anaemia (restrictive threshold ~70 g/L, ~80 if cardiac).","Identify and treat the cause — iron/B12/folate deficiency, bleeding, haemolysis, marrow, chronic disease.","Iron deficiency: oral iron (IV if intolerant/malabsorption) and find the source (GI evaluation in at-risk).","Replace B12/folate as indicated (give B12 before folate to avoid subacute combined degeneration).","Reticulocyte count and blood film direct further work-up."], ix: ["FBC, MCV, blood film, reticulocytes","Iron studies, B12/folate","Haemolysis screen; source of bleeding"], dispo: "By cause/severity; admit if unstable.", src: "Harrison 22e · AABB transfusion" },
    malignancy_b: { dx: "Constitutional 'B' symptoms (weight loss, fevers, night sweats) ± lymphadenopathy/organomegaly suggesting lymphoma/occult malignancy.", tx: ["Structured work-up: examination, bloods, imaging (CT) and targeted tissue diagnosis (excision/core biopsy).","Avoid empirical steroids before histology (can obscure lymphoma diagnosis).","Refer to the appropriate oncology/haematology MDT promptly.","Definitive treatment is tumour-specific after staging.","Manage symptoms and oncological emergencies (hypercalcaemia, SVCO, cord compression)."], ix: ["FBC, film, LDH, ESR","CT chest/abdo/pelvis ± PET","Tissue biopsy"], dispo: "Urgent oncology/haematology referral.", src: "Harrison 22e" },
    crystal_arthritis: { dx: "Acute monoarthritis (often 1st MTP/knee) — confirm with joint aspiration showing crystals; ALWAYS exclude septic arthritis.", tx: ["Aspirate the joint — crystals confirm gout/pseudogout; Gram stain/culture EXCLUDES septic arthritis.","Acute attack: NSAID, or colchicine, or corticosteroid (oral/intra-articular) — choose by comorbidity.","Rest, ice, analgesia; continue any established urate-lowering therapy through the attack.","Do NOT start/stop allopurinol during an acute flare for the first time; initiate urate-lowering later with prophylaxis.","Address risk factors (diuretics, alcohol, renal function)."], ix: ["Joint aspiration (crystals + culture)","Serum urate (after flare), renal function"], dispo: "Outpatient; admit if septic arthritis not excluded.", src: "Harrison 22e · ACR/EULAR gout" },
    sle_flare: { dx: "Multisystem flare (rash, arthritis, serositis, cytopenias, nephritis) in known/new SLE; raised anti-dsDNA, low complement.", tx: ["Assess organ involvement and severity (esp. renal, CNS, haematological).","Mild: hydroxychloroquine ± short NSAID/low-dose steroid.","Moderate–severe / organ-threatening: high-dose corticosteroids + immunosuppression (mycophenolate/cyclophosphamide; biologics).","Hydroxychloroquine for essentially all patients (reduces flares).","Exclude/treat concurrent infection (mimics flare and complicates immunosuppression); sun protection, vaccination."], ix: ["anti-dsDNA, complement (C3/C4)","FBC, renal function, urinalysis (casts/protein)","Exclude infection"], dispo: "Rheumatology; admit if organ-threatening.", src: "Harrison 22e · EULAR SLE" },
    vasculitis: { dx: "Multisystem illness — purpura, mononeuritis, renal/lung involvement, raised inflammatory markers; ANCA and biopsy guide diagnosis.", tx: ["Assess for organ/life-threatening features (alveolar haemorrhage, active glomerulonephritis — always classed as severe even with normal renal function).","Induce remission of severe ANCA-associated vasculitis with cyclophosphamide OR rituximab plus glucocorticoids; consider adjunctive avacopan to reduce steroid exposure.","Reserve plasma exchange for selected cases (concurrent anti-GBM antibody, or controversial use in the most fulminant disease) — a large RCT showed no benefit on the ESRD/death composite, so it is not routine.","Confirm with ANCA and tissue biopsy; exclude infection/mimics before immunosuppression (a rising ANCA alone is not a reason to escalate therapy).","Maintenance immunosuppression after induction; give Pneumocystis (TMP-SMX) prophylaxis plus bone/gastric protection on glucocorticoids."], ix: ["ANCA, complement, urinalysis","Renal function, CXR","Tissue biopsy"], dispo: "Urgent rheumatology/nephrology; admit if organ-threatening.", src: "Harrison 22e · EULAR/KDIGO · rev. Harrison 22e 2898-2946" },
    hyperthyroidism: { dx: "Weight loss, tremor, heat intolerance, palpitations with suppressed TSH and raised free T4/T3 (uncomplicated, no storm).", tx: ["Beta-blocker (propranolol) for symptomatic relief of adrenergic symptoms.","Antithyroid drug — carbimazole (or PTU in 1st-trimester pregnancy).","Determine cause (Graves vs nodular vs thyroiditis) — TRAb, uptake scan.","Discuss definitive options: radioactive iodine or surgery.","Monitor TFTs and FBC/LFTs (agranulocytosis, hepatotoxicity warning)."], ix: ["TFTs, TRAb","Thyroid uptake scan/US","FBC, LFTs baseline"], dispo: "Outpatient endocrinology (admit if storm).", src: "Harrison 22e · ATA" },
    ild: { dx: "Progressive exertional dyspnoea, dry cough, fine bibasal 'velcro' crackles; restrictive spirometry; HRCT pattern.", tx: ["HRCT chest and full PFTs; refer respiratory ILD service / MDT.","Identify cause — drugs, connective-tissue disease, occupational/environmental, hypersensitivity.","Treatment is pattern-specific: immunosuppression for inflammatory ILD; antifibrotics (pirfenidone/nintedanib) for IPF.","Oxygen for hypoxaemia; pulmonary rehabilitation; vaccinations.","Manage comorbidities; consider transplant referral in advanced disease."], ix: ["HRCT chest","PFTs (restrictive, low DLCO)","Autoimmune serology"], dispo: "Respiratory referral.", src: "Harrison 22e · ATS/ERS" },
    pleural_effusion: { dx: "Dyspnoea with stony dull base, reduced breath sounds; CXR/US confirms. Tap to classify (Light's criteria: exudate vs transudate).", tx: ["Diagnostic pleural aspiration (US-guided) — protein, LDH, pH, cytology, microbiology.","Apply Light's criteria; treat the underlying cause (heart failure, malignancy, etc.).","Therapeutic drainage for breathlessness (avoid >1.5 L at once — re-expansion oedema).","Suspected empyema/complicated parapneumonic: chest drain.","Malignant effusion: consider indwelling pleural catheter or pleurodesis."], ix: ["Pleural US + diagnostic tap","Light's criteria, cytology","Identify primary cause"], dispo: "Admit if large/symptomatic or infected.", src: "Harrison 22e · BTS pleural" },
    tamponade: { dx: "Hypotension, raised JVP, muffled heart sounds (Beck's triad) with pulsus paradoxus; echo shows effusion with diastolic collapse.", tx: ["EMERGENCY — urgent echo; cardiology/cardiothoracic input.","Echo-guided pericardiocentesis (or surgical drainage) to relieve tamponade.","IV fluids as a temporising measure to maintain filling.","Avoid positive-pressure ventilation if possible until drained.","Treat and investigate the underlying cause; send pericardial fluid for analysis."], ix: ["Urgent echo","ECG (low voltage/alternans)","Pericardial fluid analysis"], dispo: "ICU + pericardiocentesis.", src: "Harrison 22e · ESC pericardial" },
    htn_emergency: { dx: "Severe hypertension (often >180/120) WITH acute target-organ damage (encephalopathy, ACS, pulmonary oedema, AKI, retinopathy, dissection).", tx: ["Confirm target-organ damage (distinguishes emergency from urgency).","Controlled IV BP reduction — lower MAP by ~20–25% in the first hour (not to normal), titratable agent (labetalol, nicardipine, GTN).","Tailor target/agent to the syndrome (faster + lower in dissection/pulmonary oedema; cautious in acute stroke).","ICU/HDU monitoring with arterial line.","Identify cause; transition to oral agents once stable."], ix: ["Fundoscopy","ECG, troponin, U&E","CT head/CXR as indicated"], dispo: "ICU/HDU.", src: "Harrison 22e · ESC/ACC HTN" },
    glomerulonephritis: { dx: "Haematuria (dysmorphic RBCs/casts), proteinuria, hypertension ± AKI. Rapidly progressive GN is an emergency.", tx: ["Assess for rapidly progressive GN (rising creatinine) — nephrology emergency; urgent biopsy.","Send immunology (ANCA, anti-GBM, complement, ANA) before immunosuppression.","RPGN: high-dose corticosteroids + cyclophosphamide/rituximab ± plasma exchange (anti-GBM/severe).","Supportive: BP control (ACEi/ARB), manage fluid/electrolytes, treat any infection trigger.","Treat the specific cause; monitor renal function closely."], ix: ["Urinalysis + microscopy (casts)","Renal function, immunology panel","Renal biopsy"], dispo: "Admit; nephrology.", src: "Harrison 22e · KDIGO GN" },
    toxic_hepatitis: { dx: "Acute transaminitis ± jaundice temporally linked to a drug/toxin (esp. paracetamol). Assess for acute liver failure (INR, encephalopathy).", tx: ["Stop the offending drug/toxin immediately.","Paracetamol overdose: N-ACETYLCYSTEINE (use the nomogram / treat if staggered or uncertain timing).","Supportive care; monitor INR, glucose, lactate, creatinine and mental status for acute liver failure.","Contact a liver/transplant unit early if ALF criteria (rising INR, encephalopathy, acidosis) — King's College criteria.","Avoid further hepatotoxins; treat complications (coagulopathy, hypoglycaemia, cerebral oedema)."], ix: ["LFTs, INR, paracetamol level","Glucose, lactate, ABG, creatinine","Liver screen"], dispo: "Admit; ALF → transplant centre/ICU.", src: "Harrison 22e · AASLD ALF" },
    ibd_flare: { dx: "Bloody diarrhoea, urgency, abdominal pain ± systemic features in known/new IBD; raised CRP/faecal calprotectin; exclude infection (incl. C. difficile).", tx: ["EXCLUDE infective colitis (stool culture + C. difficile toxin) before/with immunosuppression.","Acute severe UC: admit, IV corticosteroids, VTE prophylaxis, monitor (Truelove-Witts / day-3 response).","Steroid-refractory severe UC: rescue ciclosporin or infliximab; early surgical review (colectomy).","Crohn's flare: corticosteroids to induce remission; optimise/escalate maintenance (immunomodulator/biologic).","Avoid antimotility agents in severe colitis (toxic megacolon risk); nutrition support."], ix: ["CRP, FBC, albumin, faecal calprotectin","Stool culture + C. diff","AXR (toxic megacolon), flexi-sig"], dispo: "Admit if severe; gastroenterology + surgery.", src: "Harrison 22e · ECCO/BSG IBD" },
    ttp_hus: { dx: "Microangiopathic haemolytic anaemia + thrombocytopenia (± renal failure, neuro signs, fever). Schistocytes on film; ADAMTS13 in TTP.", tx: ["HAEMATOLOGICAL EMERGENCY — urgent haematology referral.","TTP: start PLASMA EXCHANGE immediately (don't wait for ADAMTS13) + corticosteroids; add caplacizumab/rituximab.","Do NOT transfuse platelets unless life-threatening bleeding (may worsen thrombosis).","HUS: supportive care, renal support; eculizumab for atypical/complement-mediated HUS.","Monitor LDH, platelets, haemoglobin and organ function."], ix: ["FBC + blood film (schistocytes)","LDH, haptoglobin, bilirubin, reticulocytes","ADAMTS13, renal function, coagulation"], dispo: "Admit; ICU/haematology, urgent.", src: "Harrison 22e · BSH/ISTH" },
    gbs: { dx: "Progressive ascending weakness with areflexia ± sensory/autonomic involvement, often post-infective; albuminocytological dissociation on CSF; supportive NCS.", tx: ["ADMIT — monitor respiratory function (serial FVC) and autonomic status closely.","IVIG 0.4 g/kg/day ×5 days OR plasma exchange (equivalent efficacy).","ICU + ventilation if FVC falling, bulbar weakness or autonomic instability.","VTE prophylaxis, pain control, physiotherapy, pressure-area care.","Do NOT give corticosteroids (ineffective in GBS)."], ix: ["Serial spirometry (FVC)","LP (albuminocytological dissociation)","Nerve conduction studies"], dispo: "Admit; ICU if respiratory/autonomic compromise.", src: "Harrison 22e" },
    myasthenic_crisis: { dx: "Worsening bulbar/respiratory weakness in myasthenia gravis (or new presentation) with respiratory failure; often triggered by infection/drugs.", tx: ["ADMIT to ICU; monitor FVC/NIF — intubate early for respiratory failure.","IVIG or plasma exchange for the crisis.","Identify and remove triggers (infection, aminoglycosides, beta-blockers, magnesium).","Hold/adjust pyridostigmine acutely (secretions); optimise immunotherapy (steroids ± steroid-sparing) once stabilising.","Steroids may transiently worsen weakness — start cautiously under specialist care."], ix: ["FVC/NIF","Anti-AChR/MuSK antibodies","Septic screen, drug review"], dispo: "ICU + neurology.", src: "Harrison 22e" },
    cord_compression: { dx: "Bilateral leg weakness, a sensory level, and bladder/bowel dysfunction ± back pain. Urgent whole-spine MRI.", tx: ["EMERGENCY — urgent whole-spine MRI; immobilise if traumatic/unstable.","High-dose dexamethasone for malignant compression (with PPI).","Emergency referral to spinal surgery / oncology for decompression ± radiotherapy.","Time-critical: outcome depends on speed — treat within hours.","Bladder care, VTE prophylaxis, analgesia."], ix: ["Whole-spine MRI (urgent)","Identify primary if malignant"], dispo: "Emergency spinal surgery / oncology.", src: "Harrison 22e · NICE MSCC" },
    hhs: { dx: "Marked hyperglycaemia with high osmolality and minimal ketosis/acidosis, profound dehydration ± reduced consciousness (typically older T2DM).", tx: ["Aggressive IV 0.9% saline — fluid replacement is the priority (large deficits, replace gradually).","Low-rate IV insulin, started after fluids (or if ketonaemia/glucose not falling with fluids alone).","Replace potassium guided by levels; monitor osmolality fall (aim gradual to avoid cerebral oedema).","VTE prophylaxis (high thrombotic risk); find and treat the precipitant.","Monitor glucose, Na, K and neuro status closely."], ix: ["Glucose, osmolality, U&E","VBG, ketones","Septic screen, ECG"], dispo: "Admit HDU/ICU.", src: "Harrison 22e · ADA/JBDS HHS" },
    myxedema: { dx: "Severe hypothyroidism with hypothermia, bradycardia, hypoventilation and reduced consciousness ± hyponatraemia; usually a precipitant.", tx: ["ICU; IV levothyroxine (± liothyronine) — give thyroid hormone.","Give IV HYDROCORTISONE first/concurrently (until adrenal insufficiency excluded).","Passive rewarming, ventilatory support for hypoventilation/CO2 retention.","Cautious correction of hyponatraemia and hypoglycaemia; IV fluids.","Treat the precipitant (commonly infection — may be afebrile)."], ix: ["TFTs, cortisol","ABG, glucose, Na","ECG, septic screen"], dispo: "ICU.", src: "Harrison 22e · ATA" },
    pheo: { dx: "Paroxysmal hypertension with headache, sweating, palpitations; raised plasma/urine metanephrines; tumour on imaging.", tx: ["Crisis: control with a titratable agent (IV phentolamine / nicardipine).","Establish ALPHA-blockade FIRST (phenoxybenzamine/doxazosin) — never beta-block before alpha (unopposed alpha → crisis).","Add beta-blockade later for tachyarrhythmia, after adequate alpha-blockade and volume repletion.","Liberal salt/fluid to restore volume pre-operatively.","Definitive: surgical resection after adequate blockade (≈2 weeks); endocrine/surgical MDT."], ix: ["Plasma/24h urine metanephrines","CT/MRI adrenal, MIBG","Genetic screen"], dispo: "Admit; ICU if crisis.", src: "Harrison 22e · Endocrine Society" },
    hypercalcemia: { dx: "Confusion, polyuria, constipation, abdominal pain with raised corrected calcium; PTH distinguishes hyperparathyroidism from malignancy/other.", tx: ["Aggressive IV 0.9% saline rehydration (cornerstone) with monitoring of fluid status.","IV bisphosphonate (e.g. zoledronic acid) for moderate–severe hypercalcaemia (effect over 2–4 days).","Calcitonin for rapid short-term lowering in severe/symptomatic cases.","Avoid thiazides; stop calcium/vitamin D; treat the underlying cause (malignancy, hyperparathyroidism).","Denosumab for bisphosphonate-refractory malignant hypercalcaemia."], ix: ["Corrected calcium, PTH, phosphate","U&E, vitamin D","Malignancy work-up"], dispo: "Admit if symptomatic/severe.", src: "Harrison 22e · Endocrine Society" },
    opioid_od: { dx: "Reduced consciousness, respiratory depression and PINPOINT pupils; response to naloxone is both diagnostic and therapeutic.", tx: ["Support airway and ventilation (bag-mask) — hypoxia kills, not the drug per se.","NALOXONE titrated to adequate respiration (not full arousal) — start low to avoid acute withdrawal.","Repeat naloxone or start an infusion (long-acting opioids outlast a naloxone bolus — re-sedation risk).","Observe for a prolonged period after the last naloxone dose; monitor for pulmonary oedema.","Address the cause; harm reduction, take-home naloxone, addiction referral."], ix: ["Capnography/SpO2, ABG","Glucose, paracetamol/salicylate (co-ingestion)","ECG"], dispo: "Observe; ICU if infusion/intubated.", src: "Harrison 22e" },
    salicylate_tox: { dx: "Tinnitus, hyperventilation, nausea, agitation with a mixed respiratory alkalosis + high-anion-gap metabolic acidosis; rising salicylate level.", tx: ["Resuscitate; correct hypokalaemia and hypoglycaemia (cerebral glucose may be low despite normal serum).","Activated charcoal if early; generous IV fluids.","Urinary alkalinisation with IV sodium bicarbonate (target urine pH ~7.5–8) — enhances elimination; keep K replete.","HAEMODIALYSIS for severe toxicity (high levels, acidosis, CNS features, renal failure, pulmonary oedema).","Avoid intubation if possible (loss of compensatory hyperventilation is dangerous); serial levels."], ix: ["Serial salicylate levels","ABG/VBG, U&E (potassium), glucose","Paracetamol level (co-ingestion)"], dispo: "Admit; severe → ICU/dialysis.", src: "Harrison 22e · poisons service" },
    serotonin_nms: { dx: "Hyperthermia, rigidity and altered mental state with autonomic instability — serotonergic excess (clonus, hyperreflexia, rapid onset) vs NMS (lead-pipe rigidity, antipsychotic, slower).", tx: ["STOP the offending agent immediately (serotonergic drug or antipsychotic).","Aggressive cooling and IV fluids; benzodiazepines for agitation/rigidity; ICU for severe cases.","Serotonin syndrome: consider cyproheptadine. NMS: consider dantrolene ± bromocriptine.","Monitor for and treat rhabdomyolysis, hyperthermia, renal failure and DIC.","Supportive care; avoid restraints worsening hyperthermia."], ix: ["Creatine kinase, U&E, coagulation","Temperature, ECG","Drug history"], dispo: "Admit; ICU if severe/hyperthermic.", src: "Harrison 22e" },
    organophosphate: { dx: "Cholinergic toxidrome — miosis, salivation/lacrimation, bronchorrhoea, bradycardia, fasciculations — after organophosphate/carbamate exposure.", tx: ["Protect staff (PPE) and decontaminate (remove clothing, wash skin).","Secure airway; suction copious secretions — bronchorrhoea/respiratory failure is the killer.","ATROPINE in escalating/doubling doses titrated to drying of secretions and adequate oxygenation (not pupils/HR).","PRALIDOXIME (oxime) for organophosphates with nicotinic features/weakness.","Benzodiazepines for seizures; ICU monitoring (intermediate syndrome, rebound)."], ix: ["Clinical; plasma/RBC cholinesterase","ABG, ECG","Observe for delayed effects"], dispo: "ICU.", src: "Harrison 22e · WHO" },
    dic: { dx: "Bleeding and/or thrombosis with consumptive coagulopathy (low platelets, high PT/APTT, low fibrinogen, high D-dimer) secondary to a trigger (sepsis, malignancy, obstetric).", tx: ["TREAT THE UNDERLYING CAUSE — this is the priority (sepsis, obstetric emergency, malignancy).","Bleeding/high-risk: replace with platelets, fresh frozen plasma, and cryoprecipitate/fibrinogen guided by levels.","Thrombotic phenotype without bleeding: consider therapeutic anticoagulation (specialist-guided).","Supportive care; serial coagulation monitoring.","Haematology involvement."], ix: ["Platelets, PT/APTT, fibrinogen, D-dimer","Blood film","Identify trigger"], dispo: "Admit; ICU + haematology.", src: "Harrison 22e · ISTH/BSH" },
    acute_leukemia: { dx: "Pancytopenia or leucocytosis with blasts on film, bleeding/infection; bone marrow confirms. Watch for tumour lysis/DIC.", tx: ["Urgent haematology referral; admit.","Supportive: transfuse as needed, neutropenic-sepsis protocol for fever, tumour-lysis prophylaxis (hydration, allopurinol/rasburicase).","Treat coagulopathy/DIC (esp. APML — start ATRA promptly on suspicion).","Definitive remission-induction chemotherapy per subtype; consider transplant.","Central access, fertility/consent discussions as appropriate."], ix: ["FBC + blood film, coagulation","Bone marrow + cytogenetics/flow","LDH, urate, U&E (TLS)"], dispo: "Admit; haematology.", src: "Harrison 22e" },
    variceal_bleed: { dx: "Haematemesis/melaena in portal hypertension; haemodynamic compromise. Confirmed and treated at endoscopy.", tx: ["Resuscitate: large-bore IV access; restrictive transfusion (transfuse when Hb <7 g/dL); correct marked coagulopathy/thrombocytopenia before endoscopy.","Give cirrhotic UGIB patients an IV vasoactive drug (octreotide/somatostatin/terlipressin) AND an antibiotic (e.g. ceftriaxone) on presentation — both reduce rebleeding and mortality.","Consider tracheal intubation for airway protection in repeated haematemesis; IV erythromycin ~30-90 min pre-scope to improve visualisation.","Endoscopy within 24 h: variceal band ligation for oesophageal varices, tissue-adhesive injection for gastric varices.","Persistent/recurrent bleeding or advanced liver disease (Child-Pugh B 8-9 with active bleeding, or C 10-13): TIPS; secondary prophylaxis with nonselective beta blocker + band ligation."], ix: ["FBC, coagulation, cross-match, LFTs","Urgent OGD","Lactate"], dispo: "ICU/HDU + gastroenterology.", src: "Harrison 22e · Baveno/AASLD · rev. Harrison 22e 360-362" },
    svc_obstruction: { dx: "Facial/neck/arm swelling, distended veins, dyspnoea ± plethora; usually malignant. CT confirms level/cause.", tx: ["Sit the patient up; oxygen; assess airway (emergency if stridor/cerebral oedema).","CT chest to define cause and obtain tissue diagnosis before treatment where possible.","Endovascular stenting gives rapid relief, esp. for severe symptoms.","Cause-directed therapy: radiotherapy/chemotherapy for malignancy (SCLC/lymphoma chemo-sensitive).","Corticosteroids in steroid-responsive tumours/airway compromise; anticoagulate if thrombus."], ix: ["CT chest with contrast","Tissue diagnosis","Identify primary"], dispo: "Admit; oncology/IR.", src: "Harrison 22e" },
    aki: { dx: "Acute rise in creatinine and/or fall in urine output (KDIGO). Classify pre-renal / renal / post-renal.", tx: ["Assess volume status — fluid resuscitate if pre-renal/hypovolaemic; relieve obstruction (catheter/imaging) if post-renal.","Stop/avoid nephrotoxins (NSAIDs, ACEi/ARB, contrast, aminoglycosides); review drug doses.","Treat the cause (sepsis, obstruction, intrinsic disease); optimise perfusion and avoid both hypo- and hypervolaemia.","Monitor and treat complications — hyperkalaemia, acidosis, fluid overload, uraemia.","Urgent dialysis for refractory hyperkalaemia/acidosis/overload/uraemic complications; nephrology if intrinsic/unclear."], ix: ["U&E, VBG, urinalysis ± microscopy","Renal tract US (obstruction)","Creatine kinase, immunology if intrinsic"], dispo: "Admit; nephrology/ICU if severe.", src: "Harrison 22e · KDIGO AKI" },
    rhabdo: { dx: "Muscle pain/weakness with markedly raised creatine kinase ± myoglobinuria (dark urine) and AKI; common after immobility, trauma, seizures, toxins, statins.", tx: ["Early aggressive IV fluid resuscitation (isotonic saline) to maintain high urine output — cornerstone to prevent AKI.","Monitor and treat hyperkalaemia and other electrolyte/acid-base disturbances; watch calcium/phosphate.","Treat the cause (relieve compression, stop offending drug, control seizures/agitation, manage hyperthermia).","Avoid nephrotoxins; consider urinary alkalinisation in selected cases (controversial).","Dialysis for refractory hyperkalaemia/acidosis/overload; watch for compartment syndrome."], ix: ["Creatine kinase, U&E, calcium/phosphate","Urinalysis (blood without RBCs)","ECG (hyperkalaemia)"], dispo: "Admit; ICU if severe.", src: "Harrison 22e" },
    sjs_ten: { dx: "Painful mucocutaneous rash with blistering/skin detachment and mucosal erosions, usually drug-induced; SJS <10%, TEN >30% body-surface detachment.", tx: ["STOP the culprit drug immediately (single most important step affecting outcome).","Manage like a burn — fluid/electrolyte balance, temperature control, meticulous wound/eye/mucosal care; ideally a burns/specialist unit.","Analgesia, nutrition, infection surveillance (avoid prophylactic antibiotics).","Ophthalmology and urology/gynae input for mucosal involvement; calculate SCORTEN.","Immunomodulation (ciclosporin/IVIG/etanercept) per specialist — evidence evolving."], ix: ["Clinical ± skin biopsy","SCORTEN, electrolytes, cultures","Drug timeline"], dispo: "Admit (burns/ICU); urgent dermatology.", src: "Harrison 22e" },
    tia: { dx: "Transient focal neurological deficit fully resolving (usually <1 h) without infarction on imaging. Risk-stratify (ABCD2) and image vasculature.", tx: ["Start aspirin 300 mg immediately (then secondary prevention).","Short-term dual antiplatelet (aspirin + clopidogrel) for ~21 days in high-risk TIA/minor stroke.","Urgent assessment (specialist within 24 h); carotid imaging — endarterectomy if symptomatic high-grade stenosis.","Anticoagulate if AF; high-intensity statin; control BP, diabetes, smoking.","Driving advice."], ix: ["MRI/CT brain, carotid Doppler","ECG ± prolonged monitoring (AF)","Lipids, glucose"], dispo: "Urgent TIA clinic / admit if crescendo.", src: "Harrison 22e · AHA/ASA" },
    subdural: { dx: "Headache, fluctuating consciousness or cognitive decline, sometimes after (minor) trauma — esp. elderly/anticoagulated. CT shows crescentic collection.", tx: ["Non-contrast CT head; neurosurgical referral.","Reverse anticoagulation; correct coagulopathy.","Surgical evacuation (burr hole for chronic, craniotomy for acute) if symptomatic/large with mass effect.","Small asymptomatic collections: observe with repeat imaging.","Manage raised ICP; seizure precautions."], ix: ["Non-contrast CT head","Coagulation profile"], dispo: "Neurosurgery referral.", src: "Harrison 22e" },
    wernicke: { dx: "Confusion, ophthalmoplegia/nystagmus, ataxia — esp. alcohol misuse or malnutrition. Clinical diagnosis; treat empirically, don't wait for tests.", tx: ["Give IV THIAMINE BEFORE any glucose (glucose first can precipitate/worsen Wernicke).","High-dose IV thiamine (e.g. 500 mg tds for 2–3 days, then taper) — Pabrinex regimens.","Correct magnesium (cofactor) and other deficiencies; rehydrate.","Treat the underlying cause; alcohol withdrawal management.","Continue oral thiamine after the acute course."], ix: ["Clinical diagnosis","Glucose, magnesium, electrolytes","MRI if uncertain (do not delay treatment)"], dispo: "Admit.", src: "Harrison 22e · EFNS" },
    ms: { dx: "Neurological symptoms disseminated in time and space in a young adult; MRI white-matter lesions, oligoclonal bands. Confirm relapse vs pseudo-relapse (exclude infection/heat).", tx: ["Exclude infection/fever (pseudo-relapse) before treating.","Acute disabling relapse: high-dose corticosteroids (IV/oral methylprednisolone ~3–5 days).","Plasma exchange for severe steroid-refractory relapse.","Disease-modifying therapy decided by neurology (relapse rate/MRI activity).","Symptomatic care (spasticity, bladder, fatigue) and rehabilitation."], ix: ["MRI brain/cord","CSF oligoclonal bands","Exclude infection"], dispo: "Neurology referral.", src: "Harrison 22e · McDonald criteria" },
    rheumatoid: { dx: "Symmetrical small-joint polyarthritis with early-morning stiffness >30 min; RF/anti-CCP, raised ESR/CRP, erosions.", tx: ["Early referral to rheumatology — 'treat to target' (remission/low disease activity).","Start a DMARD early (methotrexate first-line) ± short-term steroid bridge.","Escalate to combination DMARDs or a biologic/targeted synthetic DMARD if inadequate response.","NSAID for symptom relief; monitor DMARD toxicity (FBC, LFTs).","Manage cardiovascular risk, bone health and vaccination."], ix: ["RF, anti-CCP, ESR/CRP","X-rays of hands/feet","FBC, LFTs baseline"], dispo: "Rheumatology referral.", src: "Harrison 22e · ACR/EULAR RA" },
    pmr: { dx: "Bilateral shoulder/hip girdle pain and stiffness in age >50, raised ESR/CRP, dramatic steroid response. Screen for coexisting GCA.", tx: ["Start prednisone 10-20 mg/day for isolated PMR — a prompt, near-complete response supports the diagnosis.","Taper gradually guided by symptoms and ESR/CRP; recurrent symptoms during tapering occur in the majority, so taper cautiously.","Screen for giant cell arteritis at every visit (headache, jaw/tongue claudication, visual symptoms) as PMR and GCA are a single disease spectrum.","Provide glucocorticoid-related risk management: bone protection (calcium/vitamin D +/- bisphosphonate) and glucose monitoring.","For glucocorticoid-resistant or relapsing disease use an IL-6 receptor inhibitor (sarilumab); methotrexate gives only marginal steroid-sparing benefit."], ix: ["ESR, CRP","Exclude RA/myeloma/myositis (CK)"], dispo: "Outpatient; rheumatology if atypical/relapsing.", src: "Harrison 22e · ACR/EULAR PMR · rev. Harrison 22e 2902-2946" },
    decomp_cirrhosis: { dx: "Ascites, jaundice, encephalopathy or variceal bleed with stigmata of chronic liver disease; LFTs/INR/imaging confirm. Always seek a precipitant.", tx: ["Identify and treat the PRECIPITANT — always do a diagnostic ascitic tap to exclude SBP (treat with IV cefotaxime + albumin if PMN ≥250).","Ascites: salt restriction + spironolactone ± furosemide; large-volume paracentesis with albumin for tense ascites.","Encephalopathy: lactulose ± rifaximin; treat triggers (bleed, infection, constipation, electrolytes).","Variceal bleed: resuscitation, terlipressin, prophylactic antibiotics, urgent endoscopic band ligation.","Avoid nephrotoxins/NSAIDs; nutrition; assess for transplant; manage AKI/HRS."], ix: ["LFTs, INR, ammonia, U&E","Diagnostic ascitic tap (cell count + culture)","USS ± Doppler, endoscopy"], dispo: "Admit; ICU for bleed/grade-3-4 encephalopathy.", src: "Harrison 22e · AASLD/EASL" },
    ibs: { dx: "Chronic abdominal pain related to defecation with altered bowel habit and no alarm features; positive symptom-based (Rome IV) diagnosis after excluding organic disease.", tx: ["Confirm alarm features absent (weight loss, bleeding, anaemia, nocturnal symptoms, onset >50) and basic tests normal.","Diet/lifestyle: regular meals, fibre adjustment, trial of low-FODMAP with dietitian; address triggers.","Symptom-targeted drugs: antispasmodics for pain, laxatives for IBS-C, loperamide for IBS-D.","Low-dose tricyclic or SSRI for pain/global symptoms; psychological therapies (CBT/gut-directed hypnotherapy).","Reassurance and a positive diagnosis; review and safety-net."], ix: ["FBC, CRP, coeliac serology, faecal calprotectin","Exclude organic disease"], dispo: "Outpatient.", src: "Harrison 22e · Rome IV/NICE IBS" },
    ckd: { dx: "Reduced eGFR and/or markers of kidney damage (albuminuria) for >3 months; stage by eGFR/albuminuria (KDIGO).", tx: ["Treat the cause and slow progression: control BP (ACEi/ARB if albuminuric), glycaemic control, SGLT2 inhibitor where indicated.","Reduce cardiovascular risk (statin, lifestyle, smoking cessation); avoid nephrotoxins; dose-adjust drugs.","Manage complications — anaemia (iron ± ESA), CKD-mineral-bone disorder (phosphate, vitamin D), acidosis, hyperkalaemia.","Monitor eGFR/ACR; vaccinate; dietary sodium/protein advice.","Plan renal replacement / transplant and refer nephrology as eGFR declines."], ix: ["eGFR, ACR, U&E","FBC (anaemia), calcium/phosphate/PTH","Renal US"], dispo: "Outpatient; nephrology by stage.", src: "Harrison 22e · KDIGO CKD" },
    nephrotic: { dx: "Heavy proteinuria (>3.5 g/day), hypoalbuminaemia, oedema ± hyperlipidaemia. Identify primary vs secondary cause; biopsy in adults.", tx: ["Quantify proteinuria; renal biopsy in adults to define the lesion (guides specific therapy).","Reduce proteinuria with ACEi/ARB; manage oedema with salt restriction + loop diuretics (cautious).","Statin for hyperlipidaemia; consider VTE prophylaxis (high thrombotic risk, esp. albumin <20–25 g/L).","Cause-specific immunosuppression (e.g. steroids for minimal change) per nephrology.","Treat secondary causes (diabetes, amyloid, drugs, infection); vaccination."], ix: ["Urine protein:creatinine, albumin, lipids","Renal biopsy","Secondary work-up (glucose, immunology, serology)"], dispo: "Nephrology referral.", src: "Harrison 22e · KDIGO GN" },
    itp: { dx: "Isolated thrombocytopenia with otherwise normal counts/film and no alternative cause; bleeding risk relates to platelet count.", tx: ["No/minor bleeding with platelets >20–30: often observe.","Treat if bleeding or very low count: corticosteroids (prednisolone or dexamethasone) ± IVIG for rapid rise.","Life-threatening bleeding: IVIG + IV methylprednisolone + platelet transfusion (and consider TXA).","Second-line: TPO-receptor agonists, rituximab, or splenectomy.","Avoid antiplatelets/anticoagulants; confirm diagnosis (exclude secondary causes)."], ix: ["FBC + blood film","Exclude secondary causes (HIV, HCV, drugs, SLE)","H. pylori where relevant"], dispo: "Outpatient if stable; admit if bleeding/very low.", src: "Harrison 22e · ASH ITP" },
    myeloma: { dx: "CRAB features — hyperCalcaemia, Renal impairment, Anaemia, Bone lesions/pain — with paraprotein and clonal marrow plasma cells.", tx: ["Manage emergencies: hypercalcaemia (fluids + bisphosphonate), AKI (hydration, stop nephrotoxins), cord compression, infection.","Bone disease: bisphosphonate (zoledronic acid) + analgesia ± radiotherapy/vertebroplasty.","Refer haematology — definitive therapy is combination anti-myeloma regimens ± autologous stem-cell transplant.","Anaemia support; VTE prophylaxis with immunomodulatory regimens; vaccination/infection prophylaxis.","Confirm with serum/urine electrophoresis, free light chains, marrow and imaging."], ix: ["Serum/urine electrophoresis, free light chains","Calcium, renal function, FBC","Skeletal survey/whole-body MRI/CT, marrow"], dispo: "Haematology referral; admit if emergency.", src: "Harrison 22e · IMWG" },
    lung_cancer: { dx: "Cough, haemoptysis, weight loss, or an incidental mass in a smoker; CT chest and tissue diagnosis with staging.", tx: ["CT chest/abdomen and tissue diagnosis (bronchoscopy/biopsy); PET-CT for staging.","Refer to lung-cancer MDT urgently.","Treatment by type/stage: surgery (early NSCLC), chemoradiotherapy, targeted/immunotherapy by molecular profile; SCLC is chemo-sensitive.","Smoking cessation; manage complications (effusion, SVCO, hypercalcaemia, cord compression).","Early palliative-care involvement improves outcomes."], ix: ["CT chest","Biopsy + molecular markers","PET-CT, brain MRI staging"], dispo: "Urgent oncology/MDT referral.", src: "Harrison 22e · NICE/ESMO" },
    sarcoidosis: { dx: "Multisystem granulomatous disease — bilateral hilar lymphadenopathy, lung infiltrates ± skin/eye/cardiac involvement; non-caseating granulomas on biopsy (exclude TB).", tx: ["Confirm histology (non-caseating granulomas) and EXCLUDE TB/infection/lymphoma first.","Asymptomatic/mild: observe — many resolve spontaneously.","Treat if organ-threatening (cardiac, neuro, eye, progressive lung, hypercalcaemia): corticosteroids first-line.","Steroid-sparing agents (methotrexate/azathioprine) for chronic disease.","Screen for cardiac and ocular involvement; monitor calcium."], ix: ["CXR/HRCT, serum ACE, calcium","Tissue biopsy","ECG/echo, ophthalmology"], dispo: "Respiratory/multispecialty referral.", src: "Harrison 22e · ATS sarcoid" },
    hyponatremia: { dx: "Symptomatic low sodium; assess volume status and serum/urine osmolality to classify (hypovolaemic / euvolaemic-SIADH / hypervolaemic).", tx: ["Severe symptoms (seizures, coma): cautious hypertonic 3% saline boluses to raise Na ~4–6 mmol/L.","Correct slowly: ≤8–10 mmol/L per 24 h (avoid osmotic demyelination); recheck Na frequently.","Hypovolaemic: 0.9% saline. SIADH: fluid restriction ± treat cause. Hypervolaemic: treat HF/cirrhosis, restrict fluid.","Identify and remove the cause (drugs, cortisol/thyroid deficiency, malignancy).","Watch for over-correction — re-lower with dextrose/desmopressin if too fast."], ix: ["Serum + urine osmolality, urine Na","Volume assessment","TFTs, cortisol"], dispo: "Admit; severe → HDU/ICU.", src: "Harrison 22e · European hyponatraemia guideline" },
    hyperkalemia: { dx: "Raised serum potassium ± ECG changes (peaked T, wide QRS). Treat urgently if K ≥6.5 or ECG changes.", tx: ["ECG changes / K ≥6.5: IV CALCIUM gluconate to stabilise the myocardium FIRST.","Shift K intracellularly: IV insulin + dextrose, and nebulised salbutamol.","Remove K: stop K-raising drugs, give a potassium binder; loop diuretic if volume-replete.","Dialysis for refractory/severe hyperkalaemia or established renal failure.","Treat the cause (AKI, drugs — ACEi/ARB/K-sparing, acidosis, rhabdo); recheck K."], ix: ["ECG (immediate)","U&E, VBG","Drug review"], dispo: "Admit/monitored area; nephrology if dialysis needed.", src: "Harrison 22e · UK Renal/KDIGO" },
    panic: { dx: "Abrupt episodes of intense fear with somatic symptoms (palpitations, dyspnoea, chest tightness, paraesthesia) peaking within minutes — a diagnosis of exclusion after ruling out organic causes.", tx: ["EXCLUDE organic mimics first (ACS, PE, arrhythmia, hypoglycaemia, thyrotoxicosis) — especially on first presentation.","Acute: calm reassurance, breathing techniques; benzodiazepines only sparingly/short-term if at all.","First-line ongoing treatment: CBT and/or an SSRI/SNRI.","Reduce stimulants (caffeine), alcohol; lifestyle and psychoeducation.","Arrange follow-up and safety-net; screen for depression and substance use."], ix: ["ECG, glucose, TFTs as indicated","Exclude organic disease"], dispo: "Outpatient; psychiatry/psychology referral.", src: "Harrison 22e · NICE anxiety" },
    angioedema_acei: { dx: "Non-pitting swelling of lips/tongue/face/airway WITHOUT urticaria; ACE-inhibitor or hereditary (bradykinin-mediated). Assess airway.", tx: ["Assess and protect the AIRWAY early — low threshold for senior anaesthetic/ENT involvement and early intubation.","Stop the ACE inhibitor permanently.","Bradykinin-mediated angioedema responds poorly to adrenaline/steroids/antihistamines, but give them if any doubt about anaphylaxis.","Hereditary angioedema: specific therapy (C1-esterase-inhibitor concentrate, icatibant).","Observe for delayed/progressive swelling; avoid ACEi/ARB in future."], ix: ["Clinical; airway assessment","C1-inhibitor/C4 if hereditary suspected"], dispo: "Admit/observe; ICU if airway threatened.", src: "Harrison 22e" },
    // ── Enrichment: Harrison 22e + society guidelines (waves 1–2, independently verified, terse) ──
    "congenital_heart_disease": { name: "Adult Congenital Heart Disease", class: "non_infective", system: "Cardiology", dx: "Transthoracic echo defines lesion, shunt direction/magnitude, chamber size, ventricular function and PA pressure; add cardiac MRI/CT for complex anatomy/RV quantification and catheterisation for haemodynamics (Qp:Qs, PVR) or coronary anatomy.", tx: ["REFER all but simplest lesions to ACHD centre for MDT anatomy-specific planning; risk-stratify by lesion/ventricular function/PVR.","CLOSE significant L→R shunts (ASD/VSD/PDA) by device or surgery if RV overload/symptoms and PVR not prohibitive; NOT in established Eisenmenger.","RELIEVE obstructive/cyanotic lesions per anatomy — coarctation stent/surgery, tetralogy repair, pulmonary/aortic valve intervention; reintervene for residual gradient, significant regurgitation or RV–PA conduit dysfunction.","TREAT sequelae — arrhythmia (rate/rhythm control, ablation, anticoagulate atrial arrhythmia/intracardiac thrombus), heart failure (GDMT, diuretics); IE prophylaxis only high-risk (prosthetic valve/material, prior IE, unrepaired cyanotic, first 6mo post-repair with prosthetic material).","PAH/EISENMENGER: ERAs (bosentan/ambrisentan), PDE5 inhibitors, then prostacyclin analogues (avoid CCBs); correct iron deficiency, avoid volume depletion/routine venesection; pre-conception + mWHO joint ACHD-obstetric care; pregnancy contraindicated in severe PAH/Eisenmenger or severe left-heart obstruction; avoid ACE-I/ARBs and ERAs in pregnancy."], ix: ["Transthoracic echo + Doppler — lesion, shunt, chamber size, ventricular function, PA pressure","ECG — rhythm, conduction disease, chamber hypertrophy","Cardiac MRI (or CT) — complex anatomy, RV volume/function, aorta, conduits","CPET + pulse oximetry — functional capacity, cyanosis/desaturation","Cardiac catheterisation with Qp:Qs and PVR — haemodynamics before shunt closure or suspected PAH"], dispo: "Specialist ACHD centre with MDT (ACHD cardiologist, congenital surgeon/interventionalist, PAH and obstetric input); lifelong structured follow-up.", src: "Harrison 22e · 2020 ESC Guidelines for the management of adult congenital heart disease" },
    "aortic_regurgitation": { name: "Aortic Regurgitation", class: "non_infective", system: "Cardiology", dx: "TTE (Doppler) is the diagnostic standard—confirms the regurgitant jet, grades severity (vena contracta, regurgitant volume/fraction, ERO, holodiastolic descending-aortic flow reversal, pressure half-time) and quantifies LV size/function; suspect from an early diastolic decrescendo murmur at the left sternal edge with wide pulse pressure and water-hammer pulse, whereas acute severe AR causes sudden cardiogenic pulmonary oedema/shock with tachycardia and a soft, short murmur lacking these peripheral signs.", tx: ["ACUTE SEVERE AR (endocarditis/dissection/trauma)—surgical emergency: emergency valve ± aortic surgery; stabilise IV nitroprusside ± dobutamine; AVOID IABP (worsens AR); avoid beta-blockers (blunt compensatory tachycardia) except type-A dissection HR/BP/shear control under surgical guidance.","SURGICAL AVR/repair is definitive—refer if symptomatic (any LVEF, Class I), asymptomatic LVEF ≤55% (ACC/AHA 2020 Class I), or normal EF with marked LV dilatation (LVESD >50 mm or >25 mm/m², Class IIa).","AORTIC ROOT/ASCENDING DILATATION (Marfan/bicuspid)—replace aorta at guideline diameter thresholds even with only mild AR; beta-blocker and/or ARB (losartan) to slow aortic growth in connective-tissue disease.","MEDICAL THERAPY (no drug improves survival or reliably delays surgery)—asymptomatic preserved-LV: serial surveillance echo + treat coexistent HTN with dihydropyridine CCB or ACEi/ARB; HF awaiting/unfit for surgery: ACEi/ARB + diuretic for afterload/volume; TAVI only in selected inoperable patients (off-label, pure AR).","INFECTIVE ENDOCARDITIS—treat active IE promptly; prophylaxis only for high-risk (prosthetic valve/material, prior IE, specified congenital heart disease, transplant valvulopathy); native-valve AR alone does not warrant prophylaxis."], ix: ["TTE with Doppler—severity, LV dimensions/EF, aortic root.","ECG—LVH, strain, conduction disease.","CXR—cardiomegaly, aortic dilatation, pulmonary congestion.","Cardiac MRI or TOE if TTE inconclusive—quantify regurgitant fraction, image aortic root/valve morphology.","CT aortography + blood cultures if dissection/endocarditis suspected; coronary angiography pre-operatively."], dispo: "Refer cardiology; chronic asymptomatic AR—outpatient surveillance echo; acute severe AR—emergency admission for urgent cardiac surgery.", src: "Harrison 22e · ACC/AHA 2020 Valvular Heart Disease" },
    "bradyarrhythmias": { name: "Bradyarrhythmias & Heart Block", class: "non_infective", system: "Cardiology", dx: "12-lead ECG plus rhythm strip confirms bradycardia (<60/min) and localises the lesion (sinus node dysfunction vs AV block: first-degree, Mobitz I/II, high-grade, complete/third-degree with AV dissociation), correlating symptoms with rhythm and using ambulatory/implantable loop monitoring for intermittent cases.", tx: ["STOP culprit drugs (beta-blockers, non-DHP CCBs, digoxin, antiarrhythmics); correct hyperkalaemia/hypothyroidism/hypoxia; treat ischaemia/inferior MI; assess haemodynamic stability.","ATROPINE 0.5–1 mg IV q3–5 min (max 3 mg) first-line if unstable (hypotension/shock/altered mentation/ischaemic chest pain/acute HF), while preparing pacing.","ATROPINE-REFRACTORY: transcutaneous pacing ± dopamine or adrenaline infusion (isoprenaline alternative); bridge with transvenous temporary pacing.","ANTIDOTES: IV glucagon (beta-blocker OD), IV calcium ± high-dose insulin-euglycaemia (CCB OD), digoxin-specific antibody fragments (digoxin toxicity).","PERMANENT PACEMAKER (dual-chamber) for symptomatic irreversible SND or Mobitz II/high-grade/complete AV block; consider conduction-system (His/left-bundle) or CRT pacing if high pacing burden/LV dysfunction; monitor continuously + refer cardiology/EP per ACC/AHA/HRS device indications."], ix: ["12-lead ECG + continuous telemetry/rhythm strip","Ambulatory monitoring – Holter, external or implantable loop recorder for symptom–rhythm correlation","Electrolytes (K+, Ca2+, Mg2+), renal + thyroid function, drug/digoxin levels where relevant","Troponin + ischaemia workup if AV block acute (assess inferior MI)","Echocardiography for structural/ischaemic disease; EP study in selected cases"], dispo: "Unstable or high-grade/complete block – admit to monitored bed/CCU with pacing capability + urgent cardiology/EP referral; stable asymptomatic – outpatient cardiology review.", src: "Harrison 22e · ACC/AHA/HRS 2018 Bradycardia & Cardiac Conduction Delay Guideline" },
    "dilated_cardiomyopathy": { name: "Dilated Cardiomyopathy", class: "non_infective", system: "Cardiology", dx: "Confirm on TTE: LV dilatation + global systolic dysfunction (LVEF <45%) unexplained by loading/coronary disease; exclude ischaemia and reversible/secondary causes before labelling idiopathic or familial DCM.", tx: ["IV LOOP DIURETIC for congestion; correct precipitant/arrhythmia; avoid negative inotropes; reserve inotropes/vasopressors + MCS/transplant referral for cardiogenic shock.","GDMT for all HFrEF (LVEF ≤40%): ARNI (or ACEi/ARB if unsuitable) + beta-blocker + MRA + SGLT2i, uptitrate to target/max-tolerated; diurese to euvolaemia; add ivabradine (sinus ≥70 on max beta-blocker), hydralazine-nitrate (Black patients or RAASi-intolerant).","CORRECT reversible drivers: rate-control/ablate AF/tachyarrhythmia; alcohol/toxin abstinence; immunosuppression for giant-cell/eosinophilic myocarditis or cardiac sarcoid; replete iron/thyroid/thiamine.","DEVICES after ≥3 months optimal GDMT: ICD if LVEF ≤35% (NYHA II–III, survival >1yr); CRT if LVEF ≤35% + LBBB QRS ≥130 ms.","ANTICOAGULATE for AF, prior thromboembolism or LV thrombus; refer advanced-HF/transplant for refractory NYHA III–IV or inotrope dependence; offer family screening + genetic counselling in familial DCM."], ix: ["TTE – LV size, LVEF, wall motion, thrombus, valvular/RV function.","ECG – conduction disease/LBBB, arrhythmia, low voltages.","Bloods – FBC, U&E, LFTs, TFTs, ferritin/iron studies, glucose/HbA1c, BNP/NT-proBNP.","Coronary or CT coronary angiography to exclude ischaemic aetiology.","Cardiac MRI (fibrosis/infiltration/myocarditis) ± genetic testing/family screening if familial DCM suspected."], dispo: "Manage under cardiology/heart-failure service; admit if decompensated or in cardiogenic shock; early advanced-HF/transplant referral for refractory disease.", src: "Harrison 22e · ESC 2021/2023 Heart Failure Guidelines" },
    "mitral_regurgitation": { name: "Mitral Regurgitation", class: "non_infective", system: "Cardiology", dx: "Confirm with TTE — define mechanism (primary/degenerative vs secondary/functional), grade severity (vena contracta, EROA, regurgitant volume/fraction), quantify LV size/EF, LA size, pulmonary pressures (apical holosystolic murmur radiating to axilla); add TOE for repair feasibility/surgical planning.", tx: ["NITROPRUSSIDE + loop diuretic for acute severe MR (papillary/chordal rupture, IE); IABP if hypotensive; emergency surgery.","REPAIR (preferred over replacement) for primary severe symptomatic MR via Heart Team.","OPERATE primary severe asymptomatic MR if LVEF ≤60%, LVESD ≥40mm, new AF or PASP >50mmHg; else serial echo.","GDMT for secondary/functional MR (ACEi/ARB or ARNI, beta-blocker, MRA, SGLT2i, ±CRT); add TEER if still symptomatic on max therapy, suitable anatomy.","MANAGE AF: rate/rhythm control + anticoagulation; loop diuretics for congestion; no IE antibiotic prophylaxis unless prosthetic valve or prior IE."], ix: ["TTE — severity, mechanism, LV/LA dimensions, EF, PASP.","TOE — valve anatomy, repair feasibility pre-intervention.","ECG — AF, LA enlargement, LVH.","CXR — cardiomegaly, pulmonary congestion.","Coronary angiography pre-surgery; cardiac MRI or exercise echo if severity/symptoms discordant; NT-proBNP for monitoring."], dispo: "Cardiology + Heart Team for surgery/TEER; acute severe MR — urgent cardiac surgical centre.", src: "Harrison 22e · ESC/EACTS 2021 VHD" },
    "mitral_stenosis": { name: "Mitral Stenosis", class: "non_infective", system: "Cardiology", dx: "Rheumatic apical mid-diastolic rumble + loud S1 + opening snap; confirm on TTE (planimetry/pressure-half-time MVA, mean gradient, PA pressure) — severe MS = MVA ≤1.5 cm².", tx: ["RATE-CONTROL to prolong diastole: beta-blocker or non-DHP CCB; treat new AF; if unstable cardiovert, else anticoagulate + TEE-exclude thrombus before elective cardioversion.","LOOP DIURETIC + sodium restriction for pulmonary congestion.","ANTICOAGULATE with VKA (INR 2–3) for AF, prior embolism or LA thrombus; avoid DOACs in rheumatic MS.","PMBC first-line for symptomatic severe MS with favourable anatomy (Wilkins ≤8), no LA thrombus, ≤mild MR; SURGERY (repair/replacement) if anatomy unfavourable, PMBC contraindicated, or significant MR/concomitant valve disease.","SECONDARY PROPHYLAXIS long-acting penicillin; in pregnancy use beta-blockade + offer PMBC for refractory severe symptomatic MS."], ix: ["TTE — MVA, mean gradient, PASP, Wilkins/splittability score","ECG — atrial fibrillation, P mitrale, RV hypertrophy","CXR — LA enlargement, pulmonary venous congestion","TEE — exclude LA/appendage thrombus and grade MR pre-intervention","Exercise/stress echo when symptoms discordant with resting haemodynamics"], dispo: "Cardiology referral; symptomatic severe MS to structural/valve heart team for PMBC or surgery.", src: "Harrison 22e · ESC/EACTS" },
    "pericardial_disease": { name: "Pericardial Disease", class: "non_infective", system: "Cardiology", dx: "Clinical diagnosis needs ≥2 of 4 (ESC 2015): sharp pleuritic pain relieved by sitting forward, friction rub, widespread concave ST-elevation with PR depression, new/worsening effusion — echo confirms effusion/tamponade/constriction, raised CRP/ESR supports, troponin flags myopericarditis.", tx: ["TAMPONADE (hypotension, raised JVP, pulsus paradoxus) — urgent echo-guided pericardiocentesis; give IV fluids/volume; avoid vasodilators + diuretics (both cut preload).","HIGH-DOSE NSAID/ASPIRIN (taper over weeks) + COLCHICINE ×3mo (speeds resolution, cuts recurrence); add PPI, restrict exertion until CRP normalises; dose colchicine by weight (0.5mg od <70kg, bd ≥70kg), reduce/avoid in renal/hepatic impairment, beware CYP3A4/P-gp interactions (macrolides, statins, ciclosporin) → severe toxicity; myopericarditis: lower NSAID doses + stricter exercise restriction; caution NSAIDs/aspirin in renal impairment, PUD, HF, pregnancy.","RECURRENT / NSAID-contraindicated — add low–moderate CORTICOSTEROID + continue colchicine ≥6mo (avoid steroids first-line, they increase recurrence); colchicine-resistant → IL-1 blockade (anakinra/rilonacept).","TREAT CAUSE — TB (anti-TB + adjunctive corticosteroid), purulent (surgical/urgent drainage + IV antibiotics), uraemic (intensify dialysis), malignant, autoimmune.","CONSTRICTIVE → refer for pericardiectomy (trial anti-inflammatory first only if transient/inflammatory constriction suspected); monitor serial CRP + echo; refer cardiology for high-risk/recurrent/large effusive/constrictive disease."], ix: ["ECG — widespread concave ST-elevation + PR depression, evolving through stages","Echo (TTE) — effusion size, tamponade physiology, constriction","Markers — CRP, ESR, FBC, troponin (myopericarditis)","CXR — cardiomegaly/water-bottle silhouette, pulmonary/mediastinal cause","Aetiology — TB testing (endemic), autoimmune serology, blood cultures, renal function; cardiac MRI/CT + pericardial fluid analysis if cause unclear/constriction suspected"], dispo: "Low-risk uncomplicated → outpatient; admit if high-risk (fever >38°C, subacute onset, large effusion/tamponade, myopericarditis, immunosuppression, oral anticoagulation, or NSAID failure ~1 week); tamponade/constriction → urgent cardiology/cardiac surgery.", src: "Harrison 22e · ESC 2015 (pericardial diseases)" },
    "pulmonary_hypertension": { name: "Pulmonary Hypertension", class: "non_infective", system: "Cardiology / Pulmonary", dx: "Suspect on echo (raised TR jet velocity, RV dilatation/dysfunction, flattened septum) with exertional dyspnoea/fatigue; confirm and classify by right heart catheterisation — mPAP >20 mmHg, pre-capillary (PAWP ≤15 mmHg + PVR ≥2 WU) vs post-capillary.", tx: ["CLASSIFY WHO group before any drugs; refer Grp1 (PAH) + Grp4 (CTEPH) to expert PH centre; TREAT CAUSE — optimise left-heart (Grp2), long-term O2 for hypoxaemic lung disease (Grp3), where PAH drugs may harm.","GROUP 1 GENERAL — diuretics for RV overload, O2 if hypoxaemic, supervised exercise rehab, vaccinate; do acute vasoreactivity test (idiopathic/heritable/drug-induced) → high-dose CCB only if responder.","GROUP 1 TARGETED by risk — low/intermediate: upfront oral ERA (ambrisentan/macitentan) + PDE5i (tadalafil/sildenafil) or sGC riociguat (never with a PDE5i); high: add parenteral prostacyclin (epoprostenol/treprostinil); ± sotatercept add-on.","GROUP 4 CTEPH — lifelong anticoagulation + assess for pulmonary endarterectomy (potentially curative); if inoperable/residual → balloon pulmonary angioplasty and/or riociguat.","REASSESS risk every 3–6 months (WHO class, 6-min walk, NT-proBNP, echo/haemodynamics); lung transplant if progressive despite max therapy; pregnancy very high-mortality — advise against, avoid teratogenic ERAs/riociguat, manage at expert centre."], ix: ["TTE — TR jet velocity, RV size/function, estimated PASP, septal geometry","Right heart catheterisation — confirm mPAP >20 mmHg, PAWP, PVR; + acute vasoreactivity testing where indicated","V/Q scan to screen CTEPH (Grp4); CT pulmonary angiography to characterise","Bloods — NT-proBNP/BNP, CTD serology (ANA, anti-centromere, Scl-70), HIV, LFTs; ± thrombophilia screen","PFTs with DLCO, overnight oximetry/sleep study, HRCT chest — identify lung-disease/left-heart contributors"], dispo: "Refer to specialist PH centre for RHC, WHO-group classification and risk-based targeted therapy; ongoing care via MDT with regular risk reassessment.", src: "Harrison 22e · ESC/ERS 2022 PH guideline" },
    "cardiovascular_collapse_cardiac_arrest_and": { name: "Cardiovascular Collapse, Cardiac Arrest, and Sudden Cardiac Death", class: "non_infective", system: "cardiovascular", dx: "Clinical: unresponsive, absent central pulse, apnoea/agonal breathing — confirm ≤10 s and start CPR without awaiting tests; monitor rhythm classifies shockable (VF/pulseless VT) vs non-shockable (PEA/asystole) to direct the algorithm.", tx: ["CPR NOW — 100–120/min, depth 5–6 cm, full recoil, minimal interruptions, rotate q2min; activate team; airway without pausing compressions, O₂, IV/IO.","DEFIBRILLATE VF/pulseless VT immediately — biphasic 150–200 J (device-specific), resume CPR at once, repeat shock q2min if persistent.","ADRENALINE 1 mg q3–5min (ASAP in PEA/asystole; after 2nd shock AHA / 3rd shock ERC in refractory VF/pVT); AMIODARONE 300 then 150 mg (lidocaine 1–1.5 mg/kg alt); MAGNESIUM 2 g IV for torsades/polymorphic VT.","TREAT reversible causes throughout — 4 Hs (hypoxia, hypovolaemia, hypo-/hyperkalaemia/metabolic-acidosis, hypothermia); 4 Ts (tamponade, tension pneumothorax, toxins, thrombosis coronary/pulmonary).","POST-ROSC — 12-lead ECG, TTM 32–36°C (or fever avoidance/TTM2), avoid hyperoxia/hypocapnia (SpO₂ 94–98%), MAP ≥65, urgent angiography±PCI if STEMI/high cardiac suspicion, ICU; ICD if non-reversible arrest or LVEF ≤35% cardiomyopathy, beta-blocker+GDMT, treat substrate."], ix: ["Cardiac monitor/rhythm strip (shockable vs non-shockable); 12-lead ECG post-ROSC for STEMI/ischaemia.","ABG with electrolytes (K⁺, Mg²⁺, Ca²⁺), glucose, lactate; troponin.","Bedside echo — tamponade, RV strain (PE), LV function, cardiac standstill.","POC toxicology/coagulation and CXR as directed by suspected cause.","CT head/pulmonary post-ROSC where non-cardiac/embolic cause suspected."], dispo: "Resuscitate in situ, then ICU/CCU post-ROSC with early cardiology/electrophysiology referral for cause-directed workup and ICD assessment.", src: "Harrison 22e · AHA/ACC (ACLS 2020) · ERC 2021" },
    "amyloidosis_and_other_restrictive_cardiomy": { name: "Amyloidosis and Other Restrictive Cardiomyopathies", class: "non_infective", system: "Cardiovascular", dx: "Restrictive echo (non-dilated, impaired filling, preserved/mildly-low EF, biatrial enlargement, thick walls) + low-voltage ECG discordance + apical-sparing strain suggests cardiac amyloid; TYPE it - AL via serum free light chains + serum/urine immunofixation, ATTR non-invasively only if grade 2-3 uptake on 99mTc-PYP/DPD scintigraphy AND negative monoclonal screen, else endomyocardial biopsy (Congo red apple-green birefringence, mass-spec typing).", tx: ["TYPE FIRST - never assume ATTR; scintigraphy interpretable only if light-chain screen negative; confirm ATTRv vs ATTRwt by TTR gene test.","LOOP DIURETICS +/- MRA for congestion preserving preload; AVOID digoxin/CCBs (fibril binding, toxicity); use beta-blockers + ACEi/ARB cautiously (hypotension, fixed stroke volume).","ATTR-CM at amyloid centre - TTR STABILISER (tafamidis/acoramidis) or CM-approved silencer vutrisiran (HELIOS-B); patisiran approved only for hereditary ATTR polyneuropathy, not CM.","AL - URGENT HAEMATOLOGY: dara-CyBorD (daratumumab-bortezomib-cyclophosphamide-dexamethasone, ANDROMEDA) +/- autologous stem-cell transplant if eligible.","ANTICOAGULATE all AF (any CHA2DS2-VASc) + TEE for LAA/intracardiac thrombus pre-cardioversion; pace symptomatic conduction disease; consider ICD, heart (+/- liver for ATTRv) transplant in refractory cases; non-amyloid RCM - treat cause (sarcoid immunosuppression, haemochromatosis phlebotomy/chelation, Fabry enzyme replacement, Loffler/eosinophilic corticosteroids)."], ix: ["ECG - low QRS voltage, pseudo-infarct pattern, conduction disease.","TTE with global longitudinal strain - restrictive filling, thick walls, relative apical sparing ('cherry on top').","Serum free light chains + serum/urine immunofixation - exclude/confirm AL (must be negative to call ATTR non-invasively).","99mTc-PYP/DPD/HMDP scintigraphy - Perugini grade 2-3 uptake + negative monoclonal screen confirms ATTR-CM.","Cardiac MRI (diffuse subendocardial/transmural LGE, raised native T1/ECV) + NT-proBNP + troponin for staging; endomyocardial biopsy if non-invasive workup inconclusive/equivocal."], dispo: "Refer to specialist cardiac amyloidosis/cardiomyopathy centre; AL needs urgent haematology co-management.", src: "Harrison 22e - ESC 2023 Cardiomyopathies; Gillmore non-invasive ATTR criteria; ANDROMEDA/ATTR-ACT/ATTRibute-CM/HELIOS-B" },
    "atrial_myxoma_and_other_cardiac": { name: "Atrial Myxoma and Other Cardiac Tumors", class: "non_infective", system: "Cardiovascular", dx: "TTE first-line, plus TOE (size/attachment/mobility) and cardiac MRI (tissue characterisation, benign myxoma vs malignant); definitive diagnosis histological after resection.", tx: ["URGENT CARDIOTHORACIC EXCISION — complete resection first-line/curative for atrial myxoma with interatrial-septum margin + defect repair; do not delay (embolic/obstructive risk); recurrence <5% sporadic, higher familial/Carney.","STABILISE complications — treat HF/pulmonary oedema (mitral-inflow obstruction) and manage systemic/cerebral embolism via stroke pathway; anticoagulation does NOT replace excision.","EXCISE papillary fibroelastoma/other benign tumours if left-sided, mobile or symptomatic (embolic risk); survey small asymptomatic right-sided lesions.","RESECT angiosarcoma/malignant tumours where feasible + adjuvant chemo/radiotherapy via cardio-oncology MDT (largely palliative); metastatic — treat primary, drain symptomatic pericardial effusion/tamponade.","SCREEN Carney complex (PRKAR1A) if young/multiple/recurrent/familial — genetic counselling, first-degree-relative echo surveillance, lifelong post-op surveillance echo."], ix: ["TTE — first-line imaging","TOE — size, attachment, mobility","Cardiac MRI — tissue characterisation, benign vs malignant","Bloods: FBC (anaemia), ESR/CRP, IL-6 (raised in myxoma)","Histology of resected specimen — definitive diagnosis"], dispo: "Urgent cardiology + cardiothoracic surgery referral; manage in a centre with advanced cardiac imaging and cardiac surgical capability.", src: "Harrison 22e · ESC/EACVI multimodality imaging of cardiac masses consensus" },
    "cardiac_transplantation_and_prolonged_assi": { name: "Cardiac Transplantation and Prolonged Assisted Circulation", class: "non_infective", system: "Cardiovascular", dx: "Therapeutic pathway (not one diagnosis) for stage D/end-stage HF refractory to optimal medical therapy — confirm advanced HF by persistent NYHA III–IV, recurrent decompensations or inotrope dependence, peak VO2 <12–14 mL/kg/min on CPET, and elevated filling pressures on right-heart cath, with transplant/MCS candidacy decided at a multidisciplinary advanced-HF unit.", tx: ["STABILISE refractory HF — IV loop diuretics + inotropes (dobutamine/milrinone), treat precipitants; escalate shock to temporary MCS (IABP/Impella/VA-ECMO) as bridge-to-decision.","REFER early to advanced-HF/transplant centre; screen contraindications (fixed pulmonary HTN, active infection/malignancy, irreversible multi-organ disease, non-adherence, substance misuse).","DURABLE continuous-flow LVAD for bridge-to-transplant/candidacy or destination — warfarin + antiplatelet, surveil driveline infection and pump thrombosis.","ORTHOTOPIC HEART TRANSPLANT is definitive if eligible — induction then lifelong CNI (tacrolimus/ciclosporin) + mycophenolate + tapering corticosteroid.","TREAT REJECTION promptly — pulsed steroids ±ATG (cellular), IVIG/plasmapheresis/rituximab (antibody); prophylax PCP co-trimoxazole + CMV antiviral + antifungal; surveil biopsy/gene-profiling, manage CAV (statin ±mTOR inhibitor), CNI nephrotoxicity, HTN, diabetes, malignancy/PTLD."], ix: ["CPET peak VO2 — quantify functional impairment and prognosis.","Right-heart catheterisation — PVR, transpulmonary gradient, vasodilator reversibility.","Echocardiography ± coronary angiography — structure/function, reversible causes.","Immunology — ABO/HLA typing, panel-reactive antibody; virology (CMV, EBV, hepatitis, HIV).","End-organ/comorbidity — renal/hepatic function, PFTs, infection/malignancy screen."], dispo: "Manage at specialist advanced-HF/transplant and mechanical-circulatory-support centre with lifelong multidisciplinary follow-up.", src: "Harrison 22e · ISHLT" },
    "cardiac_trauma": { name: "Cardiac Trauma", class: "non_infective", system: "Cardiovascular", dx: "Confirm with focused echo (subxiphoid/FAST) showing pericardial blood, wall-motion abnormality or structural lesion, plus 12-lead ECG and troponin; Beck's triad (hypotension, muffled sounds, raised JVP) with penetrating precordial wound = tamponade until proven otherwise.", tx: ["RESUSCITATE per ATLS: high-flow O2, 2 large-bore IVs, blood/balanced crystalloid (favour blood, permissive hypotension until haemorrhage control), continuous ECG + haemodynamic monitoring.","THORACOTOMY/STERNOTOMY immediately for penetrating tamponade or peri-arrest with surgical repair; do not delay for imaging.","PERICARDIOCENTESIS (echo-guided) temporises relatively stable tamponade; surgery is definitive (traumatic hemopericardium clots).","BLUNT contusion: telemetry >=24-48h, treat arrhythmias, inotropes/mechanical support for cardiogenic shock; avoid IABP if coexisting traumatic aortic injury.","SURGERY urgent for structural lesions (septal/valve/free-wall rupture, coronary dissection); COMMOTIO CORDIS - immediate CPR + defibrillation."], ix: ["12-lead ECG - sinus tachycardia commonest; also arrhythmia, ST-T change, new RBBB","Cardiac troponin I/T","Focused echo (TTE/TEE) or FAST subxiphoid - pericardial fluid, wall motion, valve/septal injury","CXR - widened mediastinum, haemo/pneumothorax, enlarged cardiac silhouette","CT chest/aortic angiography if haemodynamically stable - exclude great-vessel injury"], dispo: "Trauma centre/ICU with continuous telemetry; immediate cardiothoracic/trauma surgery for penetrating injury, tamponade or structural damage.", src: "Harrison 22e · EAST" },
    "common_atrial_flutter_and_macroreentrant": { name: "Common Atrial Flutter and Macroreentrant and Multifocal Atrial Tachycardias", class: "non_infective", system: "Cardiovascular", dx: "12-lead ECG diagnostic: typical CTI-dependent flutter = sawtooth waves negative in II/III/aVF at ~300/min with 2:1 conduction (rate ~150), while MAT = >=3 P-wave morphologies with varying P-P/P-R/R-R and atrial rate >100/min (vagal/adenosine unmask but do not terminate).", tx: ["UNSTABLE (hypotension/ischaemia/pulmonary oedema) -> immediate synchronised DC cardioversion; flutter often converts at ~50 J.","RATE CONTROL flutter (often resistant): IV then oral beta-blocker or non-DHP CCB (diltiazem/verapamil).","ANTICOAGULATE per CHA2DS2-VASc; >=3wk anticoag or TOE pre-elective cardioversion, continue >=4wk after.","CTI ABLATION first-line for typical flutter (>90% success); or ibutilide/dofetilide cardioversion under ECG/QT monitoring (torsades; dofetilide renal-dose).","MAT: treat cause (hypoxia/COPD/sepsis), correct K+/Mg2+, stop theophylline; rate-control verapamil/diltiazem or cautious cardioselective metoprolol (avoid non-selective in bronchospasm) - DC cardioversion/digoxin useless. Refer EP for atypical/recurrent flutter ablation."], ix: ["12-lead ECG (diagnostic: flutter waves vs >=3 P-morphologies), rhythm strip during vagal/adenosine if uncertain","Serum electrolytes (K+, Mg2+, Ca2+) and renal function","Thyroid function tests","Transthoracic echo - structural disease, LA size, LV function","TOE before early cardioversion; ABG/CXR for pulmonary precipitants in MAT"], dispo: "Unstable -> resus area with continuous cardiac monitoring; stable -> cardiology/EP referral for anticoagulation decision and catheter ablation.", src: "Harrison 22e | ESC 2019 SVT guideline" },
    "diseases_of_the_aorta": { name: "Diseases of the Aorta", class: "non_infective", system: "Cardiovascular", dx: "Whole-aorta CT angiography is reference test for acute aortic syndromes and aneurysm sizing; TOE confirms type A dissection when unstable/contrast-contraindicated; abdominal US for AAA screening, MRA for radiation-sparing follow-up.", tx: ["Suspected acute aortic syndrome/dissection — RESUSCITATE: large-bore IV, opioid analgesia, group-and-crossmatch; expedite whole-aorta CT angiography.","IV BETA-BLOCKER first (labetalol/esmolol) to HR<60, then vasodilator (GTN/nitroprusside) targeting SBP 100-120; never vasodilator alone (reflex tachycardia worsens shear).","TYPE A (ascending) or ruptured aneurysm — emergency OPEN SURGICAL REPAIR; immediate cardiothoracic/vascular referral.","TYPE B (descending) uncomplicated — medical anti-impulse + surveillance; TEVAR if complicated (malperfusion, rupture, refractory pain/HTN).","ELECTIVE REPAIR (open/EVAR/TEVAR) at AAA >=5.5cm men />=5.0cm women, ascending TAA >=5.5cm (>=4.5-5.0cm Marfan/bicuspid/heritable), growth >0.5cm/yr, or symptoms; long-term strict BP control (beta-blocker; losartan/ARB in Marfan), high-intensity statin, smoking cessation, serial imaging."], ix: ["Whole-aorta CT angiography (dissection/aneurysm; gold standard)","TTE +/- TOE (proximal dissection, aortic root/valve, pericardial effusion)","Abdominal aortic ultrasound (AAA detection/surveillance)","ECG and troponin (concurrent MI; coronary ostial involvement)","High-sensitivity D-dimer with ADD-RS rule-out; FBC, U&E, CRP/ESR (aortitis)"], dispo: "Acute aortic syndrome/ruptured aneurysm — emergency admission with immediate cardiothoracic/vascular referral; stable aneurysm — vascular surgery outpatient surveillance.", src: "Harrison 22e · ACC/AHA 2022 Aortic Disease Guideline · ESC 2024" },
    "electrical_storm_and_incessant_ventricular": { name: "Electrical Storm and Incessant Ventricular Tachycardia", class: "non_infective", system: "Cardiovascular", dx: "Electrical storm = ≥3 discrete sustained VT/VF or appropriate ICD therapies within 24 h (or haemodynamically-tolerated VT recurring ≥12 h despite repeated termination = incessant VT); interrogate ICD to confirm true arrhythmia vs inappropriate shocks/oversensing and define morphology (monomorphic vs polymorphic).", tx: ["DEFIBRILLATE per ACLS — shock VF/pulseless VT, synchronised DC cardioversion for unstable VT; secure airway + continuous monitoring.","CORRECT reversible triggers — replete K+/Mg2+; treat ischaemia and decompensated HF; withdraw proarrhythmic/QT-prolonging drugs.","IV AMIODARONE + beta-blockade (propranolol or titratable IV esmolol) beats amiodarone alone; in acquired long-QT torsades avoid amiodarone/QT-prolonging agents — use polymorphic pathway.","BLUNT sympathetic drive — propofol sedation, intubate if refractory, escalate to stellate ganglion block/thoracic epidural or cardiac sympathetic denervation; reprogramme ICD (extend detection, enable ATP, minimise shocks); overdrive pace or isoprenaline + IV magnesium for pause-dependent polymorphic VT/torsades.","REFRACTORY — urgent catheter ablation for scar monomorphic VT, Impella/VA-ECMO bridge, transfer to EP centre; substrate: monomorphic scar (amiodarone/ablation), polymorphic/torsades (magnesium, pacing/isoprenaline, correct QT), channelopathy (Brugada isoprenaline/quinidine; CPVT beta-blocker + flecainide)."], ix: ["12-lead ECG + continuous telemetry + full ICD interrogation (episode count, morphology, delivered therapies)","Serum K+/Mg2+/Ca2+, renal function ± ABG","Troponin + ischaemia workup; coronary angiography if ischaemia suspected","Echocardiography — LV function + structural substrate","TSH, toxicology/drug levels; review QT-prolonging meds"], dispo: "Admit CCU/ICU on continuous monitoring; urgent cardiology/EP referral and early transfer to ablation + mechanical-support centre.", src: "Harrison 22e · ESC 2022 (Ventricular Arrhythmias/SCD)" },
    "focal_atrial_tachycardia": { name: "Focal Atrial Tachycardia", class: "non_infective", system: "Cardiovascular", dx: "Regular narrow-complex SVT (~100–250/min) with non-sinus P-wave morphology and isoelectric baseline between P waves (distinguishing from flutter) plus common warm-up/cool-down; adenosine/vagal causes transient AV block exposing atrial activity without terminating, confirmed on EP study with atrial activation/3D mapping.", tx: ["UNSTABLE: immediate synchronised DC cardioversion (automatic foci often resistant); if stable, vagal/IV adenosine to unmask atrial activity (terminates a minority).","ACUTE control: IV beta-blocker or non-DHP CCB (verapamil/diltiazem); escalate to IV flecainide/propafenone or amiodarone if refractory.","CATHETER ABLATION: definitive first-line for recurrent/incessant/tachycardiomyopathy-causing AT (ESC Class I).","CHRONIC (ablation declined/unsuitable): beta-blocker or verapamil/diltiazem (IIa); add flecainide/propafenone only if no structural/ischaemic disease; avoid digoxin, sotalol, amiodarone, disopyramide.","PREGNANCY: metoprolol (beta-1-selective) or verapamil first-line, flecainide/propafenone if needed, defer ablation (fluoroless if unavoidable); correct electrolytes, thyroid, digoxin toxicity."], ix: ["12-lead ECG in tachycardia and sinus — P-wave axis/morphology localises focus","Ambulatory/Holter or event monitor for paroxysms and burden","TTE — structural disease and LV function (tachycardiomyopathy)","Bloods — electrolytes, magnesium, TFTs, digoxin level where relevant","EP study with 3D activation mapping — diagnostic and therapeutic"], dispo: "Outpatient cardiology; refer to electrophysiology for ablation if recurrent/incessant/tachycardiomyopathy — admit if haemodynamically unstable.", src: "Harrison 22e · ESC (2019 SVT)" },
    "genetic_cardiomyopathies": { name: "Genetic Cardiomyopathies", class: "non_infective", system: "Cardiovascular", dx: "Confirm phenotype (hypertrophic, dilated/non-dilated LV, arrhythmogenic RV/biventricular, restrictive) by echo plus cardiac MRI-LGE, ECG and 3-generation pedigree; establish genetics via proband gene-panel in a multidisciplinary inherited-cardiac-conditions service, then cascade-screen first-degree relatives.", tx: ["STABILISE decompensation/arrhythmia, then treat by phenotype; dilated/non-obstructive HFrEF → full GDMT (ARNI or ACEi/ARB, beta-blocker, MRA, SGLT2i); AVOID vasodilators/nitrates, aggressive diuresis, digoxin in OBSTRUCTIVE HCM (worsen LVOT obstruction).","OBSTRUCTIVE HCM negative inotropes: non-vasodilating beta-blocker first-line; verapamil if ineffective/intolerant (caution/avoid severe resting gradient, hypotension, decompensated HF); disopyramide add-on to BB/verapamil (not monotherapy); add mavacamten (serial LVEF/echo, CYP2C19, teratogenic); septal myectomy (preferred) or alcohol septal ablation if drug-refractory.","RISK-STRATIFY SCD (LGE burden, HCM Risk-SCD score, gene/phenotype models: LMNA, ARVC, FLNC/PLN/DSP); ICD for ALL secondary prevention (prior arrest/sustained VT) and high primary-prevention risk, lower thresholds in ARVC/LMNA.","TREAT arrhythmia — beta-blockers/antiarrhythmics + catheter ablation as indicated; anticoagulate AF in HCM regardless of CHA2DS2-VASc (DOAC preferred); strict NO competitive/endurance sport in ARVC (accelerates disease), HCM/others allow recreational + selected competitive after full evaluation + shared decision-making.","GIVE phenocopy therapy (enzyme replacement/migalastat in Fabry, tafamidis in hereditary ATTR amyloidosis); refer genetic counselling + cascade family screening; assess advanced HF for transplant/LVAD; pre-pregnancy counselling (high risk LMNA, peripartum, desmosomal) — ARNI/ACEi/ARB, MRA, SGLT2i, mavacamten contraindicated in pregnancy."], ix: ["ECG — LVH, low voltage/conduction disease, epsilon waves, T-wave inversion.","Echocardiography — hypertrophy, dilatation, LVOT gradient (rest + provoked), diastolic function.","Cardiac MRI with LGE + T1 mapping — fibrosis, tissue characterisation, phenocopy detection.","Proband genetic testing + 3-generation pedigree in inherited-cardiac-conditions service.","Holter for arrhythmia/SCD risk; NT-proBNP/troponin; exercise testing where indicated."], dispo: "Specialist multidisciplinary inherited-cardiac-conditions/cardiomyopathy clinic with genetic counselling; advanced HF unit for device/transplant assessment.", src: "Harrison 22e; ESC 2023 (Cardiomyopathies); AHA/ACC 2024 (HCM)" },
    "heart_failure_management": { name: "Heart Failure: Management", class: "non_infective", system: "Cardiovascular", dx: "Syndrome of dyspnoea, fatigue and fluid retention with objective cardiac dysfunction — confirm via raised BNP/NT-proBNP and transthoracic echo, classify by LVEF (HFrEF <=40%, HFmrEF 41-49%, HFpEF >=50%), and establish aetiology plus decompensation precipitant.", tx: ["ACUTE DECOMPENSATION: sit upright; O2/NIV only if SpO2<90%; IV loop diuretic (furosemide) for congestion; IV nitrate if hypertensive/flash pulmonary oedema (avoid if hypotensive); reserve inotropes/vasopressors + mechanical-support referral for cardiogenic shock; do NOT start/up-titrate beta-blocker while decompensated.","HFrEF once stabilised: start quadruple GDMT — ARNI (or ACEi/ARB) + beta-blocker + MRA + SGLT2i, up-titrate to target/max-tolerated; beta-blocker only when euvolaemic and haemodynamically stable; 36-h washout switching ACEi->ARNI (angioedema); never combine ACEi with ARB or ARNI.","ADD loop diuretic for congestion; if still symptomatic add ivabradine (sinus rhythm, resting HR>=70 on max-tolerated beta-blocker), hydralazine-nitrate (esp. Black or ACEi/ARB-intolerant), digoxin (narrow TI — reduce/monitor in renal impairment/elderly), or vericiguat.","DEVICES: ICD if LVEF<=35% despite >=3mo optimal therapy (Class I ischaemic, IIa non-ischaemic); CRT if LVEF<=35% + LBBB + QRS>=130ms (strongest >=150ms); refractory HF -> refer LVAD/transplant. HFpEF/HFmrEF: SGLT2i for all + diuretic for congestion; treat hypertension/AF/comorbidities.","MONITOR U&E/eGFR + K+ after each start/up-titration (hyperkalaemia with ARNI/ACEi+MRA); salt/fluid moderation, daily weights, treat precipitants, vaccinate, cardiac rehab; anticoagulate if AF (CHA2DS2-VASc), correct iron deficiency. PREGNANCY: ACEi/ARB/ARNI, MRA, SGLT2i, ivabradine, vericiguat teratogenic/contraindicated — suspected peripartum cardiomyopathy needs cardio-obstetric specialist using pregnancy-safe agents (beta-blocker, hydralazine-nitrate, loop diuretic; consider bromocriptine)."], ix: ["BNP or NT-proBNP","12-lead ECG","Transthoracic echo — LVEF, chamber size, valves, diastolic function","Bloods — FBC, U&E/eGFR, LFTs, TFTs, glucose/HbA1c, iron studies (ferritin + transferrin saturation)","CXR; consider coronary angiography/CT coronary and cardiac MRI if aetiology unclear"], dispo: "Acute pulmonary oedema/cardiogenic shock — admit (HDU/CCU); stable chronic HF — specialist HF clinic for GDMT up-titration and multidisciplinary follow-up.", src: "Harrison 22e · ESC 2021 (2023 focused update) Heart Failure Guidelines" },
    "heart_failure_pathophysiology_and_diagnosi": { name: "Heart Failure: Pathophysiology and Diagnosis", class: "non_infective", system: "Cardiovascular", dx: "Congestion/hypoperfusion syndrome (dyspnoea, orthopnoea, PND, raised JVP, S3, basal crepitations, oedema) with elevated BNP/NT-proBNP, confirmed on echo defining LVEF/phenotype (HFrEF <=40%, HFmrEF 41-49%, HFpEF >=50%), plus aetiology (ischaemic/hypertensive/valvular/cardiomyopathy/arrhythmic).", tx: ["STABILISE decompensation: sit upright, O2/NIV if hypoxic, IV furosemide for congestion, IV nitrate if hypertensive/flash oedema; inotropes/vasopressors only for hypoperfusion/cardiogenic shock.","TREAT CAUSE + precipitants: revascularise ischaemia, control BP/rate, anticoagulate AF per stroke risk, correct valve disease, arrhythmia, anaemia, thyroid, non-adherence.","HFrEF FOUR PILLARS: start+up-titrate ARNI (or ACEi/ARB), beta-blocker, MRA, SGLT2i to target/max-tolerated; add loop diuretic, ivabradine if sinus >=70 on max BB (LVEF <=35%), hydralazine-nitrate (Black/ACEi-ARB-intolerant), IV iron if deficient.","HFpEF/HFmrEF: SGLT2i for all, diuretic for congestion, aggressively control HTN/AF/comorbidities; MRA + ARNI benefit at lower-EF ranges.","DEVICES/ADVANCED: ICD if LVEF <=35% after >=3mo optimal Rx (NYHA II-III, survival >1yr, any QRS); CRT if LVEF <=35% + LBBB + QRS >=130ms (Class I >=150ms) sinus; refractory to transplant/LVAD; monitor U&E/eGFR/K+/weight/rhythm; pregnancy avoid ACEi/ARB/ARNI/MRA/SGLT2i/ivabradine."], ix: ["Natriuretic peptides (BNP/NT-proBNP) - diagnosis, rule-out, prognosis.","TTE - LVEF, chamber size, wall motion, valves, diastolic function.","ECG (ischaemia, LBBB, AF, LVH) + CXR (cardiomegaly, congestion, effusions).","Bloods - FBC, U&E/eGFR, LFTs, glucose/HbA1c, TFTs, ferritin/transferrin sat, troponin.","Aetiology - coronary angio/CTCA or ischaemia testing; cardiac MRI if infiltrative/inflammatory cardiomyopathy suspected."], dispo: "Confirm on echo, refer cardiology/HF clinic; admit acute decompensation, cardiogenic shock or refractory disease.", src: "Harrison 22e; ESC 2021/2023 Heart Failure Guidelines" },
    "ischemic_heart_disease": { name: "Ischemic Heart Disease", class: "non_infective", system: "Cardiovascular", dx: "Typical exertional angina plus objective ischaemia — resting/exercise ECG, stress imaging (echo/MPI/CMR) or CT coronary angiography (first-line anatomical test; invasive angiography if high-risk/refractory) — guided by pre-test probability, with serial ECG+troponin if acute to exclude ACS.", tx: ["RULE OUT ACS FIRST: acute ischaemic pain → aspirin 300 mg + serial ECG/troponin; primary PCI for STEMI, early invasive for high-risk NSTE-ACS.","RISK-FACTOR CONTROL: stop smoking, Mediterranean diet, activity, optimise weight/BP, glycaemic control in diabetes.","ANTIANGINAL: beta-blocker or dihydropyridine CCB (combine if needed; AVOID non-DHP CCB + beta-blocker) + short-acting nitrate; if refractory add long-acting nitrate, ivabradine, ranolazine or nicorandil.","SECONDARY PREVENTION: high-intensity statin (LDL <1.4 mmol/L and >=50% reduction; add ezetimibe/PCSK9i if unmet) + aspirin 75-100 mg (clopidogrel if intolerant) + ACE-I/ARB if diabetes/HF/HTN/CKD.","REVASCULARISE (PCI/CABG; CABG favoured for left main or multivessel with LV dysfunction/diabetes) if symptoms persist despite OMT or high-risk anatomy; refer cardiology + rehab, annual flu vaccine, monitor symptoms/lipids/renal/BP/adherence."], ix: ["Resting + exercise/stress 12-lead ECG","Serial troponin if acute (exclude ACS)","CT coronary angiography or stress imaging (echo/MPI/CMR)","Transthoracic echo for LV function/structure","Bloods: fasting lipids, HbA1c/glucose, FBC, U&E/eGFR, TFTs"], dispo: "Outpatient cardiology + cardiac rehab if stable; immediate transfer to PCI-capable centre if ACS suspected.", src: "Harrison 22e · ESC (Chronic Coronary Syndromes 2024)" },
    "mitral_valve_prolapse": { name: "Mitral Valve Prolapse", class: "non_infective", system: "Cardiovascular", dx: "TTE: systolic displacement of ≥1 mitral leaflet ≥2 mm above the annular plane on parasternal long-axis ± leaflet thickening (>5 mm = classic/myxomatous); clinical clue = mid-systolic click ± late-systolic murmur moving earlier/louder with standing/Valsalva (reduced preload).", tx: ["REASSURE asymptomatic MVP with no/trivial MR: no drugs or activity limits; periodic clinical + echo surveillance.","BETA-BLOCKER for palpitations/atypical chest pain/anxiety; optimise hydration/volume for orthostatic/autonomic symptoms.","SURGERY for severe primary MR — repair > replacement at experienced Heart Valve centre; refer when symptomatic, or asymptomatic with LVEF ≤60%, LVESD ≥40 mm, new AF, or PASP >50 mmHg.","RATE-CONTROL + ANTICOAGULATE for AF or prior embolism/stroke per AF stroke-prevention pathway.","NO routine endocarditis prophylaxis — reserve for prior IE or prosthetic/repaired valve material; counsel dental/skin hygiene."], ix: ["TTE with Doppler — confirm prolapse, quantify MR, LV size/EF, PASP.","ECG — rhythm, AF, repolarisation/QT, ventricular ectopy.","TOE — define leaflet/scallop anatomy + repairability pre-surgery.","Ambulatory Holter/event monitor — palpitations or suspected arrhythmia.","Exercise/stress echo — symptoms discordant with resting MR, or to assess exertional PASP."], dispo: "Primary care/cardiology outpatient with echo surveillance; refer to specialist Heart Valve/cardiac surgery centre when severe MR or surgical triggers met.", src: "Harrison 22e · ESC/EACTS 2021 Valvular Heart Disease" },
    "multiple_and_mixed_valvular_heart": { name: "Multiple and Mixed Valvular Heart Disease", class: "non_infective", system: "Cardiovascular", dx: "TTE with Doppler to grade each lesion (severity, mechanism, chamber size, LV/RV function, pulmonary pressures) and identify the haemodynamically dominant one, integrating symptoms/signs/haemodynamics since combined lesions distort severity indices and mask each other.", tx: ["GRADE every lesion; treat the haemodynamically dominant one, not each valve alone — combined loads shift severity thresholds/signs.","SUPPORTIVE meds only — diuretics, rate control, AF anticoagulation; VKA (warfarin) NOT DOAC if significant MS/mechanical prosthesis; add HF therapy per LVEF; cautious vasodilators/aggressive diuresis if significant AS; no drug corrects mechanical valve disease.","INTERVENE for mixed stenosis+regurgitation or several moderate lesions when any component is severe, or combined burden causes symptoms/LV dysfunction though none individually 'severe'; beware low-flow under-grading a tight stenosis.","REPAIR/REPLACE as definitive treatment — multivalve usually favours combined surgery; staged/transcatheter (TAVI, transcatheter mitral/tricuspid repair, balloon valvotomy) for selected high-risk patients.","FIX significant secondary TR/dilated annulus during left-sided surgery; refer early to multidisciplinary Heart Valve Team; lifelong VKA (warfarin) for mechanical prostheses; endocarditis prophylaxis where indicated."], ix: ["TTE with Doppler — grade each lesion, chamber size, LV/RV function, pulmonary artery pressure","TOE — mechanism/repairability, prosthesis assessment, exclude LA thrombus before valvotomy","ECG (AF, hypertrophy) and chest radiograph (chamber enlargement, pulmonary congestion)","Coronary or CT coronary angiography pre-surgery; cardiac CT for annular sizing/TAVI planning","Exercise testing and BNP/NT-proBNP where symptom status or lesion severity discordant"], dispo: "Refer to cardiology/multidisciplinary Heart Valve Team; surgical or transcatheter intervention at a valve centre.", src: "Harrison 22e · ESC/EACTS 2021 valvular heart disease (AHA/ACC 2020 concordant)" },
    "paroxysmal_supraventricular_tachycardias": { name: "Paroxysmal Supraventricular Tachycardias", class: "non_infective", system: "Cardiovascular", dx: "Regular narrow-complex tachycardia (~150–250/min) on 12-lead ECG; P-wave relationship separates AVNRT (pseudo-r'/pseudo-S, RP<70ms) from AVRT (retrograde P after QRS) and atrial tachycardia—confirm mechanism by vagal/adenosine response and capture sinus-rhythm ECG for pre-excitation (delta wave, WPW).", tx: ["UNSTABLE (hypotension/ischaemia/pulmonary oedema/altered mentation): immediate synchronised DC CARDIOVERSION.","STABLE—VAGAL first: modified Valsalva (legs-raised)/carotid massage (avoid bruit, recent stroke/TIA); then ADENOSINE IV push+flush 6→12mg (unmasks flutter/AT).","SECOND-LINE: IV VERAPAMIL/DILTIAZEM (avoid HFrEF/hypotension) or beta-blocker; pre-excited WPW-AF—use PROCAINAMIDE/IBUTILIDE or DC, avoid AV-nodal blockers.","ABLATION definitive (first-line curative, recurrent AVNRT/AVRT); chronic prophylaxis beta-blocker/non-DHP CCB or flecainide/propafenone if structurally normal heart.","PREGNANCY: vagal then adenosine first-line, metoprolol (beta-1 selective) prophylaxis, defer ablation; overt WPW+syncope/pre-excited AF → early EP referral."], ix: ["12-lead ECG in tachycardia + sinus rhythm (assess pre-excitation)","Holter/event monitor if paroxysms undocumented","Electrolytes, magnesium, TSH","Transthoracic echo to exclude structural heart disease","Electrophysiology study (diagnostic + therapeutic ablation)"], dispo: "Acute episode via ED/monitored bed; recurrent or pre-excited PSVT → cardiology/EP referral for ablation.", src: "Harrison 22e · 2019 ESC SVT" },
    "polymorphic_ventricular_tachycardia_and_ve": { name: "Polymorphic Ventricular Tachycardia and Ventricular Fibrillation", class: "non_infective", system: "Cardiovascular", dx: "Confirm on 12-lead ECG/telemetry: polymorphic VT = continuously varying QRS morphology/axis, torsades = polymorphic VT on a prolonged QT twisting around baseline, VF = chaotic deflections without organised QRS; pulseless polymorphic VT/VF is a cardiac-arrest rhythm.", tx: ["DEFIBRILLATE (unsynchronised) pulseless or unstable polymorphic VT/VF; high-quality CPR, repeat shock q2min, adrenaline 1mg IV q3–5min.","AMIODARONE 300mg IV (or lidocaine) after 3rd shock; dual-sequence/left-lateral pads; treat reversible causes (ischaemia, hypoxia, electrolytes).","REPLETE K⁺/Mg²⁺ (target K⁺ ~4.5–5.0); IV MAGNESIUM first-line for torsades/acquired long-QT; stop QT-prolonging drugs; revascularise if ischaemic; raise rate via isoprenaline/overdrive pacing (isoprenaline contraindicated in congenital LQTS or ischaemia).","BETA-BLOCK electrical storm (IV esmolol/propranolol) ± amiodarone + deep sedation; escalate to IABP/VA-ECMO, stellate-ganglion block, catheter ablation of triggering PVCs.","ICD once stable for VF/unstable-VT survivors (unless fully reversible cause); treat underlying disease, beta-blocker ± flecainide (flecainide only CPVT/channelopathy, not structural/ischaemic), genetic testing for CPVT/inherited channelopathy."], ix: ["12-lead ECG (QTc, ischaemia, Brugada/QT pattern) + continuous telemetry","Electrolytes K⁺/Mg²⁺/Ca²⁺ with renal and thyroid function","Serial troponin + 12-lead for acute ischaemia; urgent coronary angiography if indicated","Echocardiography for structural disease/LV function; cardiac MRI where cause unclear","Medication/toxicology review + genetic testing for suspected LQTS/CPVT/Brugada"], dispo: "Resuscitate in situ, then admit CCU/ICU under cardiology/electrophysiology; refer for ICD and inherited-arrhythmia/genetic evaluation.", src: "Harrison 22e · ESC 2022 Ventricular Arrhythmias & Sudden Cardiac Death · AHA ACLS" },
    "premature_ventricular_contractions_nonsust": { name: "Premature Ventricular Contractions, Nonsustained Idioventricular Rhythm", class: "non_infective", system: "Cardiovascular", dx: "PVCs are wide (>120 ms) premature beats with a full compensatory pause, while AIVR is a regular wide-complex rhythm at 40–120/min near sinus rate with gradual onset/offset and fusion/capture beats; quantify burden/morphology on 24–48 h Holter.", tx: ["OBSERVE AIVR (reperfusion/post-MI): benign, self-limiting, no antiarrhythmic; if lost AV synchrony compromises hemodynamics give ATROPINE — never suppress the escape rhythm.","REASSURE asymptomatic low-burden PVCs with normal heart; withdraw triggers (caffeine, alcohol, stimulants); correct hypokalaemia/hypomagnesaemia.","BETA-BLOCKER first-line for symptomatic PVCs; alternative non-DHP CCB (verapamil/diltiazem) — avoid non-DHP CCB if LV dysfunction.","For refractory/high-burden: FLECAINIDE/propafenone if structurally normal, sotalol/amiodarone if structural; ABLATION first-line for idiopathic outflow-tract PVCs and preferred when drugs fail.","ECHO-screen burden >10–15% for PVC-induced cardiomyopathy (reversible by suppression/ablation); treat structural/ischaemic substrate, assess SCD risk/ICD, refer cardiology/EP."], ix: ["12-lead ECG — morphology, coupling interval, capture/fusion beats","24–48 h Holter/ambulatory ECG — quantify PVC burden and morphology","Transthoracic echocardiography — LV function and structural disease","Serum electrolytes (K, Mg) and thyroid function","Exercise/stress test ± cardiac MRI or coronary assessment if ischaemia/structural disease suspected"], dispo: "Outpatient/primary-care reassurance if benign; refer cardiology/EP for high burden >10%, beta-blocker-refractory symptoms, LV dysfunction, or structural/ischaemic heart disease.", src: "Harrison 22e · ESC 2022 (ventricular arrhythmias & prevention of SCD)" },
    "pulmonic_valve_disease": { name: "Pulmonic Valve Disease", class: "non_infective", system: "Cardiovascular", dx: "TTE + Doppler confirms and grades PS by peak gradient (mild <36, moderate 36–64, severe >64 mmHg / velocity >4 m/s), quantifying PR, valve morphology and RV size/function — PS: ejection systolic murmur with click (softer on inspiration), widely split S2 with soft/delayed P2; PR: decrescendo diastolic (Graham Steell) murmur.", tx: ["OBSERVE mild PS (<36 mmHg): no intervention, reassure, periodic surveillance echo; excellent prognosis, rare progression.","BALLOON PULMONARY VALVULOPLASTY = treatment of choice for severe PS (>64 mmHg / >4 m/s) with mobile non-dysplastic domed valve; indicated if symptomatic, or asymptomatic with severe PS or RV dysfunction (Class I).","SURGICAL valvotomy/replacement when valvuloplasty unsuitable: dysplastic valve (e.g. Noonan), hypoplastic annulus, sub/supravalvular stenosis, or associated significant PR.","PR: treat underlying cause (e.g. pulmonary HTN), mostly well tolerated needing no valve therapy; refer severe symptomatic PR (post-TOF) with progressive RV dilatation/dysfunction or arrhythmia for pulmonary valve replacement (surgical/transcatheter).","MONITOR with serial echo + cardiac MRI for indexed RV volumes; endocarditis prophylaxis ONLY for prosthetic valve/repair material, prior IE, or unrepaired cyanotic CHD; lifelong ACHD-centre follow-up."], ix: ["TTE with Doppler – primary diagnostic and severity tool","ECG – right axis deviation and RV hypertrophy in significant PS","CXR – post-stenotic pulmonary artery dilatation and RV enlargement","Cardiac MRI – indexed RV volumes and PR regurgitant fraction, esp. post-TOF repair","Cardiac catheterisation – direct peak-to-peak gradient when echo inconclusive or pre-intervention"], dispo: "Outpatient cardiology; refer severe PS/PR to a structural/adult-congenital-heart-disease (ACHD) centre for intervention.", src: "Harrison 22e · ESC 2020 ACHD · AHA/ACC 2018 ACHD" },
    "st_segment_elevation_myocardial_infarction": { name: "ST-Segment Elevation Myocardial Infarction", class: "non_infective", system: "Cardiovascular", dx: "Ischaemic symptoms ≥20 min plus persistent ECG ST-elevation ≥1 mm in ≥2 contiguous limb leads or ≥2 mm (men)/≥1.5 mm (women) in ≥2 contiguous precordial leads (V2–V3), or new/presumed-new LBBB with ongoing ischaemia — reperfuse on the ECG, do not await troponin (though hs-troponin rise/fall confirms infarction).", tx: ["ASPIRIN 300 mg chewed; O2 only if SpO2 <90%; GTN + IV morphine for pain — avoid nitrates in hypotension/inferior-RV infarct/recent PDE5i; cardiac monitor + defib ready.","REPERFUSE now — primary PCI if deliverable ≤120 min of STEMI dx; else fibrinolysis (tenecteplase, weight-adjusted) ≤10 min then early/rescue angiography (pharmacoinvasive).","DAPT: aspirin + P2Y12 (prasugrel/ticagrelor preferred with PCI; clopidogrel if contraindicated or with lysis) + anticoagulant (UFH/enoxaparin periprocedurally; enoxaparin preferred with lysis).","PREDISCHARGE: high-intensity statin, oral beta-blocker, ACEi/ARB, MRA if LVEF ≤40% with HF/diabetes; continue DAPT 12 months (individualise to bleeding/ischaemic risk).","MONITOR continuous ECG for arrhythmia; treat complications (cardiogenic shock, mechanical rupture, LV thrombus); start early cardiac rehab + risk-factor modification."], ix: ["Serial 12-lead ECG — immediate and repeated","Serial high-sensitivity troponin — do not delay reperfusion for results","Urgent coronary angiography — diagnostic and therapeutic","TTE — LVEF, wall-motion, mechanical complications","FBC, U&E/creatinine, glucose/HbA1c, lipids"], dispo: "Emergency admission to a PCI-capable centre via primary-PCI pathway; CCU/ICU under cardiology.", src: "Harrison 22e · ESC 2023 ACS guideline" },
    "sustained_ventricular_tachycardia": { name: "Sustained Ventricular Tachycardia", class: "non_infective", system: "Cardiovascular", dx: "Regular wide-complex (QRS >120 ms) tachycardia >100/min, sustained >30 s or needing termination; favour VT via AV dissociation, capture/fusion beats, extreme axis or precordial concordance and assume VT with structural heart disease — avoid empiric AV-nodal blockers (verapamil/diltiazem), which may precipitate collapse.", tx: ["DEFIBRILLATE pulseless VT (unsynchronised + CPR/ACLS); unstable-with-pulse (hypotension/ischaemia/pulmonary oedema/altered mentation) → synchronised DC cardioversion; defibrillate if polymorphic or can't sync.","Stable monomorphic: PROCAINAMIDE first-line if LV preserved/mildly reduced (ESC 2022/PROCAMIO); AMIODARONE if severe LV dysfunction/HF; lidocaine if acute ischaemia; cardiovert if refractory/deteriorating.","Polymorphic VT/torsades: IV MAGNESIUM, correct K+/Mg2+, stop QT-prolonging drugs; isoprenaline/overdrive pacing if pause-/brady-dependent (long-QT); revascularise + beta-block if ischaemic; defibrillate if unstable.","TREAT reversible triggers: ischaemia/MI, electrolytes, drug toxicity, decompensated HF; VT STORM → beta-blockade, amiodarone, sedation, consider urgent ablation.","ICD for secondary prevention (structural disease/reduced EF); catheter ABLATION for recurrent drug-refractory monomorphic VT/storm; optimise cardiomyopathy/HF therapy; urgent cardiology/EP referral + pre-discharge ICD eval."], ix: ["12-lead ECG during and after episode, baseline/prior ECGs, continuous telemetry","Serum electrolytes (K+, Mg2+, Ca2+) and renal/hepatic function","Cardiac troponin and ischaemia workup ± coronary angiography","TTE for LV function/structural disease; cardiac MRI for scar/infiltration","EP study for risk stratification/ablation planning in selected cases"], dispo: "Admit to CCU/monitored bed with continuous telemetry; urgent cardiology/EP referral and ICD assessment.", src: "Harrison 22e · ESC 2022 (ventricular arrhythmias / prevention of SCD) · AHA ACLS 2020" },
    "the_bradyarrhythmias_disorders_of_the": { name: "The Bradyarrhythmias: Disorders of the Atrioventricular Node", class: "non_infective", system: "Cardiovascular", dx: "12-lead ECG localises/grades block (first-degree = PR prolongation; Mobitz I = progressive PR then dropped beat; Mobitz II = fixed PR with sudden non-conducted P/2:1; third-degree = AV dissociation with slow escape), while ambulatory/inpatient telemetry captures paroxysmal block and correlates symptoms with rhythm.", tx: ["ASSESS STABILITY; if unstable (hypotension/shock/ischaemia/HF/syncope): ATROPINE 0.5 mg IV q3-5 min (max 3 mg).","TRANSCUTANEOUS PACING + chronotrope bridge (isoprenaline/adrenaline/dopamine) — don't delay; atropine often fails or worsens infranodal (Mobitz II, wide-QRS complete) block.","REVERSE CAUSES — stop AV-nodal drugs (beta-blocker, verapamil/diltiazem, digoxin, amiodarone); correct hyperK, hypothyroidism, ischaemia (inferior MI); treat Lyme/infiltrative/infective disease.","TEMPORARY TRANSVENOUS PACING for persistent high-grade/complete block causing instability, bridging recovery or permanent device.","PERMANENT PACEMAKER (dual-chamber, preserves AV synchrony) for symptomatic/high-grade irreversible block (third-degree, Mobitz II/advanced); prefer conduction-system (His/LBB-area)/CRT pacing if high pacing burden + LV dysfunction; first-degree/Mobitz I — monitor + reverse causes, no pacing unless symptomatic."], ix: ["12-lead ECG — localise/grade block; assess escape rhythm width and rate","Telemetry/ambulatory monitoring (Holter, event/loop recorder) — intermittent block, symptom correlation","Electrolytes (K/Ca/Mg), renal function, TFTs; troponin if ischaemia suspected","Echocardiography — structural heart disease and LV function","Targeted aetiology tests (Lyme serology, medication review, EPS for unexplained syncope)"], dispo: "Admit high-grade/symptomatic block to monitored bed (telemetry +/- temporary pacing); urgent cardiology/EP referral for permanent device assessment.", src: "Harrison 22e · ESC 2021 Cardiac Pacing and CRT · ACC/AHA/HRS 2018 Bradycardia guideline" },
    "tricuspid_valve_disease": { name: "Tricuspid Valve Disease", class: "non_infective", system: "Cardiovascular", dx: "TTE to confirm, grade severity, define mechanism (primary/structural vs secondary/functional) and assess RV size/function and PASP; add TOE for pre-intervention anatomy and right heart cath when non-invasive data discordant.", tx: ["LOOP DIURETIC ± aldosterone antagonist + Na/fluid restriction for congestion/RHF; treat functional-TR driver — optimise left valve/myocardial disease, control AF, treat pulmonary HTN.","SURGERY (severe TR) — annuloplasty (repair > replacement) at left-sided valve surgery (Class I); consider for symptomatic isolated primary severe TR or progressive RV dilatation/dysfunction.","TRANSCATHETER T-TEER (TriClip)/TTVR (EVOQUE) — symptomatic severe TR despite optimal medical Rx, high surgical-risk, after heart-team review at valve centre.","TRICUSPID STENOSIS — diuretics for congestion; bioprosthetic replacement/repair if severe symptomatic (usually with mitral surgery); anticoagulate tricuspid bioprostheses (higher thrombosis risk).","RIGHT-SIDED IE (IVDU) — prolonged targeted antibiotics; repair/vegetectomy if medical Rx fails, vegetations large, or right heart failure."], ix: ["TTE — severity, mechanism, RV function, PASP","TOE — mechanism, pre-procedural planning","ECG (AF, RV strain/hypertrophy) + CXR (RA/cardiac enlargement)","Right heart cath — haemodynamics/PA pressure if discordant or pre-intervention","Cardiac MRI (RV volumes/function) ± NT-proBNP"], dispo: "Cardiology referral; multidisciplinary heart-team assessment at tertiary valve centre for surgical/transcatheter candidates.", src: "Harrison 22e · AHA/ACC 2020 (VHD)" },
    "arterial_diseases_of_the_extremities": { name: "Arterial Diseases of the Extremities", class: "non_infective", system: "Cardiovascular (peripheral vascular)", dx: "PAD confirmed by resting ABI ≤0.90; if borderline (0.91–0.99) or non-compressible/calcified (ABI >1.40, e.g. diabetes/CKD) use toe–brachial index (<0.70) or exercise ABI (≥20% post-exercise fall), then duplex/CT-MR/catheter angiography to localise and grade stenosis before revascularisation.", tx: ["IV HEPARIN + analgesia now for acute/critical limb ischaemia (rest pain/ulcers/gangrene); urgent vascular referral, emergency revasc—thrombolysis if viable/marginal, embolectomy/bypass if immediately threatened.","EXERCISE (supervised 30–45 min ≥3×/wk) + full smoking cessation; high-intensity STATIN ±ezetimibe/PCSK9; optimise BP (ACEi/ARB reasonable) and glycaemia.","SINGLE ANTIPLATELET (clopidogrel preferred, or aspirin); add rivaroxaban 2.5 mg BD to aspirin in high-risk symptomatic/post-revasc PAD to cut MACE/MALE—individualise bleeding, avoid CrCl <15.","CILOSTAZOL first-line for claudication (contraindicated in any-grade heart failure); exercise remains cornerstone.","REVASCULARISE (endovascular angioplasty/stent or bypass per anatomy) for refractory lifestyle-limiting claudication/CLTI; structured foot/wound care, treat infection, flu vaccine, refer non-healing ulcers/tissue loss to limb-salvage team."], ix: ["Resting ABI (+ exercise ABI or toe–brachial index if non-compressible)","Arterial duplex ultrasound to localise stenosis/occlusion","CT/MR or catheter angiography for revascularisation planning","Fasting lipids, HbA1c/glucose, renal function","Foot inspection ± wound/tissue assessment if suspected CLTI"], dispo: "Outpatient vascular medicine/surgery clinic; urgent/emergency vascular surgery for acute or critical limb ischaemia.", src: "Harrison 22e · ESC/ESVS 2024 peripheral arterial and aortic diseases" },
    "deep_venous_thrombosis_and_pulmonary": { name: "Deep-Venous Thrombosis and Pulmonary Thromboembolism", class: "non_infective", system: "Cardiovascular / Venous (Vascular)", dx: "Pre-test probability (Wells/Geneva) + D-dimer first — normal D-dimer with low probability excludes VTE without imaging; confirm DVT by compression US (non-compressible vein), PE by CT pulmonary angiography.", tx: ["RISK-STRATIFY PE severity — high-risk (shock/instability) vs intermediate vs low (sPESI); DVT assess extent + bleeding risk.","THROMBOLYSE high-risk/massive PE — alteplase (unless contraindicated) + resuscitate/O2/IV access; catheter-directed therapy or embolectomy if thrombolysis fails/contraindicated.","ANTICOAGULATE promptly (empirical if high suspicion + low bleed risk) — first-line DOAC (apixaban/rivaroxaban) for most DVT + stable PE; else LMWH→VKA (INR 2–3), LMWH mono, or UFH (thrombolysis planned/severe renal/instability).","CONTINUE ≥3 months; extend indefinitely for unprovoked/recurrent VTE or persisting risk — reassess bleed risk periodically; IVC filter only if anticoagulation absolutely contraindicated.","SPECIAL POPULATIONS — pregnancy: LMWH (avoid DOAC/warfarin); active cancer: DOAC or LMWH; CrCl<30: UFH (preferred) or dose-adjusted LMWH + anti-Xa, or warfarin."], ix: ["Compression ultrasound of proximal leg veins (DVT)","CT pulmonary angiography (PE); V/Q scan if CTPA contraindicated","D-dimer with pre-test probability score (Wells/Geneva)","ECG + troponin/BNP for RV-strain risk-stratification (PE)","Echocardiography for RV dysfunction (suspected high/intermediate-risk PE)"], dispo: "Admit high/intermediate-risk PE (consider ICU/monitored bed); low-risk PE (sPESI 0) + uncomplicated DVT — outpatient anticoagulation with early review.", src: "Harrison 22e · ESC 2019 (Acute Pulmonary Embolism)" },
    "ards": { name: "Acute Respiratory Distress Syndrome (ARDS)", class: "non_infective", system: "Critical Care", dx: "Clinical dx (Berlin/2023): acute hypoxaemic failure ≤1 wk post-insult + bilateral CXR/CT opacities not from effusion/collapse/nodules + not fully cardiac/fluid-overload; grade by PaO2/FiO2 on PEEP ≥5 cmH2O — mild 200–300, moderate 100–200, severe <100; echo to exclude cardiogenic oedema.", tx: ["TREAT PRECIPITANT — source control; early broad-spectrum antibiotics for sepsis; manage aspiration/pancreatitis/trauma.","LUNG-PROTECTIVE VENT — VT 6 mL/kg PBW, plateau <30, driving pressure <15 cmH2O; permit hypercapnia pH >7.20.","TITRATE PEEP to oxygenation/compliance (higher in moderate–severe); target SpO2 88–95%; conservative fluids once perfusion adequate.","PRONE ≥12–16 h/day if P/F <150; add short-course cisatracurium (NMB) for early severe ARDS with dyssynchrony.","DEXAMETHASONE in moderate–severe/COVID ARDS; VV-ECMO if refractory P/F <80; inhaled vasodilators rescue-bridge only; support with lung-protective sedation, VTE + stress-ulcer prophylaxis, enteral feed, daily awakening/SBT."], ix: ["ABG with PaO2/FiO2 ratio","Chest radiograph and/or chest CT","Echocardiography — exclude cardiogenic oedema, assess RV","Sepsis screen — blood/sputum cultures, FBC, CRP/procalcitonin, lactate","BNP/NT-proBNP to exclude cardiac failure"], dispo: "ICU — invasive lung-protective ventilation; refer regional ECMO centre if refractory hypoxaemia.", src: "Harrison 22e · ATS/ESICM/SCCM" },
    "DRESS_SYNDROME": { name: "DRESS syndrome", class: "non_infective", system: "Dermatology", dx: "Clinical diagnosis (RegiSCAR): morbilliform rash with facial oedema, fever, lymphadenopathy, eosinophilia/atypical lymphocytosis and internal-organ involvement (esp. hepatitis) arising 2-8 weeks after a culprit drug (aromatic anticonvulsants, allopurinol, sulfonamides, vancomycin, minocycline, dapsone), biopsy and exclusion of infection supportive — and, unlike SJS/TEN, no epidermal detachment.", tx: ["STOP culprit drug immediately; avoid ALL cross-reacting agents — single most important intervention.","ADMIT for supportive care (IV fluids, electrolytes, temp control, emollients) under dermatology; ICU/HDU if erythroderma with skin-barrier failure or multi-organ failure (no TEN-like detachment).","SYSTEMIC CORTICOSTEROIDS first-line for organ involvement — prednisolone 0.5-1 mg/kg/day PO/IV (IV methylprednisolone pulses for fulminant hepatitis/myocarditis); slow taper ≥8-12 wk, up to 3-6 mo, to prevent relapse.","MILD/skin-limited: potent topical steroids + antihistamines, avoid unnecessary new drugs (empirical abx/antipyretics) risking confounding/re-sensitisation; steroid-refractory or life-threatening → ciclosporin, MMF or IVIG (IVIG WITH steroids, not monotherapy).","MONITOR LFTs/renal/cardiac through acute illness + baseline ECG in ALL (silent myocarditis is a leading killer); screen months for thyroiditis/T1DM; document drug allergy, counsel lifelong avoidance."], ix: ["FBC + differential — eosinophilia (>0.7 x10^9/L), atypical lymphocytes","LFTs, renal function + urinalysis — hepatic/renal involvement","Skin biopsy — supportive histology, excludes mimics","HHV-6 (±CMV/EBV) serology/PCR — viral reactivation","Baseline ECG + troponin in all; echo if cardiac symptoms/abnormal markers; baseline TFTs + glucose for later autoimmune sequelae"], dispo: "Admit — dermatology inpatient with physician co-management; ICU/HDU if severe multi-organ involvement or erythroderma with skin-barrier failure (epidermal detachment = SJS/TEN or overlap, not DRESS).", src: "Harrison 22e - BAD" },
    "ERYTHEMA_NODOSUM": { name: "Erythema nodosum", class: "non_infective", system: "Dermatology", dx: "Clinical: crops of tender, non-ulcerating erythematous-to-violaceous bilateral pretibial nodules healing without scarring (bruise-like evolution); reserve deep incisional biopsy (must include subcutaneous fat) for atypical/persistent lesions, which show septal panniculitis without vasculitis.", tx: ["TREAT TRIGGER — antibiotics for strep, withdraw offending drug (sulfonamides/OCP), manage sarcoidosis/TB/IBD/infection.","SUPPORTIVE first-line — bed rest, leg elevation, compression, NSAIDs; avoid NSAIDs in IBD-EN (bowel flare), caution renal/elderly/pregnancy.","POTASSIUM IODIDE (SSKI) for persistent/recurrent ×several weeks; monitor thyroid; avoid in pregnancy or overt thyroid disease.","CORTICOSTEROIDS (short course) for severe/refractory ONLY after excluding infection (esp TB) + malignancy; colchicine/dapsone steroid-sparing (screen G6PD pre-dapsone; colchicine for Behcet-EN).","Most self-limiting (3-6 wks); escalate work-up if persists >6-8 wks or recurs; pregnancy — supportive only, avoid NSAIDs/iodide, may be pregnancy/OCP-related, settles post-partum."], ix: ["Throat swab + ASO/anti-DNase B titre (streptococcal trigger)","Chest radiograph — bilateral hilar lymphadenopathy (sarcoidosis/Lofgren) or TB","FBC, ESR/CRP","Tuberculin skin test or IGRA","Targeted per clues — faecal calprotectin/colonoscopy (IBD), fungal serology, pregnancy test"], dispo: "Outpatient; refer dermatology if diagnosis uncertain/refractory, and relevant specialty (respiratory/gastroenterology/ID) per identified underlying cause.", src: "Harrison 22e · BAD" },
    "ACHALASIA": { name: "Achalasia", class: "non_infective", system: "Gastroenterology", dx: "HRM is diagnostic (absent peristalsis + impaired LES relaxation; Chicago subtypes I–III); barium swallow shows dilated oesophagus with distal 'bird's-beak' taper; do endoscopy FIRST to exclude pseudoachalasia (GOJ tumour).", tx: ["MANOMETRY to confirm; EXCLUDE pseudoachalasia (endoscopy ± EUS/CT) before treating.","DISRUPT LES definitively: graded PNEUMATIC DILATION, laparoscopic HELLER MYOTOMY (+partial fundoplication) or POEM — choose by subtype/age/surgical risk (POEM for type III/spastic).","BOTULINUM TOXIN endoscopic into LES for poor procedure candidates — temporary, repeatable bridge/palliative.","NITRATES or CCB (nifedipine) only when procedures unsuitable — modest, short-lived benefit.","PPI for post-treatment reflux; surveil symptom recurrence + small long-term squamous-carcinoma risk."], ix: ["High-resolution oesophageal manometry (diagnostic + subtype)","Upper endoscopy to exclude pseudoachalasia","Barium / timed barium swallow","Chagas serology if relevant exposure"], dispo: "Outpatient GI referral; manometry/endoscopy-guided definitive therapy.", src: "Harrison 22e · ACG / Chicago Classification v4.0" },
    "antiphospholipid_syndrome": { name: "Antiphospholipid Syndrome", class: "non_infective", system: "Rheumatology", dx: "Persistent antiphospholipid antibodies (lupus anticoagulant, anticardiolipin and/or anti-β2GPI) on ≥2 occasions ≥12 weeks apart PLUS thrombosis or defined pregnancy morbidity; classify by 2023 ACR/EULAR criteria.", tx: ["WARFARIN to INR 2–3 after heparin/LMWH; higher target ± antiplatelet for arterial/recurrent; usually INDEFINITE.","AVOID DOACs — higher recurrence, especially triple-positive or arterial APS.","OBSTETRIC APS: low-dose aspirin + prophylactic LMWH (therapeutic if prior thrombosis); NO warfarin/DOACs in pregnancy.","Asymptomatic aPL/SLE: low-dose ASPIRIN ± hydroxychloroquine + aggressive cardiovascular risk-factor control.","CAPS emergency: TRIPLE THERAPY — anticoagulation + high-dose glucocorticoids + plasma exchange and/or IVIG; treat precipitant (often infection); rituximab/eculizumab if refractory."], ix: ["LA, anticardiolipin, anti-β2GPI (IgG/IgM); repeat ≥12 weeks","FBC (thrombocytopenia), renal function, coagulation","Imaging of thrombotic territory; screen for SLE"], dispo: "Haematology/rheumatology; CAPS → ICU.", src: "Harrison 22e · 2023 ACR/EULAR APS criteria · ISTH" },
    "PYODERMA_GANGRENOSUM": { name: "Pyoderma gangrenosum", class: "non_infective", system: "Dermatology", dx: "Clinical diagnosis of exclusion – painful ulcer with violaceous undermined border; edge biopsy shows neutrophilic infiltrate and excludes mimics (Delphi/PARACELSUS criteria).", tx: ["SYSTEMIC CORTICOSTEROIDS (prednisolone 0.5–1 mg/kg/day) first-line; ciclosporin equivalent per STOP-GAP.","Localised/mild – potent topical or intralesional corticosteroid, or topical tacrolimus.","Refractory – escalate to INFLIXIMAB (esp. IBD-associated) or MMF/azathioprine/dapsone.","AVOID debridement/surgery (pathergy); gentle moist wound dressings + strong analgesia.","Treat associated disease – IBD, RA, haematological/myeloproliferative malignancy."], ix: ["Skin biopsy from ulcer edge – histology plus tissue culture.","Wound swab/culture (bacterial, fungal, mycobacterial) to exclude infection.","FBC + peripheral blood film; CRP/ESR.","Serum + urine protein electrophoresis (IgA monoclonal gammopathy).","Underlying-disease screen – colonoscopy/IBD workup, RF/ANA; hepatitis + TB pre-biologic."], dispo: "Urgent dermatology referral; MDT wound care; admit if extensive, rapidly progressive or systemically unwell.", src: "Harrison 22e - UK STOP-GAP trial (BMJ 2015) & Delphi diagnostic consensus (Maverakis, JAMA Dermatol 2018)" },
    "skin_cancer": { name: "Skin Cancer", class: "non_infective", system: "Dermatology / Oncology", dx: "Confirm with skin biopsy (excisional/punch/shave) plus histopathology; dermoscopy guides clinical suspicion.", tx: ["SURGICAL EXCISION first-line – MOHS micrographic surgery for high-risk/facial BCC and SCC.","Melanoma: wide local excision, margins per Breslow depth; SENTINEL NODE biopsy if ≥0.8mm or ulcerated.","Superficial BCC/in-situ: topical imiquimod or 5-FU, cryotherapy/curettage; radiotherapy if inoperable.","Metastatic melanoma: anti-PD-1 IMMUNOTHERAPY ± ipilimumab; BRAF/MEK inhibitors if BRAF-V600 mutant.","Advanced BCC: hedgehog inhibitor (vismodegib); advanced SCC: CEMIPLIMAB; enforce photoprotection + surveillance."], ix: ["Biopsy histology – subtype, margins, Breslow thickness + ulceration (melanoma)","Full-body skin exam + regional lymph node palpation","Sentinel lymph node biopsy – melanoma ≥0.8mm or ulcerated","Staging CT/PET-CT + brain MRI for high-risk or advanced disease","BRAF V600 mutation testing and baseline LDH in advanced melanoma"], dispo: "Refer dermatology/surgical oncology; MDT for melanoma/advanced disease; lifelong surveillance + photoprotection.", src: "Harrison 22e - NCCN Guidelines (Melanoma; Basal & Squamous Cell Skin Cancers)" },
    "adrenal_disorders": { name: "Adrenal Cortical Disorders", class: "non_infective", system: "Endocrine", dx: "Confirm by pattern: short Synacthen test showing subnormal cortisol rise with high ACTH = primary insufficiency; dexamethasone non-suppression / raised UFC = Cushing's; high aldosterone:renin ratio = primary aldosteronism.", tx: ["ADRENAL CRISIS: IV HYDROCORTISONE 100 mg stat, then 50 mg q6h + rapid IV saline/dextrose – don't await tests; treat precipitant.","Chronic Addison's: HYDROCORTISONE 15–25 mg/day split + FLUDROCORTISONE 50–200 µg/day; double dose in illness.","Cushing's: resect source (transsphenoidal/adrenalectomy); metyrapone or ketoconazole to control cortisol pre-op.","Primary aldosteronism: confirm, then LATERALIZE by adrenal vein sampling – unilateral → adrenalectomy; bilateral → SPIRONOLACTONE/eplerenone + BP/K control.","Always: steroid emergency card + MedicAlert; taper long-term steroids slowly to avert iatrogenic crisis."], ix: ["0800 serum cortisol + paired plasma ACTH","Short Synacthen (cosyntropin) stimulation test","U&E (Na/K), glucose, plasma aldosterone:renin ratio","Overnight dexamethasone suppression / 24-h urinary free cortisol / late-night salivary cortisol","Adrenal CT + 21-hydroxylase autoantibodies (+ adrenal vein sampling to lateralize aldosteronism pre-op)"], dispo: "Crisis → HDU/ICU with hourly monitoring; stable → endocrinology for replacement titration + patient education.", src: "Harrison 22e – Endocrine Society CPG (Primary Adrenal Insufficiency; Primary Aldosteronism)" },
    "autoimmune_polyendocrine_syndromes": { name: "Autoimmune Polyendocrine Syndromes", class: "non_infective", system: "Endocrine", dx: "Confirm by ≥2 autoimmune endocrinopathies plus organ-specific autoantibodies; AIRE mutation defines APS-1.", tx: ["GLUCOCORTICOID before thyroxine — give hydrocortisone first if adrenal insufficiency co-exists to avoid precipitating crisis.","HYDROCORTISONE + fludrocortisone for Addison's; stress-dose in illness, emergency IM kit + steroid card.","LEVOTHYROXINE for hypothyroidism; INSULIN for type 1 diabetes — titrate to standard targets.","CALCIUM + calcitriol for hypoparathyroidism (APS-1); antifungals for chronic candidiasis, surveil for oral SCC.","Lifelong surveillance for new components + periodic autoantibody screen; refer endocrinology/MDT."], ix: ["0800h cortisol + ACTH ± short Synacthen; anti-21-hydroxylase antibody","TSH, free T4, anti-TPO antibody","Fasting glucose/HbA1c, anti-GAD/IA-2 antibodies","Calcium, phosphate, PTH, 25-OH vitamin D","B12, coeliac serology; AIRE gene testing if APS-1 suspected"], dispo: "Endocrinology outpatient follow-up; emergency parenteral hydrocortisone + A&E if adrenal crisis.", src: "Harrison 22e - Endocrine Society CPG (Primary Adrenal Insufficiency, 2016)" },
    "disorders_of_the_neurohypophysis": { name: "Disorders of the Neurohypophysis", class: "non_infective", system: "Endocrine", dx: "Euvolaemic hypotonic hyponatraemia with inappropriately concentrated urine (U-osm >100, U-Na >30) = SIADH; hypotonic polyuria with water-deprivation/desmopressin challenge (± copeptin) distinguishes central from nephrogenic DI.", tx: ["Severe symptomatic hyponatraemia — 3% HYPERTONIC SALINE bolus (100–150 mL, repeat); cap rise ≤8–10 mmol/L/24h to avoid osmotic demyelination.","Chronic SIADH — FLUID RESTRICT first-line; add salt tablets ± oral urea; tolvaptan/vaptan if refractory.","Central DI — DESMOPRESSIN (DDAVP) oral/intranasal/SC; allow daily breakthrough diuresis; monitor dilutional hyponatraemia.","Nephrogenic DI — thiazide + low-salt/low-protein diet; AMILORIDE for lithium-induced; stop offending drug; NSAID adjunct.","Replace free-water deficit / correct volume; treat underlying cause (malignancy, drugs, CNS insult); endocrine referral."], ix: ["Paired serum + urine osmolality and urine sodium","Serum Na/K, glucose, renal function","Water-deprivation test with desmopressin challenge (or serum copeptin)","Thyroid function + 9am cortisol (exclude hypothyroid/adrenal mimics of SIADH)","Pituitary/hypothalamic MRI"], dispo: "Admit if severe/symptomatic hyponatraemia or unstable fluid balance; otherwise outpatient titration with endocrine follow-up.", src: "Harrison 22e - European Hyponatraemia Guideline (ERBP/ESE/ESICM 2014)" },
    "hirsutism": { name: "Hirsutism", class: "non_infective", system: "Endocrine", dx: "Clinical — modified Ferriman-Gallwey score ≥8 (adjust for ethnicity) plus biochemical androgen excess; PCOS commonest cause.", tx: ["COMBINED OCP first-line — suppresses ovarian androgens, raises SHBG; expect response by ~6 months.","Add SPIRONOLACTONE (antiandrogen) if inadequate at 6/12; mandate reliable contraception (teratogenic).","Direct hair removal — photoepilation/electrolysis; topical EFLORNITHINE for facial hair.","Weight loss + treat PCOS metabolics; metformin not primary for hirsutism.","URGENT endocrine referral if rapid onset/virilisation or testosterone markedly raised — exclude androgen-secreting tumour."], ix: ["Morning total + free testosterone","DHEAS (adrenal source)","17-hydroxyprogesterone — exclude non-classic CAH","Prolactin, TSH","Pelvic/adrenal imaging if androgens markedly raised or rapid virilisation"], dispo: "Outpatient endocrine/derm; counsel slow response (>6/12); combine pharmacotherapy with cosmetic measures.", src: "Harrison 22e - Endocrine Society Clinical Practice Guideline on Hirsutism (2018)" },
    "hyperthyroidism_and_other_causes_of": { name: "Hyperthyroidism and Other Causes of Thyrotoxicosis", class: "non_infective", system: "Endocrine", dx: "Suppressed TSH with raised free T4/T3; RAIU + TRAb identify cause (Graves vs thyroiditis vs toxic nodule).", tx: ["BETA-BLOCKER (propranolol) first for adrenergic symptoms/rate control – esp AF, elderly.","METHIMAZOLE first-line thionamide; PTU only in 1st trimester or thyroid storm.","Definitive Rx – RADIOACTIVE IODINE ablation or thyroidectomy for Graves/toxic nodular disease.","MONITOR CBC + LFTs; stop thionamide if agranulocytosis (fever/sore throat) or hepatotoxicity.","Thyroid storm – PTU + iodine (>=1 h later) + glucocorticoid + beta-blocker + cooling; ICU."], ix: ["TSH, free T4, free T3","TRAb (TSH-receptor antibodies)","Radioactive iodine uptake + scan – differentiate cause","Baseline CBC + LFTs before thionamide","ECG (AF) +/- thyroid USS with Doppler"], dispo: "Outpatient endocrinology follow-up; admit thyroid storm or cardiac decompensation to ICU.", src: "Harrison 22e - ATA 2016 Hyperthyroidism Guidelines" },
    "hypopituitarism": { name: "Hypopituitarism", class: "non_infective", system: "Endocrine", dx: "Confirm by paired trophic + target-gland hormones (low free T4/cortisol/gonadal steroid with inappropriately low–normal pituitary hormone) ± dynamic testing, plus pituitary MRI.", tx: ["GLUCOCORTICOID first – hydrocortisone 15–25 mg/day split; NEVER start thyroxine before steroid (precipitates crisis).","Sick-day rules – double/triple hydrocortisone + parenteral if vomiting/surgery; steroid card + emergency IM kit.","LEVOTHYROXINE for central hypothyroidism – titrate to free T4 mid-upper range, NOT TSH.","Replace sex steroids (testosterone men; oestrogen±progestogen women) + GH if confirmed deficiency; DESMOPRESSIN for central DI.","Apoplexy/acute – IV hydrocortisone + urgent neurosurgery/endocrine referral if visual loss or ↓consciousness."], ix: ["0800h cortisol ± short Synacthen / insulin tolerance test for ACTH reserve","Free T4 with TSH (central pattern) + prolactin","LH/FSH + testosterone (men) or oestradiol (women)","IGF-1 ± GH stimulation test; paired serum/urine osmolality if polyuria","Pituitary MRI + formal visual-field perimetry"], dispo: "Endocrinology follow-up; lifelong titrated replacement + steroid-emergency education + MedicAlert.", src: "Harrison 22e - Endocrine Society Clinical Practice Guideline (Hormonal Replacement in Hypopituitarism in Adults, 2016)" },
    "hypothyroidism": { name: "Hypothyroidism", class: "non_infective", system: "Endocrine", dx: "Confirm with raised TSH + low free T4 (primary); raised TSH with normal free T4 = subclinical.", tx: ["LEVOTHYROXINE first-line - full replacement ~1.6 ug/kg/day; titrate to normalise TSH.","Start LOW 12.5-25 ug in elderly/ischaemic heart disease; titrate slowly - avoid precipitating angina.","Take fasting 30-60 min pre-breakfast; separate from calcium/iron/PPI/soya.","Recheck TSH 6 weeks after any dose change; target TSH ~0.5-4 mU/L.","MYXOEDEMA COMA - IV levothyroxine (load ~200-400 ug, then 50-100 ug/day) + IV hydrocortisone before/with LT4 + supportive ICU rewarming/ventilation; treat precipitant (e.g. infection)."], ix: ["TSH","Free T4","Anti-TPO antibodies","Fasting lipid profile","FBC (macrocytic anaemia)"], dispo: "Outpatient titration; admit myxoedema coma to ICU.", src: "Harrison 22e - ATA (American Thyroid Association) hypothyroidism guidelines" },
    "multiple_endocrine_neoplasia": { name: "Multiple Endocrine Neoplasia (MEN)", class: "non_infective", system: "Endocrine", dx: "Confirm by germline mutation testing – MEN1 gene or RET (MEN2) – plus biochemical/imaging evidence of characteristic endocrine tumours.", tx: ["GENETIC TESTING (MEN1 / RET) + cascade-screen first-degree relatives; enrol in lifelong biochemical + imaging surveillance.","MEN2 – exclude/treat PHAEOCHROMOCYTOMA first: alpha-blockade before ANY thyroid, parathyroid or other surgery.","MEN2 – RET-guided prophylactic TOTAL THYROIDECTOMY; timing by ATA risk category; advanced MTC → selpercatinib/pralsetinib.","MEN1 hyperparathyroidism → subtotal (3.5-gland) PARATHYROIDECTOMY + transcervical thymectomy; gastrinoma → high-dose PPI ± resection; prolactinoma → cabergoline.","Refer to endocrine/genetics MDT; resect functioning/large (>1–2 cm) pancreatic NETs; treat pituitary tumours per subtype."], ix: ["Serum calcium + PTH; add gastrin, fasting glucose/insulin, prolactin, IGF-1, chromogranin A","Plasma/urine metanephrines (phaeochromocytoma screen – MEN2)","Serum calcitonin + CEA (medullary thyroid carcinoma marker – MEN2)","Germline MEN1 and RET mutation analysis","Imaging: pituitary MRI, pancreatic CT/MRI/EUS, neck US; Ga-68 DOTATATE PET for NETs"], dispo: "Specialist endocrine/genetics MDT; lifelong biochemical + imaging surveillance; cascade family testing.", src: "Harrison 22e – AACE 2025 MEN1 consensus & ATA medullary thyroid carcinoma guideline" },
    "pheochromocytoma": { name: "Pheochromocytoma", class: "non_infective", system: "Endocrine", dx: "Catecholamine-secreting tumour confirmed by raised plasma free (or 24h urinary fractionated) metanephrines, then localised on CT/MRI.", tx: ["ALPHA-BLOCKADE first – phenoxybenzamine (or doxazosin) 10–14 days pre-op; never beta-block alone first.","Add BETA-BLOCKER only after adequate alpha-blockade, for reflex tachycardia/arrhythmia.","Liberal salt + fluids to re-expand volume; correct orthostasis pre-op.","SURGERY definitive – laparoscopic adrenalectomy at high-volume centre; stress-dose steroid if bilateral.","Hypertensive crisis: IV PHENTOLAMINE or nitroprusside; lifelong biochemical + genetic surveillance."], ix: ["Plasma free metanephrines OR 24h urinary fractionated metanephrines/catecholamines","CT or MRI abdomen/pelvis for localisation","123I-MIBG or 68Ga-DOTATATE PET if metastatic/extra-adrenal/multifocal","ECG + echo – catecholamine cardiomyopathy","Germline genetic testing (SDHx, RET, VHL, NF1) – ~40% hereditary"], dispo: "Refer endocrinology + experienced adrenal surgeon; elective resection only after full alpha-blockade.", src: "Harrison 22e - Endocrine Society Pheochromocytoma/Paraganglioma CPG (2014)" },
    "pituitary_tumor_syndromes": { name: "Pituitary Tumor Syndromes", class: "non_infective", system: "Endocrine", dx: "Confirm on pituitary MRI (adenoma/sella mass) plus hormonal profiling showing hyper- or hyposecretion.", tx: ["PROLACTINOMA – CABERGOLINE first-line (dopamine agonist); surgery only if intolerant/resistant or apoplexy.","Acromegaly/Cushing's/compressive non-functioning tumour – TRANSSPHENOIDAL SURGERY first-line (expert centre).","Persistent acromegaly – somatostatin analogue / pegvisomant; persistent Cushing's – steroidogenesis inhibitor (ketoconazole/metyrapone/osilodrostat) or pasireotide; RADIOTHERAPY if refractory.","Replace deficits – HYDROCORTISONE before levothyroxine; add sex steroids / GH / desmopressin as needed.","APOPLEXY = emergency – IV hydrocortisone + urgent neurosurgical decompression if visual loss or reduced GCS."], ix: ["Pituitary MRI with contrast (dedicated sella protocol)","Serum prolactin (with dilution to exclude hook effect)","IGF-1 + OGTT-GH suppression; 24h urinary free cortisol / overnight dexamethasone","Anterior pituitary panel – 0900 cortisol/ACTH, TSH/free T4, LH/FSH, testosterone/oestradiol","Formal visual field perimetry"], dispo: "Endocrine–neurosurgery MDT; emergency referral for apoplexy or acute visual field loss.", src: "Harrison 22e - Pituitary Society International Consensus (Prolactinoma, 2023)" },
    "thyroid_cancer": { name: "Thyroid Nodular Disease and Cancer", class: "non_infective", system: "Endocrine", dx: "US-guided FNA cytology (Bethesda) of a sonographically suspicious nodule confirms malignancy; post-excision histology is definitive.", tx: ["CHECK serum TSH first — if suppressed, radionuclide scan; autonomous \"hot\" nodule → treat as hyperthyroid, skip FNA.","US-GUIDED FNA per TI-RADS/ATA pattern + size — benign → surveillance; malignant/suspicious → surgical referral.","SURGERY mainstay for DTC — lobectomy (low-risk <4 cm) vs total thyroidectomy (>4 cm/high-risk/node+/bilateral).","RADIOIODINE (¹³¹I) ablation post-total-thyroidectomy in intermediate–high-risk; then LEVOTHYROXINE for TSH suppression.","MONITOR thyroglobulin + anti-Tg + neck US; RAI-refractory/metastatic → lenvatinib/sorafenib; medullary → total thyroidectomy + central node dissection."], ix: ["Serum TSH (± free T4); if suppressed, ¹²³I/⁹⁹ᵐTc radionuclide uptake scan","Neck ultrasound — TI-RADS/ATA sonographic risk pattern + regional lymph nodes","US-guided FNA cytology, reported by Bethesda category","Serum calcitonin/CEA if medullary suspected; molecular panel for indeterminate (Bethesda III/IV) cytology","Post-op thyroglobulin + anti-Tg antibodies; whole-body RAI scan for staging/surveillance"], dispo: "Refer thyroid/endocrine MDT — suspicious/malignant cytology → surgery; benign → interval US surveillance; anaplastic → urgent same-day MDT.", src: "Harrison 22e - ATA 2015 guidelines (thyroid nodules & differentiated thyroid cancer)" },
    "disorders_of_the_testes_and": { name: "Disorders of the Testes and Male Reproductive System", class: "non_infective", system: "Endocrine / Male Reproductive", dx: "Confirm male hypogonadism: unequivocally low morning (8–10am) fasting total testosterone on ≥2 occasions plus consistent symptoms; then LH/FSH to localise (primary testicular vs secondary/central).", tx: ["Confirm LOW MORNING TESTOSTERONE ×2 + symptoms before treating; exclude reversible/systemic illness, drugs, obesity.","TESTOSTERONE replacement (transdermal gel or IM enanthate/cypionate), titrate to mid-normal range; do NOT start if baseline Hct >48–50%.","Fertility wanted — AVOID exogenous testosterone; SECONDARY: hCG ± FSH or pulsatile GnRH; PRIMARY: gonadotrophins futile — sperm retrieval/ART or donor.","Low gonadotrophins — pituitary MRI; CABERGOLINE first-line for prolactinoma (incl. macro); surgery only if DA-resistant/intolerant or compressive non-prolactin mass.","Monitor testosterone, haematocrit (stop if >54%), PSA/prostate; contraindicated in prostate/breast Ca, untreated severe OSA."], ix: ["Morning fasting total testosterone ×2 (free/bioavailable T if borderline or abnormal SHBG)","LH, FSH — distinguish primary from secondary hypogonadism","Prolactin, iron studies/ferritin (haemochromatosis); pituitary MRI if low gonadotrophins","Baseline haematocrit, PSA (age >40), DXA bone densitometry","Semen analysis and karyotype (Klinefelter) if infertility/azoospermia"], dispo: "Outpatient endocrine follow-up; reassess symptoms, T, Hct and PSA at 3–6 months then annually.", src: "Harrison 22e - Endocrine Society Testosterone Therapy in Men with Hypogonadism (2018)" },
    "diabetes_mellitus": { name: "Diabetes Mellitus", class: "non_infective", system: "Endocrine / Metabolic", dx: "Confirm with HbA1c >=6.5%, FPG >=7.0 mmol/L (126 mg/dL), 2-h OGTT >=11.1, or random >=11.1 with symptoms — repeat to confirm unless unequivocal hyperglycaemia.", tx: ["LIFESTYLE + METFORMIN first-line for T2DM; titrate to individualised HbA1c (~7%).","Add SGLT2i or GLP-1 RA early if ASCVD, HF or CKD – organ protection trumps glucose.","INSULIN mandatory in T1DM (basal–bolus); use in T2DM if very high HbA1c or symptomatic/catabolic.","Screen + treat complications: annual retinal/foot/urine ACR; statin + BP and RAAS control.","Teach hypoglycaemia; relax targets in frail/elderly; DKA/HHS – IV fluids + insulin urgently."], ix: ["HbA1c","Fasting plasma glucose ± OGTT","Fasting lipid profile","Renal function + urine albumin:creatinine ratio","Dilated fundoscopy + foot/neuropathy exam (C-peptide/GAD antibodies if type unclear)"], dispo: "Outpatient chronic diabetes care; admit for DKA/HHS, severe hypo-/hyperglycaemia or acute complication.", src: "Harrison 22e - ADA Standards of Care in Diabetes 2025" },
    "dyslipidemia": { name: "Dyslipidemia", class: "non_infective", system: "Endocrine / Metabolic", dx: "Lipid panel showing raised LDL-C/non-HDL-C or triglycerides (or low HDL-C), confirmed on repeat, with formal cardiovascular risk stratification.", tx: ["LIFESTYLE first — Mediterranean diet, exercise, weight loss, stop smoking, limit alcohol.","HIGH-INTENSITY STATIN (atorvastatin 40–80 / rosuvastatin 20–40 mg) if ASCVD or LDL ≥4.9 mmol/L.","Add EZETIMIBE then PCSK9 inhibitor if LDL goal unmet in high/very-high risk.","FENOFIBRATE or icosapent ethyl if TG ≥5.6 mmol/L — prevent pancreatitis.","Recheck lipids 4–12 wks; monitor LFTs/CK if myalgia; exclude secondary causes."], ix: ["Fasting lipid profile — TC, LDL-C, HDL-C, triglycerides, non-HDL-C","10-year ASCVD / SCORE2 cardiovascular risk estimation","HbA1c/glucose, TSH, U&E, LFTs — screen secondary causes","Lp(a) once in lifetime; apoB if raised TG or diabetes","Urinalysis for proteinuria (nephrotic syndrome)"], dispo: "Outpatient; refer lipid clinic for familial hypercholesterolaemia, statin intolerance or refractory levels.", src: "Harrison 22e - 2018 ACC/AHA Multisociety Cholesterol Guideline" },
    "evaluation_and_management_of_obesity": { name: "Evaluation and Management of Obesity", class: "non_infective", system: "Endocrine / Metabolic", dx: "Clinical: BMI >=30 kg/m² (or >=27 with weight-related complication); add waist circumference and ABCD complication staging.", tx: ["LIFESTYLE first – hypocaloric diet + activity + behavioural support; target >=5–10% loss.","Add incretin therapy if BMI>=30 or >=27+comorbidity: SEMAGLUTIDE (GLP-1 RA) or TIRZEPATIDE (dual GIP/GLP-1); slow titrate for GI tolerance.","Prefer semaglutide/tirzepatide when type 2 diabetes coexists; alternatives phentermine–topiramate (teratogenic, caution CVD), naltrexone–bupropion (avoid seizure disorder / uncontrolled HTN / chronic opioids), orlistat (fat-soluble vitamin malabsorption).","BARIATRIC/METABOLIC SURGERY if BMI>=40, or >=35 with comorbidity / drug failure; consider >=30–34.9 with poorly controlled T2DM (ASMBS/IFSO 2022).","Long-term therapy – monitor weight, HbA1c, BP, lipids; expect regain on stopping."], ix: ["Fasting glucose / HbA1c","Fasting lipid profile","LFTs (screen MASLD/NAFLD)","TSH (exclude hypothyroidism)","BP + waist circumference; sleep study if OSA suspected"], dispo: "Outpatient chronic-disease model with regular follow-up; refer obesity/bariatric specialist if BMI>=40 or refractory.", src: "Harrison 22e; AACE 2025 Obesity/ABCD Algorithm; ASMBS/IFSO 2022 surgical criteria" },
    "obesity": { name: "Obesity", class: "non_infective", system: "Endocrine / Metabolic", dx: "Diagnose by BMI ≥30 kg/m² (≥27.5 in South Asians) plus waist circumference; stage by obesity-related complications.", tx: ["LIFESTYLE first – 500–750 kcal/day deficit, ≥150 min/week activity, behavioural therapy; target 5–10% loss.","INCRETIN Rx – semaglutide (GLP-1 RA) or tirzepatide (dual GIP/GLP-1 agonist) if BMI ≥30 (≥27 + comorbidity); most effective pharmacotherapy. Avoid if personal/family Hx medullary thyroid ca or MEN2; stop before planned pregnancy.","Alternatives – orlistat; phentermine–topiramate (topiramate teratogenic – avoid in pregnancy); naltrexone–bupropion (avoid in uncontrolled HTN, seizures, chronic opioids); match to comorbidity/contraindications.","BARIATRIC SURGERY if BMI ≥40 (or ≥35 + comorbidity; lower thresholds in Asians and per newer ASMBS/IFSO criteria); most durable – refer specialist centre.","Treat comorbidities – T2DM, HTN, dyslipidaemia, OSA, NAFLD; monitor micronutrients post-surgery. All anti-obesity drugs contraindicated in pregnancy."], ix: ["Fasting glucose / HbA1c","Fasting lipid profile","LFTs + hepatic imaging for NAFLD","TSH (± cortisol if Cushing suspected)","BP, OSA screen (Epworth/sleep study)"], dispo: "Outpatient endocrine/obesity clinic; multidisciplinary follow-up; surgical referral if criteria met.", src: "Harrison 22e – AACE/ACE Obesity Clinical Practice Guidelines" },
    "parathyroid_calcium_disorders": { name: "Parathyroid & Calcium Disorders", class: "non_infective", system: "Endocrine / Metabolic", dx: "Measure corrected/ionised calcium with simultaneous intact PTH: high/inappropriately-normal PTH = primary hyperparathyroidism; suppressed PTH with high Ca = malignancy/non-PTH cause; low Ca with low PTH = hypoparathyroidism.", tx: ["IV NORMAL SALINE 200-300 mL/h first for severe/symptomatic hypercalcaemia to restore volume + diuresis.","ZOLEDRONIC ACID after rehydration to lower Ca over 2-4 days; add calcitonin for rapid short-term drop.","DENOSUMAB if bisphosphonate-refractory or eGFR<30; always treat underlying cause (malignancy/PHPT).","PARATHYROIDECTOMY definitive for PHPT if symptomatic or Ca>0.25 mmol/L above ULN, eGFR<60, osteoporosis/fracture, age<50.","Acute hypocalcaemia/tetany: IV CALCIUM gluconate; then oral calcium + calcitriol, and correct magnesium."], ix: ["Corrected/ionised calcium + intact PTH (paired)","Phosphate, magnesium, ALP, 25-OH vitamin D","U&E/eGFR + 24h urinary calcium (exclude FHH)","ECG (short/long QT, arrhythmia)","Localisation for PHPT: sestamibi + neck USS; DXA for bone status"], dispo: "Admit if Ca>3.5 mmol/L, hypercalcaemic crisis or symptomatic hypocalcaemia; refer endocrine/surgery for PHPT.", src: "Harrison 22e - 2022 International Workshop Guidelines on Primary Hyperparathyroidism" },
    "osteoporosis": { name: "Osteoporosis", class: "non_infective", system: "Endocrine / Metabolic Bone", dx: "Confirm on DXA T-score <=-2.5 (lumbar spine/hip) or prior fragility fracture (hip/vertebra) regardless of T-score.", tx: ["CALCIUM 1000-1200mg + VITAMIN D 800-1000IU daily; weight-bearing exercise, fall prevention, stop smoking/alcohol.","ORAL BISPHOSPHONATE (alendronate/risedronate) first-line; IV zoledronate if intolerant/poor adherence; DENOSUMAB preferred in CKD - AVOID bisphosphonates if eGFR <30-35 (denosumab needs close Ca monitoring in advanced CKD).","Very-high risk or severe/multiple vertebral fractures: ANABOLIC first - teriparatide/abaloparatide or ROMOSOZUMAB - then follow with antiresorptive.","Correct vitamin D + dental review before starting (ONJ/hypocalcaemia); NEVER stop denosumab abruptly - rebound fractures, bridge to bisphosphonate.","Exclude secondary causes; reassess with DXA 1-2 yearly and re-stratify fracture risk (FRAX)."], ix: ["DXA (lumbar spine + hip); consider lateral spine X-ray/VFA for vertebral fractures","Serum calcium, phosphate, alkaline phosphatase, renal function/eGFR","25-OH vitamin D and PTH","TSH; testosterone in men; coeliac serology","Myeloma screen (SPEP) + FBC/ESR if unexplained; consider bone turnover markers"], dispo: "Outpatient; refer to Fracture Liaison Service / bone clinic after fragility fracture.", src: "Harrison 22e - Endocrine Society Clinical Practice Guideline (Pharmacological Management of Osteoporosis, 2020)" },
    "pagets_disease_bone": { name: "Paget's Disease of Bone", class: "non_infective", system: "Endocrine / Metabolic Bone", dx: "Raised serum total/bone-specific ALP with normal calcium; confirm with plain radiographs (osteolysis, cortical thickening, bony expansion) and a radionuclide bone scan to map extent.", tx: ["IV ZOLEDRONIC ACID 5 mg single infusion – first-line; treat symptomatic/active disease, high ALP, or pre-elective orthopaedic surgery.","Correct vitamin D + calcium BEFORE infusion – prevents post-dose hypocalcaemia; oral risedronate 30 mg/day x2 months if IV unsuitable.","ANALGESIA/NSAIDs for bone pain; manage secondary OA of adjacent joints.","MONITOR total ALP at 6–12 weeks then periodically – normalisation = remission; retreat when ALP rises.","REFER orthopaedics/neurosurgery for fracture, deformity, spinal stenosis or nerve/cord compression; new focal pain → exclude osteosarcoma."], ix: ["Serum total ALP (± bone-specific ALP / P1NP) – disease activity","Serum calcium, phosphate, 25-OH vitamin D, U&E","Plain radiographs of affected/symptomatic bones","Technetium radionuclide bone scan – define monostotic vs polyostotic extent","Audiometry if skull involvement; imaging of any rapidly worsening focal pain"], dispo: "Outpatient endocrine/metabolic-bone follow-up; day-case for zoledronate infusion with ALP surveillance.", src: "Harrison 22e – Endocrine Society Clinical Practice Guideline (Paget's Disease of Bone, 2014)" },
    "menopause_and_postmenopausal_hormone_thera": { name: "Menopause and Postmenopausal Hormone Therapy", class: "non_infective", system: "Endocrine / Reproductive", dx: "Clinical diagnosis: ≥12 months amenorrhoea (mean age ~51) with vasomotor/genitourinary symptoms; FSH not needed if typical age, useful if <45 or ambiguous.", tx: ["ESTROGEN (systemic) — first-line for moderate–severe vasomotor symptoms; ADD PROGESTOGEN if uterus intact to protect endometrium.","Prefer TRANSDERMAL estradiol (patch/gel) — lower VTE/stroke risk; lowest effective dose; duration INDIVIDUALISED (NAMS 2022 — no arbitrary cap/stopping age); start within 10 yr of menopause / <60 yr ('window').","VAGINAL low-dose estrogen for isolated genitourinary syndrome — no systemic progestogen needed; ospemifene/moisturisers as alternatives.","NON-HORMONAL if HT contraindicated — SSRI/SNRI (venlafaxine; paroxetine — but AVOID with tamoxifen, CYP2D6 inhibition), gabapentin, or FEZOLINETANT (NK3 antagonist; baseline + periodic LFTs, avoid in hepatic impairment); avoid HT in breast/endometrial Ca, VTE, CAD, stroke, unexplained vaginal bleeding, active liver disease.","MONITOR — annual review of benefit/risk, BP, mammography; counsel small increased breast Ca (combined) and VTE risk; add calcium/vit D + bone protection."], ix: ["FSH ± estradiol only if diagnosis uncertain or age <45","TSH to exclude thyroid mimic of vasomotor symptoms","Baseline mammography and cervical screening up to date","Lipids, glucose, BP; VTE risk assessment before HT","Bone density (DXA) if osteoporosis risk factors"], dispo: "Outpatient — primary care/gynae/endocrine; review at 3 months then annually to reassess indication.", src: "Harrison 22e - NAMS/Menopause Society 2022 Hormone Therapy Position Statement" },
    "diabetes_mellitus_management_and_therapies": { name: "Diabetes Mellitus: Management and Therapies", class: "non_infective", system: "Endocrine/Metabolic", dx: "Confirm with HbA1c >=6.5%, fasting glucose >=126 mg/dL, 2-h OGTT >=200, or random >=200 with symptoms – repeat unless unequivocal hyperglycaemia.", tx: ["METFORMIN + lifestyle first-line in T2DM (avoid/hold if eGFR <30); individualise HbA1c target (~7%).","Add SGLT2i or GLP-1 RA early if ASCVD/HF/CKD – regardless of HbA1c.","Escalate stepwise: SGLT2i/GLP-1/sulfonylurea/basal INSULIN to target; hold SGLT2i when acutely ill/fasting/peri-op (euglycaemic DKA).","T1DM: basal-bolus INSULIN lifelong – never omit; MDI or pump. SGLT2i not for T1DM glycaemic control.","Statin + BP control (ACE/ARB if albuminuria); screen eyes/feet/renal annually; treat hypoglycaemia.","Pregnancy/pre-conception: switch to INSULIN; stop statin, ACE/ARB, SGLT2i and GLP-1 RA."], ix: ["HbA1c (3-monthly until stable, then 6-monthly) + fasting glucose","Renal function: eGFR + urine albumin-creatinine ratio","Fasting lipid profile","Dilated retinal exam + comprehensive foot exam","BP; screen for neuropathy"], dispo: "Outpatient chronic care; admit for DKA/HHS, severe hypoglycaemia or intercurrent illness.", src: "Harrison 22e - ADA Standards of Care in Diabetes 2025" },
    "glycogen_storage_diseases_and_other": { name: "Glycogen Storage Diseases and Other Inherited Disorders of Carbohydrate Metabolism", class: "non_infective", system: "Endocrine/Metabolic", dx: "Confirm by specific enzyme activity assay (leucocytes/fibroblasts/muscle or liver biopsy) plus molecular genetic testing identifying the causative mutation.", tx: ["PREVENT HYPOGLYCAEMIA (hepatic GSD I/III) — frequent complex-carb feeds + uncooked CORNSTARCH; overnight NG/pump feeds in infants.","RESTRICT the offending sugar — galactose-free diet (galactosaemia); fructose/sucrose/sorbitol-free (HFI); avoid prolonged fasting.","POMPE — start ENZYME REPLACEMENT early: alglucosidase/avalglucosidase alfa IV 2-weekly; screen/treat cardiomyopathy.","Treat GSD I complications — ALLOPURINOL for hyperuricaemia, statin/fibrate for hyperlipidaemia, citrate for acidosis, ACEi for nephropathy.","REFER metabolic/genetics + dietitian; liver transplant for adenoma/HCC or refractory disease; genetic counselling for family."], ix: ["Fasting/postprandial glucose, lactate, uric acid, fasting lipids","LFTs, CK (muscle GSD), venous blood gas (metabolic acidosis)","Enzyme activity assay (leucocytes/fibroblasts/muscle/liver)","Molecular genetic panel for causative mutation","Abdominal USS (hepatomegaly/adenomata) +/- echo (Pompe cardiomyopathy)"], dispo: "Lifelong specialist metabolic-clinic follow-up with dietitian and genetic counselling.", src: "Harrison 22e - ACMG GSD type I diagnosis & management guideline (Kishnani, Genet Med 2014)" },
    "the_metabolic_syndrome": { name: "The Metabolic Syndrome", class: "non_infective", system: "Endocrine/Metabolic", dx: "Clinical cluster — diagnose if ≥3 of 5 harmonised criteria: raised waist circumference (ethnicity-specific), TG ≥1.7 mmol/L, HDL <1.0 (M)/<1.3 (F), BP ≥130/85, fasting glucose ≥5.6 mmol/L.", tx: ["LIFESTYLE is first-line — ≥7% weight loss, ≥150 min/wk activity, Mediterranean/calorie-reduced diet, stop smoking.","TREAT BP to <130/80 — ACEi or ARB preferred (metabolically neutral, renoprotective).","STATIN per ASCVD risk for LDL; add fibrate (fenofibrate, not gemfibrozil, with a statin)/high-dose omega-3 if TG >5.6 (pancreatitis risk).","METFORMIN if IFG/IGT persists despite lifestyle; favour GLP-1 agonist or SGLT2i when obese/diabetic for weight + CV benefit.","Low-dose ASPIRIN only in established ASCVD; screen and treat NAFLD, hyperuricaemia."], ix: ["Fasting glucose + HbA1c (± OGTT if borderline)","Fasting lipid profile (TG, HDL, LDL)","Waist circumference + resting BP","LFTs/USS for NAFLD; serum urate","10-year ASCVD risk score"], dispo: "Outpatient — annual cardiometabolic and diabetes surveillance; refer endocrinology/cardiology if refractory or established disease.", src: "Harrison 22e - AHA/NHLBI Scientific Statement on Metabolic Syndrome (harmonised 2009 IDF/AHA/NHLBI criteria)" },
    "diabetes_mellitus_complications": { name: "Diabetes Mellitus: Complications", class: "non_infective", system: "Endocrine/Metabolic (multisystem)", dx: "Complications confirmed by targeted screening — dilated fundoscopy, urine albumin:creatinine + eGFR, 10g monofilament/vibration, ABI/ECG.", tx: ["GLYCAEMIC + BP control — HbA1c <7%, BP <130/80; slows micro- and macrovascular progression.","ACE-I/ARB first-line for albuminuria (do NOT combine); add SGLT2 INHIBITOR for renoprotection + CV/HF benefit.","STATIN — moderate-intensity for primary prevention age 40-75, high-intensity for established ASCVD/high risk; add GLP-1 RA if established CVD or obesity.","Annual RETINAL screen — laser/anti-VEGF for proliferative disease; foot exam + offload/debride ulcers.","Painful neuropathy — DULOXETINE/pregabalin; screen autonomic dysfunction; podiatry for at-risk feet."], ix: ["HbA1c + fasting glucose","Urine albumin:creatinine ratio + serum creatinine/eGFR","Fasting lipid profile","Dilated fundus examination (annual)","10g monofilament + vibration; ABI/ECG if macrovascular suspected"], dispo: "Multidisciplinary outpatient follow-up; urgent ophthalmology for sight-threatening retinopathy, nephrology for falling eGFR, admit infected/ischaemic foot.", src: "Harrison 22e - ADA Standards of Care in Diabetes 2025" },
    "CARCINOID_SYNDROME": { name: "Carcinoid syndrome", class: "non_infective", system: "Endocrinology", dx: "Clinical flushing/diarrhoea + raised 24-h urinary 5-HIAA and plasma chromogranin A, with NET localised on imaging.", tx: ["SOMATOSTATIN ANALOGUE first-line - octreotide LAR / lanreotide: controls flushing + diarrhoea, antiproliferative.","Carcinoid crisis: IV OCTREOTIDE bolus + infusion; avoid catecholamines; give prophylaxis before surgery/anaesthesia/PRRT.","TELOTRISTAT ethyl add-on for SSA-refractory diarrhoea; loperamide symptomatic; avoid triggers (alcohol, exertion).","Tumour-directed: surgical debulk, hepatic-artery embolisation, PRRT (177Lu-DOTATATE), everolimus / IFN-alpha.","Screen carcinoid heart disease - echo + NT-proBNP; supplement niacin for pellagra; refer NET MDT."], ix: ["24-h urinary 5-HIAA","Plasma chromogranin A","CT/MRI abdomen-pelvis for primary + liver mets","68Ga-DOTATATE PET (somatostatin-receptor imaging)","Echocardiography + NT-proBNP"], dispo: "Refer to neuroendocrine-tumour MDT; outpatient SSA with written crisis-prophylaxis plan.", src: "Harrison 22e - NANETS neuroendocrine tumour consensus guidelines" },
    "INSULINOMA": { name: "Insulinoma", class: "non_infective", system: "Endocrinology", dx: "72-h supervised fast documenting Whipple triad with inappropriately raised insulin, C-peptide and proinsulin during hypoglycaemia, negative sulfonylurea screen.", tx: ["IV DEXTROSE for acute neuroglycopenia; frequent complex-carb feeds to abort fasting hypoglycaemia.","SURGICAL RESECTION (enucleation/pancreatectomy) – curative for benign solitary tumour; localise pre-op.","DIAZOXIDE to suppress insulin if surgery delayed/unfit/inoperable; add thiazide for fluid retention.","Octreotide/lanreotide if SSTR-positive; everolimus, sunitinib, PRRT or chemo for malignant/metastatic disease.","Screen for MEN1 if multiple/recurrent/young – genetic testing + parathyroid/pituitary workup."], ix: ["72-h supervised fast – paired glucose, insulin, C-peptide, proinsulin","Sulfonylurea/meglitinide screen + insulin antibodies (exclude factitious/autoimmune)","Contrast-enhanced CT or MRI pancreas for localisation","Endoscopic ultrasound for small intrapancreatic lesions","SSTR or GLP-1-receptor functional imaging if anatomic imaging negative"], dispo: "Refer to endocrine surgery/NET MDT; admit if severe or recurrent neuroglycopenia.", src: "Harrison 22e - ENETS pancreatic NET consensus guidelines" },
    "PRIMARY_ALDOSTERONISM": { name: "Primary aldosteronism (Conn syndrome)", class: "non_infective", system: "Endocrinology", dx: "Confirm with raised aldosterone-to-renin ratio, then a confirmatory suppression test (saline infusion/oral salt loading) showing non-suppressible aldosterone; subtype with adrenal CT + adrenal venous sampling.", tx: ["CORRECT HYPOKALAEMIA and control BP first; stop MRA/spironolactone ~4-6 wks before ARR screening.","LATERALISE by adrenal venous sampling before surgery - CT alone misclassifies, esp. age >35.","Unilateral APA -> LAPAROSCOPIC ADRENALECTOMY; cures/improves HTN + hypokalaemia.","Bilateral (IHA)/non-surgical -> SPIRONOLACTONE first-line MRA; eplerenone if gynaecomastia/side-effects.","Monitor K+, creatinine, BP on MRA; post-adrenalectomy watch transient hyperkalaemia/hypoaldosteronism."], ix: ["Plasma aldosterone + renin -> aldosterone-to-renin ratio (screen, off interfering drugs)","Confirmatory test: saline infusion / oral sodium loading / captopril challenge","Serum potassium (+ correct), sodium, creatinine, eGFR","Adrenal CT (thin-section) for morphology/adrenocortical carcinoma","Adrenal venous sampling to lateralise if surgery contemplated"], dispo: "Refer Endocrinology; surgery if lateralised, else lifelong MRA with BP/electrolyte monitoring.", src: "Harrison 22e - Endocrine Society Clinical Practice Guideline (Primary Aldosteronism, 2016)" },
    "hypothermia_and_peripheral_cold_injuries": { name: "Hypothermia and Peripheral Cold Injuries", class: "non_infective", system: "Environmental / Multisystem", dx: "Core temperature <35°C on low-reading rectal/oesophageal probe with Swiss clinical staging; frostbite graded by post-rewarming tissue appearance/perfusion.", tx: ["REWARMING — strip wet clothing, insulate (passive); active core: warmed humidified O2 + warmed (40–42°C) IV crystalloid.","Handle gently, minimal movement — cold myocardium prone to VF; continuous core-temp + ECG.","Arrest/haemodynamic instability → ECMO/cardiopulmonary bypass rewarming (first-line); if core <30°C limit defibrillation to a single shock and withhold/space epinephrine + antiarrhythmics until core >30°C; else forced-air blanket + warm cavity lavage.","FROSTBITE: RAPID REWARM in 37–39°C water until thawed (~15–30 min); ibuprofen (NSAID antiprostaglandin) + analgesia; do NOT rub / no dry heat; iloprost and/or tPA for deep injury <24 h; never refreeze.","Don't declare death until rewarmed (core ≥32°C) — 'not dead until warm and dead'; K>12 mmol/L suggests non-survivable."], ix: ["Continuous core temperature (oesophageal/rectal low-reading probe)","ECG — Osborn J waves, bradyarrhythmia, VF risk","Bloods: glucose, U&E, ABG, coagulation, CK, lactate","Point-of-care K+ (prognostic, guides termination of resuscitation)","Frostbite: angiography/Tc-99 bone scan for tissue perfusion; screen tox/TFT/cortisol if unexplained"], dispo: "Severe/unstable → ICU with ECMO capability; deep frostbite → plastics/vascular; mild rewarmed & stable may be observed/discharged.", src: "Harrison 22e - Wilderness Medical Society (WMS) accidental hypothermia & frostbite guidelines" },
    "altitude_illness": { name: "Altitude Illness", class: "non_infective", system: "Environmental / Multisystem (Neurologic-Pulmonary)", dx: "Clinical: recent ascent >2500 m + headache/GI/dizziness (AMS by Lake Louise score); HACE = ataxia/altered mentation; HAPE = dyspnoea at rest, cough, hypoxaemia, rales/frothy sputum.", tx: ["DESCEND immediately for HACE/HAPE or severe AMS (500-1000 m or to symptom relief) - non-negotiable.","OXYGEN + portable hyperbaric bag if descent delayed/impossible; target SpO2 >90%.","HACE: DEXAMETHASONE 8 mg then 4 mg q6h; AMS: dexamethasone and/or ACETAZOLAMIDE 250 mg bd.","HAPE: NIFEDIPINE XR 30 mg bd (+ oxygen); avoid over-exertion; PDE5 inhibitor (tadalafil/sildenafil) as ALTERNATIVE - do not combine with nifedipine.","PREVENT: gradual ascent, ACETAZOLAMIDE 125 mg bd prophylaxis (avoid in pregnancy; caution sulfonamide allergy); do not ascend with symptoms."], ix: ["SpO2 / pulse oximetry (hypoxaemia disproportionate to altitude in HAPE)","Clinical neuro exam incl. gait/ataxia testing (HACE)","Chest auscultation +/- CXR - patchy asymmetric infiltrates in HAPE","Lake Louise AMS score for severity/monitoring","Consider CT/MRI or bloods only to exclude mimics if diagnosis unclear"], dispo: "Mild AMS: rest/treat at altitude, no further ascent; HACE/HAPE or severe AMS: urgent descent + hospital/critical-care.", src: "Harrison 22e - Wilderness Medical Society (WMS) Clinical Practice Guidelines for Acute Altitude Illness" },
    "hyperbaric_and_diving_medicine": { name: "Hyperbaric and Diving Medicine", class: "non_infective", system: "Environmental and Occupational Medicine", dx: "Clinical: decompression illness after diving/decompression — DCS (limb/joint pain, neuro deficits, skin marbling, pulmonary \"chokes\") evolving over minutes–hours, or arterial gas embolism (sudden neuro/cardiac collapse within minutes of surfacing).", tx: ["100% NORMOBARIC O2 immediately via tight-seal non-rebreather; keep patient supine/horizontal.","RECOMPRESSION (hyperbaric O2) is definitive — US Navy Treatment Table 6 for DCS/AGE; do not delay for imaging.","IV isotonic crystalloid for diving-related dehydration; treat seizures/airway as needed.","Call DAN emergency hotline; arrange urgent transfer to nearest recompression chamber.","If air evacuation unavoidable, cabin altitude <=610 m (2000 ft) or sea-level pressurisation."], ix: ["Full neurological examination (baseline + serial)","SpO2 and ABG","CXR to exclude pneumothorax/pulmonary barotrauma","ECG (esp. suspected AGE)","Bloods incl. haematocrit (haemoconcentration) and glucose"], dispo: "Admit; urgent hyperbaric referral; neuro follow-up and diving-fitness reassessment before return to diving/flying.", src: "Harrison 22e - UHMS (Undersea & Hyperbaric Medical Society) / US Navy Treatment Tables" },
    "heat_related_illnesses": { name: "Heat-Related Illnesses", class: "non_infective", system: "Environmental/Thermoregulatory", dx: "Heat stroke = core temp >40°C (>104°F) plus CNS dysfunction (delirium/seizure/coma) after heat exposure or exertion; heat exhaustion if mentation intact and temp <40°C.", tx: ["COOL FIRST — ice-/cold-water immersion; target core <39°C within 30 min ('cool first, transport second').","If no immersion — aggressive evaporative cooling: tepid mist + fans + ice packs to neck/axillae/groin.","ABC + IV crystalloid for hypotension; give fluids cautiously in exertional (cooling alone often corrects).","STOP cooling at ~38.9°C to avoid overshoot; benzodiazepines for seizures/shivering; AVOID antipyretics + dantrolene (ineffective).","Monitor/treat rhabdomyolysis, AKI, DIC, hepatic failure + electrolytes; ICU admit for heat stroke."], ix: ["Core (rectal/oesophageal) temperature — continuous","U&E, creatinine, glucose","CK (rhabdomyolysis screen)","LFTs + coagulation (INR/platelets/fibrinogen for DIC)","ABG/lactate + ECG"], dispo: "Heat stroke → ICU admission; heat exhaustion → rehydrate, observe, discharge on recovery.", src: "Harrison 22e - Wilderness Medical Society (WMS) Heat Illness CPG 2019" },
    "chronic_pancreatitis": { name: "Chronic Pancreatitis", class: "non_infective", system: "Gastroenterology", dx: "Confirm on CT/MRCP showing pancreatic calcification, ductal dilatation or gland atrophy; EUS if imaging equivocal.", tx: ["STOP ALCOHOL and SMOKING – halts progression; single most important step.","ANALGESIA stepwise – paracetamol/NSAID first; add pregabalin or TCA for neuropathic pain; opioids sparingly.","PANCREATIC ENZYME REPLACEMENT (PERT) + PPI for steatorrhoea/weight loss; small frequent meals with adequate PERT (NO routine fat restriction); replace fat-soluble vitamins.","Treat type 3c (pancreatogenic) DIABETES – insulin usually needed; watch brittle hypoglycaemia.","ENDOSCOPY/SURGERY if refractory pain or obstruction – ductal decompression, coeliac plexus block, drainage/resection."], ix: ["CT abdomen – calcification, ductal changes, exclude mass/malignancy","MRCP +/- secretin – ductal anatomy and strictures","Faecal elastase-1 – exocrine insufficiency","HbA1c/fasting glucose – endocrine insufficiency","Fat-soluble vitamins (A,D,E,K) +/- serum IgG4 to exclude autoimmune"], dispo: "Outpatient GI follow-up; refer to pancreatic centre for refractory pain, suspected malignancy or planned intervention.", src: "Harrison 22e - ACG Clinical Guideline: Chronic Pancreatitis (2020)" },
    "CELIAC_DISEASE": { name: "Coeliac disease", class: "non_infective", system: "Gastroenterology", dx: "Confirm with anti-tTG IgA (+ total IgA) then duodenal biopsy showing villous atrophy (Marsh) while on a gluten-containing diet.", tx: ["Strict lifelong GLUTEN-FREE DIET – exclude wheat/barley/rye; early dietitian referral.","Correct deficiencies – IRON, folate, B12, vitamin D, calcium.","DEXA + bone protection; PNEUMOCOCCAL vaccine (functional hyposplenism).","Monitor tTG-IgA + symptoms to confirm adherence/mucosal response.","Non-responder → re-check adherence/diagnosis; work up REFRACTORY CD / EATL + specialist referral."], ix: ["Anti-tTG IgA + total IgA (first-line serology)","IgG-based serology (IgG-DGP and/or IgG-tTG) if IgA-deficient","Duodenal biopsy (≥4 distal + bulb) – Marsh grading","FBC, ferritin, folate, B12, vitamin D, calcium; LFTs","HLA-DQ2/DQ8 (high NPV to exclude) ± DEXA"], dispo: "Outpatient GI + dietitian; lifelong serological/clinical monitoring.", src: "Harrison 22e - ACG 2023 Coeliac Disease Guideline" },
    "diseases_of_esophagus": { name: "Diseases of the Esophagus", class: "non_infective", system: "Gastroenterology", dx: "Confirm with upper GI endoscopy + biopsy; add high-resolution manometry for suspected motility disorder and 24-h pH-impedance for refractory reflux.", tx: ["GORD: PPI once-daily 8 wk + weight loss / head-elevation / avoid late meals; then step down to lowest effective.","ACHALASIA: pneumatic dilatation or laparoscopic Heller myotomy / POEM; botulinum toxin if unfit for surgery.","EoE: swallowed topical STEROID (budesonide/fluticasone) or PPI trial; food-elimination diet; dilate tight strictures.","INFECTIVE oesophagitis: fluconazole (Candida), aciclovir (HSV), ganciclovir (CMV) - test for HIV/immunosuppression.","ALARM features (progressive dysphagia, weight loss, bleeding, anaemia) -> urgent endoscopy to exclude malignancy."], ix: ["Upper GI endoscopy with oesophageal biopsies (incl. EoE protocol)","High-resolution oesophageal manometry (Chicago classification)","Ambulatory 24-h pH-impedance study for refractory reflux","Barium oesophagram (bird-beak, stricture, ring, Zenker)","FBC + iron studies for anaemia"], dispo: "Most managed outpatient by gastroenterology; urgent endoscopy if alarm features; refer surgery/interventional for achalasia.", src: "Harrison 22e - ACG Clinical Guideline: Diagnosis and Management of GERD (2022)" },
    "diverticular_disease": { name: "Diverticular Disease", class: "non_infective", system: "Gastroenterology", dx: "Confirm acute diverticulitis on CT abdomen/pelvis with IV contrast – sigmoid wall thickening, pericolic fat stranding ± abscess/perforation.", tx: ["Uncomplicated mild: SUPPORTIVE – oral fluids + analgesia; omit routine antibiotics in immunocompetent.","ANTIBIOTICS (co-amoxiclav or ciprofloxacin+metronidazole) if sepsis, immunocompromised, or significant comorbidity.","Abscess >3–4 cm: CT-guided PERCUTANEOUS DRAINAGE + IV antibiotics; smaller → antibiotics alone.","Free perforation / faeculent peritonitis (Hinchey III–IV): urgent SURGERY – Hartmann's or resection.","Post-recovery: COLONOSCOPY at 6–8 weeks to exclude cancer; high-fibre diet; elective resection individualised."], ix: ["CT abdomen/pelvis with IV contrast (confirm + Hinchey stage)","FBC (leucocytosis) + CRP","U&E, LFTs, lactate if unwell","Urinalysis (exclude urinary source / colovesical fistula)","Interval colonoscopy 6–8 weeks after resolution"], dispo: "Mild uncomplicated – outpatient, review 48–72 h; complicated, septic, immunocompromised or failing oral intake – admit.", src: "Harrison 22e - ASCRS Clinical Practice Guidelines (Left-Sided Colonic Diverticulitis)" },
    "EOSINOPHILIC_ESOPHAGITIS": { name: "Eosinophilic oesophagitis", class: "non_infective", system: "Gastroenterology", dx: "Symptoms of oesophageal dysfunction plus ≥15 eosinophils/hpf on oesophageal biopsy, other causes excluded.", tx: ["PPI first-line — omeprazole 20–40 mg BD ×8 wk; rebiopsy to confirm histological response.","Swallowed topical CORTICOSTEROID — budesonide/fluticasone (not inhaled); no food/drink 30 min after.","DIET — six-food elimination (milk, wheat, egg, soy, nuts, seafood) with dietitian; stepwise reintroduction.","DUPILUMAB for refractory/steroid-dependent disease; endoscopic DILATION for strictures/food impaction.","Maintain long-term therapy — target remission (<15 eos/hpf); surveillance endoscopy."], ix: ["Upper GI endoscopy — rings, linear furrows, white exudates, strictures, crepe-paper mucosa.","Oesophageal biopsies — ≥6 (proximal + distal); ≥15 eos/hpf confirms diagnosis.","Exclude alternatives — GORD, infection, achalasia, secondary/systemic eosinophilia.","Allergy/atopy assessment (asthma, eczema, rhinitis); dietitian referral.","Barium oesophagram if stricture/narrow-calibre oesophagus suspected."], dispo: "Gastroenterology follow-up; long-term maintenance + surveillance endoscopy; urgent scope for food-bolus impaction.", src: "Harrison 22e - AGA/JTF 2020 EoE guideline" },
    "inflammatory_bowel_disease": { name: "Inflammatory Bowel Disease", class: "non_infective", system: "Gastroenterology", dx: "Ileocolonoscopy with biopsies confirming chronic inflammation – UC continuous from rectum; Crohn's transmural/skip lesions ± granulomas.", tx: ["MESALAZINE (5-ASA) oral + topical – first-line for mild–moderate UC induction and maintenance; add budesonide MMX if inadequate.","CORTICOSTEROIDS induce moderate–severe flares – never for maintenance; step up early to biologics (anti-TNF/vedolizumab/ustekinumab) ± thiopurine.","ACUTE SEVERE UC: admit, IV HYDROCORTISONE + VTE prophylaxis; rescue infliximab/ciclosporin day 3–5; urgent colectomy if refractory/toxic megacolon.","CROHN'S: treat-to-target mucosal healing – steroids/EEN induce, early biologics ± thiopurine maintain; surgery for stricture/fistula/abscess.","Before escalation: exclude C. difficile/CMV; screen TB + HBV, check TPMT; ongoing colonoscopic dysplasia surveillance."], ix: ["Faecal calprotectin (disease activity/monitoring)","Stool culture + C. difficile toxin (exclude infection)","FBC, CRP/ESR, albumin, ferritin/iron studies","Ileocolonoscopy + segmental biopsies","MR enterography for small-bowel Crohn's; plain film/CT if toxic megacolon"], dispo: "Outpatient GI clinic follow-up; admit acute severe colitis for IV steroids with early surgical co-review.", src: "Harrison 22e - ACG UC (2019)/CD (2018) guidelines" },
    "disorders_of_absorption": { name: "Malabsorption (Disorders of Absorption)", class: "non_infective", system: "Gastroenterology", dx: "Confirmed by demonstrating nutrient malabsorption (steatorrhoea/faecal fat) then localising cause — coeliac serology + duodenal biopsy, faecal elastase, breath tests; D-xylose separates mucosal from pancreatic cause.", tx: ["TREAT THE UNDERLYING CAUSE — cause-specific therapy drives outcome; correct deficiencies in parallel.","Coeliac → lifelong GLUTEN-FREE DIET; recheck serology/biopsy for mucosal response.","Pancreatic insufficiency → PANCREATIC ENZYME REPLACEMENT (PERT) with meals + acid suppression.","SIBO → RIFAXIMIN (or tetracycline/co-amoxiclav); relieve stasis/predisposing anatomy.","REPLACE deficits: iron, B12, folate, Ca, Mg, fat-soluble vitamins A/D/E/K; dietitian + monitor."], ix: ["FBC, ferritin, B12/folate, Ca/Mg/PO4, vitamin D, INR (fat-soluble status)","Coeliac serology (anti-tTG IgA + total IgA) with duodenal biopsy","Faecal elastase (pancreatic exocrine insufficiency); faecal fat/steatorrhoea","Glucose or lactulose breath test for SIBO; D-xylose test","CRP + small-bowel imaging/endoscopy to define structural cause"], dispo: "Outpatient gastroenterology work-up; admit if severe malnutrition, dehydration, electrolyte derangement or refeeding risk.", src: "Harrison 22e - BSG Guidelines for the investigation of chronic diarrhoea in adults (2018, 3rd ed)" },
    "MICROSCOPIC_COLITIS": { name: "Microscopic colitis", class: "non_infective", system: "Gastroenterology", dx: "Colonoscopy with random biopsies showing collagenous or lymphocytic histology", tx: ["STOP culprit drugs – NSAIDs, PPIs, SSRIs, statins – and advise smoking cessation.","BUDESONIDE 9mg OD 6–8 weeks induction, then taper – first-line.","Loperamide for mild/residual symptoms or as adjunct.","Relapse: re-induce budesonide, maintain at lowest effective dose.","Refractory/steroid-dependent: refer – immunomodulator/anti-TNF/vedolizumab, rarely surgery."], ix: ["Colonoscopy with random right- and left-colon biopsies (diagnostic)","Stool studies to exclude infection (incl. C. difficile)","Coeliac serology (tTG-IgA) – frequent association","FBC, CRP, TFTs","Medication review for offending agents"], dispo: "Outpatient; gastroenterology follow-up – most respond well to budesonide.", src: "Harrison 22e - AGA guideline on medical management of microscopic colitis" },
    "ZOLLINGER_ELLISON": { name: "Zollinger-Ellison syndrome (gastrinoma)", class: "non_infective", system: "Gastroenterology", dx: "Fasting serum gastrin >10x ULN (or >1000 pg/mL) with gastric pH <2; secretin stimulation test if equivocal.", tx: ["HIGH-DOSE PPI first (e.g. omeprazole 40–60mg od) – titrate to BAO <10 mEq/h; lifelong.","Screen for MEN1 – serum Ca/PTH, prolactin; if hyperparathyroid, parathyroidectomy first (lowers gastrin).","Localise then RESECT – surgical exploration/enucleation for sporadic tumour, curative intent.","Metastatic/unresectable – somatostatin analogue (octreotide/lanreotide); consider PRRT, everolimus, sunitinib, liver-directed therapy.","Never stop PPI abruptly – rebound hypersecretion/perforation risk; monitor B12 long-term."], ix: ["Fasting serum gastrin + gastric pH / basal acid output","Secretin stimulation test if gastrin equivocal","68Ga-DOTATATE PET/CT (or EUS/CT/MRI) for tumour localisation","Serum calcium, PTH, prolactin – MEN1 screen","Upper GI endoscopy – multiple/refractory or distal duodenal ulcers"], dispo: "Refer to neuroendocrine-tumour MDT; lifelong specialist GI / endocrine-surgery follow-up.", src: "Harrison 22e - NANETS/ENETS gastrinoma & pancreatic NET consensus guidelines" },
    "acute_appendicitis": { name: "Acute Appendicitis and Peritonitis", class: "non_infective", system: "Gastroenterology / Surgical", dx: "Confirmed by clinical picture + inflammatory markers + contrast CT (or US in children/pregnancy).", tx: ["RESUSCITATE – NBM, IV crystalloid, analgesia, antiemetic; sepsis-six + correct electrolytes if peritonitic.","IV ANTIBIOTICS early – broad-spectrum gram-neg + anaerobe cover (pip-tazo, or ceftriaxone + metronidazole).","APPENDICECTOMY – laparoscopic definitive source control; urgent if perforated/generalised peritonitis.","Complicated with contained abscess/phlegmon: percutaneous drainage + antibiotics, consider interval appendicectomy.","Uncomplicated selected cases: non-operative antibiotics an option – counsel recurrence risk."], ix: ["FBC (leucocytosis, neutrophilia) + CRP","Urinalysis + serum beta-hCG (exclude UTI/pregnancy)","Contrast-enhanced CT abdomen/pelvis (US in children/pregnancy)","U&E, lactate, VBG if septic/peritonitic","Blood cultures + group-and-save pre-op"], dispo: "Admit under general surgery; expedite theatre for appendicectomy; HDU/ICU if septic generalised peritonitis.", src: "Harrison 22e - WSES Jerusalem Guidelines 2020 (acute appendicitis)" },
    "acute_intestinal_obstruction": { name: "Acute Intestinal Obstruction", class: "non_infective", system: "Gastrointestinal", dx: "Confirm with CT abdomen/pelvis with contrast — dilated proximal bowel, collapsed distal, transition point; identifies cause and ischaemia.", tx: ["NBM + NG TUBE decompression; IV fluid resuscitation + correct K/Na; catheterise, monitor output.","URGENT SURGERY if strangulation/ischaemia, perforation, closed-loop or complete obstruction — do not delay.","Adhesive SBO without ischaemia: trial NON-OPERATIVE ~48h; Gastrografin challenge is diagnostic + therapeutic.","Large-bowel obstruction: exclude pseudo-obstruction; malignant LBO → emergency resection or stent; sigmoid volvulus → endoscopic detorsion.","IV ANTIBIOTICS if peritonitis/perforation/strangulation; serial exam + lactate for deterioration."], ix: ["CT abdomen/pelvis with IV contrast (first-line)","FBC, U&E, lactate, CRP, amylase","Erect CXR + supine AXR (air-fluid levels, free air)","VBG (metabolic derangement, lactate)","Group & save/crossmatch, coagulation"], dispo: "Admit under surgery; HDU/ICU if strangulation, sepsis or major fluid/electrolyte shifts.", src: "Harrison 22e - ASCRS/WSES adhesive small bowel obstruction guidelines" },
    "peptic_ulcer_disease_and_related": { name: "Peptic Ulcer Disease and Related Disorders", class: "non_infective", system: "Gastrointestinal", dx: "Upper GI endoscopy confirms ulcer; biopsy gastric ulcers to exclude malignancy and test for H. pylori.", tx: ["Bleeding ulcer — resuscitate, IV HIGH-DOSE PPI, urgent endoscopy + haemostasis (clip/thermal + adrenaline).","PPI first-line to heal — duodenal 4 weeks, gastric 8 weeks.","TEST-AND-TREAT H. pylori — bismuth quadruple (or clarithromycin triple if low resistance); confirm cure.","STOP NSAIDs/aspirin; if unavoidable, co-prescribe PPI and reassess indication.","Repeat endoscopy + biopsy gastric ulcers to exclude cancer; refractory/multiple → fasting gastrin (ZES)."], ix: ["Upper GI endoscopy (diagnostic + therapeutic, biopsy gastric ulcers)","H. pylori testing — urea breath test / stool antigen / biopsy urease","FBC (anaemia), urea and creatinine","Group and save / crossmatch if active bleed","Fasting serum gastrin if refractory or multiple/atypical ulcers"], dispo: "Admit if active bleed or haemodynamic instability; otherwise outpatient PPI + eradication with follow-up.", src: "Harrison 22e - ACG Clinical Guideline (H. pylori / PUD)" },
    "liver_transplantation": { name: "Liver Transplantation", class: "non_infective", system: "Gastrointestinal / Hepatobiliary", dx: "Candidacy confirmed by MELD-Na score + multidisciplinary transplant evaluation; graft dysfunction/rejection confirmed on liver biopsy.", tx: ["LIST by MELD-Na; HCC within Milan criteria earns exception points; urgent ALF listing via King's College criteria.","Maintain TACROLIMUS (calcineurin inhibitor) + mycophenolate ± tapering corticosteroids as core immunosuppression.","Acute cellular rejection – pulse IV METHYLPREDNISOLONE, biopsy-confirm; steroid-resistant → anti-thymocyte globulin.","Prophylaxis: valganciclovir (CMV), co-trimoxazole (PCP), antifungal; monitor CNI troughs + creatinine.","Long-term: surveillance for disease recurrence, de-novo malignancy, CNI renal/metabolic toxicity."], ix: ["MELD-Na components – bilirubin, INR, creatinine, sodium","Viral serologies (HBV, HCV, CMV, EBV, HIV) + ABO group/crossmatch","Triphasic CT/MRI liver – HCC staging + vascular/biliary patency","Cardiopulmonary workup – echo, stress test, PFTs","Liver biopsy + CNI trough levels if graft dysfunction post-transplant"], dispo: "Manage at transplant centre; lifelong immunosuppression + hepatology follow-up; expedite referral for acute liver failure.", src: "Harrison 22e - AASLD (Evaluation for Liver Transplantation in Adults)" },
    "malnutrition_and_nutritional_assessment": { name: "Malnutrition and Nutritional Assessment", class: "non_infective", system: "Gastrointestinal / Nutritional", dx: "Confirm via GLIM criteria after a positive screen — >=1 phenotypic (unintentional weight loss, low BMI, reduced muscle mass) plus >=1 aetiologic (reduced intake/absorption or inflammatory disease burden).", tx: ["THIAMINE 200-300 mg/day (+ vitamin B-co) BEFORE and during early feeding to prevent Wernicke.","Replace K/Mg/PO4 ALONGSIDE cautious feeding — do NOT delay feeding to normalise them.","Start LOW & SLOW: 10 kcal/kg/day if high-risk (<=5 kcal/kg if BMI<14 or negligible intake >15 days); uptitrate to target over 4-7 days.","ENTERAL route preferred if gut works — oral/ONS first, tube feed if unsafe swallow.","Parenteral nutrition ONLY if gut inaccessible/failing; central access, avoid overfeeding.","Replace micronutrients (B-vits, folate, vit D, zinc, iron); monitor K/Mg/PO4 daily first week."], ix: ["Screen: MUST or NRS-2002; anthropometry — weight, BMI, % weight loss, mid-arm circumference.","U&E + K, Mg, PO4, glucose (baseline and refeeding surveillance).","CRP/albumin — inflammation context, NOT a standalone nutrition marker.","Micronutrients: B12, folate, vitamin D, iron studies, zinc.","Muscle mass/function: handgrip strength, BIA or CT psoas area."], dispo: "Dietitian-led plan; admit high refeeding-risk for monitored feeding; community follow-up with repeat screening.", src: "Harrison 22e - NICE CG32 (Nutrition support for adults) + GLIM criteria + MARSIPAN" },
    "upper_gastrointestinal_tract_cancers": { name: "Upper Gastrointestinal Tract Cancers", class: "non_infective", system: "Gastrointestinal / Oncology", dx: "Upper GI endoscopy with multiple biopsies confirms; histology plus HER2, PD-L1 CPS and MMR/MSI on adenocarcinoma.", tx: ["Stabilise – control bleeding, correct anaemia, relieve dysphagia (NG/NJ or feeding jejunostomy nutrition; AVOID stent in curative candidates – reserve for palliation); stage via MDT before therapy.","RESECTION for localised disease – oesophagectomy/gastrectomy with D2 nodal dissection; EMR/ESD if T1a.","PERIOPERATIVE FLOT for resectable gastric/GOJ adenocarcinoma; neoadjuvant chemoRT (CROSS) for oesophageal.","PALLIATIVE 1st-line – platinum + fluoropyrimidine; add trastuzumab if HER2+, nivolumab/pembrolizumab if PD-L1 CPS high; pembrolizumab if dMMR/MSI-H.","Early palliative care + dietitian; endoscopic/RT for symptom control in advanced disease."], ix: ["Upper GI endoscopy + biopsy (HER2, PD-L1 CPS, MMR/MSI)","Contrast CT chest/abdomen/pelvis for staging","EUS for locoregional T/N assessment","FDG-PET/CT to exclude distant metastases","Staging laparoscopy + peritoneal cytology (gastric/GOJ)"], dispo: "Refer to upper-GI MDT/surgical oncology; involve palliative care early if metastatic.", src: "Harrison 22e - ESMO Oesophageal & Gastric Cancer Clinical Practice Guidelines" },
    "mesenteric_vascular_insufficiency": { name: "Mesenteric Vascular Insufficiency", class: "non_infective", system: "Gastrointestinal / Vascular", dx: "CT mesenteric angiography (arterial + venous phase) confirms; suspect on pain out-of-proportion + lactic acidosis/AF.", tx: ["RESUSCITATE - IV fluids, correct acidosis/electrolytes, broad-spectrum antibiotics; avoid splanchnic-constricting vasopressors.","Systemic HEPARIN anticoagulation early once acute mesenteric ischaemia suspected.","REVASCULARISE urgently - open embolectomy/bypass or endovascular stent/aspiration per aetiology.","LAPAROTOMY if peritonitis/perforation - resect necrotic bowel, plan second-look at 24-48 h.","NOMI - stop vasoconstrictors + intra-arterial PAPAVERINE; chronic disease - elective mesenteric stenting/bypass."], ix: ["CT mesenteric angiography - first-line diagnostic","Serum lactate + ABG (metabolic acidosis)","FBC, U&E, amylase, coagulation, group & save","ECG/echo - embolic source (AF, mural thrombus)","Mesenteric duplex - chronic ischaemia screening"], dispo: "Emergency - urgent vascular surgery + ICU; time-critical, high mortality.", src: "Harrison 22e - ESVS 2017 Mesenteric Ischaemia Guidelines" },
    "cirrhosis_and_its_complications": { name: "Cirrhosis and Its Complications", class: "non_infective", system: "Gastrointestinal/Hepatobiliary", dx: "Confirm cirrhosis via imaging (nodular liver, splenomegaly, portosystemic collaterals) + elastography/labs; biopsy only if diagnosis unclear.", tx: ["ASCITES: salt restrict (<2 g/day) + spironolactone±furosemide; LVP + albumin 8 g/L removed if tense/refractory.","SBP (ascitic PMN >=250): IV CEFTRIAXONE + albumin 1.5 g/kg d1, 1 g/kg d3; then norfloxacin prophylaxis.","VARICEAL BLEED: terlipressin/octreotide + endoscopic band ligation + prophylactic ceftriaxone; NSBB (carvedilol) prophylaxis; TIPS if refractory.","HE: LACTULOSE titrated to 2-3 stools/day + rifaximin add-on; find/treat precipitant (infection, bleed, constipation, electrolytes).","HRS-AKI: TERLIPRESSIN + albumin first-line; stop diuretics/nephrotoxins; urgent transplant referral is definitive."], ix: ["FBC (thrombocytopenia), LFTs, INR, U&E, albumin","Abdominal USG + Doppler — nodularity, ascites, portal/splenic vein","Diagnostic paracentesis — cell count, SAAG, culture","Upper GI endoscopy — screen/grade varices","MELD-Na + Child-Pugh; AFP for HCC surveillance"], dispo: "Admit GI bleed/SBP/HRS/grade III-IV HE; refer hepatology + transplant assessment.", src: "Harrison 22e - AASLD Practice Guidance (Ascites/SBP/HRS; Portal Hypertension & Varices)" },
    "gastrointestinal_neuroendocrine_tumors": { name: "Gastrointestinal Neuroendocrine Tumors", class: "non_infective", system: "Gastrointestinal/Oncology", dx: "Histology (biopsy/resection) confirms NET, graded by Ki-67/mitotic index and differentiation; localise/stage with SSTR imaging.", tx: ["SURGICAL RESECTION for localised disease; endoscopic resection for small (<1–2 cm) low-grade gastric/rectal NETs.","SOMATOSTATIN ANALOGUE (octreotide LAR/lanreotide) first-line in advanced SSTR+ well-differentiated tumours – antiproliferative + symptom control.","Carcinoid syndrome: octreotide for flushing/diarrhoea; short-acting octreotide cover to prevent peri-procedural carcinoid crisis.","Escalate: PRRT (¹⁷⁷Lu-DOTATATE) for progressive midgut; everolimus/sunitinib (pNET); platinum–etoposide for G3/poorly-differentiated NEC.","Refer to NET MDT centre; monitor chromogranin A + imaging; screen MEN1 if multiple/pancreatic."], ix: ["Histopathology + Ki-67/mitotic count → grade (G1/G2/G3) and differentiation.","Chromogranin A; 24-h urinary 5-HIAA if midgut/carcinoid suspected.","⁶⁸Ga-DOTATATE PET/CT (SSTR imaging) + contrast CT/MRI for staging.","Endoscopy/EUS to localise gastric, duodenal or rectal primaries.","Fasting gastrin/hormone panel if functional syndrome; genetics if MEN1 suspected."], dispo: "Refer to specialist NET MDT; elective work-up unless carcinoid crisis, obstruction or bleeding needs admission.", src: "Harrison 22e - ENETS 2023 GEP-NET guidelines" },
    "testicular_cancer": { name: "Testicular Cancer", class: "non_infective", system: "Genitourinary / Oncology", dx: "Confirm by radical inguinal orchidectomy histology, supported by scrotal ultrasound + serum tumour markers (AFP, β-hCG, LDH).", tx: ["RADICAL INGUINAL ORCHIDECTOMY for all – diagnosis, local control, histology; never trans-scrotal biopsy.","Sperm banking + repeat AFP/β-hCG/LDH before any adjuvant therapy.","Stage I seminoma: surveillance preferred; else single-dose CARBOPLATIN or para-aortic RT.","Metastatic/NSGCT: BEP chemo (bleomycin–etoposide–cisplatin) per IGCCCG risk; EP if bleomycin contraindicated.","Post-chemo residual mass: RPLND/resection; monitor markers + bleomycin pulmonary toxicity."], ix: ["Scrotal ultrasound (both testes)","Serum tumour markers AFP, β-hCG, LDH – pre- and post-orchidectomy","CT chest/abdomen/pelvis for staging","Radical inguinal orchidectomy specimen histology","Sperm banking before cytotoxic therapy"], dispo: "Refer to germ-cell/uro-oncology MDT; highly curable even when metastatic.", src: "Harrison 22e – EAU Testicular Cancer Guidelines" },
    "coagulation_disorders": { name: "Coagulation Disorders", class: "non_infective", system: "Haematology", dx: "Coagulation screen (prolonged PT and/or aPTT) with mixing studies plus specific factor assays identifies the defect.", tx: ["FACTOR REPLACEMENT for acute bleed — recombinant FVIII (haemophilia A) or FIX (B); dose to target level by bleed severity; in suspected CNS/major bleed treat FIRST, before imaging.","DDAVP for mild haemophilia A / type 1 VWD (avoid in type 2B VWD — worsens thrombocytopenia; watch hyponatraemia); VWF-containing concentrate for major VWD bleeding.","VITAMIN K + 4-factor PCC for warfarin/vitamin-K or liver-related bleed; FFP/cryoprecipitate (or fibrinogen concentrate) if fibrinogen low.","DIC — treat underlying cause first; replace platelets/FFP/cryoprecipitate/fibrinogen only if actively bleeding.","TRANEXAMIC ACID for mucosal bleeding (avoid in DIC and gross/upper-tract haematuria; do not routinely combine with PCC/bypassing agents — thrombotic risk); bypassing agents (rFVIIa/aPCC) if inhibitor present; urgent haematology referral."], ix: ["PT, aPTT, thrombin time, fibrinogen, platelet count + blood film","Mixing study — corrects = factor deficiency; fails to correct = inhibitor","Specific factor assays (FVIII, FIX); VWF antigen + activity (ristocetin cofactor)","D-dimer + fibrinogen if DIC suspected","LFTs + coagulation profile for suspected liver-related coagulopathy"], dispo: "Admit major/active bleed; urgent haematology input; refer inherited disorders to a haemophilia centre.", src: "Harrison 21e - WFH 2020 Guidelines for the Management of Haemophilia; ISTH/BSH for DIC" },
    "hemolytic_anemia": { name: "Hemolytic Anemia", class: "non_infective", system: "Haematology", dx: "Confirm haemolysis (↑reticulocytes, ↑LDH, ↑indirect bilirubin, ↓haptoglobin) then DAT/Coombs + blood film to classify immune vs non-immune.", tx: ["STABILISE — transfuse least-incompatible cross-matched blood if symptomatic/severe; give FOLIC ACID; treat shock; consider VTE prophylaxis during active haemolysis.","Warm AIHA: CORTICOSTEROIDS (prednisolone 1 mg/kg/day) first-line, then slow taper.","Steroid-refractory/relapsed warm AIHA: RITUXIMAB ± splenectomy; add immunosuppressant if needed.","Cold agglutinin disease: KEEP WARM + avoid cold; rituximab-based — steroids/splenectomy ineffective.","Non-immune: STOP offending drug/oxidant (G6PD); treat underlying cause; if MAHA suspect TTP → urgent PLEX."], ix: ["FBC + reticulocyte count + peripheral blood film (spherocytes, schistocytes, bite cells)","LDH, haptoglobin, indirect bilirubin","Direct antiglobulin test (DAT/Coombs) ± cold agglutinin titre + thermal amplitude","G6PD assay + Hb electrophoresis if non-immune","Urine haemoglobin/haemosiderin; PNH flow cytometry if DAT-negative"], dispo: "Admit if severe/rapidly falling Hb or haemodynamic compromise; urgent haematology referral; serial FBC/retics/LDH on follow-up.", src: "Harrison 22e - First International Consensus (AIHA) 2020" },
    "iron_deficiency_anemia": { name: "Iron Deficiency Anemia", class: "non_infective", system: "Haematology", dx: "Microcytic hypochromic anaemia with LOW serum ferritin (± low transferrin saturation) confirms iron deficiency.", tx: ["ORAL IRON first-line – ferrous sulfate 200mg; once-daily/alternate-day = better absorption, fewer GI effects.","Investigate + TREAT UNDERLYING CAUSE – GI blood loss, menorrhagia, coeliac, poor intake.","Continue iron ~3 months AFTER Hb normalises to replenish stores; recheck Hb at 2–4 weeks.","IV IRON if oral intolerance/malabsorption/CKD/ongoing loss or inadequate response.","TRANSFUSE only for symptomatic severe anaemia or haemodynamic compromise."], ix: ["FBC + blood film (low MCV/MCH, hypochromia, pencil cells)","Serum ferritin (low) + transferrin saturation/TIBC","CRP (ferritin falsely raised in inflammation) ± reticulocytes","GI workup – OGD + colonoscopy (men & postmenopausal women); coeliac serology","Urinalysis for haematuria; menstrual/dietary history"], dispo: "Mostly outpatient; 2-week-wait GI referral if suspected malignancy; admit if haemodynamically unstable.", src: "Harrison 22e - BSG guidelines for the management of iron deficiency anaemia (2021)" },
    "sickle_cell_disease": { name: "Sickle Cell Disease", class: "non_infective", system: "Haematology", dx: "Confirm with Hb electrophoresis/HPLC showing HbS predominance (HbSS or variant); FBC shows haemolytic anaemia + sickled cells on film.", tx: ["IV OPIOID analgesia promptly for vaso-occlusive crisis; add O2 if hypoxic, keep euvolaemic – avoid over-hydration.","HYDROXYUREA (hydroxycarbamide) first-line disease-modifier – raises HbF, cuts crises/ACS; monitor FBC; teratogenic – avoid in pregnancy, ensure contraception.","Acute chest syndrome: O2 + broad-spectrum antibiotics (atypical cover); EXCHANGE TRANSFUSION if hypoxic/severe.","Fever = EMERGENCY (functional asplenia): cultures + empirical antibiotics; penicillin prophylaxis (children to ≥age 5; adults if prior invasive infection/splenectomy), vaccinate, folate.","Prevent stroke via transcranial Doppler screen → chronic transfusion; refer HSCT/gene therapy if severe."], ix: ["FBC + reticulocyte count (haemolytic anaemia, reticulocytosis)","Hb electrophoresis/HPLC – quantify HbS, HbF, variants","Haemolysis markers – LDH, unconjugated bilirubin","Group & cross-match; U&E, LFTs; blood cultures if febrile","Transcranial Doppler (stroke risk); CXR + SpO2/ABG if suspected ACS"], dispo: "Admit acute crises/ACS; link to comprehensive SCD/haematology clinic with transition planning.", src: "Harrison 22e - ASH 2020 SCD Guidelines" },
    "anemia_due_to_acute_blood": { name: "Anemia Due to Acute Blood Loss", class: "non_infective", system: "Hematologic", dx: "Acute fall in Hb/Hct with overt/occult blood loss and haemodynamic signs (tachycardia, hypotension); confirm and localise bleeding source.", tx: ["CONTROL the source first — direct pressure / endoscopic / surgical / IR embolisation.","Resuscitate: 2 large-bore IV lines, crystalloid; permissive hypotension if uncontrolled trauma — but NOT in TBI/spinal injury (target SBP >=110, maintain CPP).","TRANSFUSE packed RBCs — restrictive threshold Hb<7 g/dL (<8 if cardiac/symptomatic); in active bleeding transfuse to clinical status, not a single number.","Massive haemorrhage: activate MTP, balanced 1:1:1 PRBC:FFP:platelets + IV TXA <3h; monitor and replace ionised calcium (citrate) and prevent hypothermia/acidosis.","Reverse anticoagulants/correct coagulopathy; iron replacement once stable; monitor Hb, lactate, urine output."], ix: ["Serial FBC/Hb & Hct (may be normal early until haemodilution)","Group & crossmatch + coagulation profile (PT/INR, aPTT, fibrinogen)","ABG with lactate; U&E, LFTs; ionised calcium in massive transfusion","Source workup: GI endoscopy, CT angiography, FAST/imaging","Reticulocyte count; iron studies post-recovery"], dispo: "Admit; ICU/HDU if unstable or ongoing bleed; urgent surgical/GI/IR referral.", src: "Harrison 22e; AABB 2023 RBC Transfusion Guidelines; European trauma/major-bleeding guideline 6th ed (trauma)" },
    "bone_marrow_failure_syndromes_including": { name: "Bone Marrow Failure Syndromes Including Aplastic Anemia and Myelodysplasia", class: "non_infective", system: "Hematologic", dx: "Confirm on bone marrow aspirate + trephine biopsy — hypocellular marrow (aplastic anaemia) or dysplasia/excess blasts (MDS) — with cytogenetics/FISH.", tx: ["CONFIRM severity + subtype first: marrow biopsy, cytogenetics; exclude PNH clone and inherited failure before therapy.","SUPPORTIVE care throughout: irradiated leucodepleted transfusions, iron chelation if overloaded, antimicrobial prophylaxis when neutropenic; avoid family blood donors.","Severe AA — ALLOGENEIC HSCT if young with matched sibling; else horse ATG + ciclosporin + eltrombopag.","MDS lower-risk — ESA for anaemia, luspatercept if ring sideroblasts/SF3B1, lenalidomide for del(5q); transfuse + chelate.","MDS higher-risk — AZACITIDINE (hypomethylating agent); allogeneic HSCT the only cure — refer early, consider trials."], ix: ["FBC + reticulocyte count + blood film","Bone marrow aspirate + trephine biopsy with cytogenetics/FISH","Peripheral-blood flow cytometry for PNH clone","Inherited BMF screen in young: telomere length, chromosome breakage (DEB) test","HLA typing (+ siblings), B12/folate, LFTs, viral serology (HIV, hepatitis, EBV/CMV)"], dispo: "Refer to haematology; assess transplant/trial eligibility; regular count monitoring and transfusion support.", src: "Harrison 22e - British Society for Haematology (BSH) aplastic anaemia guideline" },
    "megaloblastic_anemias": { name: "Megaloblastic Anemias", class: "non_infective", system: "Hematologic", dx: "Macrocytic anaemia (raised MCV) with oval macrocytes + hypersegmented neutrophils on film; confirm by low serum B12 and/or folate (raised MMA/homocysteine if borderline).", tx: ["CONFIRM B12 vs folate FIRST – never folate alone if B12 low (precipitates/worsens subacute combined degeneration).","HYDROXOCOBALAMIN 1 mg IM – loading alt-days x2 wks, then 1 mg 3-monthly (2-monthly if neuro involvement).","FOLIC ACID 5 mg PO daily for folate deficiency; correct dietary/malabsorptive cause.","Monitor K+ (hypokalaemia on brisk response) + reticulocytosis by day 5–7; transfuse only if haemodynamically unstable.","Treat underlying cause – pernicious anaemia needs lifelong B12; screen coeliac/malabsorption."], ix: ["FBC + blood film – MCV >100, oval macrocytes, hypersegmented neutrophils","Serum B12, serum + red-cell folate","Methylmalonic acid + homocysteine if borderline B12","Reticulocytes, LDH, unconjugated bilirubin (ineffective erythropoiesis)","Anti-intrinsic factor + anti-parietal cell antibodies (pernicious anaemia)"], dispo: "Mostly outpatient; admit if severe symptomatic anaemia, cardiac compromise or neurological deficit.", src: "Harrison 22e - BSH 2014 (cobalamin & folate deficiency guidelines)" },
    "arterial_and_venous_thrombosis": { name: "Arterial and Venous Thrombosis", class: "non_infective", system: "Hematologic / Cardiovascular", dx: "Confirm by imaging — compression US for DVT, CTPA for PE, angiography/ECG–troponin for arterial events; D-dimer to exclude low-probability VTE.", tx: ["VENOUS (VTE): ANTICOAGULATE — DOAC (apixaban/rivaroxaban) first-line; LMWH if parenteral/cancer; treat >=3 months.","ARTERIAL: ANTIPLATELET mainstay (platelet-rich thrombi) — aspirin +/- P2Y12; add heparin in acute ACS. Acute ischaemic stroke: IV thrombolysis +/- mechanical thrombectomy, then aspirin 24-48h — NOT routine heparin.","LIFE-/LIMB-THREATENING (massive PE, acute limb ischaemia, STEMI): FIBRINOLYSIS or catheter thrombectomy/PCI + heparin.","DURATION: individualise secondary prophylaxis by recurrence vs bleeding risk; extend if unprovoked/persistent risk.","MONITOR bleeding, renal/hepatic function, platelets (HIT on heparin); cancer→LMWH/DOAC, pregnancy→LMWH (avoid DOAC/warfarin)."], ix: ["FBC + platelet count (baseline, HIT surveillance)","Renal and hepatic function (DOAC/LMWH dosing)","Coagulation screen — PT/INR, aPTT; D-dimer","Imaging — Doppler US, CTPA, or arterial angiography","Troponin + ECG for suspected arterial event; selective thrombophilia screen"], dispo: "Admit massive PE/acute limb ischaemia/ACS or high bleed risk; outpatient DOAC for low-risk DVT with anticoagulation-clinic follow-up.", src: "Harrison 22e - ASH 2020 VTE Guidelines" },
    "less_common_lymphoid_and_myeloid": { name: "Less Common Lymphoid and Myeloid Malignancies", class: "non_infective", system: "Hematologic / Oncologic", dx: "Confirm the specific entity by tissue/marrow biopsy with immunophenotyping, cytogenetics and targeted molecular studies (BRAF V600E, KIT D816V, FIP1L1-PDGFRA, TCR clonality).", tx: ["CONFIRM ENTITY first — biopsy + flow + molecular; refer to haemato-oncology, do not treat empirically.","HAIRY CELL LEUKAEMIA: purine analogue (cladribine/pentostatin) first-line; vemurafenib±rituximab if relapsed/BRAF-driven.","CTCL (mycosis fungoides/Sezary): skin-directed therapy (topical steroid, PUVA, RT) early; bexarotene/brentuximab/mogamulizumab or systemic tx if advanced.","SYSTEMIC MASTOCYTOSIS: avapritinib/midostaurin (KIT D816V, advanced disease); antihistamines + adrenaline pen for mediator/anaphylaxis; avoid triggers.","HYPEREOSINOPHILIA: IMATINIB if FIP1L1-PDGFRA (or PDGFRB) rearranged — give CONCURRENT corticosteroids first 7-10d if troponin↑/cardiac involvement (imatinib can precipitate cardiogenic shock); else corticosteroids first-line (mepolizumab steroid-sparing). Screen echo/troponin."], ix: ["FBC + peripheral blood film; bone marrow aspirate/trephine with immunohistochemistry.","Flow cytometry immunophenotyping + TCR/IGH clonality.","Molecular/cytogenetics: BRAF V600E, KIT D816V, FIP1L1-PDGFRA/PDGFRB/FGFR1, JAK2.","Serum tryptase (mastocytosis); LDH, HTLV-1 serology where relevant.","CT/PET staging; echo + troponin if eosinophilia/cardiac risk."], dispo: "Refer to specialist haemato-oncology MDT; admit if cytopenias, organ infiltration or anaphylaxis risk.", src: "Harrison 22e - NCCN Guidelines (Hairy Cell Leukemia / Primary Cutaneous Lymphomas / Systemic Mastocytosis / Myeloid-Lymphoid Neoplasms with Eosinophilia)" },
    "acute_lymphoid_leukemia": { name: "Acute Lymphoid Leukemia", class: "non_infective", system: "Hematologic/Oncologic", dx: "Bone marrow aspirate/biopsy with >=20% lymphoblasts, confirmed by flow-cytometry immunophenotyping + cytogenetics/molecular (BCR-ABL1).", tx: ["Start TUMOUR LYSIS prophylaxis first — IV hydration + allopurinol; rasburicase if high urate/bulky disease (avoid rasburicase in G6PD deficiency).","MULTI-AGENT CHEMOTHERAPY: induction (vincristine + glucocorticoid + anthracycline + asparaginase) then consolidation + 2–3 yr maintenance (6-MP/MTX).","CNS prophylaxis in all — intrathecal methotrexate/cytarabine ± cranial RT.","Ph-positive: add TKI (dasatinib/imatinib) to chemo; allogeneic HSCT for high-risk or relapse.","Relapsed/refractory B-ALL: BLINATUMOMAB, inotuzumab or CD19 CAR-T; supportive transfusion, G-CSF, antimicrobial prophylaxis."], ix: ["CBC + differential, peripheral blood smear","Bone marrow aspirate/biopsy: flow cytometry, cytogenetics, FISH, BCR-ABL1","Lumbar puncture with CSF cytology","Tumour lysis panel: urate, K, phosphate, Ca, LDH, creatinine","Coagulation, LFTs, HLA typing for transplant candidates"], dispo: "Admit to specialist haemato-oncology unit; urgent oncology referral, neutropenic isolation.", src: "Harrison 22e - NCCN Acute Lymphoblastic Leukemia Guidelines" },
    "polycythemia_vera_and_other_myeloprolifera": { name: "Polycythemia Vera and Other Myeloproliferative Neoplasms", class: "non_infective", system: "Hematologic/Oncologic", dx: "Confirm by WHO criteria – raised Hb/haematocrit with JAK2 V617F (or exon 12) mutation, subnormal serum EPO, and marrow panmyelosis.", tx: ["PHLEBOTOMY to keep haematocrit <45% – cornerstone of PV; venesect to iron-deficient target.","LOW-DOSE ASPIRIN 75–100 mg OD in PV/ET unless active bleeding/contraindication.","CYTOREDUCTION – hydroxyurea 1st-line if high-risk: age >60, prior thrombosis or very high counts.","RUXOLITINIB if hydroxyurea-resistant/intolerant PV; also symptomatic myelofibrosis splenomegaly/symptoms.","ALLO-HSCT – only cure for high-risk myelofibrosis; control CV risk, treat gout/pruritus."], ix: ["FBC + blood film (Hb, haematocrit, platelets, WCC)","JAK2 V617F; if negative JAK2 exon 12 (PV) or CALR/MPL (ET/MF)","Serum erythropoietin (low in PV)","Bone marrow aspirate + trephine with cytogenetics","Serum urate, LDH; abdominal USS for splenomegaly"], dispo: "Haematology outpatient follow-up; urgent referral for thrombosis, blast/leukaemic transformation or progressive cytopenias.", src: "Harrison 22e - NCCN Myeloproliferative Neoplasms Guidelines" },
    "CASTLEMAN_DISEASE": { name: "Castleman disease", class: "non_infective", system: "Hematology", dx: "Excisional lymph node biopsy showing hyaline-vascular or plasma-cell histology, with HHV-8/HIV testing and exclusion of mimics.", tx: ["CLASSIFY first – unicentric vs multicentric; test HHV-8 + HIV to subtype and direct therapy.","UCD: complete SURGICAL EXCISION – curative; rituximab, embolisation or radiotherapy if unresectable.","Idiopathic MCD: SILTUXIMAB (anti-IL-6) first-line ± corticosteroids; tocilizumab if unavailable.","HHV-8-associated MCD: RITUXIMAB (anti-CD20) ± antiretrovirals; add liposomal doxorubicin if severe.","Severe/refractory iMCD or TAFRO: combination chemotherapy + high-dose steroids; watch for cytokine storm."], ix: ["Excisional lymph node biopsy + histopathology, with HHV-8 LANA-1 immunohistochemistry","HHV-8 viral load (PCR) + HIV serology","IL-6, CRP, ferritin, fibrinogen","FBC (anaemia, thrombocytopenia), renal and liver function, albumin","CT or PET-CT chest–abdomen–pelvis for extent; SPEP/immunofixation to exclude POEMS"], dispo: "Haematology referral – UCD curable by surgery; iMCD/HHV-8-MCD need long-term specialist immunotherapy.", src: "Harrison 22e - CDCN (Castleman Disease Collaborative Network) consensus guidelines" },
    "PNH": { name: "Paroxysmal nocturnal haemoglobinuria", class: "non_infective", system: "Hematology", dx: "Confirm by peripheral-blood flow cytometry (FLAER) showing GPI-anchored protein (CD55/CD59)-deficient RBCs and granulocytes/monocytes.", tx: ["ECULIZUMAB (anti-C5) first-line for classic haemolytic PNH; ravulizumab if long-acting preferred.","VACCINATE vs meningococcus (ACWY+B) >=2 wk before complement inhibitor + penicillin prophylaxis + alert card.","ANTICOAGULATE therapeutically for thrombosis; complement blockade itself cuts thrombotic risk.","Supportive: folic acid, iron replacement, transfuse symptomatic anaemia.","Allogeneic HSCT — only curative option; reserve for marrow failure/refractory disease."], ix: ["Flow cytometry with FLAER (definitive) — granulocyte/monocyte + RBC clone size","FBC + reticulocytes; LDH high, haptoglobin low, unconjugated bilirubin raised","Direct antiglobulin test (Coombs) — negative (excludes AIHA)","Bone marrow aspirate/trephine + cytogenetics (assess aplasia/MDS)","Urinalysis (haemoglobinuria/haemosiderinuria); U&E, D-dimer if thrombotic"], dispo: "Refer to haematology; lifelong specialist follow-up on complement inhibitor with clone/LDH monitoring.", src: "Harrison 22e - BSH (British Society for Haematology) PNH guideline" },
    "platelet_disorders": { name: "Platelet Disorders (Thrombocytopenia)", class: "non_infective", system: "Hematology", dx: "Platelet count <150×10⁹/L on FBC – confirm with repeat sample in citrate tube + peripheral blood film to exclude EDTA pseudothrombocytopenia.", tx: ["CONFIRM real – repeat count (citrate tube), review film for clumps/schistocytes/blasts; stop culprit drugs.","PLATELET TRANSFUSION only for active bleeding or count <10×10⁹/L; NEVER give in TTP or HIT (drives thrombosis).","ITP: CORTICOSTEROIDS (dexamethasone/prednisolone) first-line; add IVIG or anti-D if severe bleeding.","TTP: urgent PLASMA EXCHANGE + steroids ± caplacizumab. HIT: STOP heparin, start argatroban/fondaparinux.","DIC: treat underlying cause + supportive replacement; urgent haematology referral for TMA/refractory disease."], ix: ["FBC + peripheral blood film (clumping, schistocytes, blasts)","Coagulation screen – PT/aPTT/fibrinogen/D-dimer (DIC)","LDH, haptoglobin, bilirubin, reticulocytes; ADAMTS13 if TTP suspected","HIT 4T score + anti-PF4 antibodies if heparin-exposed","HIV/HCV/H. pylori serology; bone marrow if atypical or age >60"], dispo: "Admit if platelets <20×10⁹/L, active bleeding, or suspected TTP/HIT; otherwise urgent haematology follow-up.", src: "Harrison 22e - ASH 2019 (ITP)" },
    "POEMS_SYNDROME": { name: "POEMS syndrome", class: "non_infective", system: "Hematology", dx: "Confirm: polyneuropathy + monoclonal plasma-cell disorder (usually lambda) PLUS one other major criterion (sclerotic bone lesion, Castleman disease, or raised VEGF) PLUS >=1 minor criterion (organomegaly, volume overload, endocrinopathy, skin changes, papilledema, thrombocytosis/polycythemia).", tx: ["RISK-STRATIFY by number of bone lesions + marrow involvement - treat the clone, not just symptoms.","RADIOTHERAPY to isolated/limited (1-3) sclerotic lesions with no diffuse marrow disease - can be curative.","HIGH-DOSE MELPHALAN + autologous stem-cell transplant - first-line if disseminated/marrow disease and transplant-eligible.","If transplant-ineligible: LENALIDOMIDE-dex preferred (less neurotoxic), or melphalan-dex; bortezomib-based ONLY with caution + NCS monitoring (can worsen the polyneuropathy).","SUPPORTIVE: neuro-rehab, VTE prophylaxis (high thrombosis risk, esp. on IMiDs), manage volume overload/endocrinopathy; track VEGF as response marker."], ix: ["Serum + urine immunofixation and free light chains (lambda-restricted M-protein)","Serum VEGF (markedly raised; disease-activity marker)","PET-CT / CT skeletal survey for osteosclerotic lesions (may be missed on standard bone scan)","Bone marrow aspirate + biopsy (clonal plasma cells +/- Castleman)","Nerve conduction studies (demyelinating with axonal loss); endocrine panel"], dispo: "Refer to haematology plasma-cell centre; MDT follow-up with neurology + endocrinology.", src: "Harrison 22e - Mayo Clinic POEMS consensus (Dispenzieri) / IMWG framework" },
    "WALDENSTROM": { name: "Waldenström macroglobulinaemia", class: "non_infective", system: "Hematology", dx: "Bone marrow biopsy with >=10% clonal lymphoplasmacytic infiltrate plus serum IgM monoclonal paraprotein; MYD88 L265P mutation supports.", tx: ["PLASMAPHERESIS urgently for hyperviscosity (visual/neuro symptoms, very high IgM) – before systemic Rx.","ASYMPTOMATIC disease → observe (watch-and-wait); treat only symptomatic WM.","First-line BTK INHIBITOR (zanubrutinib/ibrutinib) or bendamustine–rituximab / DRC (dex-rituximab-cyclophosphamide).","Avoid rituximab monotherapy if IgM high – IgM flare risk; plasmapheresis/delay rituximab first.","Test MYD88/CXCR4 (guides BTKi response); refer haematology; consider ASCT / trial at relapse."], ix: ["SPEP + immunofixation; serum IgM quantification","Serum viscosity","Bone marrow biopsy + MYD88 L265P / CXCR4 mutation testing","FBC, U&E, LDH, beta-2 microglobulin","CT chest/abdomen/pelvis; fundoscopy if hyperviscosity suspected"], dispo: "Haematology referral – urgent if hyperviscosity/symptomatic; outpatient watch-and-wait if asymptomatic.", src: "Harrison 22e - IWWM consensus guidelines" },
    "HLH": { name: "Hemophagocytic Lymphohistiocytosis (HLH)", class: "non_infective", system: "Hematology / Immunology", dx: "Confirm by HLH-2004 criteria (≥5 of 8: fever, splenomegaly, ≥2-lineage cytopenia, hypertriglyceridaemia/hypofibrinogenaemia, haemophagocytosis, ferritin ≥500, high sCD25, low/absent NK activity) or causative mutation; use H-score in adult secondary HLH.", tx: ["TREAT THE TRIGGER concurrently — antimicrobials, chemo for lymphoma, immunosuppression for MAS/autoimmune.","ETOPOSIDE + DEXAMETHASONE (HLH-94) for primary/familial or severe/refractory disease; taper over ~8 weeks.","MAS/rheumatological HLH: high-dose STEROIDS ± anakinra (IL-1) or ciclosporin, not etoposide first-line.","EBV-driven: add RITUXIMAB; refractory primary HLH: EMAPALUMAB (anti-IFN-γ) salvage.","Familial/relapsed/CNS disease → allo-HSCT; intrathecal MTX + steroid for CNS involvement."], ix: ["Ferritin (often >10 000), fibrinogen, fasting triglycerides","FBC (bi-/pancytopenia), LFTs, LDH, coagulation screen","Soluble CD25 (sIL-2R) and NK-cell activity","Bone marrow aspirate/trephine — haemophagocytosis","Trigger workup: EBV/CMV/HIV PCR, cultures, autoimmune serology, CT/biopsy for lymphoma"], dispo: "Admit; ICU if organ failure/DIC; urgent haematology and specialist HLH-centre referral.", src: "Harrison 22e - Histiocyte Society HLH-94/HLH-2004 protocol" },
    "amyloidosis": { name: "Amyloidosis", class: "non_infective", system: "Hematology / Multisystem", dx: "Tissue biopsy (fat-pad aspirate or affected organ) — Congo red apple-green birefringence; type amyloid by mass spectrometry and confirm the clone.", tx: ["TYPE the amyloid first (AL vs ATTR vs AA) — treatment diverges entirely; never treat blind.","AL: DARATUMUMAB + bortezomib–cyclophosphamide–dexamethasone (Dara-VCd) first-line; aim rapid free-light-chain response.","ASCT in selected fit, low cardiac-stage patients; risk-stratify by Mayo biomarker (NT-proBNP/troponin) staging.","ATTR: TAFAMIDIS stabiliser for cardiomyopathy; patisiran/inotersen gene-silencers for hereditary ATTR neuropathy.","Supportive: loop DIURETICS for cardiac/nephrotic oedema; avoid digoxin/CCB (amyloid-binding); early specialist-centre referral."], ix: ["Serum free light chains + ratio, serum/urine immunofixation","Bone marrow biopsy with FISH (clone quantification)","NT-proBNP + troponin (Mayo cardiac staging)","Echo with global longitudinal strain ± cardiac MRI","99mTc-DPD/PYP scintigraphy + TTR gene sequencing (confirm/exclude ATTR)"], dispo: "Refer to national amyloidosis / specialist haematology centre; urgent input if Mayo stage III cardiac involvement.", src: "Harrison 22e - International Society of Amyloidosis (ISA) consensus guideline" },
    "transfusion_reactions": { name: "Transfusion Reactions", class: "non_infective", system: "Hematology / Transfusion", dx: "Clinical – fever/chills, dyspnoea, hypotension, loin/back pain, urticaria or haemoglobinuria during or ≤6h post-transfusion; subtype confirmed by clerical/ABO recheck + blood-bank workup (DAT).", tx: ["STOP TRANSFUSION immediately – keep line open with NS; recheck patient/unit ID; return unit + fresh samples to blood bank.","Acute haemolytic (ABO): aggressive IV NS to maintain urine output; pressors for shock; treat DIC; renal support.","Anaphylaxis: IM ADRENALINE 0.5mg + O2/airway; antihistamine + steroid; washed/IgA-deficient units next time.","TACO: OXYGEN + IV FUROSEMIDE, sit up, slow/stop; TRALI: respiratory/ventilatory support – NO diuretic.","Suspected sepsis: broad-spectrum ANTIBIOTICS + culture patient & unit; febrile non-haemolytic: paracetamol, exclude haemolysis."], ix: ["DAT + repeat ABO/group & crossmatch on pre- and post-transfusion samples","Haemolysis screen: FBC, LDH, haptoglobin, indirect bilirubin, plasma free Hb","Coagulation + fibrinogen/D-dimer (DIC); U&E/creatinine","Urinalysis for haemoglobinuria; blood cultures (patient + unit)","CXR if dyspnoea/hypoxia – distinguish TRALI (bilateral infiltrates) from TACO"], dispo: "Monitor in HDU/ICU for haemolytic, anaphylactic, TRALI or septic reactions; report all events to haemovigilance/blood bank.", src: "Harrison 22e - AABB (2023) transfusion reaction guidance" },
    "hematopoietic_cell_transplantation": { name: "Hematopoietic Cell Transplantation", class: "non_infective", system: "Hematology/Oncology", dx: "Not a diagnosis - confirm eligibility: appropriate indication (high-risk/relapsed leukaemia, MDS, aplastic anaemia, lymphoma, select non-malignant/immune disorders), disease in remission, and a suitable HLA-matched or haploidentical donor.", tx: ["CONDITIONING - myeloablative vs reduced-intensity, matched to disease, age, HCT-CI; pick best HLA-matched or haplo graft.","GVHD PROPHYLAXIS - calcineurin inhibitor + methotrexate/MMF; post-transplant cyclophosphamide for haploidentical (and increasingly matched/mismatched) grafts.","PROPHYLAXIS - antibacterial, mold-active antifungal (posaconazole), acyclovir for HSV/VZV, co-trimoxazole for PJP; letermovir for CMV-seropositive recipients; pre-emptive CMV/EBV PCR monitoring (rituximab for EBV-PTLD).","Acute GVHD -> CORTICOSTEROIDS first-line; add ruxolitinib if steroid-refractory; chronic GVHD -> steroids +/- CNI, ruxolitinib/belumosudil if refractory; organ-directed supportive care.","Watch VOD/SOS -> DEFIBROTIDE; monitor engraftment, chimerism, relapse; treat neutropenic fever promptly."], ix: ["HLA typing (recipient + donor), ABO group","Disease status/remission (marrow, imaging, MRD) + HCT-CI comorbidity score","Infectious serologies/PCR - CMV, EBV, HSV, VZV, HBV, HCV, HIV, toxoplasma","Organ function - echo/EF, PFTs with DLCO, renal + liver profile","Donor evaluation, graft source (marrow/PBSC/cord), CD34 dose"], dispo: "Manage in specialised transplant unit with protective isolation; lifelong follow-up for chronic GVHD, late infections, endocrine and secondary-malignancy surveillance.", src: "Harrison 22e - ASTCT/EBMT HCT guidelines; IDSA/ECIL infection prophylaxis" },
    "gallbladder_disease": { name: "Gallbladder & Biliary Tract Disease", class: "non_infective", system: "Hepatobiliary", dx: "USS confirms stones/GB wall thickening + pericholecystic fluid; acute cholangitis = fever + jaundice + RUQ pain (Charcot triad) with cholestatic LFTs and dilated ducts.", tx: ["ERCP BILIARY DRAINAGE – pivotal for acute cholangitis; plus IV fluids + empirical antibiotics, urgent if septic/Grade III.","Empirical PIPERACILLIN–TAZOBACTAM (or ceftriaxone + metronidazole) per TG18 grade; de-escalate on cultures, 4–7 days post source-control.","Early laparoscopic CHOLECYSTECTOMY within 72 h of symptom onset for acute cholecystitis (Grade I–II).","Percutaneous cholecystostomy if unfit for surgery / Grade III cholecystitis with organ dysfunction.","Elective laparoscopic cholecystectomy for symptomatic gallstones; NSAID/opioid analgesia for biliary colic."], ix: ["FBC, CRP, LFTs (cholestatic pattern), amylase/lipase, blood cultures, lactate","Abdominal ultrasound – first-line: stones, wall >4 mm, pericholecystic fluid, duct dilatation","MRCP – suspected choledocholithiasis; CT if complications/uncertain","HIDA scan if acute cholecystitis diagnosis remains uncertain","Coagulation profile pre-ERCP/surgery"], dispo: "Admit acute cholecystitis/cholangitis for IV therapy + intervention (ERCP-capable centre); refer symptomatic gallstones for elective LC.", src: "Harrison 22e – Tokyo Guidelines 2018 (TG18)" },
    "the_hyperbilirubinemias": { name: "The Hyperbilirubinemias", class: "non_infective", system: "Hepatobiliary / Gastrointestinal", dx: "Confirm by fractionating serum bilirubin (conjugated vs unconjugated), excluding haemolysis and biliary obstruction; UGT1A1 genotyping where indicated.", tx: ["FRACTIONATE bilirubin first – unconjugated (Gilbert/Crigler-Najjar/haemolysis) vs conjugated (Dubin-Johnson/Rotor/cholestasis).","GILBERT syndrome – reassurance only; benign; no treatment; avoid needless workup.","Crigler-Najjar type II – PHENOBARBITAL induces residual UGT1A1, lowers bilirubin (>25% fall confirms type II).","Crigler-Najjar type I – PHOTOTHERAPY (intensive) + exchange transfusion/plasmapheresis for crises; NO response to phenobarbital; avoid bilirubin-displacing drugs (sulfonamides, ceftriaxone); LIVER TRANSPLANT definitive; prevent kernicterus.","Dubin-Johnson/Rotor – benign, no treatment; caution with OCP/pregnancy (may worsen jaundice)."], ix: ["Fractionated (direct/indirect) serum bilirubin","Haemolysis screen – FBC, reticulocytes, film, LDH, haptoglobin","LFTs (ALT/AST/ALP/GGT), albumin, INR","UGT1A1 genotyping (Gilbert/Crigler-Najjar)","Abdominal ultrasound if conjugated – exclude obstruction"], dispo: "Outpatient; reassure benign forms; refer Crigler-Najjar type I to hepatology/transplant centre.", src: "Harrison 22e - ACG Evaluation of Abnormal Liver Chemistries (2017)" },
    "toxic_and_drug_induced_hepatitis": { name: "Toxic and Drug-Induced Hepatitis", class: "non_infective", system: "Hepatobiliary / Gastrointestinal", dx: "Diagnosis of exclusion – temporal drug/toxin link + rising LFTs, exclude viral/autoimmune/biliary; RUCAM causality, biopsy if unclear.", tx: ["STOP the culprit drug/toxin immediately; document, never re-challenge.","N-ACETYLCYSTEINE for paracetamol per nomogram; consider in non-paracetamol ALF.","Supportive care – IV fluids, N/V control, monitor INR/bilirubin/encephalopathy daily.","CORTICOSTEROIDS for hypersensitivity/autoimmune-pattern DILI or checkpoint-inhibitor hepatitis.","REFER liver unit early for transplant if ALF / King's College criteria met."], ix: ["LFTs with R-ratio (ALT/ALP) – hepatocellular vs cholestatic pattern","INR/coagulation + serum bilirubin – severity, Hy's law prognosis","Serum paracetamol level + full drug/herbal/supplement/toxin history","Viral serologies (A/B/C/E) + autoimmune markers (ANA/SMA/IgG)","Abdominal ultrasound – exclude biliary obstruction/vascular cause"], dispo: "Admit if jaundice, coagulopathy or encephalopathy; escalate to liver unit/ICU for acute liver failure.", src: "Harrison 22e - ACG Idiosyncratic Drug-Induced Liver Injury Guideline (2021)" },
    "tumors_of_the_liver_and": { name: "Tumors of the Liver and Biliary Tree", class: "non_infective", system: "Hepatobiliary / Oncology", dx: "Confirm HCC by multiphasic CT/MRI showing arterial hyperenhancement + venous washout (LI-RADS 5) in cirrhotic liver; biopsy if imaging equivocal; biliary/gallbladder tumours need histology.", tx: ["RESECT or ABLATE early HCC — single lesion, Child–Pugh A, no portal HTN.","LIVER TRANSPLANT if within Milan criteria (cirrhosis + limited tumour burden).","TACE for intermediate multinodular HCC with preserved liver function.","ATEZOLIZUMAB + BEVACIZUMAB first-line for advanced HCC (screen/treat varices; Child–Pugh A).","Biliary/gallbladder cancer — surgical resection only cure; GEM–CIS + durvalumab if advanced."], ix: ["Multiphase contrast CT/MRI liver (arterial enhancement + washout)","AFP for HCC; CA 19-9 + CEA for biliary tract tumours","LFTs + Child–Pugh score + ECOG performance status","HBV/HCV serology; staging chest CT for metastases","Image-guided biopsy if imaging non-diagnostic"], dispo: "Refer to hepatobiliary MDT/tumour board; 6-monthly USS + AFP surveillance in at-risk cirrhotics.", src: "Harrison 22e - AASLD HCC Guidance (BCLC staging)" },
    "ACUTE_LIVER_FAILURE": { name: "Acute liver failure", class: "non_infective", system: "Hepatology", dx: "Rapid hepatocellular injury – INR ≥1.5 plus any encephalopathy, illness <26 weeks, no pre-existing cirrhosis.", tx: ["N-ACETYLCYSTEINE early – all-cause ALF; full IV protocol if paracetamol suspected/confirmed.","Treat the cause: aciclovir (HSV), penicillin+silibinin (Amanita), antivirals (HBV), steroids (autoimmune), chelation (Wilson).","Phone TRANSPLANT centre early – King's College criteria decide urgent listing; definitive therapy.","Raised ICP: intubate grade 3–4 HE; head-up 30°, hypertonic saline/mannitol; avoid hypotonic fluids/overhydration.","ICU support: 2-hourly glucose, correct K/PO4/Mg, sepsis surveillance; give FFP only if bleeding/procedure."], ix: ["Paracetamol level + toxicology screen; LFTs, INR/coagulation, arterial ammonia.","Viral serology (HAV/HBV/HCV/HEV, HSV), autoimmune panel, ceruloplasmin.","U&E, glucose, ABG + lactate, FBC, group & save.","Pregnancy test (?acute fatty liver/HELLP); paracetamol nomogram timing.","Liver USS with Doppler (Budd–Chiari, vasculature, size)."], dispo: "Admit ICU; urgent transfer to liver transplant unit if poor-prognosis (King's) criteria met.", src: "Harrison 22e - AASLD Acute Liver Failure guideline" },
    "alcohol_liver_disease": { name: "Alcohol-Associated Liver Disease", class: "non_infective", system: "Hepatology", dx: "Confirm by significant alcohol history plus AST:ALT >2 (both usually <300 IU/L), macrocytosis and compatible imaging; biopsy only if diagnosis uncertain – jaundice onset defines alcoholic hepatitis.", tx: ["ALCOHOL ABSTINENCE lifelong – treat withdrawal (benzodiazepines/thiamine), refer addiction services; acamprosate/baclofen for AUD.","NUTRITION: high-calorie high-protein feed (~35 kcal/kg, 1.2–1.5 g/kg/day); no protein restriction; replace thiamine, folate, zinc.","Severe alcoholic hepatitis (Maddrey DF>=32 / MELD>20): PREDNISOLONE 40 mg/day x 28 days; screen/treat infection first; consider adjunct N-acetylcysteine.","Assess steroid response by LILLE score at day 7 – stop if >=0.45 (non-responder, poor prognosis).","Manage cirrhosis/portal-hypertension complications; refer LIVER TRANSPLANT – early transplant in selected steroid non-responders."], ix: ["LFTs with AST:ALT ratio, bilirubin, GGT","INR/PT and MELD + Maddrey discriminant function","FBC (macrocytosis, thrombocytopenia), U&E, glucose","Abdominal ultrasound +/- transient elastography","Viral hepatitis serology, ferritin, autoimmune screen to exclude other cause; septic screen"], dispo: "Admit severe alcoholic hepatitis or decompensation; hepatology + addiction follow-up; documented abstinence essential for transplant listing.", src: "Harrison 22e - AASLD Practice Guidance on Alcohol-Associated Liver Diseases (2019)" },
    "AUTOIMMUNE_HEPATITIS": { name: "Autoimmune hepatitis", class: "non_infective", system: "Hepatology", dx: "Confirm with raised IgG + autoantibodies (ANA/ASMA/anti-LKM1/anti-SLA) and interface hepatitis on liver biopsy, having excluded viral/drug/alcoholic causes (IAIHG score).", tx: ["PREDNIS(OL)ONE induction – 40–60 mg/day mono, OR 30 mg + AZATHIOPRINE 50 mg combo (less steroid toxicity).","BUDESONIDE 9 mg/day alternative to prednisone in NON-cirrhotic to cut steroid side-effects.","Check TPMT before azathioprine; taper steroid to lowest dose once AST/ALT + IgG normalise, then azathioprine maintenance.","Refractory/intolerant → MYCOPHENOLATE or tacrolimus; add bone-protection + PJP prophylaxis on high-dose steroid.","Refer for LIVER TRANSPLANT if acute liver failure, decompensated cirrhosis or HCC."], ix: ["LFTs – AST/ALT, bilirubin, ALP, albumin, INR","Serum IgG / gamma-globulins","Autoantibodies – ANA, ASMA, anti-LKM1, anti-SLA/LP","Liver biopsy – interface hepatitis, plasma-cell infiltrate","Viral serology (HAV/HBV/HCV) to exclude"], dispo: "Admit if acute-severe/ALF (rising INR, encephalopathy); otherwise hepatology follow-up with biochemical titration to remission.", src: "Harrison 22e - AASLD 2019 AIH guidance" },
    "chronic_hepatitis": { name: "Chronic Hepatitis", class: "non_infective", system: "Hepatology", dx: "Aminotransferase elevation >6 months plus aetiology-specific serology/virology (HBsAg, anti-HCV/HCV RNA, ANA/SMA/IgG); elastography or biopsy for grade/stage.", tx: ["TREAT BY AETIOLOGY – HBV: ENTECAVIR or tenofovir (TDF/TAF) when DNA/ALT criteria met; lifelong if cirrhotic.","HCV: pangenotypic DIRECT-ACTING ANTIVIRALS (sofosbuvir-based) 8–12 wks – cure >95%, interferon-free.","Autoimmune: PREDNISOLONE + azathioprine; taper to lowest maintenance, treat to biochemical/histologic remission.","HCC SURVEILLANCE – 6-monthly USS ± AFP in cirrhosis; monitor renal/bone on TDF, marrow on azathioprine.","Refer decompensated disease/HCC for TRANSPLANT; give HBV prophylaxis before immunosuppression or chemotherapy."], ix: ["HBsAg, anti-HCV with reflex HCV RNA; HBeAg/anti-HBe, HBV DNA, HCV genotype","ALT/AST, bilirubin, albumin, INR, FBC","Autoimmune panel: ANA, ASMA, anti-LKM1, serum IgG","Fibrosis staging: transient elastography (FibroScan) or liver biopsy","USS ± AFP for HCC surveillance; co-infection screen (HIV, HDV, HAV/HBV immunity)"], dispo: "Outpatient hepatology follow-up; admit and refer for transplant if decompensated (jaundice, ascites, encephalopathy, coagulopathy).", src: "Harrison 22e - AASLD guidance (HBV/HCV/autoimmune hepatitis)" },
    "HEPATORENAL_SYNDROME": { name: "Hepatorenal syndrome", class: "non_infective", system: "Hepatology", dx: "Diagnosis of exclusion — AKI in cirrhosis with ascites, no response to 2-day diuretic withdrawal + albumin (1 g/kg/day), absent shock/nephrotoxins/structural renal disease.", tx: ["TERLIPRESSIN + IV albumin first-line; noradrenaline (ICU) or midodrine+octreotide+albumin where terlipressin unavailable.","ALBUMIN 1 g/kg (max 100 g) day 1, then 20–40 g/day; stop diuretics + nephrotoxins.","Treat precipitant — SBP: antibiotics + albumin; control variceal bleed; avoid uncovered large-volume paracentesis.","LIVER TRANSPLANT is definitive — refer early; RRT/TIPS as bridge in transplant candidates only.","Monitor terlipressin ischaemia/arrhythmia + fluid overload; taper vasoconstrictor once creatinine responds."], ix: ["Serum creatinine trend, urea, electrolytes, lactate","Urine Na (<10 mmol/L)/FeNa <1%, urine protein:creatinine (<500 mg/day), bland sediment","Renal ultrasound — exclude obstruction/parenchymal disease","Diagnostic paracentesis — ascitic PMN count + culture to exclude SBP","Cultures (blood/urine), LFTs, coagulation profile"], dispo: "Admit; ICU/HDU for HRS-AKI on vasoconstrictor infusion; urgent transplant-centre referral.", src: "Harrison 22e - AASLD 2021 (ICA-AKI criteria)" },
    "nafld": { name: "MASLD / NAFLD (Fatty Liver Disease)", class: "non_infective", system: "Hepatology", dx: "Hepatic steatosis on imaging (or biopsy) plus >=1 cardiometabolic risk factor, after excluding significant alcohol intake and other liver disease.", tx: ["WEIGHT LOSS 7–10% via hypocaloric diet + regular exercise — first-line, regresses steatohepatitis/fibrosis.","Treat metabolic drivers: GLP-1 agonist (semaglutide), STATIN for dyslipidaemia (safe), optimise T2DM/HTN.","RESMETIROM (thyroid hormone receptor-β agonist) for biopsy-proven MASH with F2–F3 fibrosis.","Vitamin E 800 IU/day (non-diabetic) or pioglitazone (T2DM) in selected biopsy-proven MASH.","Abstain alcohol; vaccinate HAV/HBV; if cirrhotic → HCC surveillance + varices screen; refer hepatology if F2+."], ix: ["FIB-4 score (age, AST, ALT, platelets) — first-line fibrosis risk stratification.","Vibration-controlled transient elastography (FibroScan) if FIB-4 indeterminate/high.","Liver ultrasound ± controlled attenuation parameter (CAP) to confirm/quantify steatosis.","Metabolic workup: fasting glucose/HbA1c, lipid profile, LFTs, BMI/waist.","Exclude alternatives: alcohol history, viral + autoimmune serology, ferritin/transferrin saturation."], dispo: "Manage in primary care/metabolic clinic; refer hepatology for F2+ fibrosis, cirrhosis, or diagnostic uncertainty.", src: "Harrison 22e - AASLD 2023 MASLD Practice Guidance" },
    "PRIMARY_BILIARY_CHOLANGITIS": { name: "Primary biliary cholangitis", class: "non_infective", system: "Hepatology", dx: "Confirm with cholestatic LFTs (raised ALP/GGT) plus positive AMA (or anti-sp100/gp210); biopsy only if AMA-negative or overlap suspected.", tx: ["URSODEOXYCHOLIC ACID 13–15 mg/kg/day PO for all — lifelong; assess biochemical response at 12 months.","Inadequate response (ALP >1.67×ULN or raised bilirubin): add OBETICHOLIC ACID or bezafibrate second-line — avoid OCA in decompensated cirrhosis.","Pruritus: CHOLESTYRAMINE first (dose apart from UDCA); escalate rifampicin → naltrexone → sertraline.","Supplement fat-soluble vitamins; calcium+vitamin D ± bisphosphonate for osteopenia; screen/treat associated thyroid + Sjögren.","Refer TRANSPLANT centre if decompensated, rising bilirubin, or intractable pruritus; HCC surveillance once cirrhotic."], ix: ["ALP, GGT, bilirubin, aminotransferases","AMA + antinuclear (anti-sp100/gp210), serum IgM","Transient elastography (FibroScan) for fibrosis staging","TSH, lipid profile, fat-soluble vitamin levels","DEXA bone densitometry at baseline"], dispo: "Outpatient hepatology follow-up; specialist/transplant centre if advanced fibrosis or refractory disease.", src: "Harrison 22e - AASLD 2018 PBC Practice Guidance" },
    "PRIMARY_SCLEROSING_CHOLANGITIS": { name: "Primary sclerosing cholangitis", class: "non_infective", system: "Hepatology", dx: "Confirm on MRCP – multifocal intra-/extrahepatic strictures with intervening dilatation (\"beaded\" ducts) plus cholestatic LFTs, after excluding IgG4 and secondary causes.", tx: ["LIVER TRANSPLANTATION – only life-extending therapy; refer early for end-stage disease, recurrent cholangitis or intractable pruritus.","ERCP + balloon dilatation for dominant strictures; brush cytology/biopsy to exclude cholangiocarcinoma.","Pruritus – CHOLESTYRAMINE first-line; escalate rifampicin → naltrexone → sertraline.","SURVEILLANCE – annual MRCP + CA 19-9 (cholangiocarcinoma), annual colonoscopy if IBD, gallbladder USS.","Acute cholangitis – prompt broad-spectrum ANTIBIOTICS; give ADEK vitamins + bone protection; avoid high-dose UDCA (>28 mg/kg/day harmful)."], ix: ["MRCP – diagnostic imaging of choice","Cholestatic LFTs (ALP, GGT, bilirubin)","Serum IgG4 – exclude IgG4-sclerosing cholangitis","Colonoscopy + biopsies – screen for associated IBD","CA 19-9 (cholangiocarcinoma surveillance)"], dispo: "Hepatology + transplant-centre referral; lifelong surveillance for hepatobiliary and colorectal malignancy.", src: "Harrison 22e - AASLD Practice Guidance on PSC (2022)" },
    "hemochromatosis": { name: "Hemochromatosis", class: "non_infective", system: "Hepatology / Metabolic", dx: "Confirm with raised transferrin saturation (>=45%) + ferritin, then HFE genotyping (C282Y homozygosity); MRI/biopsy to stage iron/fibrosis.", tx: ["THERAPEUTIC PHLEBOTOMY first-line: 1 unit (~500mL)/week until ferritin 50-100 ng/mL.","Maintenance phlebotomy 3-4x/yr to keep ferritin ~50-100 ng/mL; monitor Hb pre-each.","IRON CHELATION (deferasirox/desferrioxamine) only if anaemia/cardiac disease preclude phlebotomy.","Avoid iron/vitamin-C supplements + alcohol; treat diabetes, hypogonadism, arthropathy, heart failure.","Screen for HCC (US +/- AFP 6-monthly) if cirrhosis; screen + counsel first-degree relatives."], ix: ["Transferrin saturation (fasting) + serum ferritin","HFE gene mutation analysis (C282Y, H63D)","LFTs, glucose/HbA1c, testosterone/gonadotrophins","MRI liver (R2*/T2*) for iron quantification; cardiac MRI if cardiac involvement","ECG/echo; consider liver biopsy if ferritin >1000 or abnormal LFTs to stage fibrosis"], dispo: "Outpatient hepatology follow-up; lifelong phlebotomy programme + relative screening.", src: "Harrison 22e - AASLD Practice Guidance on Haemochromatosis" },
    "wilsons_disease": { name: "Wilson's Disease", class: "non_infective", system: "Hepatology / Neurology", dx: "Confirm with low serum ceruloplasmin + raised 24h urinary copper + Kayser–Fleischer rings; ATP7B mutation or raised hepatic copper if equivocal.", tx: ["CHELATION – trientine (preferred, better tolerated) or D-penicillamine first-line for symptomatic hepatic/neuro disease.","ZINC salts (acetate/sulfate) for maintenance + pre-symptomatic patients – blocks intestinal copper uptake; separate from chelator.","LOW-COPPER DIET – avoid shellfish, liver, nuts, chocolate, mushrooms.","ACUTE LIVER FAILURE / decompensated cirrhosis – urgent LIVER TRANSPLANT referral (curative).","Monitor 24h urinary + free copper, LFTs, FBC; lifelong therapy – never stop abruptly."], ix: ["Serum ceruloplasmin (low) + serum free (non-ceruloplasmin-bound) copper","24-hour urinary copper (elevated; also for treatment monitoring)","Slit-lamp exam for Kayser–Fleischer rings","LFTs, INR, FBC; MRI brain if neurological features","ATP7B genetic testing / liver biopsy for hepatic copper quantification"], dispo: "Hepatology referral, lifelong treatment; genetic counselling + screen first-degree relatives.", src: "Harrison 22e - AASLD Practice Guidance on Wilson Disease" },
    "igg4_related_disease": { name: "IgG4-Related Disease", class: "non_infective", system: "Immune-Mediated / Multisystem (Rheumatology)", dx: "Confirm by biopsy – dense lymphoplasmacytic infiltrate, storiform fibrosis, obliterative phlebitis, IgG4+/IgG+ >40%; correlate with raised serum IgG4, imaging and organ pattern (ACR/EULAR 2019 criteria).", tx: ["GLUCOCORTICOIDS first-line induction – prednisolone 0.6 mg/kg/day (~30–40 mg), taper over 3–6 months.","RITUXIMAB for relapsing, steroid-refractory or steroid-contraindicated disease (B-cell depletion).","Add steroid-sparing agent (azathioprine/MMF/methotrexate) to maintain remission, limit steroid toxicity.","Treat URGENTLY if vital organ threatened – biliary obstruction, aortitis, tubulointerstitial nephritis, pachymeningitis.","Monitor relapse – serum IgG4, imaging, organ function; watchful waiting only for asymptomatic single-gland disease."], ix: ["Serum IgG4 + IgG subclasses (baseline and monitoring)","Tissue biopsy with IgG4 immunostaining","Cross-sectional imaging (CT/MRI) ± PET-CT to map organ involvement","Renal/liver function, eosinophils, IgE, complement C3/C4","Exclude mimics – malignancy, lymphoma, ANCA vasculitis"], dispo: "Outpatient rheumatology follow-up; urgent admission/referral if vital-organ compromise.", src: "Harrison 22e – 2015 International Consensus Guidance on Management of IgG4-RD" },
    "familial_mediterranean_fever_and_other": { name: "Familial Mediterranean Fever and Other Hereditary Autoinflammatory Diseases", class: "non_infective", system: "Immune-mediated / Rheumatologic", dx: "Clinical — recurrent short (1–3 day) fevers with serositis (peritonitis/pleuritis/synovitis) in at-risk ethnicity; confirm with MEFV mutation analysis + raised acute-phase reactants during attack.", tx: ["COLCHICINE lifelong first-line — 1–1.5 mg/day, titrate; prevents attacks AND AA amyloidosis.","Never stop colchicine — continue in pregnancy/lactation; reduce dose in renal impairment; confirm adherence before labelling resistant.","IL-1 BLOCKADE (anakinra or canakinumab) for colchicine-resistant or intolerant disease.","NSAIDs for acute-attack symptom relief only — colchicine does NOT abort an established attack.","MONITOR serum amyloid A/CRP + urine protein for amyloidosis; rheumatology referral + genetic counselling."], ix: ["MEFV genotyping (± TNFRSF1A/MVK/NLRP3 panel if MEFV-negative/atypical)","CRP, ESR and serum amyloid A — during and between attacks","FBC — neutrophil leucocytosis during attacks","Urinalysis/protein:creatinine ratio — screen for AA amyloidosis","Exclude infection and other serositis causes during acute attack"], dispo: "Outpatient rheumatology; lifelong colchicine adherence; urgent review if proteinuria/renal signs (amyloidosis).", src: "Harrison 22e - EULAR recommendations for management of FMF (Ozen et al., 2016)" },
    "sj_gren_s_disease": { name: "Sjögren’s Disease", class: "non_infective", system: "Immune-Mediated / Rheumatologic", dx: "Confirm by ACR/EULAR 2016 criteria — anti-Ro/SSA positivity or labial gland focal lymphocytic sialadenitis (focus score ≥1), plus objective sicca.", tx: ["Treat sicca FIRST — artificial tears/gels + saliva substitutes; PILOCARPINE/cevimeline if residual gland function (avoid in uncontrolled asthma, angle-closure glaucoma, symptomatic bradyarrhythmia).","HYDROXYCHLOROQUINE first-line for arthralgia and mild systemic disease (fatigue/sicca benefit unproven — JOQUER negative); baseline + annual retinal screening.","GLUCOCORTICOIDS (lowest dose, short course) for active organ flares; add MTX/azathioprine/MMF as steroid-sparing.","RITUXIMAB for severe/refractory extraglandular disease — cryoglobulinaemic vasculitis, neuropathy, resistant parotid swelling.","MONITOR for B-cell lymphoma — persistent gland swelling, purpura, low C4, cryoglobulins; refer early."], ix: ["Anti-Ro/SSA + anti-La/SSB, ANA, RF","Schirmer test / ocular staining score; unstimulated salivary flow","Labial (minor) salivary gland biopsy — focus score","IgG, C3/C4, cryoglobulins, SPEP, β2-microglobulin (lymphoma/activity)","FBC, renal/LFTs, urinalysis (RTA, extraglandular involvement)"], dispo: "Outpatient rheumatology + ophthalmology co-management; admit for organ-threatening systemic disease or vasculitis.", src: "Harrison 22e - EULAR 2020 Sjögren's syndrome management recommendations" },
    "systemic_lupus_erythematosus": { name: "Systemic Lupus Erythematosus", class: "non_infective", system: "Immune-Mediated / Rheumatologic (multisystem)", dx: "Confirm clinically per EULAR/ACR 2019 criteria: obligatory ANA ≥1:80, then additive weighted clinical/immunologic features (anti-dsDNA, anti-Sm, low complement, nephritis, cytopenias); score ≥10 classifies.", tx: ["HYDROXYCHLOROQUINE for all (≤5 mg/kg/day actual weight) – reduces flares, organ damage, mortality; baseline eye exam then annual retinal screen from year 5 (earlier if risk factors).","GLUCOCORTICOIDS for active disease – pulse IV methylpred for organ/life-threatening; minimize and taper to ≤5 mg/day prednisone.","Add IMMUNOSUPPRESSANT/biologic early to spare steroids – MMF, azathioprine or methotrexate; consider belimumab or anifrolumab for persistent non-renal disease.","SEVERE lupus nephritis – induce with MMF or low-dose IV cyclophosphamide (Euro-Lupus) + steroids, and ADD belimumab or a CNI (voclosporin) as initial combination (EULAR 2023/KDIGO); rituximab if refractory. Severe NPSLE – cyclophosphamide + steroids.","Prophylaxis + monitoring – vaccines, sun protection, BP/lipids, calcium/vit D, bone/PCP protection on high-dose steroids; screen thrombosis (APS) and infection."], ix: ["ANA, anti-dsDNA, anti-Sm, anti-Ro/La, antiphospholipid antibodies (LA, aCL, anti-β2GPI)","C3/C4 complement (low = active); FBC (cytopenias)","Urinalysis + urine protein:creatinine ratio; renal function","Renal biopsy if proteinuria/active sediment (classify ISN/RPS nephritis)","ESR/CRP, LFTs, and disease-activity scoring (SLEDAI)"], dispo: "Rheumatology-led long-term care; urgent referral/admit for major organ involvement or severe flare.", src: "Harrison 22e; EULAR 2023 SLE recommendations; KDIGO lupus nephritis" },
    "desensitization": { name: "Desensitization", class: "non_infective", system: "Immunologic/Allergy", dx: "Confirm IgE-mediated (immediate) drug hypersensitivity by history +/- skin testing; desensitisation is for essential drugs when no equivalent alternative exists.", tx: ["CONFIRM indication: essential drug + immediate/IgE-type reaction + no safe alternative; NOT for SJS/TEN/DRESS.","SETTING: monitored bed/ICU with resuscitation kit; secure IV + continuous obs; hold beta-blockers/ACE-i where clinically safe; have GLUCAGON ready if beta-blocked (adrenaline may be ineffective).","INCREMENTAL DOSING: start ~1/10,000 target dose, DOUBLE every 15-30 min over 4-8h to full dose per validated drug-specific protocol.","Treat breakthrough reactions (antihistamine/adrenaline), hold/repeat last tolerated step, then resume.","MAINTAIN uninterrupted dosing thereafter - tolerance lost within ~48h off drug, needs repeat desensitisation."], ix: ["Detailed drug-reaction history + timing/phenotype","Skin prick/intradermal testing to culprit drug where validated (e.g. penicillin)","Baseline serum tryptase + observations (HR/BP/SpO2)","Baseline spirometry/peak flow if asthmatic/aspirin desensitisation","ECG + electrolytes if QT-prolonging/relevant drug protocol"], dispo: "Perform in monitored inpatient/ICU setting by allergy specialist; maintain continuous drug dosing afterwards.", src: "Harrison 22e - AAAAI/ACAAI Drug Allergy Practice Parameter" },
    "primary_immunodeficiency": { name: "Primary Immunodeficiency", class: "non_infective", system: "Immunology", dx: "Confirm with serum immunoglobulins, specific antibody responses to vaccines, lymphocyte subsets and targeted genetic testing, classified per IUIS scheme.", tx: ["IMMUNOGLOBULIN REPLACEMENT (IVIG/SCIG) for antibody deficiency – lifelong, target trough IgG >=5-8 g/L.","Treat infections early and aggressively; prophylactic co-trimoxazole (+/- antifungal) in selected defects.","AVOID LIVE VACCINES in T-cell/combined defects; give inactivated vaccines, screen contacts.","SCID/severe combined = emergency: urgent HSCT or gene therapy; irradiated CMV-neg leucodepleted products, PJP prophylaxis, isolate.","Refer clinical immunologist; surveil for bronchiectasis (CT/PFTs), autoimmunity and malignancy."], ix: ["Serum IgG, IgA, IgM, IgE + IgG subclasses","Specific antibody titres pre/post pneumococcal and tetanus vaccine","Lymphocyte subsets by flow cytometry (CD3/4/8, CD19, CD16/56)","FBC with differential; complement CH50/AH50","Molecular/genetic testing; newborn TREC screen if SCID suspected"], dispo: "Specialist immunology follow-up; lifelong therapy; urgent transplant referral for SCID.", src: "Harrison 22e - AAAAI/ACAAI Joint Task Force Practice Parameter (Primary Immunodeficiency)" },
    "urticaria_angioedema": { name: "Urticaria, Angioedema & Allergic Rhinitis", class: "non_infective", system: "Immunology / Allergy", dx: "Clinical: itchy weals each resolving <24h ± angioedema for urticaria; allergic rhinitis by seasonal/perennial sneeze–rhinorrhoea–congestion on allergen exposure.", tx: ["Airway threat/anaphylaxis or laryngeal angioedema → IM ADRENALINE 0.5mg + secure airway; O2, IV fluids, escalate.","Chronic spontaneous urticaria → SECOND-GENERATION H1-ANTIHISTAMINE first-line; updose to 4x standard before adding on.","Refractory urticaria → add OMALIZUMAB; then ciclosporin; avoid long-term systemic steroids.","Bradykinin angioedema (HAE/ACE-inhibitor) → stop ACE-i; C1-INH CONCENTRATE or icatibant — antihistamines/steroids/adrenaline ineffective.","Allergic rhinitis → INTRANASAL CORTICOSTEROID first-line ± antihistamine; allergen avoidance; immunotherapy if refractory."], ix: ["FBC + eosinophils, CRP/ESR","C4 + C1-esterase inhibitor level & function (recurrent angioedema without weals)","Serum tryptase (if anaphylaxis/mastocytosis suspected)","Allergen-specific IgE / skin-prick testing (rhinitis triggers)","TFTs + thyroid autoantibodies (chronic spontaneous urticaria)"], dispo: "Outpatient for most; admit airway-threatening angioedema/anaphylaxis; refer allergy/immunology if refractory or bradykinin-mediated.", src: "Harrison 22e - EAACI/GA2LEN/EuroGuiDerm/APAAACI urticaria guideline 2022 (allergic rhinitis per ARIA)" },
    "mastocytosis": { name: "Mastocytosis", class: "non_infective", system: "Immunology / Hematology", dx: "Confirm by WHO/ICC criteria. Major: multifocal dense mast-cell aggregates (>=15) in marrow/extracutaneous tissue. Minors: KIT D816V; aberrant CD25/CD2/±CD30; >25% atypical/spindle-shaped mast cells; baseline tryptase >20 ng/mL. Dx = 1 major + 1 minor OR 3 minors.", tx: ["ANTIHISTAMINES first-line (H1 + H2) for mediator symptoms; add oral cromolyn (GI), antileukotrienes PRN.","ADRENALINE autoinjector + strict trigger avoidance; lifelong venom immunotherapy if Hymenoptera anaphylaxis.","AVAPRITINIB (KIT D816V inhibitor) for advanced SM; also indolent SM (low-dose, post-2022 approval); midostaurin alt; ± cladribine cytoreduction.","BISPHOSPHONATES for mastocytosis osteoporosis; treat C-finding organ damage; consider alloSCT in MCL/advanced SM.","Refer specialist mastocytosis centre; stage disease before cytoreductive therapy."], ix: ["Serum baseline tryptase (exclude HAT via TPSAB1 copy number)","Bone marrow biopsy + aspirate with CD25/CD2/CD30 flow cytometry + morphology","KIT D816V mutation analysis (ASO-qPCR, blood/marrow)","FBC, LFTs, albumin to screen C-findings / AHN","DEXA for osteoporosis; abdominal imaging for organomegaly"], dispo: "Outpatient specialist follow-up; advanced/aggressive SM or MCL – tertiary haematology centre.", src: "Harrison 22e; ECNM/WHO 2022 consensus (avapritinib-ISM per 2023 approval, post-dates 22e)" },
    "porphyria": { name: "Porphyria", class: "non_infective", system: "Metabolic / Hematology", dx: "Acute attack: raised urinary PBG (Porphobilinogen) + ALA on spot urine (Watson–Schwartz/quantitative); confirm type by enzyme/genetic testing.", tx: ["IV HAEMIN (haem arginate/hemin 3–4 mg/kg OD, 4 days) — first-line to abort acute neurovisceral attack; give early.","HIGH-DOSE CARBOHYDRATE — IV glucose ≥300 g/day if haemin delayed or mild attack; use concentrated dextrose (central line) to avoid worsening hyponatraemia/fluid overload.","STOP all porphyrinogenic drugs (barbiturates, sulphonamides, oestrogens, alcohol); treat infection/fasting trigger.","Symptom control — opioids for pain, ondansetron for nausea, correct hyponatraemia/SIADH; monitor for respiratory/bulbar weakness (serial vital capacity).","GIVOSIRAN (RNAi) for recurrent attacks; beta-blocker for tachycardia/hypertension; avoid porphyrinogenic anticonvulsants (use gabapentin/levetiracetam or benzodiazepines for seizures)."], ix: ["Spot urine PBG + ALA (protect from light)","U&E — hyponatraemia (SIADH), fluid status","FBC, CRP, cultures — seek precipitating infection","ECG + continuous monitoring — arrhythmia/autonomic instability","Baseline enzyme assay / genetic testing to subtype"], dispo: "Admit; HDU/ICU if bulbar or respiratory weakness, severe hyponatraemia or autonomic instability.", src: "Harrison 22e - American Porphyria Foundation / EPNET acute porphyria guidance" },
    "lysosomal_storage_diseases": { name: "Lysosomal Storage Diseases", class: "non_infective", system: "Metabolic / Inherited (Endocrinology and Metabolism)", dx: "Confirm with disease-specific lysosomal enzyme assay (leucocyte or dried-blood-spot) plus molecular genetic testing.", tx: ["ENZYME REPLACEMENT THERAPY first-line, lifelong IV – Gaucher, Fabry, Pompe, MPS I/II/VI; start early.","SUBSTRATE REDUCTION oral (eliglustat/miglustat Gaucher; miglustat for Niemann-Pick C) if ERT unsuitable.","Oral CHAPERONE migalastat for amenable GLA mutations in Fabry disease.","HSCT for MPS I (Hurler) / severe neuronopathic forms – refer before irreversible neuro damage.","SUPPORTIVE: organ-complication care, genetic counselling; refer specialist metabolic centre for MDT follow-up."], ix: ["Leucocyte/dried-blood-spot enzyme activity assay (disease-specific)","Molecular mutation analysis – confirm + guide chaperone eligibility","Biomarkers: lyso-Gb1 (Gaucher), lyso-Gb3 (Fabry), urinary GAG (MPS)","Organ workup: ECG/echo, renal function, LFTs, FBC/platelets","Imaging – MRI (visceral/CNS), skeletal survey; bone marrow if needed"], dispo: "Refer to specialist metabolic/lysosomal centre for MDT, lifelong follow-up and family screening.", src: "Harrison 22e - European Working Group on Gaucher Disease (EWGGD) consensus; Fabry ERT/chaperone guidelines" },
    "inherited_disorders_of_amino_acid": { name: "Inherited Disorders of Amino Acid Metabolism in Adults", class: "non_infective", system: "Metabolic/Endocrine (inborn errors of metabolism)", dx: "Confirm on plasma amino acid profile plus disorder-specific metabolite (homocysteine, succinylacetone), then enzyme assay or gene testing.", tx: ["DIETARY precursor restriction is cornerstone – lifelong, dietitian-led (low-Phe PKU; low-Met homocystinuria; low-Tyr/Phe tyrosinaemia).","PKU: SAPROPTERIN (BH4) trial in responders; PEGVALIASE for adults with persistently high Phe.","Homocystinuria: PYRIDOXINE trial; add betaine + folate/B12; VTE thromboprophylaxis peri-operatively.","NITISINONE for tyrosinaemia type 1 (+ alkaptonuria) with low Tyr/Phe diet; surveil for HCC.","Acute decompensation: reverse catabolism – IV dextrose/calories, stop protein, treat trigger, urgent metabolic team."], ix: ["Plasma amino acids (Phe, Tyr, Met) + total homocysteine","Urine organic acids; succinylacetone if tyrosinaemia suspected","Enzyme assay / targeted gene panel to confirm","LFTs, AFP + liver imaging (HCC surveillance in tyrosinaemia)","Preconception plasma Phe in all women (maternal PKU risk)"], dispo: "Refer to specialist inherited-metabolic-disease centre for lifelong multidisciplinary follow-up.", src: "Harrison 22e - ACMG/European PKU management guidelines (Van Wegberg 2017)" },
    "paraneoplastic_syndromes_endocrinologic_he": { name: "Paraneoplastic Syndromes: Endocrinologic/Hematologic", class: "non_infective", system: "Multisystem (Oncology / Endocrine / Hematologic)", dx: "Confirm by measuring the ectopic mediator (PTHrP, ADH with paired serum/urine osmolality, ACTH+cortisol, EPO, IGF-2 with paired glucose/insulin) alongside an identified underlying malignancy.", tx: ["TREAT THE TUMOUR - definitive control of nearly all paraneoplastic syndromes; syndrome measures only bridge.","Hypercalcaemia (PTHrP): IV saline rehydration + ZOLEDRONIC ACID or denosumab; add calcitonin for rapid drop.","SIADH (ectopic ADH, esp SCLC): fluid-restrict; hypertonic (3%) saline if severe/symptomatic Na; tolvaptan/demeclocycline for refractory. Cap correction to avoid osmotic demyelination.","Ectopic Cushing's (ACTH): KETOCONAZOLE/metyrapone (etomidate if acute severe) to block steroidogenesis; bilateral adrenalectomy if refractory.","NICTH hypoglycaemia (IGF-2): IV glucose/frequent feeds + glucocorticoids (+/- glucagon/GH); definitive = tumour resection.","Trousseau VTE: LMWH (not warfarin; DOAC in selected cases); EPO-driven erythrocytosis - phlebotomy; granulocytosis/thrombocytosis usually need no tx."], ix: ["Serum calcium (corrected), PTH (suppressed), PTHrP","Serum + urine osmolality, serum Na, urine Na for SIADH","0800h ACTH, cortisol, 24h urinary free cortisol / dexamethasone suppression","Fasting glucose, insulin + C-peptide (suppressed), IGF-2:IGF-1 ratio if hypoglycaemia","FBC + film (erythrocytosis/granulocytosis/thrombocytosis), serum EPO","CT chest/abdomen/pelvis to localise tumour (SCLC workup if occult)"], dispo: "Urgent oncology + endocrinology referral; admit for hypercalcaemic crisis, severe symptomatic hyponatraemia, refractory hypoglycaemia or unstable Cushing's.", src: "Harrison 22e - Endocrine Society Clinical Practice Guideline (hypercalcaemia of malignancy)" },
    "the_vasculitis_syndromes": { name: "The Vasculitis Syndromes", class: "non_infective", system: "Multisystem / Rheumatologic (Immune-Mediated Vascular)", dx: "Confirm by biopsy of an affected organ plus ANCA serology (PR3/MPO); angiography/imaging for large-vessel disease.", tx: ["GLUCOCORTICOIDS high-dose immediately – IV methylprednisolone pulse if organ- or life-threatening (RPGN, alveolar haemorrhage).","RITUXIMAB (or cyclophosphamide) for induction in severe ANCA-associated disease; add AVACOPAN to spare steroids.","PLASMA EXCHANGE for severe RPGN (rising Cr/dialysis-dependent) or diffuse alveolar haemorrhage.","GCA – urgent high-dose steroids to prevent blindness; tocilizumab steroid-sparing; do NOT delay for biopsy.","PJP prophylaxis (co-trimoxazole) + rituximab maintenance; slow steroid taper."], ix: ["ANCA (PR3/anti-proteinase-3, MPO/anti-myeloperoxidase)","Urinalysis + microscopy + serum creatinine (screen RPGN)","CXR / CT chest (nodules, haemorrhage, sinus disease)","Tissue biopsy of involved organ (kidney, skin, nerve, lung)","ESR/CRP; complement, cryoglobulins, hepatitis B/C serology"], dispo: "Urgent rheumatology/nephrology referral; admit if organ- or life-threatening.", src: "Harrison 22e - ACR/Vasculitis Foundation 2021 guideline" },
    "periarticular_disorders_of_the_extremities": { name: "Periarticular Disorders of the Extremities", class: "non_infective", system: "Musculoskeletal", dx: "Clinical diagnosis — focal periarticular tenderness with pain on resisted/active movement; passive ROM relatively preserved in tendinitis/bursitis/epicondylitis (but RESTRICTED in adhesive capsulitis); distinguishes from true articular/septic-joint disease. Confirm with ultrasound or aspiration only if atypical.", tx: ["RELATIVE REST + activity modification, ice, short-course NSAIDs for pain/inflammation.","PHYSIOTHERAPY is core — eccentric loading/stretching for tendinopathy; graded ROM for adhesive capsulitis.","LOCAL CORTICOSTEROID injection if refractory bursitis/tendinitis/epicondylitis; avoid weight-bearing tendons (Achilles/patellar) — rupture risk.","ASPIRATE + Gram stain/culture first if septic bursitis suspected (olecranon/prepatellar); antibiotics covering S. aureus, drain if pus.","REFER surgery for structural/refractory disease — cuff tear, Dupuytren, carpal tunnel, resistant frozen shoulder."], ix: ["Focused exam — localise tenderness, pain on resisted motion, compare active vs passive ROM.","Ultrasound — confirm bursitis/tendinopathy/tear and guide injection.","Bursal fluid aspirate — Gram stain, culture, crystals if septic/crystal bursitis suspected.","Plain X-ray if trauma/chronic — calcific tendinitis, erosion, exclude bony/joint cause.","Inflammatory markers +/- urate if systemic inflammatory or crystal disease suspected."], dispo: "Manage in primary/outpatient care; refer orthopaedics/rheumatology if refractory, structural tear, or septic bursitis.", src: "Harrison 22e - AAOS clinical practice guidelines (soft-tissue/rotator cuff)" },
    "heritable_disorders_of_connective_tissue": { name: "Heritable Disorders of Connective Tissue", class: "non_infective", system: "Musculoskeletal / Genetic (multisystem connective tissue)", dx: "Clinical criteria for the specific disorder (e.g. revised Ghent nosology for Marfan) plus confirmatory molecular genetic testing.", tx: ["BETA-BLOCKER or ARB (losartan) to slow aortic-root dilatation in Marfan - titrate to HR/BP. ARB/losartan CONTRAINDICATED in pregnancy: use beta-blocker; pre-pregnancy aortic imaging + high-risk counselling (dissection risk).","Serial ECHO/CT-MR aortic surveillance; PROPHYLACTIC aortic-root surgery at >=5.0 cm (lower if family dissection, rapid growth, planned pregnancy, or Loeys-Dietz).","Restrict competitive/contact sport + isometric strain; genetic counselling + first-degree-relative screening.","Vascular EDS (COL3A1) - avoid arteriography/elective surgery; CELIPROLOL; urgent imaging for arterial/organ rupture.","BISPHOSPHONATES + calcium/vitamin D for osteogenesis imperfecta; proactive fracture care."], ix: ["Echocardiography - aortic-root/ascending diameter (Z-score).","CT/MR angiography of whole aorta - aneurysm/dissection surveillance.","Molecular genetic panel - FBN1, TGFBR1/2, COL3A1, COL1A1/2.","Slit-lamp exam - ectopia lentis; ophthalmology review.","DEXA + skeletal survey - osteogenesis imperfecta."], dispo: "MDT follow-up (cardiology/genetics/ortho); urgent referral for acute chest/back pain - suspect dissection.", src: "Harrison 22e - 2022 ACC/AHA Aortic Disease Guideline" },
    "fibromyalgia": { name: "Fibromyalgia", class: "non_infective", system: "Musculoskeletal / Rheumatologic", dx: "Clinical diagnosis — 2016 ACR criteria: widespread pain ≥3 months plus WPI/SSS thresholds; exclude mimics (diagnosis valid even with coexisting disease).", tx: ["EDUCATION + graded AEROBIC/strength EXERCISE – first-line for all; set expectations, self-management.","Persistent pain/poor sleep: low-dose AMITRIPTYLINE nocte; titrate slowly (caution elderly/cardiac).","Escalate to DULOXETINE (pain/low mood) or PREGABALIN (pain/sleep) per phenotype.","Add CBT for maladaptive coping, mood or catastrophising.","AVOID opioids (esp. strong) – taper/stop if prescribed. NSAIDs/paracetamol ineffective for FM pain – reserve for comorbid nociceptive conditions only."], ix: ["FBC, ESR/CRP (exclude inflammatory cause)","TSH (exclude hypothyroidism)","CK (exclude myopathy)","Vitamin D, calcium","ANA only if clinical features of connective-tissue disease"], dispo: "Primary-care/outpatient, multidisciplinary; refer rheumatology only if diagnosis uncertain.", src: "Harrison 22e - EULAR 2017 (fibromyalgia management)" },
    "gout_and_other_crystal_associated": { name: "Gout and Other Crystal-Associated Arthropathies", class: "non_infective", system: "Musculoskeletal / Rheumatologic", dx: "Confirm by demonstrating crystals in synovial fluid under polarised light — MSU: negatively birefringent needles (gout); CPPD: positively birefringent rhomboids (pseudogout).", tx: ["Treat acute flare EARLY: NSAID, low-dose COLCHICINE (1mg then 0.5mg 1h later), or corticosteroid — choose by comorbidity/renal function.","ALLOPURINOL first-line urate-lowering; start low, titrate to urate <360 umol/L (<300 if tophi); check HLA-B*5801 in high-risk ethnicity.","NEVER STOP existing ULT during a flare — continue through attacks; ULT may be INITIATED during a flare while treating it (ACR 2020); co-prescribe colchicine/NSAID prophylaxis 3-6 months when starting.","CPPD/pseudogout: NO urate-lowering — aspirate + intra-articular steroid; screen for haemochromatosis/hyperparathyroidism/hypomagnesaemia.","EXCLUDE septic arthritis before steroids — Gram stain + culture; treat empirically if any doubt."], ix: ["Synovial fluid: polarised microscopy for crystals, cell count, Gram stain + culture (exclude sepsis)","Serum urate (may be normal in acute attack — recheck at 2-4 weeks)","U&E/eGFR, glucose, lipids (metabolic + drug-dosing screen)","CRP/ESR/WCC (inflammatory activity)","Plain X-ray affected joint (erosions/tophi in gout; chondrocalcinosis in CPPD)"], dispo: "Outpatient rheumatology follow-up; admit if septic arthritis not excluded or polyarticular/systemically unwell.", src: "Harrison 22e - ACR 2020 Gout Management Guideline" },
    "relapsing_polychondritis": { name: "Relapsing Polychondritis", class: "non_infective", system: "Musculoskeletal / Rheumatologic", dx: "Clinical — recurrent chondritis of ≥2 cartilaginous sites (auricular, nasal, laryngotracheal) per Michet criteria, or 3 of 6 McAdam features; biopsy only if atypical.", tx: ["Mild (ear/nose/joints only): NSAIDs ± low-dose prednisolone; dapsone (check G6PD) or colchicine.","PREDNISOLONE 0.5–1 mg/kg first-line for active disease; IV methylprednisolone pulses if organ/airway-threatening.","Steroid-sparing early: METHOTREXATE or azathioprine; cyclophosphamide for severe organ/vasculitic disease; escalate to biologics (TNF-i, tocilizumab) if refractory.","Airway disease: urgent ENT + respiratory — secure airway; CPAP, stent or tracheostomy.","Refractory/older man with cytopenias: screen UBA1 (VEXAS); consider JAK inhibitor."], ix: ["ESR, CRP, FBC — track disease activity.","Dynamic expiratory HRCT chest + PFTs with flow-volume loops — airway involvement.","ECG + echocardiography; urinalysis, creatinine — cardiac/renal screen.","ANA, ANCA, RF — exclude overlap/mimics (esp. GPA).","UBA1 mutation ± bone marrow if older male with cytopenias — VEXAS/MDS."], dispo: "Rheumatology-led MDT; urgent admission with ENT/respiratory if airway or organ-threatening disease.", src: "Harrison 22e - French PNDS (relapsing polychondritis)" },
    "arthritis_associated_with_systemic_disease": { name: "Arthritis Associated with Systemic Disease, and Other Arthritides", class: "non_infective", system: "Musculoskeletal/Rheumatologic", dx: "Clinical – arthritis in a patient with a recognised systemic disorder; aspirate/image the joint to exclude sepsis and crystals and to define the pattern.", tx: ["TREAT THE UNDERLYING DISEASE first – arthropathy tracks systemic activity (phlebotomy in haemochromatosis, glycaemic control in diabetic neuropathic joints, hydration/analgesia/hydroxyurea ± transfusion in sickle disease).","NSAIDs/analgesia for joint pain; intra-articular corticosteroid for an isolated non-infective flare (only after sepsis excluded).","GLUCOCORTICOIDS for active relapsing polychondritis or chronic sarcoid arthritis – laryngotracheal chondritis is an airway emergency.","Neuropathic (CHARCOT) joint – offload/immobilise, keep non-weight-bearing, urgent orthopaedic/podiatry referral.","Hypertrophic osteoarthropathy – SCREEN for lung malignancy, treat the cause; NSAIDs or bisphosphonate for pain."], ix: ["Synovial fluid aspirate – cell count, polarised-light crystals, Gram stain/culture (exclude septic and crystal arthritis).","Ferritin/transferrin saturation plus targeted systemic workup (haemoglobin electrophoresis, immunoglobulins, lipids, LFTs).","Plain radiographs – chondrocalcinosis, periostitis, neuropathic joint destruction.","ESR/CRP.","CXR/CT chest if sarcoidosis or hypertrophic osteoarthropathy suspected."], dispo: "Rheumatology referral; MDT care directed at the underlying systemic disorder, with condition-specific specialist input.", src: "Harrison 22e - ACR rheumatology guidance" },
    "GOODPASTURE": { name: "Anti-GBM disease (Goodpasture)", class: "non_infective", system: "Nephrology", dx: "Confirm with positive serum anti-GBM antibody (ELISA) plus renal biopsy showing crescentic GN with linear IgG along the GBM.", tx: ["PLASMA EXCHANGE urgently — daily (~4L, albumin ± FFP) until anti-GBM undetectable (~2–3wk/~14 sessions); removes pathogenic antibody.","CORTICOSTEROIDS — IV methylprednisolone pulse 500–1000mg x3d, then oral prednisolone ~1mg/kg/day taper.","CYCLOPHOSPHAMIDE (oral 2–3mg/kg/day, dose-reduce for age >55/renal function) to suppress antibody synthesis; rituximab if intolerant.","SUPPORT — dialysis for uraemia/overload, transfuse/ventilate for alveolar haemorrhage, STOP smoking; add PJP/co-trimoxazole prophylaxis + gastric/bone protection while on immunosuppression.","Don't delay Rx awaiting biopsy if high suspicion; oligoanuric + dialysis-dependent + 100% crescents = poor renal recovery — treat mainly to protect lungs."], ix: ["Serum anti-GBM antibody (ELISA) — urgent","Renal biopsy — crescentic GN, linear IgG on immunofluorescence","ANCA (MPO/PR3) — ~20–30% double-positive, alters course","Creatinine/eGFR + urine microscopy (dysmorphic RBCs, red-cell casts)","CXR/CT chest + FBC; DLCO/KCO or bronchoscopy if pulmonary haemorrhage suspected"], dispo: "Admit under nephrology for urgent plasma exchange + immunosuppression; ICU if alveolar haemorrhage or respiratory compromise.", src: "Harrison 22e; KDIGO 2021 Glomerular Diseases" },
    "FSGS": { name: "Focal segmental glomerulosclerosis", class: "non_infective", system: "Nephrology", dx: "Kidney biopsy: focal + segmental glomerular sclerosis with podocyte foot-process effacement on EM (diffuse effacement favours primary, segmental favours adaptive/secondary); classify primary vs secondary vs genetic.", tx: ["CLASSIFY primary vs secondary vs genetic first — only primary responds to immunosuppression; treat cause in secondary.","RAAS BLOCKADE (ACEi/ARB) + SGLT2 inhibitor + BP target + salt restriction + statin — all patients; cornerstone of secondary/genetic FSGS.","PREDNISOLONE 1 mg/kg/day (max 80 mg) for primary nephrotic FSGS; continue high dose to remission then slow taper over ~6 months.","CALCINEURIN INHIBITOR (tacrolimus/ciclosporin) if steroid-resistant, steroid-dependent or relapsing.","Nephrotic supportive: loop diuretics for oedema, prophylactic anticoagulation if albumin very low; early nephrology referral."], ix: ["Urine protein:creatinine ratio / 24-h protein (nephrotic-range) + urinalysis for haematuria","Serum albumin + fasting lipids","Serum creatinine / eGFR","Secondary screen: HIV, hepatitis B/C, APOL1 + genetic panel if young/familial","Kidney biopsy with light, immunofluorescence + electron microscopy"], dispo: "Nephrology follow-up; track proteinuria + eGFR; counsel re primary-FSGS recurrence in kidney transplant.", src: "Harrison 22e - KDIGO 2021 Glomerular Diseases" },
    "glomerular_diseases": { name: "Glomerular Diseases (Spectrum)", class: "non_infective", system: "Nephrology", dx: "Confirm by urinalysis pattern (nephritic vs nephrotic), quantify proteinuria (UPCR/24h) + serology, and RENAL BIOPSY for definitive histology.", tx: ["CLASSIFY first – nephritic / nephrotic / RPGN; biopsy directs therapy and treat any underlying cause (infection, SLE, drug, HBV/HCV).","RAAS BLOCKADE (ACEi or ARB) for proteinuria + BP <130/80 (avoid in pregnancy); add SGLT2i, salt restriction + loop diuretics for oedema.","IMMUNOSUPPRESSION is HISTOLOGY-SPECIFIC – steroids first-line for minimal-change / FSGS / lupus (+MMF or cyclophosphamide); MEMBRANOUS → rituximab or cyclophosphamide-based / CNI (steroid monotherapy ineffective); ANCA → steroids + rituximab or cyclophosphamide; IgAN → optimise supportive/RAAS first, immunosuppress selectively.","RPGN / crescentic → urgent pulse IV METHYLPREDNISOLONE + cyclophosphamide or rituximab; add PLASMA EXCHANGE for anti-GBM and severe ANCA (dialysis-dependent / pulmonary haemorrhage).","Supportive: statin, prophylactic anticoagulation if nephrotic albumin <20–25 g/L (esp. membranous), vaccinate, PJP prophylaxis on heavy immunosuppression; early nephrology referral."], ix: ["Urine microscopy – dysmorphic RBCs, red-cell casts, proteinuria","UPCR or 24h urine protein; serum albumin + lipid profile","Serology – ANA/anti-dsDNA, ANCA, anti-GBM, C3/C4, HBV/HCV/HIV, cryoglobulins","Serum creatinine/eGFR, electrolytes, renal ultrasound","Renal biopsy for histological diagnosis (guides immunosuppression)"], dispo: "Refer nephrology; urgent admission for RPGN, rapidly rising creatinine/AKI or severe nephrotic complications.", src: "Harrison 22e - KDIGO 2021 Glomerular Diseases" },
    "IGA_NEPHROPATHY": { name: "IgA nephropathy", class: "non_infective", system: "Nephrology", dx: "Renal biopsy: mesangial IgA-dominant immune deposits on immunofluorescence, with MEST-C (Oxford) scoring.", tx: ["MAXIMISE RAS BLOCKADE – ACEi or ARB up-titrated to max tolerated; BP target <120 systolic (individualise in elderly/frail); salt restriction; stop ACEi/ARB if pregnancy planned/confirmed.","Add SGLT2 INHIBITOR (dapagliflozin) for proteinuria/CKD; plus statin, weight/smoking optimisation.","If proteinuria >0.75–1 g/day after >=90 days optimised care – reassess progression risk; consider SPARSENTAN (teratogenic – ensure contraception) or targeted-release budesonide.","High-risk progression – add systemic CORTICOSTEROIDS (reduced-dose TESTING regimen), weighing infection/toxicity; avoid if eGFR <30.","Crescentic IgAN with RPGN – pulse methylprednisolone + CYCLOPHOSPHAMIDE; urgent nephrology referral."], ix: ["Urinalysis + microscopy – dysmorphic RBCs, red-cell casts","Quantify proteinuria – uPCR or 24-h urine protein","Serum creatinine/eGFR with trend","Renal biopsy with MEST-C scoring","Exclude secondary/IgA vasculitis – LFTs, skin/joint/GI review, complement"], dispo: "Nephrology follow-up; serial eGFR/proteinuria/BP; urgent referral if RPGN or rising creatinine.", src: "Harrison 22e – KDIGO 2021 Glomerular Diseases Guideline" },
    "MEMBRANOUS_NEPHROPATHY": { name: "Membranous nephropathy", class: "non_infective", system: "Nephrology", dx: "Confirm via renal biopsy (subepithelial deposits, thickened GBM/spikes, granular IgG/C3) with serum anti-PLA2R antibody supporting primary disease.", tx: ["SUPPORTIVE first-line for all: ACEi/ARB + salt restriction + statin; treat oedema with loop diuretic.","ANTICOAGULATE if albumin <25 g/L or high VTE risk: warfarin or LMWH preferred (weigh bleeding risk); DOAC evidence limited in nephrotic syndrome.","Risk-stratify: watchful wait ~6 months in low risk (proteinuria <3.5 g, preserved eGFR, normal albumin, low/falling anti-PLA2R).","IMMUNOSUPPRESSION if moderate/high risk or persistent nephrotic-range: RITUXIMAB first-line, or cyclophosphamide+steroid (Ponticelli) - preferred if very-high-risk/rapidly declining eGFR - or CNI. NEVER steroid monotherapy (ineffective).","EXCLUDE secondary causes: malignancy, hepatitis B/C, SLE, drugs (NSAIDs, gold, penicillamine)."], ix: ["Serum anti-PLA2R antibody (and anti-THSD7A if available)","Urine protein:creatinine ratio / 24h protein + serum albumin","eGFR/creatinine, lipid profile","Hepatitis B/C serology, ANA/complement, age-appropriate malignancy screen","Renal biopsy with immunofluorescence + electron microscopy"], dispo: "Outpatient nephrology follow-up; monitor proteinuria, anti-PLA2R and renal function; admit for AKI, severe oedema or thromboembolism.", src: "Harrison 22e - KDIGO 2021 Glomerular Diseases Guideline" },
    "MINIMAL_CHANGE_DISEASE": { name: "Minimal change disease", class: "non_infective", system: "Nephrology", dx: "Renal biopsy shows normal glomeruli on light microscopy, diffuse podocyte foot-process effacement on EM, no immune deposits – children often treated empirically without biopsy.", tx: ["PREDNISOLONE first-line – oral high-dose (adults ~1 mg/kg/day, children 60 mg/m2/day); most remit.","Supportive: salt restriction + LOOP DIURETIC for oedema; ACEi/ARB; statin for hyperlipidaemia.","Frequent relapse/steroid-dependent/resistant: CALCINEURIN INHIBITOR (tacrolimus/ciclosporin), cyclophosphamide or RITUXIMAB.","Thromboprophylaxis if severe hypoalbuminaemia (<20-25 g/L) or high VTE risk.","Taper steroids slowly on remission; treat relapses; monitor steroid toxicity + BP/glucose."], ix: ["Urine protein:creatinine ratio / 24h protein – nephrotic-range","Serum albumin, lipid profile, U&E, creatinine","Renal biopsy (adults, or steroid-resistant/atypical children)","Screen secondary causes – NSAIDs, Hodgkin/lymphoma","Serologies to exclude other GN (complement, ANA where indicated)"], dispo: "Outpatient nephrology follow-up; admit if severe oedema, AKI, sepsis or thrombotic complication.", src: "Harrison 22e - KDIGO 2021 Glomerular Diseases" },
    "polycystic_kidney_disease": { name: "Polycystic Kidney Disease", class: "non_infective", system: "Nephrology", dx: "Confirm by age-adjusted ultrasound cyst criteria (Pei–Ravine) with positive family history; PKD1/PKD2 genetics if equivocal or no family history.", tx: ["BP CONTROL first-line ACEi/ARB monotherapy — target <=110/75 in young with preserved eGFR (HALT-PKD); slows cyst growth. Stop/switch peri-conception (teratogenic).","TOLVAPTAN for rapid progressors (Mayo 1C–1E / declining eGFR); LFTs at baseline, 2 and 4 wks, then monthly (18 mo) then 3-monthly; expect aquaresis, ensure water access.","FLUID intake to suppress vasopressin (individualise; caution in advanced CKD/hyponatraemia) + salt restriction; avoid caffeine, nephrotoxins, NSAIDs.","TREAT COMPLICATIONS — cyst infection lipophilic abx (ciprofloxacin/co-trimoxazole), haemorrhage rest+analgesia+hydration, stones; screen ICA (MRA) only if family history of ICA/SAH or symptoms.","PLAN RRT/transplant as eGFR falls; genetic counselling + relative screening; contraception/pre-pregnancy advice (ACEi/ARB and tolvaptan contraindicated in pregnancy)."], ix: ["Creatinine/eGFR + electrolytes","Urinalysis — haematuria, proteinuria, infection","Renal USS or MRI — total kidney volume, Mayo class","Ambulatory/clinic BP","LFTs baseline and per-protocol on tolvaptan"], dispo: "Nephrology follow-up; specialist-initiated tolvaptan with LFT and progression monitoring.", src: "Harrison 22e - KDIGO 2025 ADPKD Guideline" },
    "tubulointerstitial_disease": { name: "Tubulointerstitial Kidney Disease", class: "non_infective", system: "Nephrology", dx: "Confirm by kidney biopsy – interstitial oedema + inflammatory infiltrate with tubulitis (eosinophils in drug-induced AIN); supported by exposure history.", tx: ["WITHDRAW culprit drug at once – drugs are the commonest AIN trigger: NSAIDs, PPIs, beta-lactams, sulfonamides, rifampicin.","CORTICOSTEROIDS (prednisolone 0.5–1 mg/kg/day) early if no recovery post-withdrawal or biopsy-proven AIN; taper 4–6 weeks.","Treat underlying cause – infection, sarcoid, SLE, Sjögren, TINU, obstruction, myeloma.","Supportive – correct acidosis/electrolytes, avoid nephrotoxins, dose-adjust to eGFR, ensure euvolaemia.","Chronic TIN – manage as CKD: BP control, treat acidosis; refer for dialysis/transplant if ESKD."], ix: ["Serum creatinine/eGFR, electrolytes, bicarbonate","Urinalysis – sterile pyuria, WBC casts, mild tubular proteinuria","Renal ultrasound – size, echogenicity, exclude obstruction","Kidney biopsy – definitive when diagnosis unclear","Aetiology screen – ANA, complement, SPEP/serum free light chains, infection workup"], dispo: "Urgent nephrology referral; biopsy if uncertain; monitor for renal recovery.", src: "Harrison 22e – KDIGO (AKI 2012 / CKD 2024)" },
    "urinary_tract_obstruction": { name: "Urinary Tract Obstruction", class: "non_infective", system: "Nephrology / Urology", dx: "Confirm with renal-tract ultrasound showing hydronephrosis/hydroureter; CT KUB to localise level and cause.", tx: ["DECOMPRESS urgently – percutaneous nephrostomy or retrograde ureteric stent for upper-tract obstruction.","Obstruction + infection (pyonephrosis/urosepsis) – EMERGENCY drainage (nephrostomy preferred) + IV antibiotics + resuscitate; do not delay.","Lower-tract (BPH/urethral) – urethral or suprapubic CATHETER to relieve retention.","Treat cause – stone, tumour, stricture, retroperitoneal fibrosis; definitive therapy after decompression.","Watch POST-OBSTRUCTIVE DIURESIS – replace fluid/electrolytes, monitor K+, Na+, volume; treat hyperkalaemia."], ix: ["Renal-tract ultrasound – hydronephrosis, bladder volume","Non-contrast CT KUB – level and cause","U&E, creatinine, potassium – AKI, hyperkalaemia","Urinalysis + MC&S – infection","FBC, CRP, blood cultures, VBG if septic"], dispo: "Admit under urology; emergency decompression if infected, anuric or AKI.", src: "Harrison 22e; EAU Guidelines (Urological Infections; Urolithiasis 2024)" },
    "concussion_and_other_traumatic_brain": { name: "Concussion and Other Traumatic Brain Injuries", class: "non_infective", system: "Nervous system", dx: "Clinical – post-impact GCS drop, LOC/amnesia/confusion; non-contrast CT head confirms/excludes structural injury.", tx: ["STABILISE first – secure airway, AVOID hypoxia (SpO2>=90) & hypotension (SBP>=110); C-spine precautions; TXA within 3h if GCS 9-15 (CRASH-3; no benefit/possible harm in severe TBI with fixed pupils).","CT HEAD urgent – neurosurgical evacuation of surgical haematoma; reverse anticoagulation (PCC/vit K, idarucizumab or andexanet); antiplatelets – DDAVP/platelets ONLY if neurosurgery planned (routine platelet transfusion not beneficial, may harm).","RAISED ICP: head-up 30 degrees, sedation/analgesia, osmotherapy (mannitol or hypertonic saline), target CPP 60-70; EVD/ICP monitor if GCS<=8 + abnormal CT. NO steroids (increase mortality).","LEVETIRACETAM (or phenytoin) EARLY post-traumatic seizure prophylaxis x7 days in severe TBI (do not continue long-term); brief hyperventilation only as herniation bridge.","Mild/concussion: relative rest 24-48h then graded return-to-activity; NO same-day return to play; head-injury safety-net advice."], ix: ["Non-contrast CT head (Canadian CT Head Rule / NICE criteria)","GCS + serial neuro observations, pupils","Coagulation profile; reverse if anticoagulated","Cervical spine imaging if mechanism/exam suggests","Consider invasive ICP monitoring in severe TBI (GCS<=8)"], dispo: "Moderate/severe → neuro-ICU + neurosurgery referral; mild with normal CT → discharge with head-injury advice and concussion follow-up.", src: "Harrison 22e; Brain Trauma Foundation Severe TBI Guidelines (4th ed); CRASH-3 (TXA); CISG Amsterdam consensus (concussion return-to-play)" },
    "dementia_with_lewy_bodies": { name: "Dementia with Lewy Bodies", class: "non_infective", system: "Nervous system", dx: "Clinical – probable DLB = dementia + ≥2 core features (fluctuating cognition, recurrent visual hallucinations, REM sleep behaviour disorder, spontaneous parkinsonism); DaTscan supports.", tx: ["CHOLINESTERASE INHIBITOR (rivastigmine/donepezil) first-line – aids cognition, fluctuations, hallucinations; add memantine if progresses.","AVOID antipsychotics – severe neuroleptic sensitivity may be fatal; if unavoidable, low-dose QUETIAPINE/pimavanserin only.","LOW-DOSE LEVODOPA for disabling parkinsonism – titrate slowly; may worsen psychosis; avoid dopamine agonists/anticholinergics.","MELATONIN (±low-dose clonazepam) for REM sleep behaviour disorder; secure sleep environment.","Treat orthostatic hypotension/autonomic sx – non-drug measures first, then fludrocortisone/midodrine; carer support + falls review."], ix: ["Cognitive assessment – attention/executive/visuospatial deficit > memory","DaTscan (FP-CIT SPECT) – reduced striatal dopamine-transporter uptake","MRI brain – relative preservation of medial temporal lobe; exclude other causes","Polysomnography – confirm REM sleep behaviour disorder","MIBG cardiac scintigraphy (reduced uptake); bloods to exclude reversible dementia"], dispo: "Outpatient neurology/memory clinic; MDT + carer support; flag neuroleptic sensitivity on record.", src: "Harrison 22e - DLB Consortium 4th Consensus Criteria (McKeith 2017)" },
    "diseases_of_the_spinal_cord": { name: "Diseases of the Spinal Cord", class: "non_infective", system: "Nervous system", dx: "MRI of the whole spine with gadolinium localises the lesion and separates compressive (extrinsic) from intrinsic (intramedullary) myelopathy; CSF and serology define inflammatory vs infective cause.", tx: ["URGENT MRI whole spine (<24h) for any acute/progressive myelopathy — cord viability is time-critical.","Neoplastic (MSCC): DEXAMETHASONE 16 mg/day + PPI stat; definitive Rx = decompressive surgery (mechanical instability/selected good-prognosis single-level) and/or radiotherapy (radiosensitive, multilevel, poor surgical candidate).","Transverse myelitis/inflammatory: IV METHYLPREDNISOLONE 1 g/day x3–5; plasma exchange if steroid-refractory.","Epidural abscess: emergency SURGICAL DECOMPRESSION + IV empirical MRSA-active antibiotics (e.g. vancomycin + 3rd/4th-gen cephalosporin) after blood/cultures — avoid steroids.","Supportive: immobilise if unstable, catheterise retention, VTE prophylaxis, pressure-area & bowel care."], ix: ["MRI whole spine with gadolinium (first-line, urgent)","Bloods: FBC, CRP/ESR, B12/copper, HIV, aquaporin-4 & MOG antibodies, ACE","CSF: cell count, protein, oligoclonal bands, cultures/viral PCR","Screen for primary malignancy; CT if MRI contraindicated","Somatosensory evoked potentials/NCS if diagnosis unclear"], dispo: "Admit; emergency neurosurgery/neurology referral for any acute or progressive deficit.", src: "Harrison 22e - NICE NG234 (metastatic spinal cord compression)" },
    "neuromyelitis_optica": { name: "Neuromyelitis Optica", class: "non_infective", system: "Nervous system", dx: "Confirm with serum AQP4-IgG (cell-based assay) + MRI (longitudinally extensive myelitis / optic neuritis); apply 2015 IPND criteria.", tx: ["IV METHYLPREDNISOLONE 1 g/day × 3–5 days for acute attack — start early.","PLASMA EXCHANGE (5–7 cycles) if severe or steroid-refractory relapse.","RITUXIMAB first-line maintenance; or eculizumab/inebilizumab/satralizumab; azathioprine/MMF alternatives.","AVOID MS drugs (interferon-β, natalizumab, fingolimod) — worsen NMOSD.","Vaccinate + PJP prophylaxis before immunosuppression; treat neuropathic pain/spasticity."], ix: ["Serum AQP4-IgG cell-based assay","MRI spine + brain + orbits with gadolinium","MOG-IgG if AQP4-negative","CSF: pleocytosis; oligoclonal bands usually negative (unlike MS)","OCT/visual evoked potentials; autoimmune screen (ANA, anti-Ro/La)"], dispo: "Admit for acute attacks; lifelong neurology/neuro-immunology follow-up on relapse-prevention immunotherapy.", src: "Harrison 22e - International Panel for NMO Diagnosis (Wingerchuk 2015 criteria)" },
    "seizures_and_epilepsy": { name: "Seizures and Epilepsy", class: "non_infective", system: "Nervous system", dx: "Clinical – seizure semiology + eyewitness account; EEG supports; epilepsy = ≥2 unprovoked seizures >24 h apart, or 1 with high recurrence risk.", tx: ["ABC + immediate glucose/electrolyte check (give IV THIAMINE before/with glucose if alcohol misuse/malnutrition, to prevent Wernicke); if status epilepticus → IV LORAZEPAM 0.1 mg/kg (max 4 mg), repeat once.","Seizure persisting >5 min → LOAD fosphenytoin 20 PE/kg, or IV valproate/levetiracetam.","Refractory status → intubate + anaesthetic infusion (midazolam/propofol) under continuous EEG.","New unprovoked seizure/epilepsy → single-agent ASM by type: levetiracetam/lamotrigine (focal), valproate (generalised).","AVOID valproate in women of childbearing potential; correct reversible triggers – hypoglycaemia, alcohol withdrawal, non-adherence."], ix: ["EEG – interictal, sleep-deprived if normal","MRI brain (CT if acute/unstable) for structural focus","Capillary + serum glucose, electrolytes, Ca, Mg","Toxicology/alcohol screen + ASM drug levels","Lumbar puncture if suspected CNS infection or SAH"], dispo: "Admit status epilepticus/first seizure with deficits to ICU-capable unit; refer stable first seizure to neurology; advise driving restriction.", src: "Harrison 22e - AES Status Epilepticus Guideline (2016)" },
    "trigeminal_neuralgia_bell_s_palsy": { name: "Trigeminal Neuralgia, Bell’s Palsy, and Other Cranial Nerve Disorders", class: "non_infective", system: "Nervous system", dx: "Clinical – TN: paroxysmal unilateral lancinating V2/V3 pain, trigger zones; Bell's palsy: acute unilateral LMN facial weakness (forehead involved), a diagnosis of exclusion.", tx: ["TN: CARBAMAZEPINE first-line – start 100 mg BD, titrate to effect; oxcarbazepine if intolerant.","TN refractory: add baclofen/lamotrigine; refer for microvascular decompression or gamma-knife/percutaneous rhizotomy.","Bell's palsy: PREDNISOLONE 60 mg/day ×5–7d if started <72 h from onset, then taper.","Bell's palsy: add valaciclovir if severe/complete; EYE PROTECTION – lubricants + night taping to prevent corneal ulcer.","Red flags (bilateral, other CN signs, no recovery >3 mo) – MRI, exclude secondary cause, refer."], ix: ["MRI brain/brainstem +contrast – exclude MS, tumour, vascular loop, stroke.","Full cranial-nerve exam; House–Brackmann grade for facial palsy.","Blood glucose/HbA1c; Lyme serology if endemic or bilateral palsy.","Audiometry + ENT review if hearing loss or additional CN signs."], dispo: "Outpatient; urgent neurology/ENT referral if red flags, refractory pain, or no facial recovery by 3 months.", src: "Harrison 22e – AAN practice guidelines (trigeminal neuralgia & Bell's palsy)" },
    "nervous_system_disorders_in_critical": { name: "Nervous System Disorders in Critical Care", class: "non_infective", system: "Nervous System", dx: "Clinical neuro-exam + neuroimaging + EEG to exclude structural cause and define the metabolic/anoxic/septic aetiology of altered consciousness or weakness.", tx: ["TREAT underlying cause first – correct hypoxia/CO2/glucose/Na/Ca/sepsis; stop sedatives + culprit drugs.","THIAMINE 500mg IV tds before glucose if malnourished or Wernicke suspected.","Post-arrest: active temperature control – prevent fever (controlled normothermia ≤=37.5°C; 32–36°C acceptable per 2021 guideline); defer prognostication ≥72h off sedation.","Status/NCSE: BENZODIAZEPINE then IV levetiracetam/valproate; urgent EEG in unexplained coma.","ICU-acquired weakness: minimise sedation/NMBA/steroids, control glucose, early mobilisation."], ix: ["Metabolic screen – glucose, Na/Ca/Mg/PO4, urea/creatinine, LFTs, ammonia, ABG","EEG – exclude non-convulsive status epilepticus","CT/MRI brain – exclude structural/anoxic injury","LP if CNS infection suspected","NCS/EMG if flaccid weakness or failure to wean"], dispo: "ICU with continuous neuro-monitoring; early neurology input; defer neuroprognostication.", src: "Harrison 22e - ERC-ESICM 2021 Post-Resuscitation Care (TTM per 2022 ILCOR update: controlled normothermia)" },
    "disorders_of_the_autonomic_nervous": { name: "Disorders of the Autonomic Nervous System", class: "non_infective", system: "Nervous system (autonomic)", dx: "Neurogenic orthostatic hypotension — sustained SBP fall >=20 mmHg (or DBP >=10) within 3 min upright/tilt WITHOUT adequate compensatory HR rise; confirm with autonomic function testing.", tx: ["NON-PHARM first — withdraw offending hypotensives; liberalise salt/water, rapid 500 mL water bolus, waist-high/abdominal compression, head-up-tilt sleep, physical counter-manoeuvres.","MIDODRINE — first-line alpha1-agonist for symptomatic nOH; daytime dosing only, avoid within 4 h of lying supine.","DROXIDOPA (norepinephrine prodrug/pressor) or FLUDROCORTISONE (volume expansion) second-line; add pyridostigmine in milder disease (no supine-HTN worsening).","Manage supine hypertension separately — no evening pressor; head-up sleeping +/- short-acting antihypertensive nocte.","Treat underlying cause + refer neurology/autonomic — diabetic, Parkinson/MSA, amyloid, paraneoplastic."], ix: ["Active-standing + tilt-table beat-to-beat BP/HR","Autonomic battery — Valsalva, deep-breathing HRV, QSART/sudomotor","Supine and upright plasma noradrenaline (differentiate central vs peripheral)","Bloods — glucose/HbA1c, B12, TFT, SPEP/immunofixation, autonomic/paraneoplastic antibodies","ECG + medication review for offending agents"], dispo: "Outpatient autonomic/neurology follow-up; admit if syncope with injury, recurrent falls, or severe volume depletion.", src: "Harrison 22e - AAS consensus on neurogenic orthostatic hypotension (Gibbons et al. 2017)" },
    "ataxic_disorders": { name: "Ataxic Disorders", class: "non_infective", system: "Nervous system (cerebellum and spinocerebellar pathways)", dx: "Clinical gait/limb/truncal ataxia with dysarthria/nystagmus, confirmed on MRI (cerebellar/brainstem atrophy or structural lesion) plus targeted aetiological workup.", tx: ["TREAT reversible causes first – replace vitamin E/B12; give THIAMINE BEFORE GLUCOSE in alcohol/malnutrition (Wernicke); withdraw alcohol, phenytoin, toxins.","IMMUNOTHERAPY (steroids/IVIG/plasma exchange) for anti-GAD/paraneoplastic; GLUTEN-FREE DIET for coeliac ataxia.","ACETAZOLAMIDE for episodic ataxia type 2; OMAVELOXOLONE for Friedreich; copper chelation for Wilson's – prefer trientine/zinc over penicillamine in neurological disease (penicillamine may worsen).","SYMPTOMATIC – physiotherapy, occupational + speech therapy; gait aids, falls prevention; treat tremor/spasticity.","REFER neurology + genetics; counselling for hereditary SCA/Friedreich; malignancy screen if paraneoplastic. Acute cerebellar stroke/haemorrhage with mass effect = neurosurgical emergency (urgent decompression/EVD)."], ix: ["MRI brain – cerebellar/brainstem atrophy, structural lesion, MSA features","Bloods – B12, vitamin E, TSH, LFTs, glucose/HbA1c, copper/caeruloplasmin","Anti-TTG/gliadin, anti-GAD, paraneoplastic/onconeural antibody panel","Genetic testing – SCA panel, FXN (Friedreich), FMR1 premutation if hereditary","CSF (oligoclonal bands, cytology) if inflammatory/immune suspected"], dispo: "Neurology referral + MDT rehab; genetic counselling for hereditary; expedite workup if subacute/progressive; emergency neurosurgery if acute cerebellar lesion with mass effect.", src: "Harrison 22e; EFNS/ENS consensus on chronic ataxias in adulthood (2014)" },
    "primary_and_metastatic_tumors_of": { name: "Primary and Metastatic Tumors of the Nervous System", class: "non_infective", system: "Nervous system (neuro-oncology)", dx: "Confirm with contrast-enhanced MRI brain plus histological/molecular tissue diagnosis (stereotactic biopsy or resection); stage systemically if metastasis suspected.", tx: ["DEXAMETHASONE for symptomatic peritumoral oedema/raised ICP - withhold if CNS lymphoma suspected until biopsy.","MAXIMAL SAFE RESECTION where feasible, else stereotactic biopsy - secures molecular diagnosis.","Glioblastoma: RADIOTHERAPY + concurrent/adjuvant TEMOZOLOMIDE (Stupp); consider TTFields; anti-VEGF for recurrence.","Brain metastases: STEREOTACTIC RADIOSURGERY for limited lesions; surgery/WBRT by number + systemic control.","LEVETIRACETAM for seizures (no routine prophylaxis); VTE prophylaxis; hyperosmolar therapy (MANNITOL/hypertonic saline) + urgent neurosurgery for impending herniation."], ix: ["Contrast-enhanced MRI brain (+ whole spine if drop mets suspected)","Histopathology + molecular panel: IDH, 1p/19q co-deletion, MGMT methylation","CT chest/abdomen/pelvis +/- FDG-PET to identify primary if metastasis","Bloods: FBC, coagulation, glucose (steroid monitoring)","Serial neuro-obs; assess for raised ICP/papilloedema"], dispo: "Admit for raised ICP, new seizures or deficit; refer to neuro-oncology MDT.", src: "Harrison 22e; NCCN/EANO/ASCO CNS Cancers" },
    "myalgic_encephalomyelitis_chronic_fatigue": { name: "Myalgic Encephalomyelitis/ Chronic Fatigue Syndrome", class: "non_infective", system: "Neurologic / Multisystem", dx: "Positive clinical diagnosis, excluding mimics (IOM 2015 / NICE NG206): debilitating fatigue + post-exertional malaise + unrefreshing sleep, plus cognitive impairment or orthostatic intolerance; duration >=6 months (IOM) or >=3 months (NICE).", tx: ["ENERGY MANAGEMENT (pacing) – individualise activity within energy envelope; avoid post-exertional malaise.","Do NOT prescribe graded exercise therapy as a cure – NICE withdrew GET (2021).","Symptomatic Rx – sleep hygiene, step-wise analgesia for pain, salt/fluids ± midodrine for orthostatic intolerance.","CBT offered as supportive adjunct only, not curative; treat comorbid depression/anxiety.","REFER to specialist ME/CFS service; safety-net severe/bed-bound (nutrition, pressure care, VTE)."], ix: ["Bloods to exclude mimics – FBC, ESR/CRP, U&E, LFT, TFT, glucose/HbA1c","Ferritin, calcium, CK, vitamin D, B12/folate, coeliac serology","Active-stand test (lying/standing HR+BP) for orthostatic intolerance/POTS","Morning cortisol if adrenal insufficiency suspected; urinalysis","Avoid routine imaging/autoantibodies unless red flags – no confirmatory test exists"], dispo: "Primary/community care with referral to specialist ME/CFS service; regular structured review.", src: "Harrison 22e - NICE NG206 (2021); IOM 2015" },
    "alcohol_and_alcohol_use_disorders": { name: "Alcohol and Alcohol Use Disorders", class: "non_infective", system: "Neurologic / Psychiatric (multisystem)", dx: "Clinical: DSM-5 ≥2 of 11 criteria over 12 months; screen with AUDIT-C, grade withdrawal with CIWA-Ar.", tx: ["THIAMINE IV/IM before any glucose — prevent Wernicke; give fluids + correct Mg/K/phosphate.","BENZODIAZEPINE symptom-triggered by CIWA-Ar (diazepam/chlordiazepoxide; lorazepam if cirrhosis) — prevents seizures/DTs.","Delirium tremens: escalate benzo ± PHENOBARBITAL, ICU; dexmedetomidine/propofol as adjunct only, never monotherapy.","Maintenance: NALTREXONE first-line (or acamprosate); disulfiram if abstinent-motivated; add CBT/motivational therapy/AA.","Refer addiction services; treat comorbid depression; avoid naltrexone with opioid use or acute hepatic failure."], ix: ["Serial CIWA-Ar scoring for withdrawal severity","LFTs (AST:ALT >2:1), GGT, MCV, CDT","Electrolytes incl Mg, K, phosphate; glucose","Blood alcohol level ± urine drug screen","FBC, INR/coagulation; lipase if abdominal pain"], dispo: "DTs/seizures/high CIWA → admit (ICU if severe); mild → outpatient with monitoring + addiction referral.", src: "Harrison 22e - ASAM 2020 Alcohol Withdrawal Management CPG" },
    "nicotine_addiction": { name: "Nicotine Addiction", class: "non_infective", system: "Neurologic / Substance Use", dx: "Clinical: DSM-5 tobacco use disorder criteria + Fagerström-graded dependence in a current smoker.", tx: ["ASSESS dependence + readiness every visit; give brief advice + offer behavioural counselling (5 A's).","VARENICLINE first-line (ATS) - start 1/52 pre-quit, titrate to 1mg BD x 12/52; extend if relapse-prone.","Alternatives: combination NRT (patch + PRN gum/lozenge) or bupropion SR; combine varenicline+NRT in heavy smokers.","Always PAIR pharmacotherapy with counselling/quitline - synergistic; arrange follow-up within 1/52 of quit date.","Monitor nausea/insomnia/mood (EAGLES: no excess neuropsych risk); pregnancy - behavioural first, NRT if needed; avoid bupropion if seizure risk."], ix: ["Fagerström Test for Nicotine Dependence (severity/pharmacotherapy dosing)","Exhaled CO or cotinine to confirm abstinence","Screen for depression/anxiety + other substance use","Screen contraindications: seizure history (bupropion), renal function (varenicline)","Cardiorespiratory risk review +/- spirometry given smoking comorbidity"], dispo: "Outpatient/primary care; refer to specialist cessation clinic or quitline if repeated relapse.", src: "Harrison 22e - ATS 2020 (Initiating Pharmacologic Treatment in Tobacco-Dependent Adults)" },
    "cocaine_other_psychostimulants_and_halluci": { name: "Cocaine, Other Psychostimulants, and Hallucinogens", class: "non_infective", system: "Neurologic / Substance Use (Toxicology)", dx: "Clinical – sympathomimetic toxidrome (agitation, mydriasis, tachycardia, hypertension, hyperthermia, diaphoresis); urine toxicology confirms but does not alter acute management.", tx: ["IV BENZODIAZEPINES first-line – titrate for agitation/tachycardia/hypertension/seizures; low-stimulus environment; prefer over antipsychotics (seizure/thermoregulation/QT risk).","Aggressive ACTIVE COOLING if hyperthermia (>=39°C) – antipyretics useless; paralyse + intubate if refractory.","Cocaine chest pain: benzos + NITRATES + aspirin; phentolamine for vasospasm; AVOID beta-blockers (unopposed alpha).","Cocaine wide-QRS / ventricular dysrhythmia (Na-channel block) – IV SODIUM BICARBONATE.","Refractory hypertension – phentolamine or nitroprusside/CCB; IV fluids for rhabdomyolysis/renal protection.","Hallucinogen agitation – benzodiazepines + minimal stimulation; 'talk down' for LSD; PCP often violently unpredictable, avoid provocation; supportive care."], ix: ["ECG – ischaemia, wide QRS, QT","Troponin if chest pain","U&E, creatinine + CK (rhabdomyolysis)","Core temperature + capillary glucose","CT head if seizure/focal deficit/altered GCS"], dispo: "Monitored ED bed; ICU if hyperthermia, seizures, ACS or haemodynamic instability.", src: "Harrison 22e – AHA Scientific Statement on Cocaine-Associated Chest Pain & MI (Circulation 2008)" },
    "opioid_related_disorders": { name: "Opioid-Related Disorders", class: "non_infective", system: "Neurologic/Psychiatric (substance use)", dx: "Clinical: opioid overdose triad (depressed consciousness, respiratory depression, miosis) reversed by naloxone; opioid use disorder confirmed by DSM-5 criteria (≥2 of 11 over 12 mo) plus urine toxicology.", tx: ["NALOXONE 0.4–2 mg IV/IM/IN for acute overdose — support airway/ventilation (BVM) + O2; repeat q2–3 min; watch resedation vs long-acting/fentanyl.","BUPRENORPHINE–naloxone first-line MOUD — induct at COWS ≥8–12 to avoid precipitated withdrawal.","METHADONE alternative via licensed OTP — high tolerance/pregnancy; monitor QTc, titrate slowly.","NALTREXONE XR-IM for abstinent, motivated patients — needs 7–10 d opioid-free first (10–14 d if long-acting/methadone).","Withdrawal: clonidine/lofexidine + antiemetics + loperamide; issue take-home naloxone + harm-reduction."], ix: ["Urine drug screen (opioids, fentanyl, benzodiazepines, stimulants)","COWS score + DSM-5 severity assessment","ECG/QTc before and during methadone","LFTs before naltrexone","HIV/HCV/HBV serology + pregnancy test"], dispo: "Refer to addiction services/OTP; take-home naloxone, agonist maintenance, structured follow-up.", src: "Harrison 22e – ASAM National Practice Guideline for the Treatment of Opioid Use Disorder (2020 focused update)" },
    "alzheimers_disease": { name: "Alzheimer's Disease", class: "non_infective", system: "Neurology", dx: "Clinical diagnosis: insidious progressive amnestic-led cognitive decline impairing function; support with MRI atrophy + CSF (low Aβ42, high p-tau) or amyloid PET, after excluding reversible causes.", tx: ["CHOLINESTERASE INHIBITOR (donepezil / rivastigmine / galantamine) first-line mild–moderate; titrate slowly, watch bradycardia/GI upset.","Add MEMANTINE (NMDA antagonist) in moderate–severe; may combine with ChEI.","Anti-amyloid mAb (LECANEMAB / donanemab) only in early/MCI + biomarker-confirmed amyloid; serial MRI for ARIA; caution APOE ε4 homozygotes/anticoagulation.","Non-pharm core: cognitive stimulation, exercise, optimise vascular risk factors, carer education/support.","BPSD – non-drug first; AVOID antipsychotics (stroke/death risk); short-term low-dose risperidone only if severe/dangerous."], ix: ["MRI brain – medial temporal/hippocampal atrophy; exclude vascular/structural/NPH","Bloods: FBC, U&E, LFT, TSH, B12/folate, glucose, calcium (reversible causes)","Cognitive testing: MoCA/MMSE ± neuropsychology","CSF biomarkers (Aβ42, p-tau/t-tau) or amyloid PET if diagnosis uncertain / pre-mAb","APOE genotyping before anti-amyloid mAb (ARIA risk stratification)"], dispo: "Outpatient memory-clinic MDT follow-up; carer support, driving/capacity assessment, early advance-care planning.", src: "Harrison 22e - AAN practice guideline (dementia/MCI)" },
    "amyotrophic_lateral_sclerosis": { name: "Amyotrophic Lateral Sclerosis (ALS)", class: "non_infective", system: "Neurology", dx: "Clinical diagnosis — progressive UMN + LMN signs across multiple body regions without sensory loss; confirm with El Escorial/Awaji-Shima (or Gold Coast) criteria + EMG.", tx: ["RILUZOLE 50 mg BD — only drug proven to prolong survival; monitor LFTs monthly x3 then 3-monthly.","Add EDARAVONE (IV cycles or oral) in early, rapidly-progressive disease to slow functional decline.","NON-INVASIVE VENTILATION when FVC falls / orthopnoea / hypercapnia — improves survival + QoL.","GASTROSTOMY (PEG/RIG) early for dysphagia + weight loss; place before FVC <50%.","Symptomatic + palliative: anticholinergics/botulinum for sialorrhoea, baclofen for spasticity, dextromethorphan-quinidine for pseudobulbar affect; early advance-care planning."], ix: ["EMG/nerve conduction studies — confirm widespread active + chronic denervation.","MRI brain + whole spine — exclude structural/compressive mimics.","Bloods — CK, TSH, B12, serum protein electrophoresis, anti-GM1 (rule out mimics).","Respiratory function — FVC (erect + supine), SNIP; monitor serially.","Genetic testing — C9orf72, SOD1 (familial or before tofersen consideration)."], dispo: "Refer to multidisciplinary ALS clinic with early respiratory, nutrition and palliative-care linkage.", src: "Harrison 22e - AAN ALS Practice Parameter" },
    "AUTOIMMUNE_ENCEPHALITIS": { name: "Autoimmune encephalitis", class: "non_infective", system: "Neurology", dx: "Confirm via paired serum/CSF autoantibody panel plus CSF, MRI and EEG in the right clinical syndrome.", tx: ["FIRST-LINE IMMUNOTHERAPY early — IV methylprednisolone 1g/day x5d + IVIG 0.4g/kg/day x5d or plasma exchange.","SECOND-LINE if refractory — RITUXIMAB and/or cyclophosphamide; escalate within ~2 weeks.","REMOVE TUMOUR — screen for and resect ovarian teratoma (anti-NMDAR) / offer occult malignancy hunt.","Control seizures (AEDs) and treat autonomic instability/dysautonomia; ICU + ventilation if severe.","Long-term maintenance immunosuppression (rituximab/MMF/azathioprine) to prevent relapse; psychiatric support."], ix: ["CSF: cell count, protein, glucose, oligoclonal bands; paired serum + CSF autoantibody panel","MRI brain with contrast (mesial temporal T2/FLAIR hyperintensity)","EEG (extreme delta brush in anti-NMDAR; seizures/slowing)","Tumour screen: pelvic/scrotal USS, CT chest-abdomen-pelvis +/- whole-body PET","Baseline bloods, HIV/viral PCR and infective workup to exclude infectious encephalitis"], dispo: "Admit; ICU if reduced GCS, status epilepticus or autonomic instability; neurology + immunotherapy referral.", src: "Harrison 22e - Autoimmune Encephalitis Management (Graus/Titulaer consensus, Lancet Neurol)" },
    "CEREBRAL_VENOUS_THROMBOSIS": { name: "Cerebral venous sinus thrombosis", class: "non_infective", system: "Neurology", dx: "Confirm with MR venography (or CT venography) showing thrombus/absent flow in a dural sinus or cerebral vein.", tx: ["ANTICOAGULATE – therapeutic-dose LMWH promptly, even when haemorrhagic venous infarct present.","Transition to warfarin INR 2–3 for 3–12 months; dabigatran a DOAC alternative (RE-SPECT CVT).","Escalate – endovascular thrombectomy if neurological deterioration despite adequate anticoagulation.","Control raised ICP – head-up, acetazolamide; decompressive craniectomy if herniation threatened.","Treat cause + seizures (AEDs); if VITT suspected use NON-heparin agent + IVIG, avoid platelets."], ix: ["MRI brain + MR venography (or CT venography) – confirms sinus/vein thrombosis","FBC, coagulation profile, D-dimer (normal does not exclude)","Thrombophilia/prothrombotic screen once acute phase settled","Anti-PF4 antibodies + platelets if recent heparin/vaccine (HIT/VITT)","Screen for cause – pregnancy test, infection, dehydration, malignancy"], dispo: "Admit stroke unit/HDU with neurology + neurosurgery input; urgent if reduced GCS or large infarct.", src: "Harrison 22e – ESO guideline on cerebral venous thrombosis (2017)" },
    "CIDP": { name: "Chronic inflammatory demyelinating polyneuropathy", class: "non_infective", system: "Neurology", dx: "Progressive/relapsing proximal+distal (typically symmetric) weakness developing >8 weeks with hypo/areflexia; NCS shows demyelination (conduction block, temporal dispersion, prolonged distal latencies, slowed velocity, prolonged F-waves); CSF albuminocytological dissociation (raised protein, normal cells) supports.", tx: ["FIRST-LINE, all effective: IVIG 2 g/kg over 2–5 days, OR corticosteroids (prednisolone / pulsed IV methylprednisolone or dexamethasone), OR plasma exchange.","IVIG preferred for pure motor CIDP — corticosteroids/PLEX may WORSEN pure motor disease, avoid; maintenance IVIG (e.g. 1 g/kg q3wk) or SCIG, titrated to lowest effective dose.","Corticosteroids favoured when drug-free remission is the goal (sensory/relapsing); add steroid-sparing azathioprine/MMF/rituximab if steroid-dependent or refractory (rituximab esp. for IgG4 anti-nodal/paranodal disease).","IVIG safety: thrombosis and AKI risk — caution in elderly, renal impairment, CV/hyperviscosity; avoid sucrose-stabilised products in renal impairment; screen IgA deficiency; watch aseptic meningitis. IVIG, PLEX and corticosteroids all acceptable in pregnancy.","Escalate/switch first-line class if no response in ~12 wk; reassess diagnosis — exclude anti-nodal/paranodal (NF155, CNTN1, Caspr1) causing IVIG resistance (treat with rituximab).","Monitor function (grip, gait, INCAT/I-RODS) not just NCS; taper therapy periodically to confirm ongoing need and avoid overtreatment."], ix: ["Nerve conduction studies/EMG — demyelinating features (pivotal)","Lumbar puncture — CSF protein raised, cells normal","Serum protein electrophoresis + immunofixation, anti-MAG — exclude paraprotein/MGUS and MAG neuropathy","Nodal/paranodal antibodies (NF155, CNTN1, Caspr1) if atypical or IVIG-refractory","Bloods: glucose/HbA1c, TSH, HIV, B12; MRI plexus/roots (± gadolinium, root/plexus hypertrophy or enhancement) if uncertain"], dispo: "Outpatient neurology; admit for severe/rapidly progressive weakness or for infusion; long-term follow-up with periodic treatment re-evaluation and taper attempts.", src: "Harrison 22e; EAN/PNS CIDP Guideline 2021" },
    "frontotemporal_dementia": { name: "Frontotemporal Dementia", class: "non_infective", system: "Neurology", dx: "Clinical — progressive behavioural/personality change (bvFTD) or language decline (PPA); supported by frontotemporal atrophy on MRI and Rascovsky/Gorno-Tempini consensus criteria.", tx: ["NON-PHARMACOLOGICAL first — carer education, structured routine, environmental/behavioural strategies, home-safety measures.","SSRI (sertraline, citalopram/escitalopram; avoid paroxetine — anticholinergic) or trazodone — for disinhibition, compulsions, overeating, agitation.","AVOID cholinesterase inhibitors and memantine — no benefit, may worsen behaviour.","Antipsychotics only for dangerous agitation — low-dose atypical, short-term; EPS/mortality risk.","REFER MDT — cognitive neurology, SALT for PPA, genetic counselling; early advance-care planning + capacity/driving review."], ix: ["MRI brain — frontal/anterior-temporal atrophy, often asymmetric","FDG-PET — frontotemporal hypometabolism if MRI equivocal","Neuropsychological testing — executive dysfunction/language profile","Bloods — TFTs, B12, HIV, syphilis to exclude reversible mimics","Genetic testing (C9orf72, GRN, MAPT) if familial/young-onset"], dispo: "Outpatient memory/cognitive-neurology clinic + carer support; admit only for behavioural-safety crises.", src: "Harrison 22e - FTDC (Rascovsky) bvFTD consensus criteria" },
    "movement_disorders": { name: "Movement Disorders (Tremor, Chorea, Dystonia)", class: "non_infective", system: "Neurology", dx: "Bedside phenomenology — classify as tremor (rest/postural/action), chorea, or dystonia; then pin the cause (drug-induced, Wilson, HD gene, structural, autoimmune).", tx: ["Essential tremor: PROPRANOLOL or primidone 1st-line; topiramate/gabapentin 2nd; DBS or focused-ultrasound thalamotomy if refractory.","Chorea: treat cause — immunotherapy (+/- tumour removal) for autoimmune/anti-NMDAR, anti-strep/immunomod for Sydenham — then suppress with VMAT2 INHIBITOR (tetrabenazine/deutetrabenazine) or antidopaminergic; Wilson: trientine or zinc (avoid penicillamine 1st in neuro Wilson — paradoxical worsening).","Focal dystonia: BOTULINUM TOXIN injection 1st-line; trihexyphenidyl/baclofen for generalised; pallidal (GPi) DBS if refractory.","Always trial LEVODOPA in young-onset dystonia (dopa-responsive); STOP offending neuroleptics/metoclopramide in drug-induced cases.","Refer to movement-disorder specialist; screen Wilson in young chorea/dystonia; monitor mood/suicide risk in HD (VMAT2 black-box)."], ix: ["MRI brain","Serum copper/ceruloplasmin, 24h urinary copper + slit-lamp (Wilson) if young onset","HTT genetic testing if chorea with family history","TFTs, FBC + peripheral smear (acanthocytes), electrolytes, full drug/toxin review","Autoimmune/paraneoplastic panel (anti-NMDAR) + ASO if acute chorea"], dispo: "Outpatient neurology/movement-disorder clinic; admit if acute chorea, status dystonicus, or Wilsonian crisis.", src: "Harrison 22e - AAN essential tremor practice guideline" },
    "myasthenia_gravis": { name: "Myasthenia Gravis", class: "non_infective", system: "Neurology", dx: "Fatigable proximal/ocular/bulbar weakness confirmed by positive anti-AChR (or anti-MuSK) antibodies plus decrement on repetitive nerve stimulation or jitter on single-fibre EMG.", tx: ["PYRIDOSTIGMINE first-line symptomatic – titrate to effect; watch cholinergic excess.","Immunosuppress: PREDNISONE (start low, uptitrate) + steroid-sparing azathioprine/mycophenolate.","MYASTHENIC CRISIS – intubate for respiratory failure; give IVIG or plasma exchange, NOT anticholinesterase alone.","THYMECTOMY in thymoma; also generalised AChR+ <60y non-thymomatous disease.","AVOID triggers – aminoglycosides, fluoroquinolones, magnesium, beta-blockers, neuromuscular blockers."], ix: ["Anti-AChR antibodies; if negative, anti-MuSK and anti-LRP4","Repetitive nerve stimulation and single-fibre EMG","CT/MRI chest for thymoma","TFTs and other autoimmune screen (thyroid, ANA)","FVC/NIF + bedside spirometry to gauge respiratory reserve"], dispo: "Neurology referral; admit/ICU if bulbar involvement or falling FVC (crisis risk).", src: "Harrison 22e – AAN/International Consensus Guidance for MG (Narayanaswami 2021)" },
    "SARCOID_NEURO": { name: "Neurosarcoidosis", class: "non_infective", system: "Neurology", dx: "Confirm by tissue biopsy showing non-caseating granulomas plus compatible MRI/CSF and exclusion of mimics (definite/probable per Consortium criteria).", tx: ["CORTICOSTEROIDS first-line: prednisolone 0.5-1 mg/kg/day; IV methylprednisolone 1 g/day x3-5d if severe/acute (cord, optic, encephalopathy).","Add STEROID-SPARING agent early - methotrexate (or azathioprine/mycophenolate) to enable taper and cut relapse; MTX/MMF teratogenic - prefer azathioprine in pregnancy/childbearing potential.","Refractory/severe disease: INFLIXIMAB (anti-TNF); screen latent TB + HBV first.","Taper prednisolone slowly over months; most need >=6-12 months therapy - monitor for relapse.","Monitor: glucose/BP, bone protection, FBC/LFTs; consider PCP prophylaxis on combined immunosuppression."], ix: ["MRI brain/whole spine with gadolinium - leptomeningeal/parenchymal/cranial-nerve enhancement.","CSF: lymphocytic pleocytosis, high protein, normal/low glucose, raised CSF ACE, oligoclonal bands.","Serum ACE + calcium; chest CT/FDG-PET to map systemic disease and biopsy target.","Tissue biopsy (accessible node/lung/skin) - non-caseating granulomas.","Exclude TB, fungal infection, lymphoma, vasculitis before immunosuppression."], dispo: "Neurology + sarcoidosis MDT referral; admit if acute severe deficit (myelopathy, encephalopathy, vision loss).", src: "Harrison 22e - Neurosarcoidosis Consortium Consensus Group (2018)" },
    "parkinsons_disease": { name: "Parkinson's Disease", class: "non_infective", system: "Neurology", dx: "Clinical diagnosis: bradykinesia PLUS resting tremor and/or rigidity, asymmetric onset, with sustained levodopa response; DaTscan only if uncertain.", tx: ["LEVODOPA/carbidopa – first-line for disabling motor symptoms; titrate to lowest effective dose, esp. older patients.","Younger/mild disease: MAO-B inhibitor (rasagiline) or dopamine agonist (pramipexole/ropinirole) to delay levodopa.","Motor fluctuations – fractionate levodopa, add COMT inhibitor (entacapone) or MAO-B; AMANTADINE for troublesome dyskinesia.","Refractory fluctuations – DEEP BRAIN STIMULATION (STN/GPi) or continuous apomorphine / intestinal levodopa gel.","Treat non-motor (orthostatic hypotension, depression, REM-sleep, constipation); psychosis – quetiapine/clozapine/pimavanserin; AVOID dopamine-blockers; watch impulse-control disorders on agonists."], ix: ["Bedside UPDRS motor exam ± levodopa response assessment","MRI brain – exclude vascular/structural/atypical parkinsonism","DaTscan (dopamine-transporter SPECT) if diagnosis uncertain","Orthostatic BP; cognitive and mood screen","Screen non-motor: sleep, autonomic, olfaction"], dispo: "Outpatient neurology follow-up; refer to movement-disorder specialist for fluctuations, dyskinesia or DBS assessment.", src: "Harrison 22e – AAN Parkinson's Disease Practice Guideline" },
    "peripheral_neuropathy": { name: "Peripheral Neuropathy", class: "non_infective", system: "Neurology", dx: "Clinical pattern confirmed on NCS/EMG; classify axonal vs demyelinating.", tx: ["TREAT THE CAUSE first – tight glycaemic control, replace B12/thiamine/folate, stop alcohol/neurotoxic drugs.","IMMUNOTHERAPY for inflammatory forms – IVIG or plasma exchange (GBS); IVIG/steroids (CIDP); NO steroids in GBS.","NEUROPATHIC PAIN – first-line duloxetine, pregabalin, gabapentin or amitriptyline; titrate to effect.","Foot care, fall/injury prevention, treat autonomic features (postural BP, gut, bladder).","URGENT referral if rapidly progressive/ascending weakness or respiratory/autonomic compromise – exclude GBS."], ix: ["NCS/EMG – confirm, classify axonal vs demyelinating, length-dependent","HbA1c/fasting glucose ± OGTT, B12/folate, TSH","FBC, U&E, LFTs, ESR/CRP, serum protein electrophoresis + immunofixation","CSF (raised protein in GBS/CIDP), autoimmune/vasculitis screen if multifocal","Consider genetic testing or nerve biopsy if atypical/undiagnosed"], dispo: "Outpatient neurology; admit if rapidly progressive weakness, respiratory or autonomic instability, or suspected GBS.", src: "Harrison 22e - AAN Practice Guideline: Oral/Topical Treatment of Painful Diabetic Polyneuropathy (2022)" },
    "prion_diseases": { name: "Prion Diseases (CJD)", class: "non_infective", system: "Neurology", dx: "Rapidly progressive dementia with myoclonus and ataxia; confirm via CSF RT-QuIC plus DWI-MRI cortical ribboning – definitive on neuropathology.", tx: ["NO disease-modifying/curative therapy – PALLIATIVE + supportive care is mainstay; early advance-care planning.","Symptom control: MYOCLONUS – clonazepam (or levetiracetam/valproate); treat agitation/psychosis symptomatically.","INFECTION CONTROL – prion-specific instrument decontamination per WHO (NaOH + extended autoclave); single-use where possible.","NOTIFY national CJD surveillance unit (mandatory); genetic counselling + PRNP testing if familial.","Supportive: aspiration precautions, nutrition, pressure-area/skin care, carer support."], ix: ["CSF RT-QuIC (plus 14-3-3 protein, total tau)","MRI brain DWI/FLAIR – cortical ribboning + basal-ganglia signal","EEG – periodic sharp-wave complexes (sporadic CJD)","PRNP gene testing + codon-129 genotype","Exclude treatable mimics: autoimmune/paraneoplastic encephalitis panel, TFTs, B12"], dispo: "Admit to exclude reversible mimics/confirm dx; then palliative-care pathway with hospice/home support and surveillance notification.", src: "Harrison 22e – WHO infection-control guidelines for TSE/CJD" },
    "vascular_dementia": { name: "Vascular Dementia", class: "non_infective", system: "Neurology", dx: "Cognitive decline (esp. executive/processing slowing) with cerebrovascular disease on MRI and stepwise course or temporal link to stroke – NINDS-AIREN criteria.", tx: ["CONTROL VASCULAR RISK – BP to target, high-intensity STATIN, glycaemic control (individualise; avoid over-tight targets/hypoglycaemia in elderly), smoking cessation.","ANTIPLATELET (aspirin/clopidogrel) for non-cardioembolic disease; ANTICOAGULATE if AF.","Lifestyle – regular aerobic exercise, Mediterranean diet, treat OSA.","Trial CHOLINESTERASE INHIBITOR (donepezil) only if mixed Alzheimer pathology – modest, off-label.","BPSD/depression: non-drug measures first, SSRI for depression; AVOID antipsychotics (stroke/mortality risk)."], ix: ["MRI brain – infarcts, white-matter hyperintensities, microbleeds","Cognitive testing (MoCA – executive-sensitive)","Vascular workup: HbA1c/glucose, fasting lipids, ambulatory BP","ECG/24h monitor + carotid Doppler ± echo (embolic source, AF)","Reversible-cause bloods: TSH, B12, FBC, U&E"], dispo: "Outpatient memory/neurology clinic; MDT, carer support, capacity and driving assessment.", src: "Harrison 22e - AHA/ASA statement on vascular contributions to cognitive impairment and dementia" },
    "muscular_dystrophies_and_other_muscle": { name: "Muscular Dystrophies and Other Muscle Diseases", class: "non_infective", system: "Neuromuscular / Musculoskeletal", dx: "Confirm by combining serum CK, EMG, muscle MRI and definitive genetic testing (± muscle biopsy) to pinpoint the specific myopathy subtype.", tx: ["GLUCOCORTICOIDS (prednisolone/deflazacort) in Duchenne — slow decline, prolong ambulation, preserve motor/respiratory function.","Cardiac surveillance — annual ECG/echo; ACE-inhibitor ± beta-blocker early for dystrophinopathy cardiomyopathy; pacemaker/ICD for myotonic-dystrophy conduction block/arrhythmia.","Respiratory — track FVC; nocturnal non-invasive ventilation + cough-assist when weak; vaccinate; treat sleep hypoventilation.","Disease-specific — exon-skipping/gene therapy for DMD; IMMUNOSUPPRESSION for inflammatory myopathies; mexiletine for disabling myotonia.","MDT + anaesthetic caution — physio/orthoses for contractures, scoliosis surgery; AVOID depolarising agents/volatiles (malignant hyperthermia, rhabdo, hyperkalaemia)."], ix: ["Serum CK (creatine kinase)","Genetic/DNA testing (dystrophin, DMPK, LGMD panel)","EMG ± nerve conduction studies","ECG + echocardiography (cardiac surveillance)","Pulmonary function tests (FVC); muscle biopsy if genetics inconclusive"], dispo: "Refer to specialist neuromuscular clinic — lifelong MDT surveillance (cardiology, respiratory, physio, genetics).", src: "Harrison 22e - DMD Care Considerations (Birnkrant, Lancet Neurol 2018) / AAN corticosteroid guideline" },
    "cannabis_and_cannabis_use_disorder": { name: "Cannabis and Cannabis Use Disorder", class: "non_infective", system: "Neuropsychiatric / Substance Use", dx: "DSM-5: problematic cannabis use with ≥2 of 11 criteria (tolerance, withdrawal, craving, loss of control) over 12 months; corroborate with urine THC.", tx: ["PSYCHOSOCIAL THERAPY first-line – CBT + motivational enhancement + contingency management; no approved pharmacotherapy.","WITHDRAWAL supportive – manage insomnia/irritability/anorexia; short symptomatic course only (gabapentin/NAC weak evidence).","TREAT comorbid psychiatric illness (anxiety, depression, psychosis) – lowers relapse risk.","ACUTE agitation/psychosis – BENZODIAZEPINE ± antipsychotic; supportive care, exclude co-intoxicants.","CANNABINOID HYPEREMESIS – stop cannabis; IV fluids, antiemetics, topical capsaicin; counsel cessation."], ix: ["Urine THC-metabolite immunoassay – confirm and monitor use","Screen comorbid mood, anxiety, psychotic disorders + suicide risk","Assess concurrent substance use (alcohol, tobacco, opioids)","Baseline mental state examination","Pregnancy test in women of childbearing age"], dispo: "Outpatient addiction/community mental-health referral; admit for severe withdrawal, psychosis, or intractable hyperemesis.", src: "Harrison 22e – VA/DoD Substance Use Disorders CPG (2021)" },
    "vitamin_and_trace_mineral_deficiency": { name: "Vitamin and Trace Mineral Deficiency and Excess", class: "non_infective", system: "Nutritional / Gastrointestinal", dx: "Clinical syndrome plus low or high level of the specific micronutrient confirms diagnosis (note serum zinc/Mg poorly reflect body stores; interpret with albumin/inflammation).", tx: ["IDENTIFY specific nutrient deficiency/excess — level guides therapy; treat underlying cause.","REPLACE deficit: parenteral (IM) B12, oral/IV iron, vitamin D+Ca; thiamine BEFORE glucose in alcohol/malnutrition.","VITAMIN A 200,000 IU PO for xerophthalmia (LOW-DOSE if pregnant — teratogenic); zinc for deficiency; EXCLUDE/replace B12 BEFORE folate for macrocytosis.","TOXICITY: stop supplement; vit A/D excess — hydrate, treat hypercalcaemia; venesection (1st-line) or chelate iron overload; chelate + zinc for copper (Wilson) overload.","MONITOR levels + refeeding electrolytes (K/PO4/Mg); avoid FOLATE alone masking B12 deficiency (risk of subacute combined degeneration)."], ix: ["Targeted levels: 25-OH-vitamin D, B12 with MMA/homocysteine, folate, ferritin/iron studies","Serum zinc, copper/caeruloplasmin, selenium; vitamin A/E as indicated","FBC + blood film, Ca/PO4/Mg, alkaline phosphatase","INR/coagulation (vitamin K), LFTs","Malabsorption workup: coeliac serology, faecal elastase where relevant"], dispo: "Outpatient replacement usually; admit for severe deficiency, refeeding risk or symptomatic toxicity.", src: "Harrison 22e; ASPEN micronutrient guidance; WHO vitamin A dosing" },
    "bladder_cancer": { name: "Bladder & Urinary Tract Cancer", class: "non_infective", system: "Oncology", dx: "Confirm by cystoscopy + TURBT histology showing urothelial carcinoma; CT urography images upper tract and stages disease.", tx: ["TURBT to resect + stage — ensure detrusor muscle in specimen; re-resect high-grade/T1 (or if no muscle sampled).","NMIBC: intravesical BCG (induction + maintenance) for high-risk; single-dose intravesical MITOMYCIN immediately post-TURBT for low/intermediate.","MIBC: NEOADJUVANT cisplatin-based chemo → radical cystectomy + pelvic node dissection (or trimodality preservation if selected/unfit); consider adjuvant NIVOLUMAB if high-risk post-cystectomy.","Metastatic: ENFORTUMAB VEDOTIN + pembrolizumab first-line; else platinum chemo → avelumab switch maintenance if no progression.","Upper-tract: radical nephroureterectomy + bladder cuff (kidney-sparing if low-risk); single post-op intravesical chemo dose to cut bladder recurrence; lifelong surveillance cystoscopy + monitor renal function."], ix: ["Urine cytology","Cystoscopy + TURBT biopsy (muscle in specimen)","CT urography — staging + upper-tract imaging","CT chest/abdomen/pelvis for metastatic staging","FBC, eGFR/renal function (cisplatin eligibility), LFTs"], dispo: "Refer uro-oncology MDT; smoking cessation; stage-directed therapy with lifelong cystoscopic surveillance.", src: "Harrison 22e; EAU NMIBC/MIBC + UTUC guidelines; EV-302, JAVELIN Bladder 100, CheckMate-274" },
    "breast_cancer": { name: "Breast Cancer", class: "non_infective", system: "Oncology", dx: "Triple assessment – clinical exam + imaging (mammography/USG) + core-needle biopsy confirming invasive carcinoma with receptor status.", tx: ["SURGERY first for operable disease – breast-conserving + SLNB, or mastectomy; axillary clearance if node+.","Adjuvant RADIOTHERAPY after breast-conserving surgery; post-mastectomy if T4/node+/large.","ENDOCRINE therapy for ER+ – tamoxifen (premenopausal) or aromatase inhibitor (postmenopausal) x5–10y.","Anti-HER2 TRASTUZUMAB ± pertuzumab for HER2+; chemo (anthracycline/taxane) per risk/subtype.","NEOADJUVANT chemo for locally advanced/inflammatory/triple-negative; metastatic – systemic by subtype + palliative care."], ix: ["Core-needle biopsy – histology, grade, ER/PR/HER2, Ki-67","Bilateral mammography + breast/axillary USG (± MRI if dense/lobular)","Staging CT chest/abdo/pelvis + bone scan (or PET-CT) if node+/high-risk","FBC, LFTs, serum calcium, renal function","BRCA1/2 genetic testing if young/family history/triple-negative"], dispo: "MDT-directed; urgent referral to breast surgical + medical/radiation oncology for suspected cancer.", src: "Harrison 22e - NCCN Breast Cancer Guidelines" },
    "colorectal_cancer": { name: "Colorectal Cancer", class: "non_infective", system: "Oncology", dx: "Confirm by colonoscopy with biopsy (adenocarcinoma); staging CT chest/abdomen/pelvis + carcinoembryonic antigen, plus pelvic MRI for rectal tumours.", tx: ["SURGICAL RESECTION is the curative mainstay – colectomy with regional lymphadenectomy (>=12 nodes); TME for rectal cancer.","ADJUVANT FOLFOX/CAPOX 3–6 months for stage III (and high-risk stage II) colon cancer; test MMR/MSI first.","Rectal cancer: NEOADJUVANT chemoradiation or total neoadjuvant therapy before TME to downstage.","Metastatic: chemo (FOLFOX/FOLFIRI) + biologic by RAS/BRAF/side – anti-EGFR if RAS-WT left-sided, else bevacizumab; resect oligometastatic liver disease.","dMMR/MSI-high disease: PEMBROLIZUMAB (immunotherapy) first-line for metastatic; monitor CEA, neuropathy, and 5-FU/DPD toxicity."], ix: ["Colonoscopy to caecum with biopsy of all lesions","CT chest/abdomen/pelvis for distant staging + CEA baseline","Pelvic MRI (rectal) to assess T-stage, CRM, nodes","Tumour molecular panel: MMR/MSI, RAS, BRAF (HER2 if metastatic)","FBC, U&E, LFTs; DPYD genotyping before fluoropyrimidine"], dispo: "Refer to MDT; surgical/oncology management with post-treatment surveillance (CEA, CT, colonoscopy).", src: "Harrison 22e - NCCN Colon/Rectal Cancer Guidelines" },
    "head_and_neck_cancer": { name: "Head and Neck Cancer", class: "non_infective", system: "Oncology", dx: "Biopsy of primary (squamous cell carcinoma on histology) ± FNA/core of neck node; p16/HPV testing for oropharyngeal lesions.", tx: ["MDT + STAGE first (TNM, p16/HPV status) – drives all subsequent management.","Early (I–II): single modality – SURGERY or definitive RADIOTHERAPY.","Locally advanced (III–IVB): CONCURRENT CHEMORADIOTHERAPY – cisplatin 100 mg/m² q3wk; or resection + adjuvant CRT.","Recurrent/metastatic: PEMBROLIZUMAB (PD-L1 CPS≥1) ± platinum/5-FU; cetuximab-based EXTREME as alternative.","SUPPORTIVE: PEG/nutrition, dental clearance pre-RT, smoking/alcohol cessation, monitor swallow + thyroid."], ix: ["Tissue biopsy of primary + FNA/core of nodal disease.","Contrast CT/MRI of primary site and neck.","PET-CT for staging, distant metastases and synchronous second primary.","p16/HPV (oropharynx), EBV DNA (nasopharynx).","Panendoscopy + EUA; baseline dental, nutritional and audiometric assessment."], dispo: "Refer urgently to head-and-neck MDT; manage at high-volume centre.", src: "Harrison 22e - NCCN Head and Neck Cancers Guidelines" },
    "pancreatic_cancer": { name: "Pancreatic Cancer", class: "non_infective", system: "Oncology", dx: "Confirm with pancreatic-protocol contrast CT (or EUS-guided FNA/biopsy) showing pancreatic mass; supported by raised CA 19-9.", tx: ["STAGE FIRST with pancreatic-protocol CT +/- EUS/laparoscopy — resectable vs borderline vs locally advanced vs metastatic drives everything.","RESECTABLE: upfront surgery (Whipple/distal pancreatectomy) then ADJUVANT mFOLFIRINOX x6mo (GEM+capecitabine if unfit).","BORDERLINE/LOCALLY ADVANCED: NEOADJUVANT FOLFIRINOX or gem-nab-paclitaxel, restage, then resect if downstaged.","METASTATIC: palliative FOLFIRINOX (good PS) or GEM+NAB-PACLITAXEL (gemcitabine alone if frail/ECOG 2); test BRCA/MSI/NTRK for targeted options.","SUPPORTIVE throughout: biliary stent for obstruction, PANCREATIC ENZYME REPLACEMENT, VTE prophylaxis, early palliative care + pain control."], ix: ["Pancreatic-protocol (triphasic) contrast CT abdomen for staging/resectability","EUS with FNA/core biopsy for tissue diagnosis","CA 19-9 baseline (and LFTs/bilirubin)","CT chest for metastatic staging","Molecular testing: BRCA1/2, MSI/MMR, NTRK, KRAS"], dispo: "Refer to specialist HPB/oncology MDT; only ~15–20% resectable at diagnosis — most need palliative-intent care.", src: "Harrison 22e - NCCN Pancreatic Adenocarcinoma Guidelines" },
    "renal_cell_carcinoma": { name: "Renal Cell Carcinoma", class: "non_infective", system: "Oncology", dx: "Enhancing solid renal mass on contrast CT/MRI; confirm histology (clear-cell commonest) via surgical resection or percutaneous biopsy.", tx: ["SURGERY curative for localised disease – partial nephrectomy for T1, radical for larger/central tumours; nephron-sparing preferred.","Small renal mass or unfit patient – active surveillance or thermal ablation (cryo/RFA).","Adjuvant PEMBROLIZUMAB ~1yr for high-risk resected clear-cell RCC (KEYNOTE-564).","Metastatic first-line: IO combos – IPILIMUMAB+NIVOLUMAB (intermediate/poor IMDC risk) or TKI+anti-PD1 (axitinib/cabozantinib/lenvatinib + pembrolizumab/nivolumab).","Cytoreductive nephrectomy in selected cases; monitor immune-related AEs + renal function; RT/palliation for bone/brain mets."], ix: ["Contrast CT abdomen/pelvis – characterise mass, nodes, IVC thrombus, stage","CT chest for pulmonary metastases","FBC, U&E, LFTs, corrected calcium, LDH (prognostic/paraneoplastic)","Percutaneous renal biopsy for indeterminate/small mass or before systemic therapy","Bone scan / brain imaging if symptomatic"], dispo: "Refer to uro-oncology MDT; systemic therapy under oncology; risk-stratified surveillance imaging post-op.", src: "Harrison 22e - NCCN Kidney Cancer Guidelines" },
    "soft_tissue_sarcoma": { name: "Soft Tissue & Bone Sarcoma", class: "non_infective", system: "Oncology", dx: "Confirm with core-needle/incisional biopsy (aligned to planned resection axis) plus MRI of primary and expert sarcoma-pathology review before any treatment.", tx: ["WIDE EN-BLOC SURGICAL RESECTION with negative margins is curative backbone — refer to specialist sarcoma MDT before biopsy/surgery.","ADD radiotherapy (pre- or post-op) for high-grade/deep/large (>5cm) extremity STS to improve local control; limb-sparing preferred.","ANTHRACYCLINE chemo (doxorubicin +/- ifosfamide) for metastatic/unresectable disease or selected high-risk adjuvant; osteosarcoma/Ewing need neoadjuvant multi-agent chemo.","Match systemic therapy to histology — imatinib for GIST, pazopanib in refractory non-adipocytic STS; enrol in trials where possible.","Monitor with serial imaging; staging chest CT for lung mets; long-term surveillance for local recurrence."], ix: ["MRI of primary tumour (extremity/trunk) or CT for retroperitoneal/bone lesions","Image-guided core-needle biopsy with expert sarcoma pathology + molecular/immunohistochemistry","Chest CT to assess pulmonary metastases (staging)","FDG-PET/CT for grading, staging and marrow assessment in Ewing/high-grade","Baseline FBC, LFT, renal function, LDH/ALP before cytotoxic therapy"], dispo: "Refer urgently to specialist sarcoma centre/MDT; do not resect or biopsy locally.", src: "Harrison 22e - ESMO Soft Tissue & Bone Sarcoma Clinical Practice Guidelines" },
    "TUMOR_LYSIS_SYNDROME": { name: "Tumour lysis syndrome", class: "non_infective", system: "Oncology", dx: "Cairo–Bishop criteria: laboratory TLS = >=2 of raised urate/potassium/phosphate or low calcium within -3 to +7 days of therapy; clinical TLS adds AKI, arrhythmia or seizure.", tx: ["AGGRESSIVE IV FLUIDS - 0.9% saline 2.5-3 L/m2/day (potassium-free); keep urine output high; NO alkalinisation, diuretics only if overloaded.","RASBURICASE for high-risk/established TLS (avoid in G6PD deficiency, pregnancy); ALLOPURINOL for low/intermediate-risk prophylaxis.","Treat HYPERKALAEMIA urgently - IV calcium gluconate if ECG changes/K>=6.5; insulin-dextrose +- salbutamol to shift.","Hyperphosphataemia - oral phosphate binders; treat hypocalcaemia only if symptomatic (calcium risks Ca-PO4 precipitation).","ESCALATE to haemodialysis/CRRT for refractory hyperkalaemia, oliguric AKI or severe hyperphosphataemia."], ix: ["U&E, creatinine, eGFR (baseline then 2-4x daily)","Serum uric acid, LDH","Potassium, phosphate, corrected calcium","ECG + continuous cardiac monitoring","G6PD level before rasburicase"], dispo: "Admit; high-risk cases to HDU/ICU with continuous cardiac monitoring; urgent nephrology if RRT anticipated.", src: "Harrison 22e - BSH TLS guideline" },
    "oncologic_emergencies": { name: "Oncologic Emergencies", class: "non_infective", system: "Oncology / Emergency", dx: "Recognise the specific syndrome clinically then confirm with targeted labs/imaging — ANC <0.5×10⁹/L (febrile neutropenia), whole-spine MRI (cord compression), corrected Ca/urate/K/PO4/LDH (metabolic emergencies), contrast CT/venography (SVC obstruction).", tx: ["FEBRILE NEUTROPENIA – empirical broad-spectrum beta-lactam (piperacillin–tazobactam/cefepime) within 1 h; add vancomycin if line/skin/shock.","MALIGNANT CORD COMPRESSION – DEXAMETHASONE stat + urgent whole-spine MRI; radiotherapy/decompressive surgery <24 h to salvage function.","TUMOUR LYSIS – aggressive IV fluids + RASBURICASE (allopurinol if low-risk); treat hyperkalaemia; monitor K/PO4/urate/Ca; dialysis if refractory.","HYPERCALCAEMIA – IV saline rehydration first, then IV bisphosphonate (zoledronate) ± denosumab; calcitonin for rapid transient effect.","SVC OBSTRUCTION / raised ICP – dexamethasone + head elevation; endovascular stent for SVC; secure tissue diagnosis before therapy if stable."], ix: ["FBC with differential (ANC) + blood cultures ×2 including line","U&E, corrected calcium, phosphate, urate, LDH, magnesium","Whole-spine MRI if any back pain/neurology (cord compression)","CXR/contrast CT chest for SVC obstruction/mediastinal mass","ECG for hyper-K/hypercalcaemia changes"], dispo: "Admit under oncology + acute medicine; ICU if shock, airway compromise, or severe metabolic derangement/AKI.", src: "Harrison 22e – ESMO Clinical Practice Guidelines (oncological emergencies)" },
    "acute_myeloid_leukemia": { name: "Acute Myeloid Leukemia (AML)", class: "non_infective", system: "Oncology / Hematology", dx: "Confirm on bone marrow aspirate/trephine with ≥20% myeloid blasts (or an AML-defining genetic lesion e.g. t(15;17), t(8;21), inv(16)) on flow cytometry, cytogenetics and molecular panel.", tx: ["ATRA IMMEDIATELY if APL suspected (t(15;17)/coagulopathy) + arsenic trioxide; aggressive platelet/FFP/cryoprecipitate cover — do not await genetics; do NOT leukapherese (worsens coagulopathy).","Fit adults: \"7+3\" INDUCTION — cytarabine infusion + anthracycline (daunorubicin or idarubicin); add midostaurin if FLT3-mutated, gemtuzumab if CD33+ favourable.","Unfit/elderly: VENETOCLAX + azacitidine (or low-dose cytarabine); avoid intensive chemotherapy.","Prevent TUMOUR LYSIS — IV hydration + rasburicase (avoid in G6PD deficiency; use allopurinol)/allopurinol; cytoreduce hyperleukocytosis/leukostasis (hydroxyurea ± leukapheresis — leukapheresis NOT in APL).","Post-remission per ELN risk — high-dose cytarabine consolidation vs ALLOGENEIC HSCT; empirical broad-spectrum antibiotics for neutropenic sepsis."], ix: ["FBC + peripheral smear (blasts, Auer rods); coagulation screen — PT/aPTT/fibrinogen/D-dimer for DIC/APL.","Bone marrow aspirate + trephine with flow-cytometry immunophenotyping.","Cytogenetics + molecular panel — FLT3-ITD/TKD, NPM1, CEBPA, IDH1/2, TP53.","Tumour-lysis labs — urate, K, phosphate, calcium, LDH, renal function.","Baseline pre-treatment — HLA typing, cardiac ECHO/MUGA before anthracycline, infection screen."], dispo: "Admit under haematology as a haematological emergency; urgent same-day escalation if APL, leukostasis or tumour lysis.", src: "Harrison 22e – ELN 2022 AML recommendations" },
    "carcinoma_of_unknown_primary": { name: "Carcinoma of Unknown Primary", class: "non_infective", system: "Oncology / Hematology", dx: "Biopsy-proven metastatic carcinoma with no primary found after H&P, bloods, CT chest/abdomen/pelvis and IHC characterisation.", tx: ["IDENTIFY FAVOURABLE SUBSET first (IHC + clinical pattern) — treat as that primary; drives prognosis.","Women: axillary nodes -> breast protocol; peritoneal serous -> ovarian PLATINUM-TAXANE. Men: blastic bone + PSA -> prostate hormonal.","Squamous cervical nodes -> head/neck approach (neck dissection +/- chemoRT); midline poorly-diff -> platinum-based (germ-cell-like).","Colorectal-type IHC (CK20+/CDX2+/CK7-) -> colorectal regimen (FOLFOX/FOLFIRI +/- biologics); poorly-diff NEUROENDOCRINE -> platinum-ETOPOSIDE.","Unfavourable/disseminated -> EMPIRICAL PLATINUM + TAXANE; add site-of-origin profiling + IO if MSI-H/TMB-high/PD-L1+.","Solitary metastasis -> local therapy (resection/RT); ECOG-guided goals + early palliative care."], ix: ["Core biopsy + IHC panel (CK7/CK20, TTF-1, CDX2, PSA, ER/GCDFP, p40)","CT chest/abdomen/pelvis","Mammography +/- breast MRI (women); serum PSA (men)","FDG PET-CT (esp. cervical nodal SCC or solitary met)","Molecular/gene-expression tumour profiling + MSI/TMB/PD-L1"], dispo: "Oncology MDT referral; treat favourable subsets specifically, empirical chemo +/- IO otherwise; early palliative care.", src: "Harrison 22e - ESMO Clinical Practice Guidelines (Cancers of Unknown Primary Site)" },
    "chronic_lymphocytic_leukemia": { name: "Chronic Lymphocytic Leukemia (CLL)", class: "non_infective", system: "Oncology / Hematology", dx: "Confirm on peripheral blood flow cytometry — clonal CD5+/CD19+/CD23+, dim-CD20/dim-sIg B-cells ≥5×10⁹/L.", tx: ["WATCH AND WAIT if asymptomatic — treat only active disease (iwCLL: cytopenias, bulky/progressive nodes, B-symptoms, lymphocyte doubling <6mo).","Test del(17p)/TP53 before EVERY line (clonal evolution) + IGHV once (stable) — drives drug choice; avoid chemoimmunotherapy if TP53 aberrant.","First-line: BTK INHIBITOR (acalabrutinib/zanubrutinib, continuous) or fixed-duration VENETOCLAX–obinutuzumab.","VENETOCLAX needs TLS prophylaxis — weekly ramp-up, hydration, allopurinol/rasburicase, monitor labs; watch BTKi AF/hypertension/bleeding.","Vaccinate (no live) + infection prophylaxis for hypogammaglobulinaemia; refer urgently if Richter transformation suspected."], ix: ["FBC + blood film (lymphocytosis, smudge cells)","Flow-cytometry immunophenotype (CD5/CD19/CD23, kappa/lambda clonality)","FISH del(17p)/del(11q) + TP53 and IGHV mutation status","LDH, uric acid, U&E, calcium/phosphate (TLS baseline)","Direct antiglobulin test + immunoglobulins (autoimmune cytopenias, hypogammaglobulinaemia)"], dispo: "Haematology referral; outpatient surveillance if asymptomatic, urgent if cytopenias, bulky disease or transformation.", src: "Harrison 22e - iwCLL 2018 guidelines" },
    "chronic_myeloid_leukemia": { name: "Chronic Myeloid Leukemia (CML)", class: "non_infective", system: "Oncology / Hematology", dx: "Confirm BCR-ABL1 / Philadelphia chromosome t(9;22) by RT-PCR, FISH or cytogenetics on blood or marrow.", tx: ["START TKI first-line: imatinib or 2G-TKI (dasatinib/nilotinib/bosutinib) per ELTS risk + comorbidity.","Monitor BCR-ABL1 (IS) at 3/6/12 mo; optimal milestones <=10% at 3mo, <=1% at 6mo, <=0.1% (MMR) at 12mo (>1% at 12mo = failure).","Resistance/intolerance -> switch TKI + kinase-domain mutation test; T315I -> PONATINIB or asciminib.","Accelerated/blast phase: TKI (2G/ponatinib) + chemo, urgent haematology referral for allogeneic HSCT.","Baseline ECG/QTc + CV risk before nilotinib/ponatinib; avoid TKIs in pregnancy (teratogenic)."], ix: ["FBC + peripheral smear - leukocytosis, left shift, basophilia","Quantitative BCR-ABL1 RT-PCR (IS) - baseline then serial","Bone marrow aspirate/biopsy + cytogenetics (Ph, additional abnormalities)","ELTS/Sokal risk score at diagnosis","Baseline ECG (QTc), CV risk, LFTs before TKI"], dispo: "Outpatient haematology; hydroxyurea for cytoreduction if symptomatic hyperleukocytosis; admit if blast crisis, leukostasis or severe cytopenias.", src: "Harrison 22e - ELN 2020 CML recommendations" },
    "hodgkin_lymphoma": { name: "Hodgkin's Lymphoma", class: "non_infective", system: "Oncology / Hematology", dx: "Excisional lymph-node biopsy — Reed–Sternberg cells, CD30+/CD15+ (classical HL); distinguish nodular lymphocyte-predominant.", tx: ["ABVD (doxorubicin–bleomycin–vinblastine–dacarbazine) is BACKBONE of classical HL; cycle number stage- and risk-adapted.","Early-stage: 2–4× ABVD + involved-site RT (combined modality); PET2-adapted de-escalation.","Advanced (III–IV): brentuximab-vedotin+AVD (A+AVD) or nivolumab+AVD frontline; PET-response-guided.","Relapsed/refractory: salvage chemo → AUTOLOGOUS stem-cell transplant; brentuximab vedotin, PD-1 inhibitors (nivolumab/pembrolizumab).","Baseline echo + PFTs; watch bleomycin pneumonitis + anthracycline cardiotoxicity; fertility preservation (sperm/oocyte banking) FIRST."], ix: ["PET-CT for Lugano/Ann Arbor staging; interim PET2 to assess response.","FBC, ESR, LDH, LFTs, renal function, albumin (IPS prognostic index).","HIV + hepatitis B/C serology before immunochemotherapy.","Baseline echocardiogram + pulmonary function tests pre-chemo.","Fertility counselling ± gamete banking before treatment starts."], dispo: "Refer haemato-oncology/MDT; treat in specialist centre; long-term survivorship follow-up (second malignancy, cardiac, thyroid).", src: "Harrison 22e - NCCN Hodgkin Lymphoma Guidelines (2025)" },
    "non_hodgkin_lymphoma": { name: "Non-Hodgkin's Lymphoma", class: "non_infective", system: "Oncology / Hematology", dx: "Confirm by excisional/core lymph-node biopsy with immunophenotyping (IHC ± flow) — classify per WHO; FNA inadequate.", tx: ["CONFIRM subtype/grade first — management diverges: aggressive (curative intent) vs indolent.","DLBCL/aggressive B-cell: R-CHOP x6 — add CNS prophylaxis (methotrexate) if high CNS-IPI.","Indolent (follicular): WATCH-AND-WAIT if low burden/asymptomatic; else bendamustine–rituximab.","TUMOUR-LYSIS prophylaxis — hydration + rasburicase/allopurinol in bulky or high-grade disease.","Relapsed/refractory: salvage chemo + auto-SCT; CAR-T for refractory DLBCL — refer haemato-oncology."], ix: ["Excisional/core biopsy: histology, IHC (CD20/CD3/Ki-67), flow cytometry","PET-CT for Lugano staging + bone-marrow biopsy if indicated","FBC, LDH, urate, U&E, calcium, phosphate (tumour-lysis risk)","HBV/HCV/HIV serology before rituximab; beta-2-microglobulin","Baseline echo/MUGA (LVEF) before anthracycline"], dispo: "Refer haemato-oncology MDT; treat as specialist; safety-net for tumour lysis and neutropenic sepsis.", src: "Harrison 22e - NCCN B-Cell Lymphomas" },
    "plasma_cell_disorders": { name: "Plasma Cell Disorders (MGUS, Waldenström)", class: "non_infective", system: "Oncology / Hematology", dx: "Serum electrophoresis + immunofixation confirms monoclonal protein; IgM paraprotein with marrow lymphoplasmacytic infiltrate (MYD88 L265P) = Waldenström, whereas MGUS = M-protein <30 g/L, clonal marrow <10%, no end-organ damage.", tx: ["MGUS — NO drug therapy; risk-stratify (Mayo: M-protein >15 g/L, non-IgG, abnormal FLC ratio) + surveil SPEP.","Asymptomatic Waldenström — WATCH AND WAIT; early treatment confers no survival benefit.","Hyperviscosity (visual/neuro symptoms, very high IgM) — urgent PLASMAPHERESIS, then start systemic therapy.","Symptomatic WM first-line — BTK INHIBITOR (zanubrutinib/ibrutinib) or bendamustine–rituximab; test MYD88/CXCR4 to guide.","Avoid single-agent RITUXIMAB if IgM >40 g/L — flare risk; plasmapherese or cover first."], ix: ["SPEP + immunofixation + serum free light chains + quantitative IgM","FBC, calcium, creatinine/eGFR, β2-microglobulin, LDH","Bone-marrow aspirate/biopsy with MYD88 L265P and CXCR4 mutation testing","Serum viscosity + fundoscopy if hyperviscosity suspected","Cryoglobulins, cold agglutinins, anti-MAG antibody if neuropathy/haemolysis"], dispo: "Haematology referral for tissue diagnosis and staging; MGUS managed by primary-care surveillance.", src: "Harrison 22e - IWWM-11 consensus (2023)" },
    "prostate_cancer": { name: "Prostate Disease (BPH & Cancer)", class: "non_infective", system: "Oncology / Urology", dx: "DRE + serum PSA; TRUS-guided or MRI-fusion biopsy (Gleason/ISUP grade) confirms cancer; BPH is clinical (LUTS + enlarged benign gland).", tx: ["BPH LUTS: ALPHA-BLOCKER (tamsulosin/alfuzosin) first-line for rapid symptom relief.","Add 5-ARI (finasteride/dutasteride) if gland >30–40 mL or raised PSA; combo best for large glands.","TURP/laser (HoLEP) if refractory, retention, stones, recurrent UTI or haematuria.","Localised cancer: ACTIVE SURVEILLANCE (low-risk) vs radical prostatectomy or radiotherapy (intermediate/high); add long-course ADT with RT for high-risk.","Metastatic: ADT (LHRH agonist/antagonist) + upfront ABIRATERONE/docetaxel/darolutamide; cover LHRH-agonist start with anti-androgen (e.g. bicalutamide) to prevent testosterone flare; monitor PSA + testosterone."], ix: ["Serum PSA (with velocity/density) + DRE","Multiparametric prostate MRI (PI-RADS) before biopsy","Prostate biopsy for histology + ISUP/Gleason grade","Uroflowmetry + post-void residual; renal function (U&E, creatinine)","Staging PSMA-PET/CT + bone scan if intermediate/high-risk cancer"], dispo: "Outpatient urology/uro-oncology MDT; admit only for acute retention, obstructive AKI, biopsy sepsis or metastatic cord-compression.", src: "Harrison 22e - EAU Prostate Cancer & BPH/Non-neurogenic Male LUTS Guidelines 2024" },
    "psychiatric_disorders": { name: "Psychiatric Disorders", class: "non_infective", system: "Psychiatric / Behavioral (Neurologic Disorders)", dx: "Clinical diagnosis by DSM-5-TR criteria, made only after excluding organic and substance-induced causes.", tx: ["RULE OUT organic/substance cause first – delirium, thyroid, intoxication, withdrawal.","Acute agitation/psychosis – verbal de-escalation + ensure safety FIRST, offer oral meds; IM haloperidol + lorazepam if refused/ineffective (caution QTc; use benzo alone if suspected alcohol/sedative withdrawal).","Depression/anxiety – SSRI first-line (sertraline/escitalopram); review 2–4 wks, add CBT.","Bipolar/mania – mood stabiliser lithium or valproate + antipsychotic; avoid antidepressant monotherapy; avoid valproate in pregnancy/women of childbearing potential (teratogenic) and use lithium with caution.","Assess SUICIDE RISK each visit; urgent psychiatry referral if high-risk, psychotic or catatonic."], ix: ["TSH, FBC, U&E, LFTs, glucose – exclude metabolic/endocrine mimics.","Urine toxicology + alcohol level.","B12/folate; HIV/syphilis if cognitive change.","ECG (QTc) before/on antipsychotics or TCAs.","CT/MRI brain if new-onset, focal signs or atypical presentation."], dispo: "Outpatient with psychiatry follow-up; admit if suicidal, psychotic, catatonic or unsafe.", src: "Harrison 22e - APA Practice Guidelines" },
    "IPF": { name: "Idiopathic pulmonary fibrosis", class: "non_infective", system: "Pulmonology", dx: "Confirm via HRCT showing UIP pattern (subpleural/basal-predominant reticulation, honeycombing, traction bronchiectasis) + MDT exclusion of other ILD causes; surgical/transbronchial lung biopsy only if imaging indeterminate.", tx: ["ANTIFIBROTIC — start pirfenidone or nintedanib EARLY in confirmed IPF to slow FVC decline.","Best supportive care: supplemental O2 for resting/exertional hypoxaemia + pulmonary rehabilitation.","AVOID triple therapy (prednisone + azathioprine + NAC) — increased mortality (PANTHER-IPF).","Refer EARLY for lung-transplant assessment; screen/treat GORD, pulmonary HTN, OSA.","Acute exacerbation — supportive O2 ± high-dose steroids (weak evidence); opioids for refractory dyspnoea/cough."], ix: ["HRCT chest — assess for UIP pattern","PFTs with DLCO — restrictive defect, reduced DLCO","CTD serology (ANA, RF, anti-CCP, myositis panel) to exclude CTD-ILD","6-minute walk test with oximetry","Echocardiography — screen for pulmonary hypertension"], dispo: "Refer to specialist ILD centre/MDT; early transplant referral; palliative-care input for symptom burden.", src: "Harrison 22e - ATS/ERS/JRS/ALAT IPF guideline (2022)" },
    "nephrolithiasis": { name: "Nephrolithiasis", class: "non_infective", system: "Renal/Genitourinary", dx: "Confirm with non-contrast CT abdomen/pelvis (CT KUB) — defines stone size, site and hydronephrosis; US in pregnancy/children.", tx: ["NSAID analgesia first-line (diclofenac/ketorolac IM/IV); opioid if contraindicated; add antiemetic + fluids.","URGENT DECOMPRESSION (ureteric stent/percutaneous nephrostomy) + IV antibiotics if obstruction with infection — urosepsis is an emergency.","MEDICAL EXPULSIVE THERAPY: tamsulosin for distal ureteric stones 5–10 mm; most <5 mm pass spontaneously.","Definitive removal by size/site — SWL, ureteroscopy or PCNL; refer if >10 mm, failed passage, AKI or solitary kidney.","Prevent recurrence: fluids >2.5 L/day; thiazide (hypercalciuria), potassium citrate (hypocitraturia/uric-acid stones), allopurinol (hyperuricosuria)."], ix: ["Non-contrast CT KUB (gold standard); US in pregnancy/children","Urinalysis + microscopy — haematuria, pH, crystals, infection","FBC, U&E, creatinine, serum calcium, urate","Stone analysis on any passed/retrieved fragment","24-h urine metabolic screen (Ca, oxalate, citrate, urate, Na, volume) if recurrent/high-risk"], dispo: "Discharge with analgesia + MET if uncomplicated stone <10 mm; admit if infected obstruction, AKI, intractable pain, or solitary/transplant kidney.", src: "Harrison 22e - EAU Urolithiasis Guidelines (2024)" },
    "renovascular_disease": { name: "Renovascular Disease", class: "non_infective", system: "Renal/Genitourinary", dx: "Confirm renal artery stenosis on duplex US, CT/MR angiography; catheter angiography is gold standard.", tx: ["OPTIMISE MEDICAL THERAPY first — ACE inhibitor/ARB to target BP; monitor creatinine + K within 1–2 wk.","Add STATIN + aspirin; aggressive risk-factor control, smoking cessation, glycaemic control.","Reserve REVASCULARISATION (angioplasty ± stent) for refractory HTN, flash pulmonary oedema, or progressive renal failure — routine stenting no benefit (CORAL/ASTRAL).","FMD (young women) → percutaneous ANGIOPLASTY without stent, often curative.","Halt/reduce ACEi-ARB if creatinine rises >30% or hyperkalaemia — flags bilateral disease/solitary kidney."], ix: ["Renal duplex ultrasonography — peak systolic velocity, resistive index","CT angiography or MR angiography of renal arteries","Serum creatinine/eGFR, electrolytes (K+)","Urinalysis; plasma renin/aldosterone if indicated","Catheter angiography — gold standard, confirms FMD/atherosclerotic pattern"], dispo: "Refer nephrology/vascular; outpatient BP + renal monitoring; urgent if flash pulmonary oedema or rapidly falling eGFR.", src: "Harrison 22e - 2017 ESC/ESVS Peripheral Arterial Diseases guideline" },
    "thrombotic_renovascular_disorders": { name: "Thrombotic Renovascular Disorders", class: "non_infective", system: "Renal/Genitourinary", dx: "Confirm with contrast CT angiography (arterial + venous phase) showing renal vessel occlusion/infarction; renal Doppler US if contrast contraindicated.", tx: ["IV HEPARIN immediately for acute renal artery/vein thrombosis; bridge to warfarin/DOAC long-term.","REVASCULARISE – catheter thrombolysis/thrombectomy or surgery if solitary/bilateral kidney within viable window.","Control BP; hunt and treat embolic source – AF, mural thrombus, thrombophilia.","Nephrotic renal-vein thrombosis – anticoagulate (WARFARIN preferred over DOAC in severe hypoalbuminaemia) + treat underlying glomerulonephritis (esp. membranous).","Atheroembolic (cholesterol) disease – supportive + STATIN; AVOID anticoagulation/instrumentation."], ix: ["CT renal angiography – gold standard for occlusion/infarct.","Renal Doppler ultrasound – arterial/venous flow, thrombus.","U&E/eGFR, urinalysis (haematuria, proteinuria), LDH (raised in infarction).","ECG + echocardiogram – cardioembolic source (AF, mural thrombus).","Thrombophilia + nephrotic screen (albumin, antiphospholipid, ANA)."], dispo: "Admit; urgent nephrology + vascular/interventional radiology referral.", src: "Harrison 22e - KDIGO 2021 Glomerular Diseases guideline" },
    "inherited_defects_of_membrane_transport": { name: "Inherited Defects of Membrane Transport", class: "non_infective", system: "Renal/Metabolic", dx: "Disorder-specific — urine amino-acid chromatography/stone analysis plus serum electrolyte pattern, confirmed by targeted genetic testing.", tx: ["CYSTINURIA – high fluid intake >3 L/day + POTASSIUM CITRATE to urine pH >7; add tiopronin/penicillamine if stones recur.","BARTTER/GITELMAN – replace K+ and Mg2+; add spironolactone/amiloride; INDOMETHACIN for Bartter (prostaglandin-driven).","HARTNUP disease – NICOTINAMIDE + high-protein diet for pellagra-like rash/ataxia.","Nephrogenic DI – THIAZIDE + amiloride, low-solute diet, guarantee free-water access.","X-linked hypophosphataemic rickets – oral phosphate + calcitriol, or BUROSUMAB (anti-FGF23)."], ix: ["Serum K+, Mg2+, Ca2+, PO4, bicarbonate, creatinine","Urinary amino-acid chromatography + 24-h cystine","Urine pH, calcium, electrolytes; renal stone analysis","Plasma renin and aldosterone (Bartter/Gitelman workup)","Targeted gene panel / whole-exome sequencing"], dispo: "Refer nephrology + metabolic genetics; lifelong electrolyte and renal-function monitoring.", src: "Harrison 22e - KDIGO Bartter–Gitelman consensus (Blanchard 2017)" },
    "gynecologic_malignancies": { name: "Gynecologic Malignancies", class: "non_infective", system: "Reproductive (Female Genital Tract)", dx: "Confirm by tissue histopathology (biopsy or surgical specimen) with imaging-based FIGO staging.", tx: ["GYNAE-ONCOLOGY MDT + surgical staging first: TAH-BSO/staging (endometrial, ovarian); radical hysterectomy for early cervical.","OVARIAN: maximal cytoreduction + PLATINUM doublet (carboplatin+paclitaxel); PARP maintenance (olaparib) if BRCA/HRD-positive.","LOCALLY ADVANCED CERVICAL: concurrent CHEMORADIATION (weekly cisplatin) + brachytherapy; add pembrolizumab if PD-L1+.","Escalate with BEVACIZUMAB or immunotherapy (PEMBROLIZUMAB) per biomarker – dMMR/MSI-H, PD-L1, TMB-high.","Monitor CA-125 (ovarian) + surveillance imaging; VTE prophylaxis; fertility/menopause counselling in young early-stage."], ix: ["Tissue biopsy + histopathology – definitive diagnosis and grade","CT/MRI abdomen-pelvis +/- PET-CT for staging; transvaginal USS (adnexal mass)","CA-125 (+HE4/ROMA ovarian), CEA/CA19-9 as indicated","Cervical cytology + HPV testing (cervical/endometrial)","Molecular profiling: BRCA1/2, MMR/MSI, PD-L1, HER2 (endometrial)"], dispo: "Refer to specialist gynae-oncology centre for MDT-directed multimodal therapy and structured surveillance.", src: "Harrison 22e - NCCN Gynecologic Cancers (2025)" },
    "infertility_and_contraception": { name: "Infertility and Contraception", class: "non_infective", system: "Reproductive / Endocrine", dx: "Infertility = failure to conceive after 12 months unprotected intercourse (6 months if woman >=35yr); assess both partners.", tx: ["IDENTIFY & TREAT CAUSE – correct thyroid/prolactin, optimise weight, stop gonadotoxins; evaluate both partners.","LETROZOLE first-line for anovulatory/PCOS ovulation induction; clomiphene alternative; add metformin if insulin-resistant.","IUI for mild male/unexplained; IVF/ICSI for tubal factor, severe male factor or failed first-line.","CONTRACEPTION – LARC (implant/IUD) most effective; screen eligibility via WHO/CDC MEC before starting.","Avoid combined oestrogen if migraine-with-aura, VTE history, >=35yr smoker, or <6 weeks postpartum."], ix: ["Semen analysis (male partner)","Mid-luteal (day-21) progesterone to confirm ovulation","Day-2/3 FSH, LH, oestradiol; AMH/antral follicle count for ovarian reserve","TSH, prolactin","Tubal patency – HSG or HyCoSy"], dispo: "Refer to reproductive endocrinology/fertility clinic; deliver contraception counselling in primary care.", src: "Harrison 22e - ASRM & WHO/CDC MEC (contraception)" },
    "menstrual_disorders_and_pelvic_pain": { name: "Menstrual Disorders and Pelvic Pain", class: "non_infective", system: "Reproductive / Gynecologic", dx: "Menstrual history + pelvic exam + pregnancy test; classify abnormal uterine bleeding by FIGO PALM-COEIN and image the uterus (TVUS).", tx: ["EXCLUDE PREGNANCY (β-hCG) first; acute heavy bleed – resuscitate + high-dose oestrogen (follow with progestin taper) or TRANEXAMIC ACID to arrest; avoid TXA/oestrogen in active thromboembolic disease.","Chronic AUB, no structural cause – LEVONORGESTREL-IUS first-line; else combined OCP / oral progestogen / tranexamic acid.","Dysmenorrhoea / primary pelvic pain – NSAIDs first-line; add combined hormonal contraception. ACUTE pelvic pain – first exclude ectopic, ovarian torsion, PID/tubo-ovarian abscess, appendicitis.","Structural cause (PALM) – refer gynae for hysteroscopy, myomectomy, endometrial ablation or hysterectomy.","ENDOMETRIAL BIOPSY + urgent referral if postmenopausal bleed, age >45, persistent bleed, or hyperplasia/cancer risk."], ix: ["Urine/serum β-hCG – exclude pregnancy","FBC + ferritin (anaemia); TSH, prolactin, coagulation screen if indicated","Transvaginal ultrasound – structural causes (PALM)","Endometrial biopsy if postmenopausal bleed, age >45, or hyperplasia/malignancy risk","STI swabs; consider diagnostic laparoscopy for chronic pelvic pain/endometriosis"], dispo: "Mostly outpatient; admit for haemodynamic instability/severe acute haemorrhage or acute pelvic pain with surgical red flags; refer gynae for structural or refractory disease.", src: "Harrison 22e - FIGO/ACOG/NICE Abnormal Uterine Bleeding (PALM-COEIN)" },
    "chronic_obstructive_pulmonary_disease": { name: "Chronic Obstructive Pulmonary Disease", class: "non_infective", system: "Respiratory", dx: "Post-bronchodilator spirometry showing persistent FEV1/FVC <0.70 in a patient with dyspnoea/chronic cough/sputum and exposure risk (tobacco/biomass).", tx: ["SMOKING CESSATION (+ LTOT in chronic hypoxaemia) — the measures that alter natural history/survival (LVRS in selected); vaccinate (influenza/pneumococcal/COVID/RSV) to cut exacerbations.","Long-acting bronchodilator per GOLD group (A: single LABA or LAMA; B/E: LABA+LAMA dual mainstay); escalate by symptom/exacerbation burden.","Add INHALED CORTICOSTEROID (triple LABA+LAMA+ICS) if blood eosinophils >=300, or >=100 with recurrent exacerbations; never ICS monotherapy.","Exacerbation: controlled O2 (SpO2 88-92%), nebulised SABA+SAMA, oral PREDNISOLONE 40mg x5d, antibiotics if sputum purulent.","NIV for acute hypercapnic failure (pH<7.35); LONG-TERM O2 if PaO2<=55 mmHg (>=15h/day) improves survival."], ix: ["Post-bronchodilator spirometry — FEV1/FVC and FEV1% predicted (severity grade)","Chest X-ray +/- CT chest — exclude alternatives, assess emphysema/bullae","Pulse oximetry; ABG if SpO2<92% or exacerbation (detect hypercapnia/acidosis)","FBC (polycythaemia; blood eosinophils to guide ICS)","Alpha-1 antitrypsin level once; ECG/echo if cor pulmonale suspected"], dispo: "Admit exacerbations with hypoxaemia, acidosis (pH<7.35) or frailty; otherwise outpatient with pulmonary rehab, LTOT assessment and specialist follow-up.", src: "Harrison 22e - GOLD 2025" },
    "cystic_fibrosis": { name: "Cystic Fibrosis", class: "non_infective", system: "Respiratory", dx: "Confirm by clinical/newborn-screen features PLUS evidence of CFTR dysfunction: sweat chloride >=60 mmol/L OR two disease-causing CFTR mutations.", tx: ["CFTR MODULATOR (elexacaftor–tezacaftor–ivacaftor) if eligible genotype – start early, disease-modifying.","AIRWAY CLEARANCE daily + inhaled dornase alfa and hypertonic saline to mobilise secretions.","Exacerbation – IV anti-pseudomonal ABx (two agents); chronic Pseudomonas – inhaled tobramycin + azithromycin (screen NTM before chronic azithromycin).","PANCREATIC ENZYME replacement + ADEK vitamins, high-calorie diet; screen/treat CF-related diabetes.","Refer specialist CF-centre MDT; transplant work-up if FEV1 falling; manage haemoptysis/pneumothorax."], ix: ["Sweat chloride test (>=60 mmol/L diagnostic; 30-59 intermediate)","CFTR mutation genotyping","Sputum culture – Pseudomonas, S. aureus, Burkholderia cepacia (+ NTM screen)","Spirometry (FEV1) for baseline/monitoring","Faecal elastase, fat-soluble vitamin levels, OGTT/HbA1c; chest imaging"], dispo: "Lifelong specialist CF-centre multidisciplinary follow-up.", src: "Harrison 22e - CF Foundation (CFF) Pulmonary Guidelines" },
    "disorders_of_the_mediastinum": { name: "Disorders of the Mediastinum", class: "non_infective", system: "Respiratory", dx: "Contrast CT chest defines mediastinal compartment/lesion; tissue biopsy confirms mass aetiology, and contrast oesophagram/CT confirms mediastinitis or perforation.", tx: ["ACUTE MEDIASTINITIS = surgical emergency — broad-spectrum IV antibiotics + urgent drainage/debridement; repair oesophageal perforation.","Anterior mass: image + tumour markers first. Marker-neg, resectable, thymoma-like → upfront complete resection (AVOID needle biopsy — seeding risk); lymphoma suspected → biopsy then chemo, don't resect.","Check AFP/β-hCG before biopsy — raised → non-seminomatous germ-cell tumour → cisplatin-based CHEMOTHERAPY.","Fibrosing mediastinitis (usually post-histoplasmosis): limited drug therapy; STENT/dilate for SVC or airway/oesophageal compression.","Spontaneous pneumomediastinum: SUPPORTIVE O2 + rest, self-limiting; exclude oesophageal/tracheal rupture as driver."], ix: ["Contrast-enhanced CT chest (compartment localisation)","Serum AFP + β-hCG (anterior mass, germ-cell) BEFORE any biopsy","Image-guided/mediastinoscopic biopsy for tissue diagnosis (defer if resectable thymoma-like)","Contrast oesophagram if perforation/mediastinitis suspected","Blood cultures + inflammatory markers if febrile/septic"], dispo: "Admit acute mediastinitis to surgical/ICU care; refer mediastinal masses to thoracic MDT for tissue-guided therapy.", src: "Harrison 22e – NCCN Thymomas & Thymic Carcinomas" },
    "disorders_of_the_pleura": { name: "Disorders of the Pleura", class: "non_infective", system: "Respiratory", dx: "Confirm by diagnostic thoracentesis applying Light's criteria (transudate vs exudate); imaging localises fluid/air.", tx: ["TREAT UNDERLYING CAUSE — transudates (CCF/cirrhosis/nephrosis): diuretics; tap only if symptomatic.","INTERCOSTAL DRAIN + IV antibiotics for empyema/complicated parapneumonic effusion (pus, pH<7.2, organisms).","Loculated empyema — intrapleural TPA + DNase; VATS/decortication if drainage fails.","Tension pneumothorax — immediate NEEDLE/finger DECOMPRESSION then chest drain; size- and symptom-guided otherwise.","Malignant effusion — therapeutic drainage + TALC PLEURODESIS or indwelling pleural catheter."], ix: ["Erect CXR + bedside thoracic ultrasound — detect/localise, guide safe tap.","Diagnostic thoracentesis: protein, LDH, pH, glucose, cytology, Gram stain + culture.","Paired serum protein/LDH for Light's criteria.","CT chest with contrast — loculation, malignancy, pleural thickening.","Pleural fluid ADA/AFB and cytology if TB or malignancy suspected."], dispo: "Admit for empyema, tension pneumothorax, or symptomatic effusion needing drainage; refer respiratory/thoracic surgery.", src: "Harrison 22e - BTS Pleural Disease Guideline 2023" },
    "disorders_of_ventilation": { name: "Disorders of Ventilation", class: "non_infective", system: "Respiratory", dx: "Confirm on daytime ABG — chronic hypoventilation = awake PaCO2 >45 mmHg with compensatory raised HCO3; then define central/neuromuscular/chest-wall/obesity cause.", tx: ["NOCTURNAL NIV (BiPAP) — mainstay for chronic hypoventilation; titrate to normalise sleep CO2/SpO2.","TREAT cause — weight loss/bariatric + PAP for OHS (CPAP first-line if severe concurrent OSA, else NIV); manage neuromuscular/chest-wall disease.","Supplemental O2 CAUTIOUSLY — add only atop ventilation; target modest SpO2, avoid CO2 narcosis.","Escalate — diaphragmatic pacing for select central hypoventilation; tracheostomy/invasive vent if NIV fails.","Hyperventilation syndrome — exclude organic cause, then breathing retraining + treat underlying anxiety."], ix: ["ABG — daytime PaCO2, HCO3, A–a gradient","Overnight oximetry / polysomnography — sleep-disordered breathing","Spirometry + supine FVC and MIP/MEP — respiratory muscle strength","CXR / chest imaging — chest-wall, diaphragm, parenchyma","BMI, serum HCO3, TSH; consider daytime hypercapnia workup"], dispo: "Sleep/respiratory clinic follow-up; admit for acute-on-chronic hypercapnic failure or NIV initiation.", src: "Harrison 22e - ATS 2019 Obesity Hypoventilation Syndrome guideline" },
    "hypersensitivity_pneumonitis": { name: "Hypersensitivity Pneumonitis & Eosinophilic Lung Disease", class: "non_infective", system: "Respiratory", dx: "Exposure history + HRCT (mosaic attenuation, air-trapping, centrilobular nodules) + BAL lymphocytosis confirm HP; blood/BAL eosinophilia (BAL >25%) defines eosinophilic pneumonia.", tx: ["ANTIGEN/DRUG REMOVAL first – identify and eliminate inciting exposure; cornerstone of HP.","CORTICOSTEROIDS for acute/severe HP and for idiopathic acute (AEP)/chronic (CEP) eosinophilic pneumonia; prednisolone ~0.5 mg/kg/day, slow taper – use high-dose IV methylprednisolone if respiratory failure (esp. AEP).","SAFETY: before/with steroids in any eosinophilia, screen + empirically treat Strongyloides (ivermectin) to avert hyperinfection/dissemination.","Eosinophilic lung disease – treat the cause: DEC for tropical pulmonary eosinophilia, stop culprit drug, anti-Aspergillus + steroids for ABPA, immunosuppression for EGPA; CEP shows dramatic steroid response but high relapse – watch.","Progressive fibrotic HP – add NINTEDANIB (antifibrotic) ± mycophenolate/azathioprine as steroid-sparing.","Refer for LUNG TRANSPLANT in end-stage fibrosis; supplemental O2 + pulmonary rehab."], ix: ["HRCT chest – mosaic/air-trapping, centrilobular nodules; fibrosis (traction bronchiectasis, honeycombing) if chronic.","BAL – lymphocytosis (HP) vs marked eosinophilia (eosinophilic pneumonia).","FBC eosinophil count; serum specific IgG/precipitins to suspected antigen; total IgE + Aspergillus if ABPA suspected.","PFTs – restrictive pattern, reduced DLCO.","Strongyloides serology (+ stool O&P) before immunosuppression; lung biopsy (transbronchial/cryobiopsy/surgical) if diagnosis uncertain."], dispo: "Admit if hypoxic/acute-severe (AEP may need ICU/ventilation + IV steroids); else respiratory clinic follow-up with serial PFT/HRCT.", src: "Harrison 22e - ATS/JRS/ALAT Hypersensitivity Pneumonitis Guideline (2020)" },
    "occupational_lung_disease": { name: "Occupational and Environmental Lung Disease", class: "non_infective", system: "Respiratory", dx: "Confirm by detailed exposure history + compatible HRCT/spirometry pattern, supported by specific serology, BAL or lung biopsy when the diagnosis is uncertain.", tx: ["REMOVE FROM EXPOSURE first — cessation/substitution is the single decisive step; report notifiable occupational disease.","CORTICOSTEROIDS for acute/subacute hypersensitivity pneumonitis and chronic beryllium disease; taper to lowest effective dose.","INHALED bronchodilators + ICS for occupational asthma — manage as asthma once workplace trigger removed.","SUPPORTIVE: smoking cessation, influenza/pneumococcal vaccination, pulmonary rehab, O2 for hypoxaemia; antifibrotics/transplant if progressive fibrosis.","SCREEN/REFER: TB in silicosis (screen active + treat latent TB — high reactivation risk); lung-cancer/mesothelioma surveillance in asbestos exposure; early ILD-clinic referral."], ix: ["Detailed occupational/environmental exposure history with timeline and latency","Spirometry + lung volumes + DLCO (± bronchoprovocation/serial peak-flow for occupational asthma)","Chest X-ray and HRCT (ILO profusion scoring for pneumoconioses)","Specific IgG precipitins (HP) or beryllium lymphocyte proliferation test (BeLPT) as indicated","Bronchoscopy with BAL ± lung biopsy when diagnosis unclear"], dispo: "Outpatient pulmonology + occupational-medicine follow-up; notify statutory occupational disease register.", src: "Harrison 22e - ATS/JRS/ALAT Hypersensitivity Pneumonitis CPG (2020) + ATS/ERS Occupational Burden statement (2019)" },
    "sleep_apnea": { name: "Sleep Apnea", class: "non_infective", system: "Respiratory", dx: "Confirm with polysomnography (or home sleep apnea test in uncomplicated cases) — obstructive apnoeas/hypopnoeas giving AHI ≥5 with symptoms, or ≥15 regardless.", tx: ["CPAP first-line for moderate–severe OSA — titrate pressure, optimise mask fit + adherence.","WEIGHT LOSS + lifestyle: avoid alcohol/sedatives; positional therapy (avoid supine sleep).","Mandibular advancement/oral appliance if mild–moderate or CPAP-intolerant.","Treat comorbidities (HTN, AF, hypothyroidism); ENT referral — surgery/hypoglossal-nerve stimulation if CPAP fails.","Central sleep apnoea: treat underlying heart failure; AVOID ASV if LVEF ≤45% (SERVE-HF harm)."], ix: ["Polysomnography — AHI + oxygen desaturation index (gold standard)","Home sleep apnea test (only if no significant cardiopulmonary comorbidity)","Epworth Sleepiness Scale / STOP-BANG screening","TSH; screen for HTN, AF, heart failure","ECG ± echocardiogram if cardiac disease/central apnoea suspected"], dispo: "Outpatient sleep-medicine referral for PSG + CPAP titration; expedite if severe with cardiorespiratory compromise or hypersomnolent driver.", src: "Harrison 22e – AASM (obstructive sleep apnoea clinical practice guidelines)" },
    "neoplasms_of_the_lung": { name: "Neoplasms of the Lung", class: "non_infective", system: "Respiratory / Thoracic Oncology", dx: "Confirm with tissue biopsy (bronchoscopy/EBUS/CT-guided) + histology — separate NSCLC from SCLC, then molecular + PD-L1 profiling on NSCLC.", tx: ["STAGE + histology + molecular/PD-L1 FIRST — dictates all therapy; every case via MDT.","Early NSCLC (I–IIIA resectable): SURGICAL RESECTION (lobectomy + nodal dissection); adjuvant chemo ± osimertinib (EGFR+)/atezolizumab.","Unresectable stage III NSCLC: concurrent CHEMORADIOTHERAPY, then durvalumab consolidation.","Metastatic NSCLC: driver+ → matched TKI (osimertinib/alectinib/etc.); driver− → PEMBROLIZUMAB ± platinum-doublet by PD-L1.","SCLC: PLATINUM–ETOPOSIDE + atezolizumab/durvalumab; limited-stage add thoracic RT + PCI; treat SVCO/cord/brain emergencies urgently."], ix: ["Contrast CT chest + upper abdomen; PET-CT for staging","Biopsy with histology + IHC; NSCLC → EGFR/ALK/ROS1/BRAF/KRAS-G12C/MET/RET/NTRK + PD-L1","MRI brain (stage III–IV NSCLC and all SCLC)","Pulmonary function tests + FBC/U&E/LFTs/Ca prior to treatment","EBUS/mediastinoscopy for nodal staging if resection considered"], dispo: "Admit for oncological emergency (SVCO, cord compression, massive effusion, haemoptysis); otherwise urgent MDT + oncology/thoracic-surgery referral, smoking cessation, early palliative care.", src: "Harrison 22e - NCCN NSCLC/SCLC Guidelines (2025)" },
    "beh_et_syndrome": { name: "Behçet Syndrome", class: "non_infective", system: "Rheumatologic / Multisystem vasculitis", dx: "Clinical – recurrent oral aphthae plus ≥2 of genital ulcers, uveitis, skin lesions or positive pathergy (ISG/ICBD criteria); no confirmatory test.", tx: ["COLCHICINE first-line for mucocutaneous disease (oral/genital ulcers, erythema nodosum); topical steroids; apremilast if refractory.","Posterior uveitis/retinal vasculitis – systemic GLUCOCORTICOIDS + azathioprine; sight-threatening → INFLIXIMAB or interferon-α.","Neuro-Behçet (parenchymal) – high-dose IV METHYLPREDNISOLONE then taper + immunosuppressant; anti-TNF if refractory; avoid ciclosporin (neurotoxic).","Major vascular/venous thrombosis – GLUCOCORTICOIDS + cyclophosphamide/azathioprine; treat inflammation, anticoagulation adjunctive only.","Screen for PULMONARY ARTERY ANEURYSM before anticoagulating – fatal haemorrhage risk; urgent immunosuppression."], ix: ["Pathergy test (skin hyperreactivity to needle prick)","HLA-B51 – supportive association, not diagnostic","Ophthalmology slit-lamp + fundoscopy for uveitis","ESR/CRP for disease activity","MRI brain (neuro) and CT/MR angiography (vascular/aneurysm)"], dispo: "Multidisciplinary specialist care – rheumatology plus ophthalmology/neurology per organ; urgent admit for ocular, neuro or vascular flares.", src: "Harrison 22e - EULAR 2018 recommendations for the management of Behçet syndrome" },
    "ADULT_ONSET_STILL": { name: "Adult-onset Still disease", class: "non_infective", system: "Rheumatology", dx: "Clinical diagnosis of exclusion (Yamaguchi criteria): quotidian spiking fever, evanescent salmon-pink rash, arthralgia, sore throat, hyperferritinaemia — after excluding infection, malignancy (esp. lymphoma) and other autoimmune disease.", tx: ["NSAIDs as short bridge in mild disease only — rarely control systemic disease alone.","GLUCOCORTICOIDS (prednisolone 0.5–1 mg/kg/day) first-line for systemic disease; IV pulse methylprednisolone if severe/MAS.","IL-1 blockade (ANAKINRA / canakinumab) — preferred first-line steroid-sparing biologic, esp. systemic phenotype.","Tocilizumab (IL-6) or methotrexate for chronic articular disease / steroid sparing.","Watch MACROPHAGE ACTIVATION SYNDROME — falling counts, rising ferritin, low fibrinogen; escalate urgently (pulse steroids + anakinra)."], ix: ["Ferritin — markedly raised; low glycosylated fraction (<20%) supports dx.","FBC (neutrophilic leucocytosis), ESR/CRP raised, LFTs (transaminitis).","Blood cultures + serology to exclude infection; ANA/RF usually negative.","Imaging ± lymph-node/marrow biopsy to exclude lymphoma.","MAS screen: fibrinogen, triglycerides, serial ferritin, sCD25."], dispo: "Refer Rheumatology; admit if MAS, organ involvement or systemic instability.", src: "Harrison 22e – EULAR/PReS 2024 Still's disease recommendations" },
    "CATASTROPHIC_APS": { name: "Catastrophic antiphospholipid syndrome", class: "non_infective", system: "Rheumatology", dx: "Confirm ≥3 organs thrombosed within 1 week plus persistent aPL positivity, ideally with small-vessel occlusion on biopsy.", tx: ["Identify/treat TRIGGER — empirical antibiotics if infection; never withhold anticoagulation.","TRIPLE THERAPY first-line — therapeutic IV heparin + high-dose IV methylprednisolone pulse + plasma exchange and/or IVIG (give IVIG after PLEX).","Escalate/adjunct — RITUXIMAB for refractory disease; add eculizumab if complement-mediated/microangiopathic or life-threatening; add cyclophosphamide if SLE-associated CAPS.","Long-term — bridge to warfarin (target INR 2–3), avoid DOACs; lifelong anticoagulation.","Supportive — ICU organ support; avoid oestrogens and elective procedures."], ix: ["aPL panel — lupus anticoagulant, anti-cardiolipin, anti-β2-glycoprotein I","FBC + blood film — thrombocytopenia, schistocytes/haemolysis (MAHA)","U&E + urinalysis — renal microthrombosis/AKI","Organ imaging + tissue biopsy — small-vessel occlusion","Sepsis/infection screen — identify precipitant"], dispo: "ICU admission with urgent rheumatology and haematology co-management.", src: "Harrison 22e - McMaster RARE-Best Practices CAPS Clinical Practice Guideline" },
    "KAWASAKI_DISEASE": { name: "Kawasaki disease", class: "non_infective", system: "Rheumatology", dx: "Clinical diagnosis: fever ≥5 days plus ≥4 of 5 principal features (bilateral non-exudative conjunctivitis, oral mucosal changes, polymorphous rash, extremity changes, cervical lymphadenopathy); echo confirms coronary involvement.", tx: ["IV IMMUNOGLOBULIN 2 g/kg single infusion within 10 days of fever onset — cuts coronary aneurysm risk.","High-dose ASPIRIN 30–50 mg/kg/day until afebrile 48–72h; then low-dose 3–5 mg/kg/day antiplatelet.","IVIG-resistant/persistent fever ≥36h: second IVIG 2 g/kg or add CORTICOSTEROIDS (give upfront if high-risk).","Refractory disease: INFLIXIMAB or ciclosporin; anakinra as salvage.","Serial ECHO (baseline, ~2wk, ~6wk); anticoagulate large/giant aneurysms."], ix: ["Echocardiography — baseline + serial for coronary aneurysms","FBC (leukocytosis, week-2 thrombocytosis), ESR + CRP raised","LFTs/albumin (hypoalbuminaemia, transaminitis)","Urinalysis (sterile pyuria)","ECG"], dispo: "Admit for IVIG; paediatric cardiology follow-up with serial echocardiography.", src: "Harrison 22e - AHA 2017 Kawasaki Disease Scientific Statement" },
    "MCTD": { name: "Mixed connective tissue disease", class: "non_infective", system: "Rheumatology", dx: "High-titre anti-U1-RNP antibody plus Raynaud's and overlapping SLE/systemic sclerosis/myositis features meeting classification criteria (Alarcon-Segovia/Kasukawa).", tx: ["TAILOR to organ + severity — no MCTD-specific regimen; treat overlap as SLE/SSc/myositis.","Mild (arthralgia/Raynaud): NSAIDs + HYDROXYCHLOROQUINE; dihydropyridine CCB (nifedipine) + cold-avoidance for Raynaud.","Organ disease (myositis/ILD/serositis/cytopenias): GLUCOCORTICOIDS + steroid-sparing agent — mycophenolate or azathioprine (cyclophosphamide/rituximab for severe ILD); MTX for arthritis/myositis but AVOID in significant ILD (pneumonitis).","CAUTION high-dose steroids with prominent SSc features — scleroderma renal crisis risk; monitor BP + renal function.","SCREEN annually for PAH (echo + DLCO) — leading killer; PAH-targeted vasodilators +/- immunosuppression (steroids/cyclophosphamide/rituximab — MCTD-PAH more IS-responsive than SSc-PAH).","REFER rheumatology; PAH/severe ILD to specialist centre early."], ix: ["Anti-U1-RNP antibody (high titre) + ANA (speckled pattern)","FBC, U&E, ESR/CRP","CK +/- EMG if myositis suspected","Echocardiography + PFTs with DLCO (PAH/ILD screen)","HRCT chest if interstitial lung disease suspected"], dispo: "Outpatient rheumatology follow-up; admit for severe ILD, PAH decompensation, or active myositis.", src: "Harrison 22e - ESC/ERS 2022 Pulmonary Hypertension guideline" },
    "osteoarthritis": { name: "Osteoarthritis", class: "non_infective", system: "Rheumatology", dx: "Clinical diagnosis — activity-related joint pain, brief (<30 min) morning stiffness, crepitus, bony enlargement; radiographs confirm.", tx: ["EXERCISE + weight loss first-line — supervised aerobic/strengthening, tai chi, self-management education.","TOPICAL NSAIDs preferred for knee/hand — first choice in elderly/comorbid before systemic therapy.","Oral NSAIDs at lowest dose/shortest course — add PPI or use COX-2 if GI risk; caution renal/CVD.","INTRA-ARTICULAR corticosteroid for flares; duloxetine/topical capsaicin adjuncts; AVOID glucosamine, IA hyaluronate; limit opioids (tramadol only if NSAIDs unsuitable).","Refer for JOINT REPLACEMENT once pain/function refractory to optimal medical therapy."], ix: ["Weight-bearing radiographs — joint-space narrowing, osteophytes, subchondral sclerosis/cysts","ESR/CRP normal — helps exclude inflammatory arthritis (no diagnostic serology for OA)","Baseline U&E/creatinine + FBC before starting NSAIDs","Synovial aspirate + polarised microscopy if effusion — exclude crystal/septic arthritis"], dispo: "Primary-care/outpatient management; refer orthopaedics if refractory pain or major functional limitation.", src: "Harrison 22e - ACR/Arthritis Foundation 2019 OA guideline" },
    "REACTIVE_ARTHRITIS": { name: "Reactive arthritis", class: "non_infective", system: "Rheumatology", dx: "Clinical: asymmetric lower-limb oligoarthritis ± enthesitis/dactylitis 1–4 weeks after GU (Chlamydia) or enteric infection; exclude septic and crystal arthritis.", tx: ["NSAIDs high-dose first-line (e.g. indometacin/naproxen) for arthritis + enthesitis; PPI cover.","INTRA-ARTICULAR GLUCOCORTICOIDS for mono/oligoarthritis; short systemic course only if polyarticular/severe.","ANTIBIOTICS only if Chlamydia-triggered – doxycycline/azithromycin (azithromycin if pregnant) + treat sexual partners; NOT useful for post-enteric ReA.","Persistent >3–6 months → SULFASALAZINE (or methotrexate); add TNF inhibitor if DMARD-refractory.","Acute anterior uveitis → URGENT ophthalmology + topical steroid + cycloplegic; test HIV if severe/atypical."], ix: ["ESR/CRP (raised, non-specific)","Synovial fluid aspirate – Gram stain/culture + crystals to exclude septic/crystal arthritis","Chlamydia trachomatis NAAT (first-void urine/urethral/cervical) ± stool culture if enteric symptoms","HLA-B27 (prognostic – predicts chronicity/axial/uveitis)","HIV test + full STI screen"], dispo: "Outpatient rheumatology; most resolve <6 months – urgent referral for uveitis, severe/persistent or systemic disease.", src: "Harrison 22e – ASAS-EULAR recommendations for peripheral spondyloarthritis (2018)" },
    "spondyloarthritis": { name: "Spondyloarthritis", class: "non_infective", system: "Rheumatology", dx: "Confirm via ASAS axial SpA criteria (chronic back pain >=3mo, onset <45yr): sacroiliitis on X-ray/MRI + >=1 SpA feature, OR HLA-B27 + >=2 SpA features.", tx: ["NSAIDs first-line — continuous full-dose while active (caution renal/GI/elderly; avoid 3rd-trimester); combine with structured EXERCISE/physiotherapy (cornerstone of axial SpA).","Escalate to TNF INHIBITOR or IL-17 inhibitor if >=2 NSAIDs fail over 4wk + high activity (ASDAS>=2.1 / BASDAI>=4).","csDMARDs (sulfasalazine/methotrexate) only for PERIPHERAL arthritis — no axial benefit; MTX teratogenic (contraception in reproductive-age); avoid systemic steroids, use local injections.","Screen TB/HBV/HCV before biologics; tailor drug to comorbidity — TNF mAb for recurrent uveitis/IBD, avoid IL-17 in IBD.","Refer OPHTHALMOLOGY urgently for acute anterior uveitis; if first bDMARD fails SWITCH to another TNFi/IL-17i or to a JAK inhibitor — do NOT combine biologic + JAK."], ix: ["HLA-B27","ESR + CRP (disease activity)","Plain X-ray sacroiliac joints/pelvis","MRI SI joints (active sacroiliitis if X-ray normal)","Pre-biologic screen: IGRA/CXR for TB + HBV/HCV serology"], dispo: "Rheumatology outpatient follow-up; periodic ASDAS/BASDAI monitoring and long-term biologic surveillance.", src: "Harrison 22e - ASAS-EULAR 2022 axial SpA recommendations" },
    "systemic_sclerosis": { name: "Systemic Sclerosis (Scleroderma)", class: "non_infective", system: "Rheumatology", dx: "Clinical – skin thickening proximal to MCPs (or characteristic distal features) plus Raynaud's; confirm with ANA and SSc-specific antibodies (anti-centromere, anti-Scl-70/topoisomerase, anti-RNA-pol III) and nailfold capillaroscopy; classify by 2013 ACR/EULAR criteria.", tx: ["ORGAN-BASED therapy – no single cure; risk-stratify by antibody + subset (limited vs diffuse) and screen all organs early.","SCLERODERMA RENAL CRISIS (SRC): start ACE INHIBITOR (captopril) immediately, uptitrate to control BP – do NOT prophylax with ACEi and avoid high-dose steroids (>15mg/d) which precipitate it.","ILD (anti-Scl-70, diffuse): MYCOPHENOLATE or cyclophosphamide first-line; add/switch NINTEDANIB for progression, tocilizumab an option; refer for transplant if severe.","PAH: confirm on right-heart cath, then PDE5 inhibitor/endothelin-antagonist/prostacyclin – early combination therapy; annual echo + PFT screening.","RAYNAUD/digital ulcers: CCB (nifedipine) first, then PDE5i/IV iloprost/bosentan; GI reflux – PPI + prokinetics; skin/joints – methotrexate or MMF."], ix: ["ANA + SSc antibodies (centromere, Scl-70, RNA-pol III) and nailfold capillaroscopy","HRCT chest + PFTs (FVC, DLCO) for ILD screening","Transthoracic echo (RVSP/TR) annually to screen for PAH; RHC if suspected","Baseline + serial BP, U&E/creatinine and urinalysis (renal crisis surveillance)","ECG/NT-proBNP; barium swallow/manometry if significant GI symptoms"], dispo: "Rheumatology-led multidisciplinary care (resp/cardio/nephro); urgent admission for scleroderma renal crisis or rapidly progressive ILD/PAH.", src: "Harrison 22e - EULAR 2023 recommendations for the treatment of systemic sclerosis" },
    "acute_rheumatic_fever": { name: "Acute Rheumatic Fever", class: "non_infective", system: "Rheumatology / Cardiology", dx: "Confirm by revised Jones criteria — evidence of preceding GAS infection PLUS 2 major or 1 major + 2 minor manifestations (population risk-stratified in 2015 revision).", tx: ["BENZATHINE PENICILLIN G IM single dose to eradicate GAS (penicillin V 10d oral alt; macrolide if allergic).","ASPIRIN/NSAID high-dose for arthritis + mild carditis; taper over 2–4 weeks per symptoms/CRP.","CORTICOSTEROIDS (prednisone) for severe carditis/heart failure; add diuretics + ACEi, restrict activity/bed rest.","SYDENHAM CHOREA usually self-limiting; if disabling, valproate or carbamazepine first-line (haloperidol/dopamine antagonists 2nd-line); avoid valproate in females of childbearing potential — teratogenic.","SECONDARY PROPHYLAXIS benzathine penicillin IM q3–4wk — duration by carditis/RHD severity (up to age 40 or 10y); penicillin-allergic: sulfadiazine (macrolide only if sulfa-allergic too)."], ix: ["Throat swab culture / rapid strep antigen for GAS.","ASO + anti-DNase B titres (raised or rising).","ECG (PR prolongation, block) + echocardiography for valvulitis/subclinical carditis.","ESR + CRP (acute-phase reactants).","FBC; blood cultures if septic-picture to exclude endocarditis/sepsis."], dispo: "Admit if carditis, heart failure or chorea; cardiology + rheumatology follow-up; enrol in prophylaxis register.", src: "Harrison 22e - AHA 2015 Revised Jones Criteria" },
    "inflammatory_myopathies": { name: "Inflammatory Myopathies", class: "non_infective", system: "Rheumatology / Neurology", dx: "Confirm via proximal weakness + raised CK + myopathic EMG + muscle biopsy, backed by myositis-specific antibodies (heliotrope/Gottron rash in dermatomyositis).", tx: ["HIGH-DOSE CORTICOSTEROIDS first-line - prednisolone 1 mg/kg/day PO; IV methylprednisolone pulse if severe/dysphagia/ILD.","Add STEROID-SPARING agent early - methotrexate or azathioprine; mycophenolate preferred if ILD.","Escalate refractory/severe - IVIG (dysphagia, DM skin) then RITUXIMAB; tailor to autoantibody phenotype.","Anti-MDA5 rapidly-progressive ILD - urgent triple immunosuppression; screen for occult malignancy in DM (esp anti-TIF1-gamma).","PJP + bone/GI prophylaxis; monitor CK + strength; IBM largely steroid-refractory - physiotherapy, no immunosuppression."], ix: ["Serum CK (+ aldolase, LDH, transaminases)","Myositis antibody panel - Jo-1, Mi-2, MDA5, HMGCR, SRP, TIF1-gamma","EMG + muscle MRI (oedema, biopsy targeting)","Muscle biopsy for definitive histology/subtype","ILD + malignancy screen - HRCT/PFTs + age-appropriate cancer workup"], dispo: "Refer rheumatology/neurology; admit if dysphagia, respiratory-muscle weakness, or rapidly progressive ILD.", src: "Harrison 22e - EULAR/ACR 2017 myositis classification criteria" },
    "disorders_caused_by_venomous_snakebites": { name: "Disorders Caused by Venomous Snakebites and Marine Animal Exposures", class: "non_infective", system: "Toxicology / Envenomation (multisystem)", dx: "Clinical — bite/sting history + local signs (fang marks, pain, swelling) plus systemic features (neurotoxicity, coagulopathy, haemolysis); confirm with 20-min whole-blood clotting test (20WBCT) for haematotoxic snakebite.", tx: ["ABC + IMMOBILISE limb (neutral splint), pressure-immobilisation only for neurotoxic elapid bites; NEVER incise/suck/tourniquet.","ANTIVENOM IV is the priority — give for any systemic envenoming (coagulopathy, neurotoxicity, shock, active local spread); repeat if signs persist.","Pre-treat / keep ready for anaphylaxis: ADRENALINE IM at bedside; treat antivenom reactions promptly, then resume infusion.","NEUROTOXIC bites: trial NEOSTIGMINE + atropine; intubate/ventilate early for respiratory failure.","Marine stings: hot-water immersion 45C for pain; box jellyfish (Chironex) → vinegar + IV antivenom; supportive ICU."], ix: ["20-min whole-blood clotting test (bedside), PT/INR + fibrinogen","FBC, platelets, peripheral smear (haemolysis/schistocytes)","U&E, creatinine, CK, urinalysis (myoglobinuria, AKI)","ECG + continuous SpO2/respiratory monitoring","Group & save; serial neuro obs (ptosis, single-breath count)"], dispo: "Admit all systemic envenoming to HDU/ICU for antivenom + monitoring; observe dry/local bites 24h; early referral if antivenom or dialysis unavailable.", src: "Harrison 22e - WHO Guidelines for the Management of Snakebite (SEARO 2016)" },
    "heavy_metal_poisoning": { name: "Heavy Metal Poisoning", class: "non_infective", system: "Toxicology / Environmental Medicine", dx: "Confirm by metal-specific blood and/or 24-h urine levels matched to exposure history and clinical syndrome.", tx: ["REMOVE from source + supportive ABC; whole-bowel irrigation if radiopaque metal (Pb/As/Fe) on AXR.","Confirm metal + level and phone POISONS CENTRE before starting chelation.","CHELATE per metal – succimer (DMSA) oral for moderate; for severe lead/encephalopathy give DIMERCAPROL (BAL) FIRST, then add CaNa2EDTA (calcium disodium – NEVER disodium/Na2EDTA: fatal hypocalcaemia).","Arsenic/inorganic mercury – DMSA/DMPS; thallium – PRUSSIAN BLUE; iron – DEFEROXAMINE.","AVOID BAL in organic (methyl)mercury – redistributes to brain; also avoid BAL in G6PD deficiency (haemolysis) and with iron/cadmium; monitor renal/LFT/lytes + repeat levels."], ix: ["Metal-specific blood + 24-h urine panel (± provoked urine)","FBC + blood film (basophilic stippling in lead)","U&E/creatinine + LFTs","Abdominal X-ray for radiopaque ingested metal","ECG (QT/arrhythmia); G6PD before certain chelators"], dispo: "Admit symptomatic/severe cases to ICU/toxicology; discuss all with poisons centre; notify public health for source control.", src: "Harrison 22e - ACMT chelation guidance" },
    "poisoning_and_drug_overdose": { name: "Poisoning and Drug Overdose", class: "non_infective", system: "Toxicology / Multisystem", dx: "Clinical toxidrome recognition plus history/witness account, confirmed by targeted toxicology screen, drug levels and metabolic/anion-gap assessment.", tx: ["AIRWAY/BREATHING/CIRCULATION first – secure airway, O2, IV access, treat hypotension with fluids then vasopressors.","GIVE ANTIDOTE early: naloxone (opioid), N-acetylcysteine (paracetamol), fomepizole (methanol/ethylene glycol), atropine+pralidoxime (organophosphate), digoxin-specific Fab (digoxin), bicarbonate (TCA/QRS>100ms); flumazenil rarely – seizure risk.","DECONTAMINATE: activated charcoal if <1h + airway safe; whole-bowel irrigation for sustained-release/metals/packers.","ENHANCE ELIMINATION: urinary alkalinisation (salicylate/phenobarbital); haemodialysis for toxic alcohols, lithium, salicylate, metformin-lactic acidosis.","CORRECT hypoglycaemia (empiric glucose+thiamine if altered), seizures (benzodiazepines), hyperthermia (cooling); admit ICU, involve Poisons Centre early."], ix: ["ABG with anion + osmolar gap, glucose, U&E, creatinine","Paracetamol + salicylate levels; ethanol/toxic-alcohol screen","ECG (QRS/QTc), continuous cardiac monitoring","FBC, LFTs, coagulation, creatine kinase, lactate","Paracetamol/urine toxicology; specific drug levels (lithium, digoxin, iron)"], dispo: "ICU/HDU for unstable, altered mental status, arrhythmia or antidote infusion; psychiatric review before discharge if intentional.", src: "Harrison 22e - AACT/EAPCCT Position Statements (Gastrointestinal Decontamination)" },
    "chronic_venous_disease": { name: "Chronic Venous Disease & Lymphedema", class: "non_infective", system: "Vascular", dx: "Clinical CEAP staging plus venous duplex confirming reflux (>0.5 s superficial, >1 s deep); lymphedema by positive Stemmer sign +/- lymphoscintigraphy.", tx: ["COMPRESSION first-line - graded stockings 20-30 mmHg (higher for ulcers/lymphedema); check ABI to exclude PAD first.","Leg ELEVATION + calf-muscle exercise + weight loss + emollient skin care.","ENDOVENOUS ablation (RFA/laser) or foam sclerotherapy for symptomatic superficial reflux/varicosities.","Venous ulcer - multilayer compression + wound care; add PENTOXIFYLLINE to speed healing.","Lymphedema - COMPLETE DECONGESTIVE THERAPY (manual drainage, bandaging, exercise); prompt antibiotics for cellulitis."], ix: ["Venous duplex ultrasound - reflux/obstruction","ABI before compression - exclude significant PAD","CEAP class + Venous Clinical Severity Score","Lymphoscintigraphy if lymphedema diagnosis unclear","Skin/ulcer assessment; swab if infected"], dispo: "Outpatient vascular/lymphedema clinic; refer for ablation if superficial reflux; admit for severe cellulitis or non-healing ulcer.", src: "Harrison 22e - SVS/AVF Venous Disease CPG (+ ISL Lymphedema Consensus)" }
  };
})();
